# =============================================================================
# GENERIC HELPERS
# =============================================================================

def _safe_float(value: Any, default: float | None = None) -> float | None:
        try:
                if value is None or pd.isna(value):
                        return default
                value = float(value)
                if not np.isfinite(value):
                        return default
                return value
        except Exception:
                return default


def _safe_div(numerator: float, denominator: float, default: float = np.nan) -> float:
        if denominator is None or abs(float(denominator)) < EPS:
                return default
        return float(numerator) / float(denominator)


def _slug(value: Any) -> str:
        return re.sub(r"[^a-zA-Z0-9_-]+", "_", str(value or "")).strip("_").lower()


def _is_cash(ticker: str, asset_class: str | None = None) -> bool:
        ticker = str(ticker or "").upper().strip()
        asset_class = str(asset_class or "").lower().strip()
        return ticker in CASH_ALIASES or asset_class == "cash"


def _asset_class_bucket(ticker: str, asset_class: str, sector: str = "", name: str = "") -> str:
        text = " ".join([str(ticker), str(asset_class), str(sector), str(name)]).lower()
        if _is_cash(ticker, asset_class):
                return "Cash"
        if "gold" in text or "precious metal" in text:
                return "Gold"
        if any(token in text for token in ["bond", "fixed income", "treasury", "rates", "credit"]):
                return "Bond"
        if any(token in text for token in ["crypto", "bitcoin", "ethereum"]):
                return "Crypto"
        if any(token in text for token in ["commodity", "oil", "energy future", "metal", "agri"]):
                return "Commodity"
        if any(token in text for token in ["fx", "forex", "currency"]):
                return "FX"
        if any(token in text for token in ["equity", "stock", "etf", "index"]):
                return "Equity"
        return "Other"


def _fmt_pct(value: Any, digits: int = 2) -> str:
        number = _safe_float(value)
        return "N/A" if number is None else f"{number:.{digits}%}"


def _fmt_num(value: Any, digits: int = 2) -> str:
        number = _safe_float(value)
        return "N/A" if number is None else f"{number:,.{digits}f}"


def _fmt_money(value: Any, currency: str = "") -> str:
        number = _safe_float(value)
        if number is None:
                return "N/A"
        suffix = f" {currency}" if currency else ""
        return f"{number:,.2f}{suffix}"


def _normalise_weights(weights: pd.Series, target_sum: float = 1.0) -> pd.Series:
        weights = pd.to_numeric(weights, errors="coerce").fillna(0.0).astype(float)
        total = float(weights.sum())
        if abs(total) < EPS:
                if len(weights) == 0:
                        return weights
                return pd.Series(target_sum / len(weights), index=weights.index, dtype=float)
        return weights * (target_sum / total)


def _clean_book(book: pd.DataFrame) -> pd.DataFrame:
        if not isinstance(book, pd.DataFrame):
                book = pd.DataFrame(book)

        work = book.copy()

        for column in BOOK_COLUMNS:
                if column not in work.columns:
                        work[column] = DEFAULT_ROW.get(column, np.nan)

        work = work[BOOK_COLUMNS].copy()
        work["Active"] = work["Active"].fillna(True).astype(bool)
        work["Ticker"] = work["Ticker"].fillna("").astype(str).str.upper().str.strip()
        work["Name"] = work["Name"].fillna("").astype(str).str.strip()

        for column in ["Asset Class", "Sector", "Country", "Currency", "Strategy"]:
                fallback = DEFAULT_ROW[column]
                work[column] = work[column].fillna(fallback).astype(str).str.strip().replace("", fallback)

        for column in NUMERIC_BOOK_COLUMNS:
                work[column] = pd.to_numeric(work[column], errors="coerce")

        work["Quantity"] = work["Quantity"].fillna(0.0)
        work["Cost bps"] = work["Cost bps"].fillna(10.0).clip(lower=0.0)
        work["Lot Size"] = work["Lot Size"].fillna(1.0).clip(lower=EPS)
        work["Duration"] = work["Duration"].fillna(0.0)
        work["Min Weight"] = work["Min Weight"].fillna(0.0)
        work["Max Weight"] = work["Max Weight"].fillna(1.0)
        work = work.loc[work["Active"] & work["Ticker"].ne("")].copy()

        # Duplicate symbols are aggregated later only after validation; preserve metadata now.
        work = work.drop_duplicates(subset=["Ticker"], keep="last").reset_index(drop=True)

        if len(work) > MAX_ASSETS:
                work = work.head(MAX_ASSETS).copy()

        return work


def _book_template_csv() -> bytes:
        return pd.DataFrame([{**DEFAULT_ROW, "Ticker": "AAPL", "Quantity": 10.0}])[BOOK_COLUMNS].to_csv(index=False).encode("utf-8")


def _book_fingerprint(book: pd.DataFrame) -> str:
        clean = _clean_book(book).sort_values("Ticker").reset_index(drop=True)
        payload = clean.to_csv(index=False, na_rep="").encode("utf-8")
        return hashlib.sha256(payload).hexdigest()


def _json_default(value: Any) -> Any:
        if isinstance(value, (np.integer,)):
                return int(value)
        if isinstance(value, (np.floating,)):
                return float(value)
        if isinstance(value, (pd.Timestamp, datetime)):
                return value.isoformat()
        if isinstance(value, pd.Series):
                return value.to_dict()
        if isinstance(value, pd.DataFrame):
                return value.to_dict(orient="records")
        raise TypeError(f"Object of type {type(value).__name__} is not JSON serializable")


# =============================================================================
# MARKET DATA
# =============================================================================

def _extract_yf_series(raw: pd.DataFrame, candidates: Sequence[str]) -> pd.Series:
        if raw is None or raw.empty:
                return pd.Series(dtype=float)

        data = raw.copy()

        if isinstance(data.columns, pd.MultiIndex):
                # A single-ticker download may still produce a two-level index.
                flattened = []
                for col in data.columns:
                        parts = [str(part).strip() for part in col if str(part).strip()]
                        flattened.append("__".join(parts))
                data.columns = flattened
        else:
                data.columns = [str(column) for column in data.columns]

        lower_map = {str(column).lower().replace("_", " "): column for column in data.columns}

        for candidate in candidates:
                key = candidate.lower().replace("_", " ")
                if key in lower_map:
                        series = pd.to_numeric(data[lower_map[key]], errors="coerce")
                        return series

        # MultiIndex-flattened fallback such as "Close__AAPL".
        for column in data.columns:
                column_lower = str(column).lower()
                if any(candidate.lower().replace(" ", "") in column_lower.replace(" ", "").replace("_", "") for candidate in candidates):
                        return pd.to_numeric(data[column], errors="coerce")

        return pd.Series(dtype=float)


@st.cache_data(ttl=900, show_spinner=False)
def _download_single_asset(ticker: str, period: str, interval: str) -> dict[str, Any]:
        ticker = str(ticker).upper().strip()

        try:
                raw = yf.download(
                        ticker,
                        period=period,
                        interval=interval,
                        auto_adjust=True,
                        progress=False,
                        threads=False,
                )
        except Exception as exc:
                return {"ticker": ticker, "price": pd.Series(dtype=float), "volume": pd.Series(dtype=float), "error": str(exc)}

        if raw is None or raw.empty:
                return {"ticker": ticker, "price": pd.Series(dtype=float), "volume": pd.Series(dtype=float), "error": "No data"}

        price = _extract_yf_series(raw, ["Close", "Adj Close"])
        volume = _extract_yf_series(raw, ["Volume"])

        price.index = pd.to_datetime(raw.index, errors="coerce", utc=True).tz_convert(None)
        volume.index = (
                pd.to_datetime(raw.index, errors="coerce", utc=True).tz_convert(None)
                if not volume.empty
                else pd.DatetimeIndex([])
        )

        price = price.dropna().sort_index()
        volume = volume.dropna().sort_index()

        return {"ticker": ticker, "price": price, "volume": volume, "error": None}


@st.cache_data(ttl=900, show_spinner=False)
def download_portfolio_market_data(
        tickers: tuple[str, ...],
        cash_tickers: tuple[str, ...],
        period: str,
        interval: str,
        benchmark: str,
) -> dict[str, Any]:
        """Download price and volume data with per-symbol fault isolation."""
        prices: dict[str, pd.Series] = {}
        volumes: dict[str, pd.Series] = {}
        diagnostics: list[dict[str, Any]] = []

        cash_set = {str(t).upper() for t in cash_tickers}
        requested = list(dict.fromkeys([str(t).upper().strip() for t in tickers if str(t).strip()]))
        benchmark = str(benchmark or "").upper().strip()

        download_list = list(requested)
        if benchmark and benchmark not in cash_set and benchmark not in download_list:
                download_list.append(benchmark)

        for symbol in download_list:
                if symbol in cash_set:
                        continue

                payload = _download_single_asset(symbol, period, interval)
                price = payload["price"]
                volume = payload["volume"]
                error = payload["error"]

                if isinstance(price, pd.Series) and not price.empty:
                        prices[symbol] = price.rename(symbol)
                if isinstance(volume, pd.Series) and not volume.empty:
                        volumes[symbol] = volume.rename(symbol)

                diagnostics.append(
                        {
                                "Ticker": symbol,
                                "Status": "OK" if symbol in prices else "KO",
                                "Observations": int(len(price)) if isinstance(price, pd.Series) else 0,
                                "Start": price.index.min() if isinstance(price, pd.Series) and not price.empty else pd.NaT,
                                "End": price.index.max() if isinstance(price, pd.Series) and not price.empty else pd.NaT,
                                "Error": error or "",
                        }
                )

        price_df = pd.concat(prices.values(), axis=1) if prices else pd.DataFrame()
        volume_df = pd.concat(volumes.values(), axis=1) if volumes else pd.DataFrame()

        if not price_df.empty:
                price_df = price_df.sort_index()
        if not volume_df.empty:
                volume_df = volume_df.sort_index()

        return {
                "prices": price_df,
                "volumes": volume_df,
                "diagnostics": pd.DataFrame(diagnostics),
                "benchmark": benchmark,
        }


def prepare_return_matrix(
        price_df: pd.DataFrame,
        asset_tickers: Sequence[str],
        min_coverage: float = 0.80,
) -> tuple[pd.DataFrame, pd.DataFrame]:
        """Create an aligned return matrix and a coverage audit table."""
        if price_df is None or price_df.empty:
                return pd.DataFrame(), pd.DataFrame()

        requested = [ticker for ticker in asset_tickers if ticker in price_df.columns]
        work = price_df[requested].copy()
        work = work.apply(pd.to_numeric, errors="coerce").sort_index()

        # Limited forward fill handles non-synchronous holidays without hiding long gaps.
        work = work.ffill(limit=3)
        raw_returns = work.pct_change(fill_method=None).replace([np.inf, -np.inf], np.nan)

        rows = []
        retained = []
        total_rows = max(len(raw_returns), 1)

        for ticker in requested:
                valid = int(raw_returns[ticker].notna().sum())
                coverage = valid / total_rows
                keep = valid >= MIN_OBSERVATIONS and coverage >= min_coverage
                rows.append(
                        {
                                "Ticker": ticker,
                                "Valid Returns": valid,
                                "Coverage": coverage,
                                "Retained": keep,
                        }
                )
                if keep:
                        retained.append(ticker)

        returns = raw_returns[retained].dropna(how="any") if retained else pd.DataFrame()
        return returns, pd.DataFrame(rows)


def latest_market_snapshot(
        book: pd.DataFrame,
        price_df: pd.DataFrame,
        volume_df: pd.DataFrame,
) -> pd.DataFrame:
        rows = []

        for _, position in book.iterrows():
                ticker = position["Ticker"]
                asset_class = position["Asset Class"]

                if _is_cash(ticker, asset_class):
                        latest_price = 1.0
                        latest_date = pd.Timestamp.now(tz="UTC").tz_localize(None)
                        adv20 = np.nan
                elif ticker in price_df.columns and not price_df[ticker].dropna().empty:
                        series = price_df[ticker].dropna()
                        latest_price = float(series.iloc[-1])
                        latest_date = pd.Timestamp(series.index[-1])

                        if ticker in volume_df.columns:
                                aligned_volume = volume_df[ticker].dropna().tail(20)
                                aligned_price = price_df[ticker].reindex(aligned_volume.index).ffill()
                                adv20 = float((aligned_volume * aligned_price).mean()) if not aligned_volume.empty else np.nan
                        else:
                                adv20 = np.nan
                else:
                        latest_price = np.nan
                        latest_date = pd.NaT
                        adv20 = np.nan

                rows.append(
                        {
                                "Ticker": ticker,
                                "Latest Price": latest_price,
                                "Latest Date": latest_date,
                                "ADV20 Value": adv20,
                        }
                )

        return pd.DataFrame(rows)


# =============================================================================
# PORTFOLIO BOOK / CURRENT WEIGHTS
# =============================================================================

def build_current_portfolio(
        book: pd.DataFrame,
        market_snapshot: pd.DataFrame,
        settings: PortfolioSettings,
) -> tuple[pd.DataFrame, pd.Series, float, list[str]]:
        work = book.merge(market_snapshot, on="Ticker", how="left")
        warnings: list[str] = []

        if settings.input_mode == "Current Weights":
                weights = pd.to_numeric(work["Current Weight"], errors="coerce").fillna(0.0)
                if abs(float(weights.sum())) < EPS:
                        raise ValueError("Current Weight mode selected, but the weight column sums to zero.")
                weights = weights / float(weights.sum())
                nav = float(settings.portfolio_nav)
                work["Current Weight Resolved"] = weights.values
                work["Market Value"] = work["Current Weight Resolved"] * nav
                work["Quantity Resolved"] = np.where(
                        pd.to_numeric(work["Latest Price"], errors="coerce").abs() > EPS,
                        work["Market Value"] / work["Latest Price"],
                        0.0,
                )
        else:
                work["Quantity Resolved"] = pd.to_numeric(work["Quantity"], errors="coerce").fillna(0.0)
                work["Market Value"] = work["Quantity Resolved"] * pd.to_numeric(work["Latest Price"], errors="coerce")

                unavailable = work.loc[work["Latest Price"].isna(), "Ticker"].tolist()
                if unavailable:
                        warnings.append(f"No usable latest price for: {', '.join(unavailable)}")

                work["Market Value"] = work["Market Value"].fillna(0.0)
                nav = float(work["Market Value"].sum())
                if nav <= EPS:
                        raise ValueError("Portfolio NAV is non-positive. Check quantities, cash and market data.")
                work["Current Weight Resolved"] = work["Market Value"] / nav

        work["Unrealized P&L"] = np.where(
                pd.to_numeric(work["Avg Cost"], errors="coerce").notna(),
                work["Quantity Resolved"] * (work["Latest Price"] - work["Avg Cost"]),
                np.nan,
        )
        work["Unrealized P&L %"] = np.where(
                pd.to_numeric(work["Avg Cost"], errors="coerce").abs() > EPS,
                work["Latest Price"] / work["Avg Cost"] - 1.0,
                np.nan,
        )

        weights = work.set_index("Ticker")["Current Weight Resolved"].astype(float)
        return work, weights, nav, warnings


# =============================================================================
# RETURN / COVARIANCE ESTIMATION
# =============================================================================

def geometric_annual_return(returns: pd.Series) -> float:
        clean = pd.to_numeric(returns, errors="coerce").dropna()
        if clean.empty or (clean <= -1.0).any():
                return np.nan
        return float(np.expm1(np.log1p(clean).mean() * TRADING_DAYS))


def expected_returns_from_history(
        returns: pd.DataFrame,
        model: str,
        ewma_lambda: float,
) -> pd.Series:
        if returns.empty:
                return pd.Series(dtype=float)

        if model == "Historical Arithmetic":
                mu = returns.mean() * TRADING_DAYS
        elif model == "EWMA":
                count = len(returns)
                decay = float(np.clip(ewma_lambda, 0.50, 0.999))
                weights = np.power(decay, np.arange(count - 1, -1, -1))
                weights = weights / weights.sum()
                mu = pd.Series(np.average(returns.values, axis=0, weights=weights) * TRADING_DAYS, index=returns.columns)
        else:
                mu = returns.apply(geometric_annual_return, axis=0)

        return pd.to_numeric(mu, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0).clip(-1.0, 2.0)


def nearest_psd(matrix: pd.DataFrame, floor: float = 1e-10) -> pd.DataFrame:
        values = np.asarray(matrix, dtype=float)
        values = (values + values.T) / 2.0
        eigenvalues, eigenvectors = np.linalg.eigh(values)
        eigenvalues = np.maximum(eigenvalues, floor)
        repaired = eigenvectors @ np.diag(eigenvalues) @ eigenvectors.T
        repaired = (repaired + repaired.T) / 2.0
        return pd.DataFrame(repaired, index=matrix.index, columns=matrix.columns)


def estimate_covariance(
        returns: pd.DataFrame,
        model: str,
        shrinkage: float,
        ewma_lambda: float,
) -> pd.DataFrame:
        if returns.empty:
                return pd.DataFrame()

        sample = returns.cov() * TRADING_DAYS

        if model == "EWMA":
                decay = float(np.clip(ewma_lambda, 0.50, 0.999))
                demeaned = returns - returns.mean()
                count = len(demeaned)
                weights = np.power(decay, np.arange(count - 1, -1, -1))
                weights = weights / weights.sum()
                values = demeaned.values
                cov_values = (values * weights[:, None]).T @ values * TRADING_DAYS
                cov = pd.DataFrame(cov_values, index=returns.columns, columns=returns.columns)
        elif model == "Diagonal Shrinkage":
                alpha = float(np.clip(shrinkage, 0.0, 1.0))
                diagonal = pd.DataFrame(np.diag(np.diag(sample.values)), index=sample.index, columns=sample.columns)
                cov = (1.0 - alpha) * sample + alpha * diagonal
        else:
                cov = sample

        return nearest_psd(cov)


def apply_expected_return_overrides(mu: pd.Series, book: pd.DataFrame) -> pd.Series:
        output = mu.copy()
        override_map = book.set_index("Ticker")["Expected Return Override"]

        for ticker, value in override_map.items():
                override = _safe_float(value)
                if ticker in output.index and override is not None:
                        output.loc[ticker] = float(np.clip(override, -1.0, 2.0))

        return output


def black_litterman_posterior(
        covariance: pd.DataFrame,
        market_weights: pd.Series,
        views: pd.DataFrame,
        risk_aversion: float = 2.5,
        tau: float = 0.05,
) -> tuple[pd.Series, pd.DataFrame]:
        assets = list(covariance.index)
        cov = covariance.loc[assets, assets].values
        w_market = market_weights.reindex(assets).fillna(0.0).values
        w_market = w_market / max(abs(w_market.sum()), EPS)
        prior = risk_aversion * cov @ w_market

        clean_views = views.copy() if isinstance(views, pd.DataFrame) else pd.DataFrame()
        required = {"Ticker", "View Return", "Confidence"}

        if clean_views.empty or not required.issubset(clean_views.columns):
                return pd.Series(prior, index=assets, name="BL Expected Return"), pd.DataFrame()

        rows = []
        p_rows = []
        q_values = []
        omega_values = []

        for _, row in clean_views.iterrows():
                ticker = str(row.get("Ticker", "")).upper().strip()
                view_return = _safe_float(row.get("View Return"))
                confidence = _safe_float(row.get("Confidence"), 0.50)

                if ticker not in assets or view_return is None:
                        continue

                confidence = float(np.clip(confidence or 0.50, 0.01, 0.99))
                p = np.zeros(len(assets))
                index = assets.index(ticker)
                p[index] = 1.0
                variance = float(p @ (tau * cov) @ p.T)
                omega = max(variance * (1.0 - confidence) / confidence, 1e-10)

                p_rows.append(p)
                q_values.append(view_return)
                omega_values.append(omega)
                rows.append({"Ticker": ticker, "View Return": view_return, "Confidence": confidence, "Omega": omega})

        if not p_rows:
                return pd.Series(prior, index=assets, name="BL Expected Return"), pd.DataFrame()

        p_matrix = np.vstack(p_rows)
        q_vector = np.asarray(q_values)
        omega_matrix = np.diag(omega_values)
        tau_cov = tau * cov

        # Numerically stable posterior mean formulation.
        middle = np.linalg.pinv(p_matrix @ tau_cov @ p_matrix.T + omega_matrix)
        posterior = prior + tau_cov @ p_matrix.T @ middle @ (q_vector - p_matrix @ prior)

        return (
                pd.Series(posterior, index=assets, name="BL Expected Return").clip(-1.0, 2.0),
                pd.DataFrame(rows),
        )


# =============================================================================
# ANALYTICS
# =============================================================================

def portfolio_return_series(returns: pd.DataFrame, weights: pd.Series) -> pd.Series:
        aligned = weights.reindex(returns.columns).fillna(0.0)
        return returns.mul(aligned, axis=1).sum(axis=1)


def drawdown_series(returns: pd.Series) -> pd.Series:
        wealth = (1.0 + returns.fillna(0.0)).cumprod()
        running_max = wealth.cummax()
        return wealth / running_max - 1.0


def historical_var_cvar(returns: pd.Series, confidence: float = 0.95) -> tuple[float, float]:
        clean = pd.to_numeric(returns, errors="coerce").dropna()
        if clean.empty:
                return np.nan, np.nan
        alpha = 1.0 - float(np.clip(confidence, 0.50, 0.999))
        quantile = float(clean.quantile(alpha))
        tail = clean[clean <= quantile]
        cvar = float(tail.mean()) if not tail.empty else quantile
        return -quantile, -cvar


def omega_ratio(returns: pd.Series, threshold_annual: float = 0.0) -> float:
        clean = pd.to_numeric(returns, errors="coerce").dropna()
        if clean.empty:
                return np.nan
        threshold_daily = (1.0 + threshold_annual) ** (1.0 / TRADING_DAYS) - 1.0
        excess = clean - threshold_daily
        gains = excess.clip(lower=0.0).sum()
        losses = -excess.clip(upper=0.0).sum()
        return _safe_div(gains, losses)


def compute_portfolio_metrics(
        returns: pd.DataFrame,
        weights: pd.Series,
        expected_returns: pd.Series,
        risk_free_rate: float,
        benchmark_returns: pd.Series | None = None,
) -> dict[str, float]:
        series = portfolio_return_series(returns, weights)
        annual_return = geometric_annual_return(series)
        annual_arithmetic = float(series.mean() * TRADING_DAYS) if not series.empty else np.nan
        volatility = float(series.std(ddof=1) * math.sqrt(TRADING_DAYS)) if len(series) > 1 else np.nan
        expected_return = float(expected_returns.reindex(weights.index).fillna(0.0) @ weights)
        sharpe = _safe_div(annual_arithmetic - risk_free_rate, volatility)

        downside = series[series < 0.0]
        downside_vol = float(downside.std(ddof=1) * math.sqrt(TRADING_DAYS)) if len(downside) > 1 else np.nan
        sortino = _safe_div(annual_arithmetic - risk_free_rate, downside_vol)

        drawdown = drawdown_series(series)
        max_drawdown = float(drawdown.min()) if not drawdown.empty else np.nan
        calmar = _safe_div(annual_return, abs(max_drawdown))
        var95, cvar95 = historical_var_cvar(series, 0.95)

        skew = float(series.skew()) if len(series) >= 3 else np.nan
        kurtosis = float(series.kurt()) if len(series) >= 4 else np.nan
        omega = omega_ratio(series, risk_free_rate)

        gross = float(weights.abs().sum())
        net = float(weights.sum())
        hhi = float(np.square(weights).sum())
        effective_bets = _safe_div(1.0, hhi)

        beta = np.nan
        tracking_error = np.nan
        information_ratio = np.nan

        if benchmark_returns is not None and not benchmark_returns.empty:
                aligned = pd.concat([series.rename("portfolio"), benchmark_returns.rename("benchmark")], axis=1).dropna()
                if len(aligned) > 2:
                        benchmark_var = float(aligned["benchmark"].var(ddof=1))
                        if benchmark_var > EPS:
                                beta = float(aligned.cov().loc["portfolio", "benchmark"] / benchmark_var)
                        active = aligned["portfolio"] - aligned["benchmark"]
                        tracking_error = float(active.std(ddof=1) * math.sqrt(TRADING_DAYS))
                        information_ratio = _safe_div(float(active.mean() * TRADING_DAYS), tracking_error)

        return {
                "Expected Return": expected_return,
                "Historical Return": annual_return,
                "Historical Arithmetic Return": annual_arithmetic,
                "Volatility": volatility,
                "Sharpe": sharpe,
                "Sortino": sortino,
                "Max Drawdown": max_drawdown,
                "Calmar": calmar,
                "VaR 95% (1D)": var95,
                "CVaR 95% (1D)": cvar95,
                "Skew": skew,
                "Excess Kurtosis": kurtosis,
                "Omega": omega,
                "Beta": beta,
                "Tracking Error": tracking_error,
                "Information Ratio": information_ratio,
                "Gross Exposure": gross,
                "Net Exposure": net,
                "HHI": hhi,
                "Effective Bets": effective_bets,
        }


def risk_decomposition(weights: pd.Series, covariance: pd.DataFrame) -> pd.DataFrame:
        assets = [asset for asset in weights.index if asset in covariance.index]
        w = weights.reindex(assets).fillna(0.0).values
        cov = covariance.loc[assets, assets].values
        variance = float(w.T @ cov @ w)
        volatility = math.sqrt(max(variance, 0.0))

        if volatility < EPS:
                marginal = np.zeros_like(w)
                component = np.zeros_like(w)
                percent = np.zeros_like(w)
        else:
                marginal = cov @ w / volatility
                component = w * marginal
                percent = component / volatility

        standalone_vol = np.sqrt(np.clip(np.diag(cov), 0.0, None))

        return pd.DataFrame(
                {
                        "Ticker": assets,
                        "Weight": w,
                        "Standalone Vol": standalone_vol,
                        "Marginal Risk": marginal,
                        "Component Risk": component,
                        "Risk Contribution %": percent,
                }
        )


def diversification_ratio(weights: pd.Series, covariance: pd.DataFrame) -> float:
        assets = [asset for asset in weights.index if asset in covariance.index]
        w = weights.reindex(assets).fillna(0.0).values
        cov = covariance.loc[assets, assets].values
        standalone = np.sqrt(np.clip(np.diag(cov), 0.0, None))
        portfolio_vol = math.sqrt(max(float(w.T @ cov @ w), 0.0))
        return _safe_div(float(np.abs(w) @ standalone), portfolio_vol)


def group_exposure_and_risk(
        book: pd.DataFrame,
        weights: pd.Series,
        risk_table: pd.DataFrame,
        group_column: str,
) -> pd.DataFrame:
        metadata = book.set_index("Ticker")
        frame = pd.DataFrame({"Ticker": weights.index, "Weight": weights.values})
        frame[group_column] = frame["Ticker"].map(metadata[group_column]).fillna("Unclassified")
        risk_map = risk_table.set_index("Ticker")["Risk Contribution %"] if not risk_table.empty else pd.Series(dtype=float)
        frame["Risk Contribution %"] = frame["Ticker"].map(risk_map).fillna(0.0)

        grouped = (
                frame.groupby(group_column, dropna=False)
                .agg(
                        Net_Weight=("Weight", "sum"),
                        Gross_Weight=("Weight", lambda x: float(np.abs(x).sum())),
                        Risk_Contribution=("Risk Contribution %", "sum"),
                        Positions=("Ticker", "count"),
                )
                .reset_index()
                .rename(
                        columns={
                                "Net_Weight": "Net Weight",
                                "Gross_Weight": "Gross Weight",
                                "Risk_Contribution": "Risk Contribution %",
                        }
                )
        )
        return grouped.sort_values("Gross Weight", ascending=False)


# =============================================================================
# OPTIMISATION
# =============================================================================

def _portfolio_vol_array(weights: np.ndarray, covariance: np.ndarray) -> float:
        return math.sqrt(max(float(weights.T @ covariance @ weights), 0.0))


def _asset_bounds(
        book: pd.DataFrame,
        assets: Sequence[str],
        settings: OptimizerSettings,
) -> tuple[list[tuple[float, float]], list[str]]:
        metadata = book.set_index("Ticker")
        bounds = []
        warnings = []

        for asset in assets:
                row = metadata.loc[asset]
                row_min = _safe_float(row.get("Min Weight"), settings.global_min_weight)
                row_max = _safe_float(row.get("Max Weight"), settings.global_max_weight)

                lower = max(float(row_min if row_min is not None else settings.global_min_weight), settings.global_min_weight)
                upper = min(float(row_max if row_max is not None else settings.global_max_weight), settings.global_max_weight)

                if settings.long_only:
                        lower = max(0.0, lower)
                        upper = max(0.0, upper)
                else:
                        lower = max(-settings.global_max_weight, lower)
                        upper = min(settings.global_max_weight, upper)

                if lower > upper:
                        warnings.append(f"Invalid bounds for {asset}: lower {lower:.2%} > upper {upper:.2%}.")
                        lower, upper = upper, lower

                bounds.append((lower, upper))

        return bounds, warnings


def _bounded_initial_weights(
        current: pd.Series,
        assets: Sequence[str],
        bounds: Sequence[tuple[float, float]],
        target_sum: float = 1.0,
) -> np.ndarray:
        initial = current.reindex(assets).fillna(0.0).values.astype(float)

        if len(assets) == 0:
                return np.array([], dtype=float)

        if abs(float(initial.sum())) < EPS:
                initial = np.repeat(float(target_sum) / len(assets), len(assets))
        else:
                initial = initial * (float(target_sum) / float(initial.sum()))
        lower = np.array([b[0] for b in bounds])
        upper = np.array([b[1] for b in bounds])
        initial = np.clip(initial, lower, upper)

        # Iterative redistribution inside bounds.
        for _ in range(100):
                gap = float(target_sum) - float(initial.sum())
                if abs(gap) < 1e-10:
                        break
                if gap > 0:
                        capacity = np.maximum(upper - initial, 0.0)
                else:
                        capacity = np.maximum(initial - lower, 0.0)
                total_capacity = float(capacity.sum())
                if total_capacity < EPS:
                        break
                adjustment = abs(gap) * capacity / total_capacity
                initial = initial + adjustment if gap > 0 else initial - adjustment
                initial = np.clip(initial, lower, upper)

        return initial


def _cash_assets(book: pd.DataFrame, assets: Sequence[str]) -> list[str]:
        metadata = book.set_index("Ticker")
        return [
                asset
                for asset in assets
                if asset in metadata.index and _is_cash(asset, metadata.at[asset, "Asset Class"])
        ]


def _apply_fixed_cash_to_heuristic(
        raw_weights: pd.Series,
        current: pd.Series,
        book: pd.DataFrame,
        assets: Sequence[str],
        bounds: Sequence[tuple[float, float]],
        fix_cash_weight: bool,
) -> pd.Series:
        if not fix_cash_weight:
                values = _bounded_initial_weights(raw_weights, assets, bounds, target_sum=1.0)
                return pd.Series(values, index=assets, dtype=float)

        cash_assets = _cash_assets(book, assets)
        if not cash_assets:
                values = _bounded_initial_weights(raw_weights, assets, bounds, target_sum=1.0)
                return pd.Series(values, index=assets, dtype=float)

        risky_assets = [asset for asset in assets if asset not in cash_assets]
        fixed_cash = current.reindex(cash_assets).fillna(0.0).astype(float)
        cash_total = float(fixed_cash.sum())

        if cash_total < -1e-8 or cash_total > 1.0 + 1e-8:
                # Leave the audit to flag the infeasible state rather than silently changing cash.
                values = _bounded_initial_weights(raw_weights, assets, bounds, target_sum=1.0)
                return pd.Series(values, index=assets, dtype=float)

        target = pd.Series(0.0, index=assets, dtype=float)
        target.loc[cash_assets] = fixed_cash.values

        if risky_assets:
                risky_bounds = [bounds[assets.index(asset)] for asset in risky_assets]
                risky_raw = raw_weights.reindex(risky_assets).fillna(0.0)
                risky_values = _bounded_initial_weights(
                        risky_raw,
                        risky_assets,
                        risky_bounds,
                        target_sum=max(0.0, 1.0 - cash_total),
                )
                target.loc[risky_assets] = risky_values

        return target


def _constraint_report(
        weights: pd.Series,
        current: pd.Series,
        expected_returns: pd.Series,
        covariance: pd.DataFrame,
        book: pd.DataFrame,
        settings: OptimizerSettings,
        sector_caps: Mapping[str, float] | None,
) -> pd.DataFrame:
        expected = float(expected_returns.reindex(weights.index).fillna(0.0) @ weights)
        cov = covariance.reindex(index=weights.index, columns=weights.index).fillna(0.0)
        vol = _portfolio_vol_array(weights.values, cov.values)
        turnover = 0.5 * float((weights - current.reindex(weights.index).fillna(0.0)).abs().sum())
        gross = float(weights.abs().sum())

        rows = [
                {"Constraint": "Net exposure", "Value": float(weights.sum()), "Limit": 1.0, "Pass": abs(float(weights.sum()) - 1.0) <= 1e-5},
                {"Constraint": "Gross exposure", "Value": gross, "Limit": settings.gross_limit, "Pass": gross <= settings.gross_limit + 1e-5},
        ]

        bounds, _ = _asset_bounds(book, list(weights.index), settings)
        for asset, (lower, upper) in zip(weights.index, bounds):
                value = float(weights.loc[asset])
                rows.append(
                        {
                                "Constraint": f"Asset bounds: {asset}",
                                "Value": value,
                                "Limit": upper,
                                "Pass": lower - 1e-5 <= value <= upper + 1e-5,
                        }
                )

        if settings.fix_cash_weight:
                cash_assets = _cash_assets(book, list(weights.index))
                if cash_assets:
                        target_cash = float(current.reindex(cash_assets).fillna(0.0).sum())
                        actual_cash = float(weights.reindex(cash_assets).fillna(0.0).sum())
                        rows.append(
                                {
                                        "Constraint": "Fixed cash allocation",
                                        "Value": actual_cash,
                                        "Limit": target_cash,
                                        "Pass": abs(actual_cash - target_cash) <= 1e-5,
                                }
                        )

        if settings.turnover_limit is not None:
                rows.append({"Constraint": "Turnover", "Value": turnover, "Limit": settings.turnover_limit, "Pass": turnover <= settings.turnover_limit + 1e-5})
        if settings.minimum_expected_return is not None:
                rows.append({"Constraint": "Minimum expected return", "Value": expected, "Limit": settings.minimum_expected_return, "Pass": expected + 1e-5 >= settings.minimum_expected_return})
        if settings.maximum_volatility is not None:
                rows.append({"Constraint": "Maximum volatility", "Value": vol, "Limit": settings.maximum_volatility, "Pass": vol <= settings.maximum_volatility + 1e-5})

        if sector_caps:
                sector_map = book.set_index("Ticker")["Sector"]
                for sector, cap in sector_caps.items():
                        mask_assets = [asset for asset in weights.index if str(sector_map.get(asset, "Unclassified")) == str(sector)]
                        exposure = float(weights.reindex(mask_assets).abs().sum()) if not settings.long_only else float(weights.reindex(mask_assets).sum())
                        rows.append({"Constraint": f"Sector cap: {sector}", "Value": exposure, "Limit": cap, "Pass": exposure <= cap + 1e-5})

        return pd.DataFrame(rows)


def _heuristic_weights(
        method: str,
        covariance: pd.DataFrame,
        expected_returns: pd.Series,
) -> pd.Series:
        assets = list(covariance.index)
        variances = np.clip(np.diag(covariance.values), EPS, None)
        vols = np.sqrt(variances)

        if method == "Equal Weight":
                values = np.ones(len(assets))
        elif method == "Inverse Volatility":
                values = 1.0 / vols
        elif method == "Minimum Variance":
                inv_cov = np.linalg.pinv(covariance.values)
                values = inv_cov @ np.ones(len(assets))
                values = np.clip(values, 0.0, None)
        else:
                values = np.clip(expected_returns.reindex(assets).fillna(0.0).values, 0.0, None) / vols

        if float(values.sum()) <= EPS:
                values = np.ones(len(assets))
        values = values / values.sum()
        return pd.Series(values, index=assets)


def _hrp_cluster_variance(cov: pd.DataFrame, cluster_items: list[str]) -> float:
        sub_cov = cov.loc[cluster_items, cluster_items]
        diagonal = np.clip(np.diag(sub_cov.values), EPS, None)
        inverse_variance = 1.0 / diagonal
        inverse_variance /= inverse_variance.sum()
        return float(inverse_variance.T @ sub_cov.values @ inverse_variance)


def hierarchical_risk_parity(covariance: pd.DataFrame) -> pd.Series:
        if not SCIPY_AVAILABLE or len(covariance) < 2:
                return _heuristic_weights("Inverse Volatility", covariance, pd.Series(0.0, index=covariance.index))

        corr = covariance.corr()
        # covariance.corr() is not the return correlation. Derive it explicitly.
        vol = np.sqrt(np.clip(np.diag(covariance.values), EPS, None))
        corr_values = covariance.values / np.outer(vol, vol)
        corr_values = np.clip(corr_values, -1.0, 1.0)
        corr = pd.DataFrame(corr_values, index=covariance.index, columns=covariance.columns)

        distance = np.sqrt(np.maximum((1.0 - corr.values) / 2.0, 0.0))
        condensed = squareform(distance, checks=False)
        link = linkage(condensed, method="single")
        order = leaves_list(link)
        sorted_assets = [covariance.index[i] for i in order]

        weights = pd.Series(1.0, index=sorted_assets)
        clusters = [sorted_assets]

        while clusters:
                next_clusters: list[list[str]] = []
                for cluster in clusters:
                        if len(cluster) <= 1:
                                continue
                        split = len(cluster) // 2
                        left = cluster[:split]
                        right = cluster[split:]
                        var_left = _hrp_cluster_variance(covariance, left)
                        var_right = _hrp_cluster_variance(covariance, right)
                        alpha = 1.0 - var_left / max(var_left + var_right, EPS)
                        weights[left] *= alpha
                        weights[right] *= 1.0 - alpha
                        next_clusters.extend([left, right])
                clusters = next_clusters

        return _normalise_weights(weights.reindex(covariance.index))


def optimise_portfolio(
        method: str,
        expected_returns: pd.Series,
        covariance: pd.DataFrame,
        returns: pd.DataFrame,
        current_weights: pd.Series,
        book: pd.DataFrame,
        risk_free_rate: float,
        settings: OptimizerSettings,
        sector_caps: Mapping[str, float] | None = None,
) -> OptimizerResult:
        assets = list(covariance.index)

        if not assets:
                return OptimizerResult(False, pd.Series(dtype=float), method, "No optimisable assets.")

        current = current_weights.reindex(assets).fillna(0.0)
        bounds, bound_warnings = _asset_bounds(book, assets, settings)
        lower_sum = sum(bound[0] for bound in bounds)
        upper_sum = sum(bound[1] for bound in bounds)

        if lower_sum > 1.0 + 1e-9 or upper_sum < 1.0 - 1e-9:
                message = f"Infeasible individual bounds: sum(min)={lower_sum:.2%}, sum(max)={upper_sum:.2%}."
                return OptimizerResult(False, current, method, message)

        if method == "Current Portfolio":
                weights = _normalise_weights(current)
                report = _constraint_report(weights, current, expected_returns, covariance, book, settings, sector_caps)
                return OptimizerResult(True, weights, method, "Current weights retained.", constraint_report=report)

        if method == "Hierarchical Risk Parity":
                if not settings.long_only:
                        return OptimizerResult(False, current, method, "HRP is restricted to long-only mode in this implementation.")
                raw = hierarchical_risk_parity(covariance)
                weights = _apply_fixed_cash_to_heuristic(
                        raw, current, book, assets, bounds, settings.fix_cash_weight
                )
                report = _constraint_report(weights, current, expected_returns, covariance, book, settings, sector_caps)
                success = bool(report["Pass"].all())
                return OptimizerResult(success, weights, method, "HRP allocation computed." if success else "HRP computed but one or more constraints are not satisfied.", constraint_report=report)

        if method in {"Equal Weight", "Inverse Volatility"}:
                raw = _heuristic_weights(method, covariance, expected_returns)
                weights = _apply_fixed_cash_to_heuristic(
                        raw, current, book, assets, bounds, settings.fix_cash_weight
                )
                report = _constraint_report(weights, current, expected_returns, covariance, book, settings, sector_caps)
                success = bool(report["Pass"].all())
                return OptimizerResult(success, weights, method, "Heuristic allocation computed." if success else "Heuristic allocation violates at least one active constraint.", constraint_report=report)

        if not SCIPY_AVAILABLE:
                fallback = _heuristic_weights("Minimum Variance", covariance, expected_returns)
                weights = _apply_fixed_cash_to_heuristic(
                        fallback, current, book, assets, bounds, settings.fix_cash_weight
                )
                report = _constraint_report(weights, current, expected_returns, covariance, book, settings, sector_caps)
                return OptimizerResult(
                        False,
                        weights,
                        method,
                        f"SciPy unavailable ({SCIPY_IMPORT_ERROR}). A minimum-variance heuristic is shown as fallback.",
                        constraint_report=report,
                )

        mu = expected_returns.reindex(assets).fillna(0.0).values
        cov = covariance.loc[assets, assets].values
        return_matrix = returns.reindex(columns=assets).dropna(how="any").values
        current_array = current.values
        initial = _bounded_initial_weights(current, assets, bounds)
        asset_vols = np.sqrt(np.clip(np.diag(cov), EPS, None))

        if method == "Minimum Variance":
                objective = lambda w: float(w.T @ cov @ w)
        elif method == "Maximum Sharpe":
                objective = lambda w: -_safe_div(float(w @ mu) - risk_free_rate, _portfolio_vol_array(w, cov), default=-1e6)
        elif method == "Maximum Diversification":
                objective = lambda w: -_safe_div(float(np.abs(w) @ asset_vols), _portfolio_vol_array(w, cov), default=-1e6)
        elif method == "Risk Parity":
                def objective(w: np.ndarray) -> float:
                        vol = _portfolio_vol_array(w, cov)
                        if vol < EPS:
                                return 1e6
                        component = w * (cov @ w) / vol
                        target = np.repeat(vol / len(w), len(w))
                        return float(np.square(component - target).sum())
        elif method == "Minimum CVaR":
                alpha = float(np.clip(settings.cvar_alpha, 0.80, 0.995))

                def objective(w: np.ndarray) -> float:
                        if return_matrix.size == 0:
                                return 1e6
                        portfolio_losses = -(return_matrix @ w)
                        quantile = np.quantile(portfolio_losses, alpha)
                        tail = portfolio_losses[portfolio_losses >= quantile]
                        return float(tail.mean()) if len(tail) else float(quantile)
        else:
                objective = lambda w: float(w.T @ cov @ w)

        constraints: list[dict[str, Any]] = [
                {"type": "eq", "fun": lambda w: float(np.sum(w) - 1.0)},
                {"type": "ineq", "fun": lambda w: float(settings.gross_limit - np.sum(np.abs(w)))},
        ]

        if settings.fix_cash_weight:
                cash_assets = _cash_assets(book, assets)
                cash_indices = np.array([assets.index(asset) for asset in cash_assets], dtype=int)
                if len(cash_indices):
                        fixed_cash_total = float(current.reindex(cash_assets).fillna(0.0).sum())
                        constraints.append(
                                {
                                        "type": "eq",
                                        "fun": lambda w, idx=cash_indices, target=fixed_cash_total: float(np.sum(w[idx]) - target),
                                }
                        )

        if settings.turnover_limit is not None:
                turnover_limit = float(settings.turnover_limit)
                constraints.append({"type": "ineq", "fun": lambda w, limit=turnover_limit: float(limit - 0.5 * np.sum(np.abs(w - current_array)))})

        if settings.minimum_expected_return is not None:
                minimum_return = float(settings.minimum_expected_return)
                constraints.append({"type": "ineq", "fun": lambda w, target=minimum_return: float(w @ mu - target)})

        if settings.maximum_volatility is not None:
                maximum_volatility = float(settings.maximum_volatility)
                constraints.append({"type": "ineq", "fun": lambda w, limit=maximum_volatility: float(limit - _portfolio_vol_array(w, cov))})

        if sector_caps:
                sector_map = book.set_index("Ticker")["Sector"]
                for sector, cap in sector_caps.items():
                        indices = np.array([i for i, asset in enumerate(assets) if str(sector_map.get(asset, "Unclassified")) == str(sector)], dtype=int)
                        if len(indices) == 0:
                                continue
                        if settings.long_only:
                                constraints.append({"type": "ineq", "fun": lambda w, idx=indices, limit=float(cap): float(limit - np.sum(w[idx]))})
                        else:
                                constraints.append({"type": "ineq", "fun": lambda w, idx=indices, limit=float(cap): float(limit - np.sum(np.abs(w[idx])))})

        result = minimize(
                objective,
                initial,
                method="SLSQP",
                bounds=bounds,
                constraints=constraints,
                options={"maxiter": 1000, "ftol": 1e-10, "disp": False},
        )

        weights = pd.Series(result.x if result.x is not None else initial, index=assets, dtype=float)
        report = _constraint_report(weights, current, expected_returns, covariance, book, settings, sector_caps)
        feasible = bool(report["Pass"].all())
        success = bool(result.success and feasible)
        message_parts = [str(result.message)]
        if bound_warnings:
                message_parts.extend(bound_warnings)
        if result.success and not feasible:
                message_parts.append("Numerical solution returned, but the post-trade constraint audit failed.")

        return OptimizerResult(
                success=success,
                weights=weights,
                method=method,
                message=" | ".join(message_parts),
                objective_value=_safe_float(result.fun),
                iterations=int(result.nit) if getattr(result, "nit", None) is not None else None,
                constraint_report=report,
        )


# =============================================================================
# REBALANCING / ATTRIBUTION / STRESS
# =============================================================================

def build_rebalancing_table(
        current_book: pd.DataFrame,
        current_weights: pd.Series,
        target_weights: pd.Series,
        nav: float,
        settings: OptimizerSettings,
) -> pd.DataFrame:
        work = current_book.set_index("Ticker").copy()
        assets = list(dict.fromkeys(list(current_weights.index) + list(target_weights.index)))
        rows = []

        for ticker in assets:
                current_weight = float(current_weights.get(ticker, 0.0))
                target_weight = float(target_weights.get(ticker, 0.0))
                price = _safe_float(work.at[ticker, "Latest Price"] if ticker in work.index else np.nan)
                current_value = current_weight * nav
                target_value_raw = target_weight * nav
                weight_delta = target_weight - current_weight
                cost_bps = _safe_float(work.at[ticker, "Cost bps"] if ticker in work.index else 10.0, 10.0) or 0.0
                lot_size = _safe_float(work.at[ticker, "Lot Size"] if ticker in work.index else 1.0, 1.0) or 1.0

                trade_value_raw = target_value_raw - current_value
                no_trade = abs(weight_delta) < settings.no_trade_band or abs(trade_value_raw) < settings.minimum_trade_value

                if no_trade:
                        target_value = current_value
                        target_weight_executable = current_weight
                        trade_value = 0.0
                else:
                        target_value = target_value_raw
                        target_weight_executable = target_weight
                        trade_value = trade_value_raw

                if price is not None and abs(price) > EPS:
                        raw_target_quantity = target_value / price
                        if _is_cash(ticker, work.at[ticker, "Asset Class"] if ticker in work.index else None):
                                target_quantity = raw_target_quantity
                        else:
                                target_quantity = round(raw_target_quantity / lot_size) * lot_size
                        current_quantity = _safe_float(work.at[ticker, "Quantity Resolved"] if ticker in work.index else 0.0, 0.0) or 0.0
                        trade_quantity = target_quantity - current_quantity
                        executable_trade_value = trade_quantity * price
                        executable_target_value = target_quantity * price
                        executable_target_weight = executable_target_value / nav if nav > EPS else np.nan
                else:
                        current_quantity = _safe_float(work.at[ticker, "Quantity Resolved"] if ticker in work.index else 0.0, 0.0) or 0.0
                        target_quantity = np.nan
                        trade_quantity = np.nan
                        executable_trade_value = trade_value
                        executable_target_value = target_value
                        executable_target_weight = target_weight_executable

                estimated_cost = abs(executable_trade_value) * cost_bps / 10_000.0
                adv20 = _safe_float(work.at[ticker, "ADV20 Value"] if ticker in work.index else np.nan)
                adv_participation = abs(executable_trade_value) / adv20 if adv20 not in [None, 0] else np.nan

                if executable_trade_value > settings.minimum_trade_value:
                        action = "BUY"
                elif executable_trade_value < -settings.minimum_trade_value:
                        action = "SELL"
                else:
                        action = "HOLD"

                rows.append(
                        {
                                "Ticker": ticker,
                                "Action": action,
                                "Current Weight": current_weight,
                                "Target Weight": target_weight,
                                "Executable Weight": executable_target_weight,
                                "Weight Delta": target_weight - current_weight,
                                "Current Quantity": current_quantity,
                                "Target Quantity": target_quantity,
                                "Trade Quantity": trade_quantity,
                                "Latest Price": price,
                                "Trade Value": executable_trade_value,
                                "Estimated Cost": estimated_cost,
                                "Cost bps": cost_bps,
                                "ADV20 Participation": adv_participation,
                                "No-Trade Band Applied": no_trade,
                        }
                )

        table = pd.DataFrame(rows)
        if not table.empty:
                table = table.sort_values("Trade Value", key=lambda series: series.abs(), ascending=False)
        return table


def static_attribution(
        returns: pd.DataFrame,
        weights: pd.Series,
        book: pd.DataFrame,
) -> tuple[pd.DataFrame, dict[str, pd.DataFrame]]:
        if returns.empty:
                return pd.DataFrame(), {}

        aligned_weights = weights.reindex(returns.columns).fillna(0.0)
        cumulative_asset_returns = (1.0 + returns).prod() - 1.0
        arithmetic_contribution = returns.mul(aligned_weights, axis=1).sum(axis=0)

        table = pd.DataFrame(
                {
                        "Ticker": returns.columns,
                        "Weight": aligned_weights.values,
                        "Cumulative Asset Return": cumulative_asset_returns.reindex(returns.columns).values,
                        "Arithmetic Contribution": arithmetic_contribution.reindex(returns.columns).values,
                }
        )

        metadata = book.set_index("Ticker")
        for column in ["Asset Class", "Sector", "Currency", "Strategy"]:
                table[column] = table["Ticker"].map(metadata[column]).fillna("Unclassified")

        grouped: dict[str, pd.DataFrame] = {}
        for column in ["Asset Class", "Sector", "Currency", "Strategy"]:
                grouped[column] = (
                        table.groupby(column, dropna=False)
                        .agg(
                                Weight=("Weight", "sum"),
                                Contribution=("Arithmetic Contribution", "sum"),
                                Positions=("Ticker", "count"),
                        )
                        .reset_index()
                        .sort_values("Contribution", ascending=False)
                )

        return table.sort_values("Arithmetic Contribution", ascending=False), grouped


def historical_stress_results(
        price_df: pd.DataFrame,
        current_weights: pd.Series,
        target_weights: pd.Series,
) -> pd.DataFrame:
        rows = []

        for scenario, (start, end) in HISTORICAL_SCENARIOS.items():
                scenario_prices = price_df.loc[(price_df.index >= pd.Timestamp(start)) & (price_df.index <= pd.Timestamp(end))]
                if len(scenario_prices) < 2:
                        rows.append({"Scenario": scenario, "Start": start, "End": end, "Current Portfolio": np.nan, "Target Portfolio": np.nan, "Coverage": 0.0})
                        continue

                asset_returns = scenario_prices.iloc[-1] / scenario_prices.iloc[0] - 1.0
                for asset in set(current_weights.index) | set(target_weights.index):
                        if str(asset).upper().strip() in CASH_ALIASES and asset not in asset_returns.index:
                                asset_returns.loc[asset] = 0.0
                current_assets = [asset for asset in current_weights.index if asset in asset_returns.index]
                target_assets = [asset for asset in target_weights.index if asset in asset_returns.index]
                current_result = float(current_weights.reindex(current_assets).fillna(0.0) @ asset_returns.reindex(current_assets).fillna(0.0))
                target_result = float(target_weights.reindex(target_assets).fillna(0.0) @ asset_returns.reindex(target_assets).fillna(0.0))
                total_required = max(len(set(current_weights.index) | set(target_weights.index)), 1)
                coverage = len(set(current_assets) | set(target_assets)) / total_required

                rows.append({"Scenario": scenario, "Start": start, "End": end, "Current Portfolio": current_result, "Target Portfolio": target_result, "Coverage": coverage})

        return pd.DataFrame(rows)


def hypothetical_stress_results(
        book: pd.DataFrame,
        current_weights: pd.Series,
        target_weights: pd.Series,
        custom_shocks: pd.DataFrame | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
        metadata = book.set_index("Ticker")
        assets = list(dict.fromkeys(list(current_weights.index) + list(target_weights.index)))
        asset_class_map = metadata["Asset Class"].to_dict()

        scenario_rows = []
        detail_rows = []

        scenarios = dict(HYPOTHETICAL_SCENARIOS)
        if isinstance(custom_shocks, pd.DataFrame) and {"Ticker", "Shock"}.issubset(custom_shocks.columns):
                custom_map = {
                        str(row["Ticker"]).upper().strip(): float(row["Shock"])
                        for _, row in custom_shocks.iterrows()
                        if str(row.get("Ticker", "")).strip() and _safe_float(row.get("Shock")) is not None
                }
                if custom_map:
                        scenarios["Custom ticker shock"] = custom_map

        for scenario_name, shock_map in scenarios.items():
                current_pnl = 0.0
                target_pnl = 0.0

                for asset in assets:
                        asset_class = str(asset_class_map.get(asset, "Other"))
                        row = metadata.loc[asset] if asset in metadata.index else pd.Series(dtype=object)
                        sector = str(row.get("Sector", ""))
                        name = str(row.get("Name", ""))
                        bucket = _asset_class_bucket(asset, asset_class, sector, name)
                        beta_override = _safe_float(row.get("Beta Override"))
                        duration = _safe_float(row.get("Duration"), 0.0) or 0.0
                        yield_shock = HYPOTHETICAL_YIELD_SHOCKS.get(scenario_name)

                        if scenario_name == "Custom ticker shock":
                                shock = float(shock_map.get(asset, 0.0))
                        else:
                                shock = float(shock_map.get(bucket, shock_map.get("Other", 0.0)))

                                # First-order mechanical sensitivities. They are intentionally
                                # transparent and remain editable through the Portfolio Book.
                                if bucket == "Bond" and duration > 0 and yield_shock is not None:
                                        shock = float(np.clip(-duration * yield_shock, -0.80, 0.80))
                                elif bucket in {"Equity", "Crypto", "Commodity"} and beta_override is not None:
                                        shock = float(np.clip(shock * beta_override, -1.00, 5.00))

                        current_contribution = float(current_weights.get(asset, 0.0)) * shock
                        target_contribution = float(target_weights.get(asset, 0.0)) * shock
                        current_pnl += current_contribution
                        target_pnl += target_contribution

                        detail_rows.append(
                                {
                                        "Scenario": scenario_name,
                                        "Ticker": asset,
                                        "Asset Class": asset_class,
                                        "Stress Bucket": bucket,
                                        "Shock": shock,
                                        "Yield Shock": yield_shock if scenario_name != "Custom ticker shock" else np.nan,
                                        "Duration Used": duration if bucket == "Bond" else np.nan,
                                        "Beta Used": beta_override if bucket in {"Equity", "Crypto", "Commodity"} else np.nan,
                                        "Current Weight": float(current_weights.get(asset, 0.0)),
                                        "Target Weight": float(target_weights.get(asset, 0.0)),
                                        "Current Contribution": current_contribution,
                                        "Target Contribution": target_contribution,
                                }
                        )

                scenario_rows.append({"Scenario": scenario_name, "Current Portfolio": current_pnl, "Target Portfolio": target_pnl, "Difference": target_pnl - current_pnl})

        return pd.DataFrame(scenario_rows), pd.DataFrame(detail_rows)


# =============================================================================
# GOVERNANCE / MODEL BUILD
# =============================================================================

def build_governance_report(
        book: pd.DataFrame,
        market_snapshot: pd.DataFrame,
        returns: pd.DataFrame,
        covariance: pd.DataFrame,
        data_diagnostics: pd.DataFrame,
        coverage_table: pd.DataFrame,
        settings: PortfolioSettings,
) -> tuple[pd.DataFrame, list[str], dict[str, Any]]:
        warnings: list[str] = []
        rows = []

        active_assets = len(book)
        return_assets = len(returns.columns)
        observations = len(returns)
        latest_dates = pd.to_datetime(market_snapshot["Latest Date"], errors="coerce", utc=True).dt.tz_convert(None).dropna()
        staleness_days = np.nan

        if not latest_dates.empty:
                today = pd.Timestamp.now(tz="UTC").tz_localize(None).normalize()
                staleness_days = int((today - latest_dates.min().normalize()).days)

        condition_number = np.nan
        minimum_eigenvalue = np.nan
        if not covariance.empty:
                eigenvalues = np.linalg.eigvalsh(covariance.values)
                minimum_eigenvalue = float(eigenvalues.min())

                # Deterministic cash accrual has near-zero variance and would make the full
                # matrix condition number look unstable even when the risky sleeve is sound.
                diagonal = np.diag(covariance.values)
                risky_mask = diagonal > 1e-8
                stable_block = covariance.values[np.ix_(risky_mask, risky_mask)]
                if stable_block.size:
                        condition_number = float(np.linalg.cond(stable_block))

        checks = [
                ("Active positions", active_assets, active_assets >= 2, "At least two positions are recommended for portfolio optimisation."),
                ("Assets with return history", return_assets, return_assets >= 2, "At least two risky assets require usable return history."),
                ("Aligned observations", observations, observations >= MIN_OBSERVATIONS, f"Minimum target: {MIN_OBSERVATIONS} aligned observations."),
                ("Minimum covariance eigenvalue", minimum_eigenvalue, pd.notna(minimum_eigenvalue) and minimum_eigenvalue > 0.0, "Covariance is repaired to positive semi-definite form."),
                ("Covariance condition number", condition_number, pd.notna(condition_number) and condition_number < 1e8, "Very high values imply unstable optimisation."),
                ("Oldest latest quote staleness (days)", staleness_days, pd.notna(staleness_days) and staleness_days <= 7, "Large values may indicate stale or unavailable symbols."),
                ("SciPy optimisation engine", SCIPY_AVAILABLE, SCIPY_AVAILABLE, "Advanced constrained optimisers require SciPy."),
        ]

        for check, value, passed, detail in checks:
                rows.append({"Check": check, "Value": value, "Status": "PASS" if passed else "REVIEW", "Detail": detail})
                if not passed:
                        warnings.append(f"{check}: {detail}")

        unavailable = data_diagnostics.loc[data_diagnostics.get("Status", pd.Series(dtype=str)).eq("KO"), "Ticker"].tolist() if not data_diagnostics.empty else []
        if unavailable:
                warnings.append(f"Unavailable market data: {', '.join(unavailable)}")

        dropped = coverage_table.loc[~coverage_table.get("Retained", pd.Series(dtype=bool)), "Ticker"].tolist() if not coverage_table.empty else []
        if dropped:
                warnings.append(f"Dropped by return coverage filter: {', '.join(dropped)}")

        manifest = {
                "generated_at_utc": datetime.now(timezone.utc).isoformat(),
                "module": "Portfolio Lab v1",
                "book_fingerprint": _book_fingerprint(book),
                "settings": asdict(settings),
                "active_assets": active_assets,
                "return_assets": return_assets,
                "observations": observations,
                "covariance_condition_number": condition_number,
                "minimum_covariance_eigenvalue": minimum_eigenvalue,
                "scipy_available": SCIPY_AVAILABLE,
                "warnings": warnings,
        }

        return pd.DataFrame(rows), warnings, manifest


def build_portfolio_model(
        book: pd.DataFrame,
        settings: PortfolioSettings,
        bl_views: pd.DataFrame | None = None,
) -> dict[str, Any]:
        clean_book = _clean_book(book)
        if clean_book.empty:
                raise ValueError("Portfolio Book is empty.")

        risky_book = clean_book.loc[~clean_book.apply(lambda row: _is_cash(row["Ticker"], row["Asset Class"]), axis=1)].copy()
        cash_tickers = clean_book.loc[clean_book.apply(lambda row: _is_cash(row["Ticker"], row["Asset Class"]), axis=1), "Ticker"].tolist()
        risky_tickers = risky_book["Ticker"].tolist()

        data = download_portfolio_market_data(
                tickers=tuple(risky_tickers),
                cash_tickers=tuple(cash_tickers),
                period=settings.period,
                interval=settings.interval,
                benchmark=settings.benchmark,
        )
        price_df = data["prices"]
        volume_df = data["volumes"]
        market_snapshot = latest_market_snapshot(clean_book, price_df, volume_df)
        current_book, current_weights_all, nav, book_warnings = build_current_portfolio(clean_book, market_snapshot, settings)

        returns, coverage_table = prepare_return_matrix(price_df, risky_tickers, settings.min_coverage)
        if returns.empty or len(returns.columns) < 1:
                raise ValueError("Insufficient aligned return history. At least one risky asset is required.")

        # Cash is represented as a deterministic daily accrual at the configured
        # risk-free rate. This keeps cash inside allocation, risk and rebalancing
        # instead of silently forcing the optimiser to invest the full NAV in risky assets.
        cash_daily_return = (1.0 + settings.risk_free_rate) ** (1.0 / TRADING_DAYS) - 1.0
        for cash_ticker in cash_tickers:
                returns[cash_ticker] = cash_daily_return
                coverage_table = pd.concat(
                        [
                                coverage_table,
                                pd.DataFrame(
                                        [
                                                {
                                                        "Ticker": cash_ticker,
                                                        "Valid Returns": len(returns),
                                                        "Coverage": 1.0,
                                                        "Retained": True,
                                                }
                                        ]
                                ),
                        ],
                        ignore_index=True,
                )

        if len(returns.columns) < 2:
                raise ValueError("Portfolio Lab requires at least two positions, including cash if applicable.")

        optimisable_assets = list(returns.columns)
        current_weights = current_weights_all.reindex(optimisable_assets).fillna(0.0)

        covariance = estimate_covariance(
                returns,
                model=settings.covariance_model,
                shrinkage=settings.shrinkage,
                ewma_lambda=settings.ewma_lambda,
        )
        expected_returns = expected_returns_from_history(
                returns,
                model=settings.expected_return_model,
                ewma_lambda=settings.ewma_lambda,
        )
        for cash_ticker in cash_tickers:
                if cash_ticker in expected_returns.index:
                        expected_returns.loc[cash_ticker] = settings.risk_free_rate
        expected_returns = apply_expected_return_overrides(expected_returns, clean_book)

        bl_audit = pd.DataFrame()
        if settings.expected_return_model == "Black-Litterman":
                risky_market_weights = current_weights.copy()
                if abs(float(risky_market_weights.sum())) < EPS:
                        risky_market_weights[:] = 1.0 / len(risky_market_weights)
                else:
                        risky_market_weights = risky_market_weights / float(risky_market_weights.sum())
                expected_returns, bl_audit = black_litterman_posterior(
                        covariance,
                        market_weights=risky_market_weights,
                        views=bl_views if bl_views is not None else pd.DataFrame(),
                )
                expected_returns = apply_expected_return_overrides(expected_returns, clean_book)

        benchmark_returns = pd.Series(dtype=float)
        if settings.benchmark in price_df.columns:
                benchmark_returns = price_df[settings.benchmark].pct_change(fill_method=None).dropna()

        current_metrics = compute_portfolio_metrics(
                returns,
                current_weights,
                expected_returns,
                settings.risk_free_rate,
                benchmark_returns,
        )
        current_metrics["Diversification Ratio"] = diversification_ratio(current_weights, covariance)
        current_risk = risk_decomposition(current_weights, covariance)

        governance, governance_warnings, manifest = build_governance_report(
                clean_book,
                market_snapshot,
                returns,
                covariance,
                data["diagnostics"],
                coverage_table,
                settings,
        )

        return {
                "settings": settings,
                "book_fingerprint": _book_fingerprint(clean_book),
                "book": clean_book,
                "current_book": current_book,
                "current_weights_all": current_weights_all,
                "current_weights": current_weights,
                "nav": nav,
                "prices": price_df,
                "volumes": volume_df,
                "returns": returns,
                "covariance": covariance,
                "correlation": returns.corr(),
                "expected_returns": expected_returns,
                "benchmark_returns": benchmark_returns,
                "current_metrics": current_metrics,
                "current_risk": current_risk,
                "data_diagnostics": data["diagnostics"],
                "coverage_table": coverage_table,
                "market_snapshot": market_snapshot,
                "governance": governance,
                "governance_warnings": list(dict.fromkeys(book_warnings + governance_warnings)),
                "manifest": manifest,
                "black_litterman_audit": bl_audit,
                "optimizer": None,
                "target_weights": current_weights.copy(),
                "target_metrics": current_metrics.copy(),
                "target_risk": current_risk.copy(),
                "rebalancing": pd.DataFrame(),
        }


def attach_optimisation_to_model(
        model: dict[str, Any],
        optimizer_settings: OptimizerSettings,
        sector_caps: Mapping[str, float] | None,
) -> dict[str, Any]:
        result = optimise_portfolio(
                method=optimizer_settings.method,
                expected_returns=model["expected_returns"],
                covariance=model["covariance"],
                returns=model["returns"],
                current_weights=model["current_weights"],
                book=model["book"],
                risk_free_rate=model["settings"].risk_free_rate,
                settings=optimizer_settings,
                sector_caps=sector_caps,
        )

        target_weights = result.weights.reindex(model["returns"].columns).fillna(0.0)
        target_metrics = compute_portfolio_metrics(
                model["returns"],
                target_weights,
                model["expected_returns"],
                model["settings"].risk_free_rate,
                model["benchmark_returns"],
        )
        target_metrics["Diversification Ratio"] = diversification_ratio(target_weights, model["covariance"])
        target_risk = risk_decomposition(target_weights, model["covariance"])
        rebalancing = build_rebalancing_table(
                model["current_book"],
                model["current_weights"],
                target_weights,
                model["nav"],
                optimizer_settings,
        )

        updated = dict(model)
        updated.update(
                {
                        "optimizer": result,
                        "optimizer_settings": optimizer_settings,
                        "sector_caps": dict(sector_caps or {}),
                        "target_weights": target_weights,
                        "target_metrics": target_metrics,
                        "target_risk": target_risk,
                        "rebalancing": rebalancing,
                }
        )
        return updated


