def _metrics_comparison_table(current: Mapping[str, Any], target: Mapping[str, Any]) -> pd.DataFrame:
        percent_metrics = {
                "Expected Return",
                "Historical Return",
                "Historical Arithmetic Return",
                "Volatility",
                "Max Drawdown",
                "VaR 95% (1D)",
                "CVaR 95% (1D)",
                "Tracking Error",
                "Gross Exposure",
                "Net Exposure",
        }
        rows = []
        for metric in current.keys():
                current_value = _safe_float(current.get(metric))
                target_value = _safe_float(target.get(metric))
                rows.append(
                        {
                                "Metric": metric,
                                "Current": current_value,
                                "Target": target_value,
                                "Delta": None if current_value is None or target_value is None else target_value - current_value,
                                "Format": "percent" if metric in percent_metrics else "number",
                        }
                )
        return pd.DataFrame(rows)


def _format_metrics_table(table: pd.DataFrame) -> pd.DataFrame:
        """Return a display-only metrics table without mutating numeric dtypes.

        Pandas 3.x no longer allows assigning formatted strings such as ``10.73%``
        into columns inferred as ``float64``.    Building a fresh object-typed table is
        both explicit and stable across pandas versions.
        """
        if table is None or table.empty:
                return pd.DataFrame(columns=["Metric", "Current", "Target", "Delta"])

        rows: list[dict[str, Any]] = []

        for _, row in table.iterrows():
                value_format = str(row.get("Format", "number"))
                formatter = _fmt_pct if value_format == "percent" else _fmt_num
                delta = _safe_float(row.get("Delta"))

                if delta is None:
                        delta_display = "N/A"
                elif value_format == "percent":
                        delta_display = f"{delta:+.2%}"
                else:
                        delta_display = f"{delta:+.2f}"

                rows.append(
                        {
                                "Metric": row.get("Metric", "N/A"),
                                "Current": formatter(row.get("Current")),
                                "Target": formatter(row.get("Target")),
                                "Delta": delta_display,
                        }
                )

        return pd.DataFrame(rows, columns=["Metric", "Current", "Target", "Delta"])


def _allocation_figure(current: pd.Series, target: pd.Series, title: str) -> go.Figure:
        assets = list(dict.fromkeys(list(current.index) + list(target.index)))
        fig = go.Figure()
        fig.add_trace(go.Bar(name="Current", x=assets, y=current.reindex(assets).fillna(0.0)))
        fig.add_trace(go.Bar(name="Target", x=assets, y=target.reindex(assets).fillna(0.0)))
        fig.update_layout(
                title=title,
                barmode="group",
                height=430,
                yaxis_tickformat=".0%",
                xaxis_title="Asset",
                yaxis_title="Weight",
                margin=dict(l=20, r=20, t=60, b=30),
        )
        return fig


def _risk_contribution_figure(current: pd.DataFrame, target: pd.DataFrame) -> go.Figure:
        current_map = current.set_index("Ticker")["Risk Contribution %"] if not current.empty else pd.Series(dtype=float)
        target_map = target.set_index("Ticker")["Risk Contribution %"] if not target.empty else pd.Series(dtype=float)
        assets = list(dict.fromkeys(list(current_map.index) + list(target_map.index)))
        fig = go.Figure()
        fig.add_trace(go.Bar(name="Current", x=assets, y=current_map.reindex(assets).fillna(0.0)))
        fig.add_trace(go.Bar(name="Target", x=assets, y=target_map.reindex(assets).fillna(0.0)))
        fig.update_layout(
                title="Component Risk Contribution",
                barmode="group",
                height=430,
                yaxis_tickformat=".0%",
                xaxis_title="Asset",
                yaxis_title="Share of portfolio volatility",
                margin=dict(l=20, r=20, t=60, b=30),
        )
        return fig


def _equity_curve_figure(returns: pd.DataFrame, current: pd.Series, target: pd.Series) -> go.Figure:
        current_series = portfolio_return_series(returns, current)
        target_series = portfolio_return_series(returns, target)
        current_curve = (1.0 + current_series).cumprod()
        target_curve = (1.0 + target_series).cumprod()
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=current_curve.index, y=current_curve, mode="lines", name="Current"))
        fig.add_trace(go.Scatter(x=target_curve.index, y=target_curve, mode="lines", name="Target"))
        fig.update_layout(
                title="Historical Static-Weight Growth of 1",
                height=460,
                xaxis_title="Date",
                yaxis_title="Growth of 1",
                hovermode="x unified",
                margin=dict(l=20, r=20, t=60, b=30),
        )
        return fig


def _correlation_figure(correlation: pd.DataFrame) -> go.Figure:
        fig = go.Figure(
                data=go.Heatmap(
                        z=correlation.values,
                        x=correlation.columns,
                        y=correlation.index,
                        zmin=-1,
                        zmax=1,
                        colorbar=dict(title="Correlation"),
                        hovertemplate="%{y} / %{x}<br>Correlation: %{z:.2f}<extra></extra>",
                )
        )
        fig.update_layout(title="Return Correlation Matrix", height=560, margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _efficient_frontier_points(
        expected_returns: pd.Series,
        covariance: pd.DataFrame,
        samples: int = 3000,
        seed: int = 42,
) -> pd.DataFrame:
        if covariance.empty:
                return pd.DataFrame()
        rng = np.random.default_rng(seed)
        assets = list(covariance.index)
        raw = rng.dirichlet(np.ones(len(assets)), size=samples)
        mu = expected_returns.reindex(assets).fillna(0.0).values
        cov = covariance.values
        expected = raw @ mu
        volatility = np.sqrt(np.einsum("ij,jk,ik->i", raw, cov, raw))
        sharpe = np.divide(expected, volatility, out=np.full_like(expected, np.nan), where=volatility > EPS)
        return pd.DataFrame({"Expected Return": expected, "Volatility": volatility, "Sharpe": sharpe})


def _frontier_figure(
        frontier: pd.DataFrame,
        current_metrics: Mapping[str, Any],
        target_metrics: Mapping[str, Any],
) -> go.Figure:
        fig = go.Figure()
        if not frontier.empty:
                fig.add_trace(
                        go.Scatter(
                                x=frontier["Volatility"],
                                y=frontier["Expected Return"],
                                mode="markers",
                                marker=dict(size=5, color=frontier["Sharpe"], colorscale="Viridis", showscale=True, colorbar=dict(title="Sharpe")),
                                name="Feasible random portfolios",
                                hovertemplate="Vol: %{x:.2%}<br>Return: %{y:.2%}<extra></extra>",
                        )
                )
        fig.add_trace(go.Scatter(x=[current_metrics.get("Volatility")], y=[current_metrics.get("Expected Return")], mode="markers+text", text=["Current"], textposition="top center", marker=dict(size=14), name="Current"))
        fig.add_trace(go.Scatter(x=[target_metrics.get("Volatility")], y=[target_metrics.get("Expected Return")], mode="markers+text", text=["Target"], textposition="top center", marker=dict(size=14), name="Target"))
        fig.update_layout(
                title="Risk / Expected Return Map",
                height=520,
                xaxis_title="Annualised volatility",
                yaxis_title="Expected return",
                xaxis_tickformat=".0%",
                yaxis_tickformat=".0%",
                margin=dict(l=20, r=20, t=60, b=30),
        )
        return fig


