def _render_top_metrics(model: dict[str, Any]) -> None:
        current = model["current_metrics"]
        target = model["target_metrics"]
        optimizer = model.get("optimizer")

        cols = st.columns(7)
        cols[0].metric("NAV", _fmt_money(model["nav"]))
        cols[1].metric("Expected Return", _fmt_pct(target.get("Expected Return")), delta=None if target.get("Expected Return") is None or current.get("Expected Return") is None else _fmt_pct(target.get("Expected Return") - current.get("Expected Return")))
        cols[2].metric("Volatility", _fmt_pct(target.get("Volatility")), delta=None if target.get("Volatility") is None or current.get("Volatility") is None else _fmt_pct(target.get("Volatility") - current.get("Volatility")), delta_color="inverse")
        cols[3].metric("Sharpe", _fmt_num(target.get("Sharpe")), delta=None if target.get("Sharpe") is None or current.get("Sharpe") is None else _fmt_num(target.get("Sharpe") - current.get("Sharpe")))
        cols[4].metric("CVaR 95%", _fmt_pct(target.get("CVaR 95% (1D)")), delta=None if target.get("CVaR 95% (1D)") is None or current.get("CVaR 95% (1D)") is None else _fmt_pct(target.get("CVaR 95% (1D)") - current.get("CVaR 95% (1D)")), delta_color="inverse")
        cols[5].metric("Effective Bets", _fmt_num(target.get("Effective Bets")), delta=None if target.get("Effective Bets") is None or current.get("Effective Bets") is None else _fmt_num(target.get("Effective Bets") - current.get("Effective Bets")))
        status = "Not run" if optimizer is None else ("PASS" if optimizer.success else "REVIEW")
        cols[6].metric("Optimizer", status)


