def _render_book_editor(ticker: str | None) -> pd.DataFrame:
        state_key = "portfolio_lab_book_v1"
        nonce_key = "portfolio_lab_book_editor_nonce_v1"
        if state_key not in st.session_state:
                st.session_state[state_key] = _initial_book(ticker)
        if nonce_key not in st.session_state:
                st.session_state[nonce_key] = 0

        action_cols = st.columns([1, 1, 2, 2])
        if action_cols[0].button("Reset book", key="pl_reset_book", width="stretch"):
                st.session_state[state_key] = _initial_book(ticker)
                st.session_state[nonce_key] += 1
                st.session_state.pop("portfolio_lab_model_v1", None)
                st.rerun()
        if action_cols[1].button("Load demo", key="pl_load_demo", width="stretch", help="Loads a clearly labelled editable demonstration portfolio."):
                st.session_state[state_key] = DEMO_BOOK.copy()
                st.session_state[nonce_key] += 1
                st.session_state.pop("portfolio_lab_model_v1", None)
                st.rerun()

        uploaded = action_cols[2].file_uploader("Import Portfolio CSV", type=["csv"], key="pl_book_upload")
        action_cols[3].download_button(
                "Download CSV template",
                data=_book_template_csv(),
                file_name="portfolio_book_template.csv",
                mime="text/csv",
                width="stretch",
        )

        if uploaded is not None:
                upload_token = f"{uploaded.name}:{uploaded.size}"
                if st.session_state.get("portfolio_lab_upload_token") != upload_token:
                        try:
                                imported = pd.read_csv(uploaded)
                                st.session_state[state_key] = _clean_book(imported)
                                st.session_state[nonce_key] += 1
                                st.session_state.pop("portfolio_lab_model_v1", None)
                                st.session_state["portfolio_lab_upload_token"] = upload_token
                                st.success("Portfolio CSV imported. Review the fields before running analytics.")
                        except Exception as exc:
                                st.error(f"CSV import failed: {exc}")

        column_config = {
                "Active": st.column_config.CheckboxColumn("Active", default=True),
                "Ticker": st.column_config.TextColumn("Ticker", required=True),
                "Quantity": st.column_config.NumberColumn("Quantity", format="%.4f"),
                "Avg Cost": st.column_config.NumberColumn("Avg Cost", format="%.4f"),
                "Current Weight": st.column_config.NumberColumn("Current Weight", format="%.2f"),
                "Expected Return Override": st.column_config.NumberColumn("Expected Return Override", format="%.2f"),
                "Min Weight": st.column_config.NumberColumn("Min Weight", min_value=-2.0, max_value=2.0, format="%.2f"),
                "Max Weight": st.column_config.NumberColumn("Max Weight", min_value=0.0, max_value=2.0, format="%.2f"),
                "Cost bps": st.column_config.NumberColumn("Cost bps", min_value=0.0, format="%.1f"),
                "Lot Size": st.column_config.NumberColumn("Lot Size", min_value=0.000001, format="%.4f"),
                "Duration": st.column_config.NumberColumn("Duration", format="%.2f"),
                "Beta Override": st.column_config.NumberColumn("Beta Override", format="%.2f"),
        }

        edited = st.data_editor(
                st.session_state[state_key],
                width="stretch",
                height=430,
                num_rows="dynamic",
                hide_index=True,
                column_config=column_config,
                key=f"portfolio_lab_book_editor_v1_{st.session_state[nonce_key]}",
        )
        cleaned = _clean_book(edited)
        st.session_state[state_key] = edited
        return cleaned


def _render_settings_form() -> tuple[PortfolioSettings, bool]:
        with st.form("portfolio_lab_settings_form_v1"):
                row1 = st.columns(5)
                input_mode = row1[0].selectbox("Current portfolio input", ["Quantities", "Current Weights"], index=0)
                portfolio_nav = row1[1].number_input("Portfolio NAV (used in weight mode)", min_value=1.0, value=100_000.0, step=10_000.0)
                period = row1[2].selectbox("History", ["1y", "2y", "5y", "10y", "max"], index=2)
                benchmark = row1[3].text_input("Benchmark", value=DEFAULT_BENCHMARK).upper().strip()

                row2 = st.columns(5)
                risk_free_rate = row2[0].number_input("Risk-free rate", min_value=-0.10, max_value=0.30, value=0.02, step=0.005, format="%.3f")
                covariance_model = row2[1].selectbox("Covariance", ["Diagonal Shrinkage", "Sample", "EWMA"], index=0)
                shrinkage = row2[2].slider("Shrinkage", 0.0, 1.0, 0.25, 0.05)
                ewma_lambda = row2[3].slider("EWMA lambda", 0.80, 0.99, 0.94, 0.01)
                expected_return_model = row2[4].selectbox("Expected returns", ["Historical Geometric", "Historical Arithmetic", "EWMA", "Black-Litterman"], index=0)

                row3 = st.columns([2, 2, 1])
                min_coverage = row3[0].slider("Minimum return-history coverage", 0.50, 1.00, 0.80, 0.05)
                row3[1].caption("Black-Litterman views are configured below when that model is selected.")
                run = row3[2].form_submit_button("Run Portfolio Lab", type="primary", width="stretch")

        settings = PortfolioSettings(
                input_mode=input_mode,
                portfolio_nav=float(portfolio_nav),
                period=period,
                interval="1d",
                benchmark=benchmark or DEFAULT_BENCHMARK,
                risk_free_rate=float(risk_free_rate),
                covariance_model=covariance_model,
                shrinkage=float(shrinkage),
                ewma_lambda=float(ewma_lambda),
                expected_return_model=expected_return_model,
                min_coverage=float(min_coverage),
        )
        return settings, run


def _render_bl_views(book: pd.DataFrame, enabled: bool) -> pd.DataFrame:
        key = "portfolio_lab_bl_views_v1"
        default = pd.DataFrame(
                {
                        "Ticker": book["Ticker"].head(3).tolist(),
                        "View Return": [np.nan] * min(3, len(book)),
                        "Confidence": [0.50] * min(3, len(book)),
                }
        )
        if key not in st.session_state:
                st.session_state[key] = default

        if not enabled:
                return st.session_state[key]

        with st.expander("Black-Litterman absolute views", expanded=True):
                st.caption("View Return and Confidence are decimal inputs. Example: 0.08 = 8% annual expected return.")
                views = st.data_editor(
                        st.session_state[key],
                        num_rows="dynamic",
                        hide_index=True,
                        width="stretch",
                        column_config={
                                "Ticker": st.column_config.SelectboxColumn("Ticker", options=book["Ticker"].tolist(), required=True),
                                "View Return": st.column_config.NumberColumn("View Return", format="%.3f"),
                                "Confidence": st.column_config.NumberColumn("Confidence", min_value=0.01, max_value=0.99, format="%.2f"),
                        },
                        key="portfolio_lab_bl_views_editor_v1",
                )
                st.session_state[key] = views
                return views


