        if optimizer is not None:
                if optimizer.success:
                        st.success(f"{optimizer.method}: optimisation and post-trade constraint audit passed.")
                else:
                        st.warning(f"{optimizer.method}: {optimizer.message}")

        left, right = st.columns(2)
        left.plotly_chart(_allocation_figure(model["current_weights"], model["target_weights"], "Current vs Target Allocation"), width="stretch")
        right.plotly_chart(_risk_contribution_figure(model["current_risk"], model["target_risk"]), width="stretch")
        st.plotly_chart(_equity_curve_figure(model["returns"], model["current_weights"], model["target_weights"]), width="stretch")

