def render_portfolio_lab_v1(
        ticker: str | None = None,
        price_data: pd.DataFrame | None = None,
        analysis: dict[str, Any] | None = None,
) -> None:
        """Render Portfolio Lab inside the existing Quant Terminal router."""
        del price_data, analysis    # Multi-asset data are fetched inside the module.

        _inject_portfolio_css()
        _render_header()

        with st.expander("Portfolio Book & Model Settings", expanded=st.session_state.get("portfolio_lab_model_v1") is None):
                book = _render_book_editor(ticker)
                settings, run_model = _render_settings_form()
                bl_views = _render_bl_views(book, settings.expected_return_model == "Black-Litterman")

                if run_model:
                        try:
                                with st.spinner("Building portfolio market data, covariance and risk model..."):
                                        model = build_portfolio_model(book, settings, bl_views=bl_views)
                                st.session_state["portfolio_lab_model_v1"] = model
                                st.success("Portfolio model built. Review Governance before relying on optimisation outputs.")
                        except Exception as exc:
                                st.error(f"Portfolio model failed: {exc}")

        model = st.session_state.get("portfolio_lab_model_v1")
        if isinstance(model, dict):
                model.setdefault("manifest", {})["module"] = f"Portfolio Lab v{PORTFOLIO_LAB_VERSION}"
                model["manifest"]["version"] = PORTFOLIO_LAB_VERSION
        if not isinstance(model, dict):
                st.info("Configure the Portfolio Book, then click Run Portfolio Lab.")
                st.caption("The demonstration portfolio is never loaded automatically and is not presented as a real portfolio.")
                return

        current_fingerprint = _book_fingerprint(book)
        if model.get("book_fingerprint") != current_fingerprint:
                st.warning(
                        "Portfolio Book changed after the last model run. The analytics below still use the previous book; "
                        "run Portfolio Lab again before making a decision."
                )

        tabs = st.tabs(
                [
                        "Overview",
                        "Portfolio Book",
                        "Risk Decomposition",
                        "Optimizer",
                        "Rebalancing",
                        "Attribution",
                        "Stress Lab",
                        "Governance & Export",
                ]
        )

        with tabs[0]:
                _render_overview_tab(model)
        with tabs[1]:
                _render_book_tab(model)
        with tabs[2]:
                _render_risk_tab(model)
        with tabs[3]:
                model = _render_optimizer_tab(model)
        with tabs[4]:
                _render_rebalance_tab(model)
        with tabs[5]:
                _render_attribution_tab(model)
        with tabs[6]:
                _render_stress_tab(model)
        with tabs[7]:
                _render_governance_tab(model)


# Backward-compatible alias for a shorter import name.
render_portfolio_lab = render_portfolio_lab_v1


