def _utc_now_iso() -> str:
        return datetime.now(timezone.utc).isoformat()


def _normalise_signal_score(value: Any, direction: str | None = None) -> float:
        score = _safe_float(value, 0.0) or 0.0
        if abs(score) > 1.0:
                if abs(score) <= 100.0:
                        score /= 100.0
                else:
                        score = math.tanh(score / 100.0)
        score = float(np.clip(score, -1.0, 1.0))

        direction_text = str(direction or "").strip().lower()
        if direction_text in {"sell", "short", "bearish", "underweight", "negative"}:
                score = -abs(score or 1.0)
        elif direction_text in {"buy", "long", "bullish", "overweight", "positive"}:
                score = abs(score or 1.0)
        return score


def _direction_from_score(score: float) -> str:
        if score > 0.10:
                return "BUY"
        if score < -0.10:
                return "SELL"
        return "NEUTRAL"


def publish_terminal_signal(
        source: str,
        ticker: str,
        *,
        score: float | None = None,
        direction: str | None = None,
        expected_return: float | None = None,
        confidence: float = 0.50,
        horizon: str = "Medium",
        risk_multiplier: float = 1.0,
        notes: str = "",
        metadata: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
        """Publish a governed signal into the shared terminal signal bus.

        Other Quant Terminal modules can call this function after computing their
        own output.    The bus stores data only; it does not execute user code and it
        does not automatically trade.
        """
        record = {
                "Timestamp": _utc_now_iso(),
                "Source": str(source or "Unknown").strip(),
                "Ticker": str(ticker or "").upper().strip(),
                "Direction": str(direction or "").upper().strip(),
                "Score": _normalise_signal_score(score, direction),
                "Expected Return": _safe_float(expected_return),
                "Confidence": float(np.clip(_safe_float(confidence, 0.50) or 0.50, 0.0, 1.0)),
                "Horizon": str(horizon or "Medium"),
                "Risk Multiplier": float(max(_safe_float(risk_multiplier, 1.0) or 1.0, 0.0)),
                "Notes": str(notes or ""),
                "Metadata": dict(metadata or {}),
        }
        if not record["Direction"]:
                record["Direction"] = _direction_from_score(record["Score"])

        bus = st.session_state.setdefault(SIGNAL_BUS_KEY, [])
        if not isinstance(bus, list):
                bus = []
                st.session_state[SIGNAL_BUS_KEY] = bus
        bus.append(record)
        st.session_state[SIGNAL_BUS_KEY] = bus[-500:]
        return record


def clear_terminal_signal_bus() -> None:
        st.session_state[SIGNAL_BUS_KEY] = []


def _flatten_mapping(mapping: Mapping[str, Any], prefix: str = "") -> dict[str, Any]:
        output: dict[str, Any] = {}
        for key, value in mapping.items():
                name = f"{prefix}.{key}" if prefix else str(key)
                if isinstance(value, Mapping) and len(output) < 250:
                        output.update(_flatten_mapping(value, name))
                else:
                        output[name] = value
        return output


def _find_first_alias(flat: Mapping[str, Any], aliases: Sequence[str]) -> Any:
        aliases_lower = [alias.lower() for alias in aliases]
        for key, value in flat.items():
                key_lower = str(key).lower()
                if any(key_lower == alias or key_lower.endswith(f".{alias}") for alias in aliases_lower):
                        return value
        for key, value in flat.items():
                key_lower = str(key).lower()
                if any(alias in key_lower for alias in aliases_lower):
                        return value
        return None


def _signal_record_from_mapping(
        payload: Mapping[str, Any],
        source: str,
        ticker_hint: str | None = None,
) -> dict[str, Any] | None:
        flat = _flatten_mapping(payload)
        ticker = _find_first_alias(flat, ["ticker", "symbol", "asset", "instrument"])
        ticker = str(ticker or ticker_hint or "").upper().strip()
        if not ticker:
                return None

        direction = _find_first_alias(flat, ["direction", "signal", "stance", "recommendation", "action", "zone"])
        score = _find_first_alias(flat, ["score", "signal_score", "confidence_score", "probability", "edge_score", "composite_score"])
        expected_return = _find_first_alias(flat, ["expected_return", "return_forecast", "forecast_return", "alpha", "expected alpha"])
        confidence = _find_first_alias(flat, ["confidence", "conviction", "probability", "quality", "reliability"])
        horizon = _find_first_alias(flat, ["horizon", "holding_period", "window"])
        risk_multiplier = _find_first_alias(flat, ["risk_multiplier", "risk_budget", "position_multiplier", "size_multiplier"])
        notes = _find_first_alias(flat, ["notes", "reason", "rationale", "summary", "explanation"])

        score_value = _normalise_signal_score(score, str(direction or ""))
        confidence_value = _safe_float(confidence, 0.50) or 0.50
        if confidence_value > 1.0 and confidence_value <= 100.0:
                confidence_value /= 100.0

        return {
                "Timestamp": _utc_now_iso(),
                "Source": source,
                "Ticker": ticker,
                "Direction": str(direction or _direction_from_score(score_value)).upper(),
                "Score": score_value,
                "Expected Return": _safe_float(expected_return),
                "Confidence": float(np.clip(confidence_value, 0.0, 1.0)),
                "Horizon": str(horizon or "Unknown"),
                "Risk Multiplier": float(max(_safe_float(risk_multiplier, 1.0) or 1.0, 0.0)),
                "Notes": str(notes or ""),
        }


def _records_from_object(
        value: Any,
        source: str,
        ticker_hint: str | None = None,
) -> list[dict[str, Any]]:
        records: list[dict[str, Any]] = []
        if value is None:
                return records
        if isinstance(value, pd.DataFrame):
                for _, row in value.head(250).iterrows():
                        record = _signal_record_from_mapping(row.to_dict(), source, ticker_hint)
                        if record:
                                records.append(record)
                return records
        if isinstance(value, pd.Series):
                record = _signal_record_from_mapping(value.to_dict(), source, ticker_hint)
                return [record] if record else []
        if isinstance(value, Mapping):
                # A mapping can either be one signal or a ticker -> payload dictionary.
                direct = _signal_record_from_mapping(value, source, ticker_hint)
                if direct:
                        records.append(direct)
                else:
                        for key, nested in list(value.items())[:250]:
                                if isinstance(nested, Mapping):
                                        record = _signal_record_from_mapping(nested, source, str(key))
                                        if record:
                                                records.append(record)
                return records
        if isinstance(value, (list, tuple)):
                for item in list(value)[:250]:
                        records.extend(_records_from_object(item, source, ticker_hint))
        return records


def collect_terminal_signals(
        book: pd.DataFrame,
        analysis: Mapping[str, Any] | None = None,
        ticker_hint: str | None = None,
) -> pd.DataFrame:
        """Collect explicitly published and discoverable module signals.

        Auto-discovery is deliberately conservative and only checks documented
        session-state aliases.    A module can always publish an exact record through
        :func:`publish_terminal_signal`.
        """
        records: list[dict[str, Any]] = []

        bus = st.session_state.get(SIGNAL_BUS_KEY, [])
        if isinstance(bus, list):
                for item in bus[-500:]:
                        if isinstance(item, Mapping):
                                record = _signal_record_from_mapping(item, str(item.get("Source", "Signal Bus")), ticker_hint)
                                if record:
                                        record.update({key: item.get(key, record.get(key)) for key in SIGNAL_COLUMNS})
                                        records.append(record)

        imported = st.session_state.get(SIGNAL_IMPORT_KEY)
        records.extend(_records_from_object(imported, "Manual / CSV", ticker_hint))

        if isinstance(analysis, Mapping) and analysis:
                records.extend(_records_from_object(analysis, "Current Analysis", ticker_hint))

        for source, keys in KNOWN_SIGNAL_STATE_KEYS.items():
                for key in keys:
                        if key in st.session_state:
                                records.extend(_records_from_object(st.session_state.get(key), source, ticker_hint))

        frame = pd.DataFrame(records)
        if frame.empty:
                return pd.DataFrame(columns=SIGNAL_COLUMNS)

        for column in SIGNAL_COLUMNS:
                if column not in frame.columns:
                        frame[column] = np.nan if column in {"Score", "Expected Return", "Confidence", "Risk Multiplier"} else ""

        frame["Ticker"] = frame["Ticker"].astype(str).str.upper().str.strip()
        valid_tickers = set(book["Ticker"].astype(str).str.upper().str.strip()) if not book.empty else set()
        frame = frame.loc[frame["Ticker"].isin(valid_tickers)].copy()
        if frame.empty:
                return pd.DataFrame(columns=SIGNAL_COLUMNS)

        frame["Score"] = [
                _normalise_signal_score(score, direction)
                for score, direction in zip(frame["Score"], frame["Direction"])
        ]
        frame["Confidence"] = pd.to_numeric(frame["Confidence"], errors="coerce").fillna(0.50).clip(0.0, 1.0)
        frame["Expected Return"] = pd.to_numeric(frame["Expected Return"], errors="coerce")
        frame["Risk Multiplier"] = pd.to_numeric(frame["Risk Multiplier"], errors="coerce").fillna(1.0).clip(lower=0.0)
        frame["Timestamp"] = pd.to_datetime(frame["Timestamp"], errors="coerce", utc=True)
        frame["Timestamp"] = frame["Timestamp"].fillna(pd.Timestamp.now(tz="UTC"))
        frame["Direction"] = frame.apply(
                lambda row: str(row["Direction"] or _direction_from_score(float(row["Score"]))).upper(),
                axis=1,
        )
        frame = frame.sort_values("Timestamp", ascending=False)
        frame = frame.drop_duplicates(subset=["Source", "Ticker", "Direction", "Score", "Expected Return"], keep="first")
        return frame[SIGNAL_COLUMNS].reset_index(drop=True)


def aggregate_terminal_signals(
        signals: pd.DataFrame,
        baseline_expected_returns: pd.Series,
        source_weights: Mapping[str, float] | None = None,
        maximum_tilt: float = 0.08,
) -> tuple[pd.DataFrame, pd.Series]:
        source_weights = dict(DEFAULT_SIGNAL_SOURCE_WEIGHTS | dict(source_weights or {}))
        baseline = baseline_expected_returns.astype(float).copy()

        if signals is None or signals.empty:
                empty = pd.DataFrame(
                        columns=[
                                "Ticker",
                                "Signals",
                                "Consensus Score",
                                "Average Confidence",
                                "Signal Tilt",
                                "Baseline Expected Return",
                                "Adjusted Expected Return",
                                "Risk Multiplier",
                        ]
                )
                return empty, baseline

        rows: list[dict[str, Any]] = []
        adjusted = baseline.copy()

        for ticker, group in signals.groupby("Ticker"):
                if ticker not in baseline.index:
                        continue
                weights = group["Source"].map(source_weights).fillna(0.50).astype(float)
                confidence = group["Confidence"].astype(float).clip(0.0, 1.0)
                effective_weight = weights * confidence
                denominator = float(effective_weight.sum())
                consensus = _safe_div(float((group["Score"].astype(float) * effective_weight).sum()), denominator, 0.0)
                average_confidence = float(confidence.mean())
                score_tilt = float(np.clip(consensus * maximum_tilt, -maximum_tilt, maximum_tilt))

                explicit = group["Expected Return"].dropna().astype(float)
                explicit_target = np.nan
                if not explicit.empty:
                        explicit_weights = effective_weight.reindex(explicit.index).replace(0.0, np.nan)
                        if explicit_weights.notna().any():
                                explicit_target = float(np.average(explicit.values, weights=explicit_weights.fillna(0.0).values))
                        else:
                                explicit_target = float(explicit.mean())

                base = float(baseline.get(ticker, 0.0))
                adjusted_value = base + score_tilt
                if np.isfinite(explicit_target):
                        blend = float(np.clip(average_confidence, 0.0, 1.0))
                        adjusted_value = (1.0 - 0.50 * blend) * adjusted_value + (0.50 * blend) * explicit_target

                risk_multiplier = float(
                        np.average(
                                group["Risk Multiplier"].astype(float).values,
                                weights=np.maximum(effective_weight.values, EPS),
                        )
                )
                adjusted.loc[ticker] = adjusted_value
                rows.append(
                        {
                                "Ticker": ticker,
                                "Signals": int(len(group)),
                                "Consensus Score": consensus,
                                "Average Confidence": average_confidence,
                                "Signal Tilt": score_tilt,
                                "Baseline Expected Return": base,
                                "Adjusted Expected Return": adjusted_value,
                                "Risk Multiplier": risk_multiplier,
                        }
                )

        return pd.DataFrame(rows).sort_values("Consensus Score", ascending=False), adjusted


# =============================================================================
# EXTENDED PERFORMANCE ANALYTICS
# =============================================================================


def _periods_per_year(index: pd.Index | None = None) -> int:
        # Portfolio Lab currently uses daily data.    Keeping this helper explicit
        # makes the annualisation convention auditable and easy to extend.
        return TRADING_DAYS


def drawdown_episodes(returns: pd.Series) -> pd.DataFrame:
        """Return a stable drawdown-episode table for any return series.

        The output schema is preserved even when no drawdown exists.    This is
        important for cash-like or monotonically increasing assets, where an
        empty list of episodes previously produced a column-less DataFrame and
        ``sort_values("Depth")`` raised ``KeyError: 'Depth'``.

        The running peak is floored at the initial capital value of 1.0 so that
        a loss occurring on the first observation is also treated as a genuine
        drawdown.
        """
        columns = [
                "Start",
                "Trough",
                "Recovery",
                "Depth",
                "Days to Trough",
                "Days to Recovery",
        ]

        series = pd.to_numeric(returns, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        if series.empty:
                return pd.DataFrame(columns=columns)

        wealth = (1.0 + series).cumprod()
        running_peak = wealth.cummax().clip(lower=1.0)
        dd = wealth / running_peak - 1.0

        episodes: list[dict[str, Any]] = []
        in_drawdown = False
        start: Any = None
        trough: Any = None
        depth = 0.0

        def _elapsed(start_value: Any, end_value: Any, start_pos: int, end_pos: int) -> int:
                """Calendar days for dated data, observation count otherwise."""
                try:
                        return int((pd.Timestamp(end_value) - pd.Timestamp(start_value)).days)
                except Exception:
                        return max(int(end_pos - start_pos), 0)

        start_pos = 0
        trough_pos = 0

        for position, (date, value) in enumerate(dd.items()):
                value = float(value)

                if value < -1e-12 and not in_drawdown:
                        in_drawdown = True
                        start = date
                        trough = date
                        start_pos = position
                        trough_pos = position
                        depth = value
                        continue

                if not in_drawdown:
                        continue

                if value < depth:
                        depth = value
                        trough = date
                        trough_pos = position

                if value >= -1e-12:
                        recovery = date
                        episodes.append(
                                {
                                        "Start": start,
                                        "Trough": trough,
                                        "Recovery": recovery,
                                        "Depth": depth,
                                        "Days to Trough": _elapsed(start, trough, start_pos, trough_pos),
                                        "Days to Recovery": _elapsed(start, recovery, start_pos, position),
                                }
                        )
                        in_drawdown = False
                        start = None
                        trough = None
                        depth = 0.0

        if in_drawdown:
                end = dd.index[-1]
                end_pos = len(dd) - 1
                episodes.append(
                        {
                                "Start": start,
                                "Trough": trough,
                                "Recovery": pd.NaT,
                                "Depth": depth,
                                "Days to Trough": _elapsed(start, trough, start_pos, trough_pos),
                                "Days to Recovery": _elapsed(start, end, start_pos, end_pos),
                        }
                )

        if not episodes:
                return pd.DataFrame(columns=columns)

        return (
                pd.DataFrame(episodes, columns=columns)
                .sort_values("Depth", ascending=True, na_position="last")
                .reset_index(drop=True)
        )


def _capture_ratio(portfolio: pd.Series, benchmark: pd.Series, upside: bool) -> float:
        aligned = pd.concat([portfolio.rename("p"), benchmark.rename("b")], axis=1).dropna()
        if aligned.empty:
                return np.nan
        mask = aligned["b"] > 0.0 if upside else aligned["b"] < 0.0
        selected = aligned.loc[mask]
        if selected.empty:
                return np.nan
        return 100.0 * _safe_div(float(selected["p"].mean()), float(selected["b"].mean()))


def extended_performance_metrics(
        returns: pd.Series,
        benchmark_returns: pd.Series | None = None,
        risk_free_rate: float = 0.0,
) -> dict[str, float]:
        series = pd.to_numeric(returns, errors="coerce").dropna()
        if series.empty:
                return {}

        ann = _periods_per_year(series.index)
        daily_rf = (1.0 + risk_free_rate) ** (1.0 / ann) - 1.0
        wealth = (1.0 + series).cumprod()
        cumulative = float(wealth.iloc[-1] - 1.0)
        years = max(len(series) / ann, 1.0 / ann)
        cagr = float(wealth.iloc[-1] ** (1.0 / years) - 1.0) if wealth.iloc[-1] > 0.0 else np.nan
        arithmetic = float(series.mean() * ann)
        volatility = float(series.std(ddof=1) * math.sqrt(ann)) if len(series) > 1 else np.nan
        excess = series - daily_rf
        sharpe = _safe_div(float(excess.mean() * ann), volatility)
        downside = np.minimum(excess.values, 0.0)
        downside_deviation = float(np.sqrt(np.mean(np.square(downside))) * math.sqrt(ann)) if len(downside) else np.nan
        sortino = _safe_div(float(excess.mean() * ann), downside_deviation)

        dd = drawdown_series(series)
        max_dd = float(dd.min()) if not dd.empty else np.nan
        average_dd = float(dd[dd < 0.0].mean()) if (dd < 0.0).any() else 0.0
        ulcer = float(np.sqrt(np.mean(np.square(dd.values)))) if not dd.empty else np.nan
        pain = abs(average_dd)
        calmar = _safe_div(cagr, abs(max_dd))
        upi = _safe_div(cagr - risk_free_rate, ulcer)
        recovery_factor = _safe_div(cumulative, abs(max_dd))
        serenity = _safe_div(cagr - risk_free_rate, ulcer * max(volatility, EPS))

        var95, cvar95 = historical_var_cvar(series, 0.95)
        var99, cvar99 = historical_var_cvar(series, 0.99)
        gains = series[series > 0.0]
        losses = series[series < 0.0]
        gain_loss = _safe_div(float(gains.mean()) if not gains.empty else 0.0, abs(float(losses.mean())) if not losses.empty else 0.0)
        tail_ratio = _safe_div(float(series.quantile(0.95)), abs(float(series.quantile(0.05))))
        win_rate = float((series > 0.0).mean())

        episodes = drawdown_episodes(series)
        max_underwater_days = int(episodes["Days to Recovery"].max()) if not episodes.empty else 0

        monthly = (1.0 + series).resample("ME").prod() - 1.0 if isinstance(series.index, pd.DatetimeIndex) else pd.Series(dtype=float)
        yearly = (1.0 + series).resample("YE").prod() - 1.0 if isinstance(series.index, pd.DatetimeIndex) else pd.Series(dtype=float)

        metrics = {
                "Cumulative Return": cumulative,
                "CAGR": cagr,
                "Arithmetic Return": arithmetic,
                "Annualized Volatility": volatility,
                "Downside Deviation": downside_deviation,
                "Sharpe": sharpe,
                "Sortino": sortino,
                "Calmar": calmar,
                "Omega": omega_ratio(series, risk_free_rate),
                "Max Drawdown": max_dd,
                "Average Drawdown": average_dd,
                "Ulcer Index": ulcer,
                "Pain Index": pain,
                "UPI": upi,
                "Recovery Factor": recovery_factor,
                "Serenity Ratio": serenity,
                "VaR 95% (1D)": var95,
                "CVaR 95% (1D)": cvar95,
                "VaR 99% (1D)": var99,
                "CVaR 99% (1D)": cvar99,
                "Skew": float(series.skew()) if len(series) >= 3 else np.nan,
                "Excess Kurtosis": float(series.kurt()) if len(series) >= 4 else np.nan,
                "Tail Ratio": tail_ratio,
                "Gain / Loss Ratio": gain_loss,
                "Win Rate": win_rate,
                "Best Day": float(series.max()),
                "Worst Day": float(series.min()),
                "Best Month": float(monthly.max()) if not monthly.empty else np.nan,
                "Worst Month": float(monthly.min()) if not monthly.empty else np.nan,
                "Best Year": float(yearly.max()) if not yearly.empty else np.nan,
                "Worst Year": float(yearly.min()) if not yearly.empty else np.nan,
                "Max Time Underwater (days)": float(max_underwater_days),
        }

        if benchmark_returns is not None and not benchmark_returns.empty:
                aligned = pd.concat([series.rename("portfolio"), benchmark_returns.rename("benchmark")], axis=1).dropna()
                if len(aligned) > 2:
                        bench = aligned["benchmark"]
                        port = aligned["portfolio"]
                        covariance = float(np.cov(port, bench, ddof=1)[0, 1])
                        benchmark_variance = float(bench.var(ddof=1))
                        beta = _safe_div(covariance, benchmark_variance)
                        alpha = float((port.mean() - daily_rf - beta * (bench.mean() - daily_rf)) * ann) if np.isfinite(beta) else np.nan
                        correlation = float(port.corr(bench))
                        r2 = correlation ** 2 if np.isfinite(correlation) else np.nan
                        active = port - bench
                        tracking_error = float(active.std(ddof=1) * math.sqrt(ann))
                        active_return = float(active.mean() * ann)
                        information_ratio = _safe_div(active_return, tracking_error)
                        treynor = _safe_div(float((port.mean() - daily_rf) * ann), beta)
                        benchmark_vol = float(bench.std(ddof=1) * math.sqrt(ann))
                        m2 = risk_free_rate + sharpe * benchmark_vol if np.isfinite(sharpe) else np.nan

                        metrics.update(
                                {
                                        "Benchmark Correlation": correlation,
                                        "Beta": beta,
                                        "Alpha": alpha,
                                        "R²": r2,
                                        "Active Return": active_return,
                                        "Tracking Error": tracking_error,
                                        "Information Ratio": information_ratio,
                                        "Treynor Ratio": treynor,
                                        "M²": m2,
                                        "Upside Capture": _capture_ratio(port, bench, True),
                                        "Downside Capture": _capture_ratio(port, bench, False),
                                }
                        )

        return metrics


def simulate_rebalanced_portfolio(
        returns: pd.DataFrame,
        target_weights: pd.Series,
        *,
        rebalance_frequency: str = "Quarterly",
        transaction_cost_bps: float = 5.0,
        rebalance_band: float = 0.0,
        initial_value: float = 100_000.0,
) -> dict[str, Any]:
        frame = returns.reindex(columns=target_weights.index).apply(pd.to_numeric, errors="coerce").dropna(how="all")
        if frame.empty:
                return {
                        "returns": pd.Series(dtype=float),
                        "nav": pd.Series(dtype=float),
                        "turnover": pd.Series(dtype=float),
                        "costs": pd.Series(dtype=float),
                        "weights": pd.DataFrame(),
                }

        frame = frame.fillna(0.0)
        weights = _normalise_weights(target_weights.reindex(frame.columns).fillna(0.0))
        holdings = weights * float(initial_value)
        previous_nav = float(initial_value)

        nav_values: list[float] = []
        return_values: list[float] = []
        turnover_values: list[float] = []
        cost_values: list[float] = []
        weight_rows: list[pd.Series] = []

        frequency_map = {
                "Daily": "D",
                "Weekly": "W",
                "Monthly": "M",
                "Quarterly": "Q",
                "Annual": "Y",
                "Buy & Hold": None,
        }
        period_code = frequency_map.get(rebalance_frequency, "Q")
        previous_period = None

        for date, row in frame.iterrows():
                holdings = holdings * (1.0 + row.fillna(0.0))
                gross_nav = float(holdings.sum())
                cost = 0.0
                turnover = 0.0

                if period_code is None:
                        rebalance = False
                elif period_code == "D":
                        rebalance = True
                else:
                        current_period = pd.Timestamp(date).to_period(period_code)
                        rebalance = previous_period is not None and current_period != previous_period
                        previous_period = current_period

                if rebalance and gross_nav > EPS:
                        current_w = holdings / gross_nav
                        deviation = float(np.abs(current_w - weights).max())
                        if deviation >= float(rebalance_band):
                                trade_values = weights * gross_nav - holdings
                                turnover = 0.5 * float(np.abs(trade_values).sum()) / gross_nav
                                cost = float(np.abs(trade_values).sum()) * float(transaction_cost_bps) / 10_000.0
                                net_nav = max(gross_nav - cost, 0.0)
                                holdings = weights * net_nav
                                gross_nav = net_nav

                portfolio_return = gross_nav / previous_nav - 1.0 if previous_nav > EPS else 0.0
                previous_nav = gross_nav
                nav_values.append(gross_nav)
                return_values.append(portfolio_return)
                turnover_values.append(turnover)
                cost_values.append(cost)
                weight_rows.append((holdings / gross_nav if gross_nav > EPS else weights).rename(date))

        index = frame.index
        return {
                "returns": pd.Series(return_values, index=index, name="Return"),
                "nav": pd.Series(nav_values, index=index, name="NAV"),
                "turnover": pd.Series(turnover_values, index=index, name="Turnover"),
                "costs": pd.Series(cost_values, index=index, name="Transaction Cost"),
                "weights": pd.DataFrame(weight_rows, index=index),
        }


def rolling_analytics(
        portfolio_returns: pd.Series,
        benchmark_returns: pd.Series | None,
        window: int,
        risk_free_rate: float,
) -> pd.DataFrame:
        series = pd.to_numeric(portfolio_returns, errors="coerce").dropna()
        result = pd.DataFrame(index=series.index)
        daily_rf = (1.0 + risk_free_rate) ** (1.0 / TRADING_DAYS) - 1.0
        result["Rolling Return"] = (1.0 + series).rolling(window).apply(np.prod, raw=True) - 1.0
        result["Rolling Volatility"] = series.rolling(window).std(ddof=1) * math.sqrt(TRADING_DAYS)
        result["Rolling Sharpe"] = (
                (series - daily_rf).rolling(window).mean() * TRADING_DAYS
                / result["Rolling Volatility"].replace(0.0, np.nan)
        )
        if benchmark_returns is not None and not benchmark_returns.empty:
                aligned = pd.concat([series.rename("p"), benchmark_returns.rename("b")], axis=1).dropna()
                covariance = aligned["p"].rolling(window).cov(aligned["b"])
                variance = aligned["b"].rolling(window).var(ddof=1)
                result.loc[aligned.index, "Rolling Beta"] = covariance / variance.replace(0.0, np.nan)
                result.loc[aligned.index, "Rolling Correlation"] = aligned["p"].rolling(window).corr(aligned["b"])
        return result


def annual_return_table(series_map: Mapping[str, pd.Series]) -> pd.DataFrame:
        columns: dict[str, pd.Series] = {}
        for name, series in series_map.items():
                clean = pd.to_numeric(series, errors="coerce").dropna()
                if isinstance(clean.index, pd.DatetimeIndex) and not clean.empty:
                        annual = (1.0 + clean).resample("YE").prod() - 1.0
                        annual.index = annual.index.year
                        columns[name] = annual
        return pd.DataFrame(columns).sort_index()


def monthly_return_matrix(returns: pd.Series) -> pd.DataFrame:
        clean = pd.to_numeric(returns, errors="coerce").dropna()
        if clean.empty or not isinstance(clean.index, pd.DatetimeIndex):
                return pd.DataFrame()
        monthly = (1.0 + clean).resample("ME").prod() - 1.0
        frame = pd.DataFrame({"Year": monthly.index.year, "Month": monthly.index.month, "Return": monthly.values})
        pivot = frame.pivot(index="Year", columns="Month", values="Return")
        pivot = pivot.reindex(columns=range(1, 13))
        pivot.columns = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
        return pivot


# =============================================================================
# ADVANCED OPTIMISATION / FRONTIER / VALIDATION
# =============================================================================


def _advanced_optimizer_constraints(
        assets: list[str],
        current: pd.Series,
        expected_returns: pd.Series,
        covariance: pd.DataFrame,
        book: pd.DataFrame,
        settings: OptimizerSettings,
        bounds: list[tuple[float, float]],
        sector_caps: Mapping[str, float] | None,
) -> list[dict[str, Any]]:
        mu = expected_returns.reindex(assets).fillna(0.0).values
        cov = covariance.loc[assets, assets].values
        current_array = current.reindex(assets).fillna(0.0).values
        constraints: list[dict[str, Any]] = [
                {"type": "eq", "fun": lambda w: float(np.sum(w) - 1.0)},
                {"type": "ineq", "fun": lambda w: float(settings.gross_limit - np.sum(np.abs(w)))},
        ]

        if settings.fix_cash_weight:
                cash_assets = _cash_assets(book, assets)
                cash_indices = np.array([assets.index(asset) for asset in cash_assets], dtype=int)
                if len(cash_indices):
                        fixed_cash_total = float(current.reindex(cash_assets).fillna(0.0).sum())
                        constraints.append(
                                {
                                        "type": "eq",
                                        "fun": lambda w, idx=cash_indices, target=fixed_cash_total: float(np.sum(w[idx]) - target),
                                }
                        )

        if settings.turnover_limit is not None:
                limit = float(settings.turnover_limit)
                constraints.append(
                        {
                                "type": "ineq",
                                "fun": lambda w, cap=limit: float(cap - 0.5 * np.sum(np.abs(w - current_array))),
                        }
                )

        if settings.minimum_expected_return is not None:
                target = float(settings.minimum_expected_return)
                constraints.append({"type": "ineq", "fun": lambda w, target=target: float(w @ mu - target)})

        if settings.maximum_volatility is not None:
                limit = float(settings.maximum_volatility)
                constraints.append(
                        {
                                "type": "ineq",
                                "fun": lambda w, cap=limit: float(cap - _portfolio_vol_array(w, cov)),
                        }
                )

        if sector_caps:
                sector_map = book.set_index("Ticker")["Sector"]
                for sector, cap in sector_caps.items():
                        indices = np.array(
                                [i for i, asset in enumerate(assets) if str(sector_map.get(asset, "Unclassified")) == str(sector)],
                                dtype=int,
                        )
                        if not len(indices):
                                continue
                        if settings.long_only:
                                constraints.append(
                                        {
                                                "type": "ineq",
                                                "fun": lambda w, idx=indices, cap=float(cap): float(cap - np.sum(w[idx])),
                                        }
                                )
                        else:
                                constraints.append(
                                        {
                                                "type": "ineq",
                                                "fun": lambda w, idx=indices, cap=float(cap): float(cap - np.sum(np.abs(w[idx]))),
                                        }
                                )
        return constraints


def optimise_portfolio_advanced(
        model: dict[str, Any],
        method: str,
        settings: OptimizerSettings,
        sector_caps: Mapping[str, float] | None = None,
        *,
        risk_aversion: float = 3.0,
        robustness: float = 0.35,
        resamples: int = 25,
        seed: int = 42,
) -> OptimizerResult:
        original_methods = {
                "Current Portfolio",
                "Equal Weight",
                "Inverse Volatility",
                "Minimum Variance",
                "Maximum Sharpe",
                "Maximum Diversification",
                "Risk Parity",
                "Hierarchical Risk Parity",
                "Minimum CVaR",
        }
        if method in original_methods:
                return optimise_portfolio(
                        method=method,
                        expected_returns=model["expected_returns"],
                        covariance=model["covariance"],
                        returns=model["returns"],
                        current_weights=model["current_weights"],
                        book=model["book"],
                        risk_free_rate=model["settings"].risk_free_rate,
                        settings=settings,
                        sector_caps=sector_caps,
                )

        if not SCIPY_AVAILABLE:
                return OptimizerResult(False, model["current_weights"].copy(), method, "SciPy is required for this optimizer.")

        assets = list(model["covariance"].index)
        current = model["current_weights"].reindex(assets).fillna(0.0)
        expected = model["expected_returns"].reindex(assets).fillna(0.0)
        covariance = model["covariance"].loc[assets, assets]
        returns = model["returns"].reindex(columns=assets).dropna(how="any")
        bounds, bound_warnings = _asset_bounds(model["book"], assets, settings)
        if sum(lower for lower, _ in bounds) > 1.0 + 1e-9 or sum(upper for _, upper in bounds) < 1.0 - 1e-9:
                return OptimizerResult(False, current, method, "Infeasible individual bounds.")

        initial = _bounded_initial_weights(current, assets, bounds)
        mu = expected.values
        cov = covariance.values
        return_matrix = returns.values
        daily_rf = (1.0 + model["settings"].risk_free_rate) ** (1.0 / TRADING_DAYS) - 1.0
        benchmark = model.get("benchmark_returns", pd.Series(dtype=float)).reindex(returns.index)
        benchmark_array = benchmark.values if benchmark.notna().all() and len(benchmark) == len(returns) else None
        constraints = _advanced_optimizer_constraints(
                assets, current, expected, covariance, model["book"], settings, bounds, sector_caps
        )

        def solve_with_data(
                local_mu: np.ndarray,
                local_cov: np.ndarray,
                local_returns: np.ndarray,
                start: np.ndarray,
                local_method: str,
        ) -> Any:
                if local_method == "Maximum Sortino":
                        def objective(w: np.ndarray) -> float:
                                path = local_returns @ w
                                excess = path - daily_rf
                                downside = np.minimum(excess, 0.0)
                                downside_dev = float(np.sqrt(np.mean(np.square(downside))) * math.sqrt(TRADING_DAYS))
                                numerator = float(np.mean(excess) * TRADING_DAYS)
                                return -_safe_div(numerator, downside_dev, -1e6)
                elif local_method == "Maximum Omega":
                        def objective(w: np.ndarray) -> float:
                                path = local_returns @ w
                                excess = path - daily_rf
                                gains = float(np.clip(excess, 0.0, None).sum())
                                losses = float(-np.clip(excess, None, 0.0).sum())
                                return -_safe_div(gains, losses, -1e6)
                elif local_method == "Minimum Max Drawdown":
                        def objective(w: np.ndarray) -> float:
                                path = local_returns @ w
                                wealth = np.cumprod(1.0 + path)
                                peak = np.maximum.accumulate(wealth)
                                dd = wealth / np.maximum(peak, EPS) - 1.0
                                return abs(float(np.min(dd)))
                elif local_method == "Minimum Tracking Error":
                        if benchmark_array is None:
                                return None

                        def objective(w: np.ndarray) -> float:
                                active = local_returns @ w - benchmark_array
                                return float(np.std(active, ddof=1) * math.sqrt(TRADING_DAYS))
                elif local_method == "Maximum Information Ratio":
                        if benchmark_array is None:
                                return None

                        def objective(w: np.ndarray) -> float:
                                active = local_returns @ w - benchmark_array
                                te = float(np.std(active, ddof=1) * math.sqrt(TRADING_DAYS))
                                active_return = float(np.mean(active) * TRADING_DAYS)
                                return -_safe_div(active_return, te, -1e6)
                elif local_method == "Maximum Quadratic Utility":
                        def objective(w: np.ndarray) -> float:
                                return -(float(w @ local_mu) - 0.5 * float(risk_aversion) * float(w.T @ local_cov @ w))
                elif local_method == "Robust Maximum Sharpe":
                        cross_sectional_anchor = float(np.nanmedian(local_mu))
                        robust_mu = (1.0 - float(robustness)) * local_mu + float(robustness) * cross_sectional_anchor
                        uncertainty = np.diag(np.diag(local_cov)) * float(robustness)
                        robust_cov = local_cov + uncertainty

                        def objective(w: np.ndarray) -> float:
                                vol = _portfolio_vol_array(w, robust_cov)
                                return -_safe_div(float(w @ robust_mu) - model["settings"].risk_free_rate, vol, -1e6)
                else:
                        return None

                return minimize(
                        objective,
                        start,
                        method="SLSQP",
                        bounds=bounds,
                        constraints=constraints,
                        options={"maxiter": 1200, "ftol": 1e-10, "disp": False},
                )

        if method == "Resampled Maximum Sharpe":
                rng = np.random.default_rng(int(seed))
                solutions: list[np.ndarray] = []
                iterations = 0
                for _ in range(max(5, min(int(resamples), 100))):
                        indices = rng.integers(0, len(returns), size=len(returns))
                        sample = return_matrix[indices]
                        sample_mu = np.mean(sample, axis=0) * TRADING_DAYS
                        sample_cov = np.cov(sample, rowvar=False, ddof=1) * TRADING_DAYS
                        sample_cov = nearest_psd(pd.DataFrame(sample_cov, index=assets, columns=assets)).values

                        def objective(w: np.ndarray) -> float:
                                return -_safe_div(
                                        float(w @ sample_mu) - model["settings"].risk_free_rate,
                                        _portfolio_vol_array(w, sample_cov),
                                        -1e6,
                                )

                        result = minimize(
                                objective,
                                initial,
                                method="SLSQP",
                                bounds=bounds,
                                constraints=constraints,
                                options={"maxiter": 500, "ftol": 1e-9, "disp": False},
                        )
                        iterations += int(getattr(result, "nit", 0) or 0)
                        if result.success and result.x is not None:
                                solutions.append(np.asarray(result.x, dtype=float))
                if not solutions:
                        return OptimizerResult(False, current, method, "No bootstrap optimisation converged.")
                averaged = np.mean(np.vstack(solutions), axis=0)
                weights = pd.Series(averaged, index=assets)
                # The averaged solution remains inside convex long-only constraints;
                # normalize defensively for numerical drift.
                weights = _normalise_weights(weights)
                report = _constraint_report(weights, current, expected, covariance, model["book"], settings, sector_caps)
                success = bool(report["Pass"].all())
                return OptimizerResult(
                        success,
                        weights,
                        method,
                        f"Averaged {len(solutions)} converged bootstrap portfolios.",
                        objective_value=None,
                        iterations=iterations,
                        constraint_report=report,
                )

        result = solve_with_data(mu, cov, return_matrix, initial, method)
        if result is None:
                return OptimizerResult(False, current, method, "Required benchmark data are unavailable or method is unsupported.")

        weights = pd.Series(result.x if result.x is not None else initial, index=assets, dtype=float)
        report = _constraint_report(weights, current, expected, covariance, model["book"], settings, sector_caps)
        feasible = bool(report["Pass"].all())
        success = bool(result.success and feasible)
        message_parts = [str(result.message)]
        if bound_warnings:
                message_parts.extend(bound_warnings)
        if result.success and not feasible:
                message_parts.append("Post-optimisation constraint audit failed.")
        return OptimizerResult(
                success,
                weights,
                method,
                " | ".join(message_parts),
                objective_value=_safe_float(result.fun),
                iterations=int(result.nit) if getattr(result, "nit", None) is not None else None,
                constraint_report=report,
        )


def apply_optimizer_result_to_model(
        model: dict[str, Any],
        result: OptimizerResult,
        optimizer_settings: OptimizerSettings,
        sector_caps: Mapping[str, float] | None = None,
) -> dict[str, Any]:
        target_weights = result.weights.reindex(model["returns"].columns).fillna(0.0)
        target_metrics = compute_portfolio_metrics(
                model["returns"],
                target_weights,
                model["expected_returns"],
                model["settings"].risk_free_rate,
                model["benchmark_returns"],
        )
        target_metrics["Diversification Ratio"] = diversification_ratio(target_weights, model["covariance"])
        target_risk = risk_decomposition(target_weights, model["covariance"])
        rebalancing = build_rebalancing_table(
                model["current_book"],
                model["current_weights"],
                target_weights,
                model["nav"],
                optimizer_settings,
        )
        updated = dict(model)
        updated.update(
                {
                        "optimizer": result,
                        "optimizer_settings": optimizer_settings,
                        "sector_caps": dict(sector_caps or {}),
                        "target_weights": target_weights,
                        "target_metrics": target_metrics,
                        "target_risk": target_risk,
                        "rebalancing": rebalancing,
                }
        )
        return enhance_model_v2(updated)


def run_optimizer_suite(
        model: dict[str, Any],
        methods: Sequence[str],
        settings: OptimizerSettings,
        sector_caps: Mapping[str, float] | None = None,
        *,
        risk_aversion: float = 3.0,
        robustness: float = 0.35,
        resamples: int = 25,
) -> tuple[dict[str, OptimizerResult], pd.DataFrame]:
        results: dict[str, OptimizerResult] = {}
        rows: list[dict[str, Any]] = []
        for method in methods:
                try:
                        result = optimise_portfolio_advanced(
                                model,
                                method,
                                settings,
                                sector_caps,
                                risk_aversion=risk_aversion,
                                robustness=robustness,
                                resamples=resamples,
                        )
                except Exception as exc:
                        result = OptimizerResult(False, model["current_weights"].copy(), method, f"Unhandled optimizer error: {exc}")
                results[method] = result
                metrics = compute_portfolio_metrics(
                        model["returns"],
                        result.weights.reindex(model["returns"].columns).fillna(0.0),
                        model["expected_returns"],
                        model["settings"].risk_free_rate,
                        model["benchmark_returns"],
                )
                metrics["Diversification Ratio"] = diversification_ratio(result.weights, model["covariance"])
                rows.append(
                        {
                                "Method": method,
                                "Feasible": bool(result.success),
                                "Expected Return": metrics.get("Expected Return"),
                                "Volatility": metrics.get("Volatility"),
                                "Sharpe": metrics.get("Sharpe"),
                                "Sortino": metrics.get("Sortino"),
                                "Max Drawdown": metrics.get("Max Drawdown"),
                                "CVaR 95%": metrics.get("CVaR 95% (1D)"),
                                "Tracking Error": metrics.get("Tracking Error"),
                                "Information Ratio": metrics.get("Information Ratio"),
                                "Diversification Ratio": metrics.get("Diversification Ratio"),
                                "Turnover": 0.5 * float(np.abs(result.weights.reindex(model["current_weights"].index).fillna(0.0) - model["current_weights"]).sum()),
                                "Message": result.message,
                        }
                )
        return results, pd.DataFrame(rows)


def constrained_efficient_frontier(
        model: dict[str, Any],
        optimizer_settings: OptimizerSettings,
        points: int = 35,
) -> tuple[pd.DataFrame, pd.DataFrame]:
        if not SCIPY_AVAILABLE:
                return pd.DataFrame(), pd.DataFrame()

        assets = list(model["covariance"].index)
        mu = model["expected_returns"].reindex(assets).fillna(0.0).values
        cov = model["covariance"].loc[assets, assets].values
        current = model["current_weights"].reindex(assets).fillna(0.0)
        bounds, _ = _asset_bounds(model["book"], assets, optimizer_settings)
        initial = _bounded_initial_weights(current, assets, bounds)

        base_constraints = [
                {"type": "eq", "fun": lambda w: float(np.sum(w) - 1.0)},
                {"type": "ineq", "fun": lambda w: float(optimizer_settings.gross_limit - np.sum(np.abs(w)))},
        ]
        if optimizer_settings.fix_cash_weight:
                cash_assets = _cash_assets(model["book"], assets)
                cash_indices = np.array([assets.index(asset) for asset in cash_assets], dtype=int)
                if len(cash_indices):
                        fixed_cash_total = float(current.reindex(cash_assets).fillna(0.0).sum())
                        base_constraints.append(
                                {
                                        "type": "eq",
                                        "fun": lambda w, idx=cash_indices, target=fixed_cash_total: float(np.sum(w[idx]) - target),
                                }
                        )
        min_result = minimize(
                lambda w: float(w.T @ cov @ w),
                initial,
                method="SLSQP",
                bounds=bounds,
                constraints=base_constraints,
                options={"maxiter": 1000, "ftol": 1e-10, "disp": False},
        )
        if not min_result.success:
                return pd.DataFrame(), pd.DataFrame()

        min_w = np.asarray(min_result.x)
        min_return = float(min_w @ mu)
        max_result = minimize(
                lambda w: -float(w @ mu),
                min_w,
                method="SLSQP",
                bounds=bounds,
                constraints=base_constraints,
                options={"maxiter": 1000, "ftol": 1e-10, "disp": False},
        )
        max_return = float(max_result.x @ mu) if max_result.success and max_result.x is not None else float(np.max(mu))
        if max_return < min_return:
                max_return = min_return
        targets = np.linspace(min_return, max_return, max(10, int(points)))
        previous = min_w
        rows: list[dict[str, Any]] = []
        allocations: list[dict[str, Any]] = []

        for index, target in enumerate(targets, start=1):
                constraints = base_constraints + [
                        {"type": "eq", "fun": lambda w, target=target: float(w @ mu - target)}
                ]
                result = minimize(
                        lambda w: float(w.T @ cov @ w),
                        previous,
                        method="SLSQP",
                        bounds=bounds,
                        constraints=constraints,
                        options={"maxiter": 800, "ftol": 1e-9, "disp": False},
                )
                if not result.success or result.x is None:
                        continue
                previous = np.asarray(result.x)
                vol = _portfolio_vol_array(previous, cov)
                ret = float(previous @ mu)
                rows.append(
                        {
                                "Portfolio": f"Frontier {index}",
                                "Expected Return": ret,
                                "Volatility": vol,
                                "Sharpe": _safe_div(ret - model["settings"].risk_free_rate, vol),
                        }
                )
                allocation_row = {"Portfolio": f"Frontier {index}", "Volatility": vol, **dict(zip(assets, previous))}
                allocations.append(allocation_row)

        return pd.DataFrame(rows), pd.DataFrame(allocations)


def walk_forward_optimizer_validation(
        model: dict[str, Any],
        method: str,
        settings: OptimizerSettings,
        *,
        training_days: int = 504,
        test_days: int = 63,
        step_days: int = 63,
        maximum_windows: int = 10,
) -> tuple[pd.DataFrame, pd.DataFrame]:
        returns = model["returns"].dropna(how="any")
        if len(returns) < training_days + test_days:
                return pd.DataFrame(), pd.DataFrame()

        windows: list[dict[str, Any]] = []
        path_parts: list[pd.DataFrame] = []
        start_points = list(range(training_days, len(returns) - test_days + 1, step_days))[-maximum_windows:]

        for window_number, split in enumerate(start_points, start=1):
                train = returns.iloc[split - training_days:split]
                test = returns.iloc[split:split + test_days]
                covariance = estimate_covariance(
                        train,
                        model=model["settings"].covariance_model,
                        shrinkage=model["settings"].shrinkage,
                        ewma_lambda=model["settings"].ewma_lambda,
                )
                expected = expected_returns_from_history(
                        train,
                        model=model["settings"].expected_return_model if model["settings"].expected_return_model != "Black-Litterman" else "Historical Geometric",
                        ewma_lambda=model["settings"].ewma_lambda,
                )
                temporary = dict(model)
                temporary.update({"returns": train, "covariance": covariance, "expected_returns": expected})
                benchmark_train = model["benchmark_returns"].reindex(train.index).dropna()
                temporary["benchmark_returns"] = benchmark_train

                result = optimise_portfolio_advanced(temporary, method, settings)
                target = result.weights.reindex(test.columns).fillna(0.0)
                current = model["current_weights"].reindex(test.columns).fillna(0.0)
                optimized_returns = test.mul(target, axis=1).sum(axis=1)
                current_returns = test.mul(current, axis=1).sum(axis=1)
                benchmark_test = model["benchmark_returns"].reindex(test.index)

                optimized_growth = float((1.0 + optimized_returns).prod() - 1.0)
                current_growth = float((1.0 + current_returns).prod() - 1.0)
                benchmark_growth = float((1.0 + benchmark_test.dropna()).prod() - 1.0) if benchmark_test.notna().any() else np.nan
                optimized_metrics = extended_performance_metrics(optimized_returns, benchmark_test, model["settings"].risk_free_rate)
                windows.append(
                        {
                                "Window": window_number,
                                "Train Start": train.index.min(),
                                "Train End": train.index.max(),
                                "Test Start": test.index.min(),
                                "Test End": test.index.max(),
                                "Optimizer Success": result.success,
                                "Optimized Return": optimized_growth,
                                "Current Return": current_growth,
                                "Benchmark Return": benchmark_growth,
                                "Optimized Sharpe": optimized_metrics.get("Sharpe"),
                                "Optimized Max Drawdown": optimized_metrics.get("Max Drawdown"),
                                "Turnover vs Current": 0.5 * float(np.abs(target - current).sum()),
                        }
                )
                path_parts.append(
                        pd.DataFrame(
                                {
                                        "Optimized": optimized_returns,
                                        "Current": current_returns,
                                        "Benchmark": benchmark_test,
                                        "Window": window_number,
                                },
                                index=test.index,
                        )
                )

        path = pd.concat(path_parts).sort_index() if path_parts else pd.DataFrame()
        return pd.DataFrame(windows), path


