# FACTOR PROXY / LIQUIDITY / SCENARIO ANALYTICS
# =============================================================================


def proxy_factor_exposures(
        model: dict[str, Any],
        weights: pd.Series,
        selected_factors: Sequence[str],
        window: int | str = 756,
) -> tuple[pd.DataFrame, dict[str, Any], pd.DataFrame]:
        selected = [factor for factor in selected_factors if factor in FACTOR_PROXY_MAP]
        if not selected:
                return pd.DataFrame(), {}, pd.DataFrame()

        factor_returns: dict[str, pd.Series] = {}
        diagnostics: list[dict[str, Any]] = []
        period = model["settings"].period
        interval = model["settings"].interval
        existing_prices = model.get("prices", pd.DataFrame())

        for factor in selected:
                ticker = FACTOR_PROXY_MAP[factor]
                if ticker in existing_prices.columns:
                        price = pd.to_numeric(existing_prices[ticker], errors="coerce").dropna()
                        error = None
                else:
                        payload = _download_single_asset(ticker, period, interval)
                        price = payload.get("price", pd.Series(dtype=float))
                        error = payload.get("error")
                if isinstance(price, pd.Series) and not price.empty:
                        factor_returns[factor] = price.pct_change(fill_method=None).dropna()
                diagnostics.append(
                        {
                                "Factor": factor,
                                "Proxy": ticker,
                                "Status": "OK" if factor in factor_returns else "KO",
                                "Observations": len(factor_returns.get(factor, [])),
                                "Error": error or "",
                        }
                )

        if not factor_returns:
                return pd.DataFrame(), {}, pd.DataFrame(diagnostics)

        portfolio = portfolio_return_series(model["returns"], weights).rename("Portfolio")
        factors = pd.concat(factor_returns, axis=1)
        aligned = pd.concat([portfolio, factors], axis=1).dropna()
        if window != "All":
                aligned = aligned.tail(int(window))
        if len(aligned) < max(60, len(factor_returns) * 10):
                return pd.DataFrame(), {"Warning": "Insufficient aligned observations for a stable proxy regression."}, pd.DataFrame(diagnostics)

        y = aligned["Portfolio"].values
        x = aligned[list(factor_returns)].values
        x_design = np.column_stack([np.ones(len(x)), x])
        coefficients, _, _, _ = np.linalg.lstsq(x_design, y, rcond=None)
        fitted = x_design @ coefficients
        residuals = y - fitted
        ss_res = float(np.sum(np.square(residuals)))
        ss_total = float(np.sum(np.square(y - np.mean(y))))
        r2 = 1.0 - ss_res / ss_total if ss_total > EPS else np.nan

        factor_vol = aligned[list(factor_returns)].std(ddof=1) * math.sqrt(TRADING_DAYS)
        factor_mean = aligned[list(factor_returns)].mean() * TRADING_DAYS
        rows = []
        for index, factor in enumerate(factor_returns, start=1):
                beta = float(coefficients[index])
                rows.append(
                        {
                                "Factor": factor,
                                "Proxy": FACTOR_PROXY_MAP[factor],
                                "Beta": beta,
                                "Annual Proxy Return": float(factor_mean[factor]),
                                "Annual Proxy Volatility": float(factor_vol[factor]),
                                "Approx. Return Contribution": beta * float(factor_mean[factor]),
                        }
                )
        summary = {
                "Annual Alpha": float(coefficients[0] * TRADING_DAYS),
                "R²": r2,
                "Residual Volatility": float(np.std(residuals, ddof=1) * math.sqrt(TRADING_DAYS)),
                "Observations": int(len(aligned)),
                "Method": "OLS on user-selected ETF proxies; descriptive, not a licensed factor risk model.",
        }
        return pd.DataFrame(rows), summary, pd.DataFrame(diagnostics)


def build_tca_workbench(
        model: dict[str, Any],
        *,
        spread_bps: float = 5.0,
        impact_coefficient_bps: float = 35.0,
        daily_participation_limit: float = 0.10,
        urgency_multiplier: float = 1.0,
) -> pd.DataFrame:
        rebalance = model.get("rebalancing", pd.DataFrame()).copy()
        if rebalance.empty:
                return pd.DataFrame()

        snapshot = model.get("market_snapshot", pd.DataFrame()).set_index("Ticker")
        rows: list[dict[str, Any]] = []
        for _, row in rebalance.iterrows():
                ticker = str(row.get("Ticker", ""))
                trade_value = float(_safe_float(row.get("Trade Value"), 0.0) or 0.0)
                absolute_trade = abs(trade_value)
                adv20 = _safe_float(snapshot.at[ticker, "ADV20 Value"] if ticker in snapshot.index and "ADV20 Value" in snapshot.columns else np.nan)
                participation = _safe_div(absolute_trade, adv20, np.nan) if adv20 is not None else np.nan
                capped_participation = min(float(participation), 1.0) if np.isfinite(participation) else np.nan
                market_impact_bps = (
                        float(impact_coefficient_bps) * math.sqrt(max(capped_participation, 0.0)) * float(urgency_multiplier)
                        if np.isfinite(capped_participation)
                        else np.nan
                )
                total_bps = float(spread_bps) + (market_impact_bps if np.isfinite(market_impact_bps) else 0.0)
                estimated_cost = absolute_trade * total_bps / 10_000.0
                days_to_liquidate = (
                        absolute_trade / max(float(adv20) * float(daily_participation_limit), EPS)
                        if adv20 is not None and np.isfinite(adv20) and adv20 > 0.0
                        else np.nan
                )
                if absolute_trade <= EPS:
                        execution_style = "HOLD"
                elif np.isfinite(participation) and participation <= 0.02:
                        execution_style = "Limit / opportunistic"
                elif np.isfinite(participation) and participation <= 0.10:
                        execution_style = "VWAP / POV"
                else:
                        execution_style = "Stage order / multi-day"
                rows.append(
                        {
                                **row.to_dict(),
                                "ADV20 Value": adv20,
                                "Participation": participation,
                                "Days to Liquidate": days_to_liquidate,
                                "Spread bps": spread_bps,
                                "Impact bps": market_impact_bps,
                                "All-in Cost bps": total_bps,
                                "TCA Cost": estimated_cost,
                                "Execution Style": execution_style,
                        }
                )
        return pd.DataFrame(rows)


def historical_stress_results_v2(
        prices: pd.DataFrame,
        current_weights: pd.Series,
        target_weights: pd.Series,
) -> pd.DataFrame:
        rows: list[dict[str, Any]] = []
        for scenario, (start, end) in EXTENDED_HISTORICAL_SCENARIOS.items():
                window = prices.loc[(prices.index >= pd.Timestamp(start)) & (prices.index <= pd.Timestamp(end))]
                available_assets = [asset for asset in current_weights.index if asset in window.columns]
                if window.empty or not available_assets:
                        rows.append(
                                {
                                        "Scenario": scenario,
                                        "Start": start,
                                        "End": end,
                                        "Current Portfolio": np.nan,
                                        "Target Portfolio": np.nan,
                                        "Coverage": 0.0,
                                }
                        )
                        continue
                valid = window[available_assets].dropna(axis=1, how="all")
                if len(valid) < 2 or valid.shape[1] == 0:
                        rows.append(
                                {
                                        "Scenario": scenario,
                                        "Start": start,
                                        "End": end,
                                        "Current Portfolio": np.nan,
                                        "Target Portfolio": np.nan,
                                        "Coverage": 0.0,
                                }
                        )
                        continue
                asset_returns = valid.ffill().iloc[-1] / valid.ffill().iloc[0] - 1.0
                current = current_weights.reindex(asset_returns.index).fillna(0.0)
                target = target_weights.reindex(asset_returns.index).fillna(0.0)
                coverage = float(current.abs().sum())
                rows.append(
                        {
                                "Scenario": scenario,
                                "Start": start,
                                "End": end,
                                "Current Portfolio": float(current @ asset_returns),
                                "Target Portfolio": float(target @ asset_returns),
                                "Coverage": coverage,
                        }
                )
        return pd.DataFrame(rows)


def scenario_mixer_results(
        book: pd.DataFrame,
        current_weights: pd.Series,
        target_weights: pd.Series,
        asset_class_shocks: Mapping[str, float],
        custom_ticker_shocks: Mapping[str, float] | None = None,
) -> tuple[dict[str, float], pd.DataFrame]:
        metadata = book.set_index("Ticker")
        custom = {str(key).upper(): float(value) for key, value in (custom_ticker_shocks or {}).items()}
        rows: list[dict[str, Any]] = []
        current_total = 0.0
        target_total = 0.0
        for ticker in current_weights.index.union(target_weights.index):
                asset_class = str(metadata.at[ticker, "Asset Class"] if ticker in metadata.index else "Other")
                bucket = _asset_class_bucket(
                        ticker,
                        asset_class,
                        str(metadata.at[ticker, "Sector"] if ticker in metadata.index else ""),
                        str(metadata.at[ticker, "Name"] if ticker in metadata.index else ""),
                )
                shock = custom.get(str(ticker).upper(), float(asset_class_shocks.get(bucket, asset_class_shocks.get(asset_class, 0.0))))
                current_contribution = float(current_weights.get(ticker, 0.0)) * shock
                target_contribution = float(target_weights.get(ticker, 0.0)) * shock
                current_total += current_contribution
                target_total += target_contribution
                rows.append(
                        {
                                "Ticker": ticker,
                                "Bucket": bucket,
                                "Shock": shock,
                                "Current Weight": float(current_weights.get(ticker, 0.0)),
                                "Target Weight": float(target_weights.get(ticker, 0.0)),
                                "Current Contribution": current_contribution,
                                "Target Contribution": target_contribution,
                        }
                )
        return {"Current Portfolio": current_total, "Target Portfolio": target_total}, pd.DataFrame(rows)


def reverse_stress_multiplier(portfolio_loss: float, target_loss: float) -> float:
        if portfolio_loss >= -EPS or target_loss >= 0.0:
                return np.nan
        return float(target_loss / portfolio_loss)


