def enhance_model_v2(model: dict[str, Any]) -> dict[str, Any]:
        enhanced = dict(model)
        current_returns = portfolio_return_series(enhanced["returns"], enhanced["current_weights"])
        target_returns = portfolio_return_series(enhanced["returns"], enhanced["target_weights"])
        benchmark = enhanced.get("benchmark_returns", pd.Series(dtype=float))
        risk_free = enhanced["settings"].risk_free_rate
        enhanced["current_extended_metrics"] = extended_performance_metrics(current_returns, benchmark, risk_free)
        enhanced["target_extended_metrics"] = extended_performance_metrics(target_returns, benchmark, risk_free)
        enhanced["current_return_series"] = current_returns
        enhanced["target_return_series"] = target_returns
        enhanced["current_drawdown_episodes"] = drawdown_episodes(current_returns)
        enhanced["target_drawdown_episodes"] = drawdown_episodes(target_returns)
        enhanced.setdefault("optimizer_suite", {})
        enhanced.setdefault("optimizer_suite_table", pd.DataFrame())
        enhanced.setdefault("signal_consensus", pd.DataFrame())
        enhanced.setdefault("factor_exposures", pd.DataFrame())
        enhanced.setdefault("factor_summary", {})
        enhanced.setdefault("walk_forward_windows", pd.DataFrame())
        enhanced.setdefault("walk_forward_path", pd.DataFrame())
        enhanced["manifest"] = dict(enhanced.get("manifest", {}))
        enhanced["manifest"].update(
                {
                        "module": f"Portfolio Lab v{PORTFOLIO_LAB_VERSION}",
                        "enhanced_at_utc": _utc_now_iso(),
                        "features": [
                                "multi_optimizer_suite",
                                "true_efficient_frontier",
                                "periodic_rebalancing_backtest",
                                "factor_proxy_model",
                                "signal_bus",
                                "tca_workbench",
                                "walk_forward_validation",
                        ],
                }
        )
        return enhanced


def publish_portfolio_context(model: dict[str, Any]) -> dict[str, Any]:
        payload = {
                "Timestamp": _utc_now_iso(),
                "Version": PORTFOLIO_LAB_VERSION,
                "NAV": float(model.get("nav", 0.0)),
                "Current Weights": model.get("current_weights", pd.Series(dtype=float)).to_dict(),
                "Target Weights": model.get("target_weights", pd.Series(dtype=float)).to_dict(),
                "Current Metrics": dict(model.get("current_extended_metrics", {})),
                "Target Metrics": dict(model.get("target_extended_metrics", {})),
                "Expected Returns": model.get("expected_returns", pd.Series(dtype=float)).to_dict(),
                "Benchmark": model.get("settings").benchmark if model.get("settings") else None,
                "Optimizer": model.get("optimizer").method if isinstance(model.get("optimizer"), OptimizerResult) else None,
                "Rebalancing": model.get("rebalancing", pd.DataFrame()).to_dict(orient="records"),
                "Risk Contributions": model.get("target_risk", pd.DataFrame()).to_dict(orient="records"),
                "Manifest": dict(model.get("manifest", {})),
        }
        st.session_state[PORTFOLIO_CONTEXT_KEY] = payload
        st.session_state[TARGET_EXPORT_KEY] = {
                "timestamp": payload["Timestamp"],
                "weights": payload["Target Weights"],
                "benchmark": payload["Benchmark"],
                "method": payload["Optimizer"],
        }
        # Compatibility payloads for modules that want a simple, explicit contract.
        st.session_state["risk_monitor_portfolio_context"] = payload
        st.session_state["decision_engine_portfolio_context"] = payload
        st.session_state["backtest_lab_external_portfolio"] = st.session_state[TARGET_EXPORT_KEY]
        st.session_state["trading_plan_portfolio_context"] = payload
        return payload


def build_export_zip_v2(model: dict[str, Any]) -> bytes:
        buffer = BytesIO()
        with zipfile.ZipFile(buffer, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                exports: dict[str, Any] = {
                        "portfolio_book.csv": model.get("current_book", pd.DataFrame()),
                        "expected_returns.csv": model.get("expected_returns", pd.Series(dtype=float)).rename("Expected Return").reset_index().rename(columns={"index": "Ticker"}),
                        "covariance.csv": model.get("covariance", pd.DataFrame()),
                        "correlation.csv": model.get("correlation", pd.DataFrame()),
                        "current_risk.csv": model.get("current_risk", pd.DataFrame()),
                        "target_risk.csv": model.get("target_risk", pd.DataFrame()),
                        "rebalancing.csv": model.get("rebalancing", pd.DataFrame()),
                        "governance.csv": model.get("governance", pd.DataFrame()),
                        "optimizer_suite.csv": model.get("optimizer_suite_table", pd.DataFrame()),
                        "signal_consensus.csv": model.get("signal_consensus", pd.DataFrame()),
                        "factor_exposures.csv": model.get("factor_exposures", pd.DataFrame()),
                        "walk_forward_windows.csv": model.get("walk_forward_windows", pd.DataFrame()),
                        "current_drawdown_episodes.csv": model.get("current_drawdown_episodes", pd.DataFrame()),
                        "target_drawdown_episodes.csv": model.get("target_drawdown_episodes", pd.DataFrame()),
                }
                for filename, frame in exports.items():
                        if isinstance(frame, pd.DataFrame):
                                archive.writestr(filename, frame.to_csv(index=False))
                archive.writestr(
                        "portfolio_context.json",
                        json.dumps(publish_portfolio_context(model), indent=2, default=_json_default),
                )
                archive.writestr(
                        "portfolio_manifest.json",
                        json.dumps(
                                {
                                        "current_metrics": model.get("current_extended_metrics", {}),
                                        "target_metrics": model.get("target_extended_metrics", {}),
                                        "factor_summary": model.get("factor_summary", {}),
                                        "manifest": model.get("manifest", {}),
                                },
                                indent=2,
                                default=_json_default,
                        ),
                )
        buffer.seek(0)
        return buffer.getvalue()


