def _format_extended_metrics_table(
        current: Mapping[str, Any],
        target: Mapping[str, Any],
) -> pd.DataFrame:
        percentage_names = {
                "Cumulative Return", "CAGR", "Arithmetic Return", "Annualized Volatility",
                "Downside Deviation", "Max Drawdown", "Average Drawdown", "Ulcer Index",
                "Pain Index", "VaR 95% (1D)", "CVaR 95% (1D)", "VaR 99% (1D)",
                "CVaR 99% (1D)", "Win Rate", "Best Day", "Worst Day", "Best Month",
                "Worst Month", "Best Year", "Worst Year", "Alpha", "Active Return",
                "Tracking Error", "M²",
        }
        ratio_names = {
                "Sharpe", "Sortino", "Calmar", "Omega", "UPI", "Recovery Factor",
                "Serenity Ratio", "Skew", "Excess Kurtosis", "Tail Ratio",
                "Gain / Loss Ratio", "Benchmark Correlation", "Beta", "R²",
                "Information Ratio", "Treynor Ratio",
        }
        capture_names = {"Upside Capture", "Downside Capture"}
        names = list(dict.fromkeys(list(current.keys()) + list(target.keys())))
        rows = []
        for name in names:
                current_value = _safe_float(current.get(name))
                target_value = _safe_float(target.get(name))
                if name in percentage_names:
                        formatter = _fmt_pct
                        delta_formatter = lambda x: f"{x:+.2%}"
                elif name in capture_names:
                        formatter = lambda x: "N/A" if _safe_float(x) is None else f"{float(x):.1f}%"
                        delta_formatter = lambda x: f"{x:+.1f} pp"
                elif name == "Max Time Underwater (days)":
                        formatter = lambda x: "N/A" if _safe_float(x) is None else f"{int(round(float(x)))}"
                        delta_formatter = lambda x: f"{x:+.0f}"
                else:
                        formatter = _fmt_num
                        delta_formatter = lambda x: f"{x:+.2f}"
                delta = None if current_value is None or target_value is None else target_value - current_value
                rows.append(
                        {
                                "Metric": name,
                                "Current": formatter(current_value),
                                "Target": formatter(target_value),
                                "Delta": "N/A" if delta is None else delta_formatter(delta),
                                "Category": "Risk-adjusted" if name in ratio_names else "Performance / Risk",
                        }
                )
        return pd.DataFrame(rows)


def _performance_growth_figure(series_map: Mapping[str, pd.Series], title: str) -> go.Figure:
        fig = go.Figure()
        for name, returns in series_map.items():
                clean = pd.to_numeric(returns, errors="coerce").dropna()
                if clean.empty:
                        continue
                growth = (1.0 + clean).cumprod()
                fig.add_trace(go.Scatter(x=growth.index, y=growth.values, mode="lines", name=name))
        fig.update_layout(title=title, height=500, yaxis_title="Growth of 1", xaxis_title="Date", margin=dict(l=20, r=20, t=60, b=30), hovermode="x unified")
        return fig


def _drawdown_figure(series_map: Mapping[str, pd.Series], title: str) -> go.Figure:
        fig = go.Figure()
        for name, returns in series_map.items():
                clean = pd.to_numeric(returns, errors="coerce").dropna()
                if clean.empty:
                        continue
                dd = drawdown_series(clean)
                fig.add_trace(go.Scatter(x=dd.index, y=dd.values, mode="lines", fill="tozeroy", name=name))
        fig.update_layout(title=title, height=420, yaxis_tickformat=".0%", margin=dict(l=20, r=20, t=60, b=30), hovermode="x unified")
        return fig


def _rolling_figure(rolling_frames: Mapping[str, pd.DataFrame], metric: str, title: str) -> go.Figure:
        fig = go.Figure()
        for name, frame in rolling_frames.items():
                if metric in frame.columns:
                        fig.add_trace(go.Scatter(x=frame.index, y=frame[metric], mode="lines", name=name))
        fig.update_layout(title=title, height=430, margin=dict(l=20, r=20, t=60, b=30), hovermode="x unified")
        if "Return" in metric or "Volatility" in metric or "Correlation" in metric:
                fig.update_yaxes(tickformat=".1%" if "Correlation" not in metric else ".2f")
        return fig


def _monthly_heatmap_figure(matrix: pd.DataFrame, title: str) -> go.Figure:
        if matrix.empty:
                return go.Figure()
        text = matrix.copy().astype(object)
        for _column in matrix.columns:
                text[_column] = pd.to_numeric(matrix[_column], errors="coerce").map(lambda value: "" if pd.isna(value) else f"{float(value):.1%}")
        fig = go.Figure(
                go.Heatmap(
                        z=matrix.values,
                        x=matrix.columns,
                        y=matrix.index.astype(str),
                        text=text.values,
                        texttemplate="%{text}",
                        colorscale="RdYlGn",
                        zmid=0.0,
                        colorbar=dict(title="Return"),
                )
        )
        fig.update_layout(title=title, height=max(350, 35 * len(matrix) + 120), margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _frontier_v2_figure(frontier: pd.DataFrame, current: Mapping[str, Any], target: Mapping[str, Any]) -> go.Figure:
        fig = go.Figure()
        if not frontier.empty:
                fig.add_trace(
                        go.Scatter(
                                x=frontier["Volatility"],
                                y=frontier["Expected Return"],
                                mode="lines+markers",
                                name="Constrained efficient frontier",
                                marker=dict(size=5),
                        )
                )
        fig.add_trace(
                go.Scatter(
                        x=[current.get("Volatility")],
                        y=[current.get("Expected Return")],
                        mode="markers+text",
                        text=["Current"],
                        textposition="top center",
                        marker=dict(size=13, symbol="diamond"),
                        name="Current",
                )
        )
        fig.add_trace(
                go.Scatter(
                        x=[target.get("Volatility")],
                        y=[target.get("Expected Return")],
                        mode="markers+text",
                        text=["Target"],
                        textposition="top center",
                        marker=dict(size=13, symbol="star"),
                        name="Target",
                )
        )
        fig.update_layout(title="Constrained Efficient Frontier", height=500, xaxis_title="Annualized volatility", yaxis_title="Expected return", xaxis_tickformat=".1%", yaxis_tickformat=".1%", margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _transition_map_figure(allocations: pd.DataFrame) -> go.Figure:
        fig = go.Figure()
        if allocations.empty:
                return fig
        asset_columns = [column for column in allocations.columns if column not in {"Portfolio", "Volatility"}]
        for asset in asset_columns:
                fig.add_trace(
                        go.Scatter(
                                x=allocations["Volatility"],
                                y=allocations[asset],
                                stackgroup="one",
                                mode="lines",
                                name=asset,
                        )
                )
        fig.update_layout(title="Efficient Frontier Allocation Transition Map", height=450, xaxis_title="Annualized volatility", yaxis_title="Allocation", xaxis_tickformat=".1%", yaxis_tickformat=".0%", margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _optimizer_suite_figure(table: pd.DataFrame) -> go.Figure:
        fig = go.Figure()
        if table.empty:
                return fig
        feasible = table.loc[table["Feasible"]].copy()
        if feasible.empty:
                feasible = table.copy()
        fig.add_trace(
                go.Scatter(
                        x=feasible["Volatility"],
                        y=feasible["Expected Return"],
                        mode="markers+text",
                        text=feasible["Method"],
                        textposition="top center",
                        marker=dict(
                                size=np.clip(10.0 + pd.to_numeric(feasible["Sharpe"], errors="coerce").fillna(0.0) * 8.0, 9.0, 25.0),
                                color=pd.to_numeric(feasible["Sharpe"], errors="coerce"),
                                colorscale="Viridis",
                                showscale=True,
                                colorbar=dict(title="Sharpe"),
                        ),
                        name="Optimizer methods",
                )
        )
        fig.update_layout(title="Optimizer Method Map", height=520, xaxis_title="Annualized volatility", yaxis_title="Expected return", xaxis_tickformat=".1%", yaxis_tickformat=".1%", margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _risk_budget_figure(risk: pd.DataFrame, title: str) -> go.Figure:
        data = risk.copy().sort_values("Risk Contribution %", ascending=True)
        fig = go.Figure(go.Bar(x=data["Risk Contribution %"], y=data["Ticker"], orientation="h"))
        fig.update_layout(title=title, height=max(350, 34 * len(data) + 120), xaxis_tickformat=".1%", margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _signal_consensus_figure(consensus: pd.DataFrame) -> go.Figure:
        fig = go.Figure()
        if consensus.empty:
                return fig
        ordered = consensus.sort_values("Consensus Score")
        fig.add_trace(go.Bar(x=ordered["Consensus Score"], y=ordered["Ticker"], orientation="h", name="Consensus"))
        fig.update_layout(title="Cross-Module Signal Consensus", height=max(350, 34 * len(ordered) + 120), xaxis_range=[-1, 1], margin=dict(l=20, r=20, t=60, b=30))
        return fig


