def _pl29_model_signal_count(model: Mapping[str, Any]) -> int:
        consensus = model.get("signal_consensus", pd.DataFrame())
        if isinstance(consensus, pd.DataFrame) and not consensus.empty:
                if "Signals" in consensus.columns:
                        values = pd.to_numeric(consensus["Signals"], errors="coerce").fillna(0.0)
                        return int((values > 0.0).sum())
                return int(len(consensus))

        context = model.get("signal_context_v29")
        if isinstance(context, Mapping):
                processed = context.get("processed_signals")
                if isinstance(processed, pd.DataFrame) and not processed.empty and "Eligibility" in processed.columns:
                        return int(processed["Eligibility"].fillna(False).astype(bool).sum())

        records = model.get("signal_records", pd.DataFrame())
        if isinstance(records, pd.DataFrame) and not records.empty:
                if "Eligibility" in records.columns:
                        return int(records["Eligibility"].fillna(False).astype(bool).sum())
                return int(len(records))
        return 0


def _render_model_status_strip(model: dict[str, Any]) -> None:
        optimizer = model.get("optimizer")
        optimizer_text = "Not selected" if optimizer is None else f"{optimizer.method} · {'PASS' if optimizer.success else 'REVIEW'}"
        warnings = len(model.get("governance_warnings", []))
        signals = _pl29_model_signal_count(model)
        st.markdown(
                f"""
                <div class="pl2-strip">
                <strong>MODEL</strong> Portfolio Lab v{PORTFOLIO_LAB_VERSION}
                &nbsp;&nbsp;·&nbsp;&nbsp; <strong>ASSETS</strong> {len(model.get('returns', pd.DataFrame()).columns)}
                &nbsp;&nbsp;·&nbsp;&nbsp; <strong>OBS</strong> {len(model.get('returns', pd.DataFrame())):,}
                &nbsp;&nbsp;·&nbsp;&nbsp; <strong>OPTIMIZER</strong> {optimizer_text}
                &nbsp;&nbsp;·&nbsp;&nbsp; <strong>SIGNAL TICKERS</strong> {signals}
                &nbsp;&nbsp;·&nbsp;&nbsp; <strong>MODEL GOVERNANCE</strong> {'PASS' if warnings == 0 else f'{warnings} REVIEW'}
                </div>
                """,
                unsafe_allow_html=True,
        )

def _metric_delta(target: Mapping[str, Any], current: Mapping[str, Any], key: str, percent: bool = False) -> str | None:
        t = _safe_float(target.get(key))
        c = _safe_float(current.get(key))
        if t is None or c is None:
                return None
        value = t - c
        return f"{value:+.2%}" if percent else f"{value:+.2f}"


def _render_top_metrics_v2(model: dict[str, Any]) -> None:
        current = model["current_extended_metrics"]
        target = model["target_extended_metrics"]
        cols = st.columns(8)
        cols[0].metric("NAV", _fmt_money(model["nav"]))
        cols[1].metric("CAGR", _fmt_pct(target.get("CAGR")), _metric_delta(target, current, "CAGR", True))
        cols[2].metric("Volatility", _fmt_pct(target.get("Annualized Volatility")), _metric_delta(target, current, "Annualized Volatility", True), delta_color="inverse")
        cols[3].metric("Sharpe", _fmt_num(target.get("Sharpe")), _metric_delta(target, current, "Sharpe"))
        cols[4].metric("Sortino", _fmt_num(target.get("Sortino")), _metric_delta(target, current, "Sortino"))
        cols[5].metric("Max Drawdown", _fmt_pct(target.get("Max Drawdown")), _metric_delta(target, current, "Max Drawdown", True))
        cols[6].metric("CVaR 95%", _fmt_pct(target.get("CVaR 95% (1D)")), _metric_delta(target, current, "CVaR 95% (1D)", True), delta_color="inverse")
        optimizer = model.get("optimizer")
        cols[7].metric("Target", "Current" if optimizer is None else optimizer.method)


def _render_dashboard_v2(model: dict[str, Any]) -> None:
        _render_top_metrics_v2(model)
        current = model["current_extended_metrics"]
        target = model["target_extended_metrics"]

        alerts: list[str] = []
        if _safe_float(target.get("Max Drawdown"), 0.0) is not None and float(target.get("Max Drawdown", 0.0)) < -0.25:
                alerts.append("Target historical maximum drawdown exceeds 25%.")
        if _safe_float(target.get("Downside Capture")) is not None and float(target.get("Downside Capture")) > 110.0:
                alerts.append("Target downside capture remains above 110% of the benchmark.")
        top_risk = model["target_risk"].sort_values("Risk Contribution %", ascending=False).head(1)
        if not top_risk.empty and float(top_risk.iloc[0]["Risk Contribution %"]) > 0.40:
                alerts.append(f"{top_risk.iloc[0]['Ticker']} contributes more than 40% of total portfolio volatility.")
        if model.get("governance_warnings"):
                alerts.append(f"{len(model['governance_warnings'])} governance item(s) require review.")

        if alerts:
                for alert in alerts:
                        st.warning(alert)
        else:
                st.success("No material dashboard alert detected by the current mechanical rules.")

        left, right = st.columns(2)
        left.plotly_chart(_allocation_figure(model["current_weights"], model["target_weights"], "Current vs Target Allocation"), width="stretch")
        right.plotly_chart(_risk_contribution_figure(model["current_risk"], model["target_risk"]), width="stretch")
        st.plotly_chart(
                _performance_growth_figure(
                        {
                                "Current": model["current_return_series"],
                                "Target": model["target_return_series"],
                                "Benchmark": model.get("benchmark_returns", pd.Series(dtype=float)),
                        },
                        "Historical Growth Comparison",
                ),
                width="stretch",
        )

        st.subheader("Institutional metric comparison")
        st.dataframe(_format_extended_metrics_table(current, target), width="stretch", hide_index=True)

        if not model.get("signal_consensus", pd.DataFrame()).empty:
                st.subheader("Cross-module signal overlay")
                signal_left, signal_right = st.columns([1.2, 1])
                signal_left.plotly_chart(_signal_consensus_figure(model["signal_consensus"]), width="stretch")
                display = model["signal_consensus"].copy()
                for column in ["Signal Tilt", "Baseline Expected Return", "Adjusted Expected Return"]:
                        if column in display.columns:
                                display[column] = display[column].apply(_fmt_pct)
                signal_right.dataframe(display, width="stretch", hide_index=True)


def _project_weights_to_bounds_v2(
        weights: pd.Series,
        lower: pd.Series,
        upper: pd.Series,
        target_sum: float = 1.0,
        tolerance: float = 1e-10,
        max_iterations: int = 200,
) -> pd.Series:
        """Project a weight vector inside box bounds while targeting a fixed net sum.

        The routine is deterministic and deliberately simple. It is used by the
        interactive what-if presets, not as a substitute for the institutional
        optimizer.
        """
        index = weights.index
        w = pd.to_numeric(weights.reindex(index), errors="coerce").fillna(0.0).astype(float)
        lo = pd.to_numeric(lower.reindex(index), errors="coerce").fillna(-np.inf).astype(float)
        hi = pd.to_numeric(upper.reindex(index), errors="coerce").fillna(np.inf).astype(float)

        invalid = lo > hi
        if invalid.any():
                swapped_lo = np.minimum(lo[invalid], hi[invalid])
                swapped_hi = np.maximum(lo[invalid], hi[invalid])
                lo.loc[invalid] = swapped_lo
                hi.loc[invalid] = swapped_hi

        w = w.clip(lower=lo, upper=hi)

        minimum_sum = float(lo.replace(-np.inf, 0.0).sum())
        maximum_sum = float(hi.replace(np.inf, 0.0).sum())
        if np.isfinite(minimum_sum) and minimum_sum > target_sum + tolerance:
                return w
        if np.isfinite(maximum_sum) and maximum_sum < target_sum - tolerance:
                return w

        for _ in range(max_iterations):
                residual = float(target_sum - w.sum())
                if abs(residual) <= tolerance:
                        break

                if residual > 0:
                        room = (hi - w).clip(lower=0.0)
                else:
                        room = (w - lo).clip(lower=0.0)

                finite_room = room.replace([np.inf, -np.inf], np.nan)
                if finite_room.notna().any() and float(finite_room.fillna(0.0).sum()) > tolerance:
                        allocation = finite_room.fillna(0.0)
                else:
                        allocation = pd.Series(1.0, index=index)
                        allocation.loc[room <= tolerance] = 0.0

                total_room = float(allocation.sum())
                if total_room <= tolerance:
                        break

                step = residual * allocation / total_room
                w = (w + step).clip(lower=lo, upper=hi)

        return w.astype(float)


def _whatif_preset_weights_v2(
        preset: str,
        model: dict[str, Any],
        lower: pd.Series,
        upper: pd.Series,
) -> pd.Series:
        assets = pd.Index(model["returns"].columns)
        current = model["current_weights"].reindex(assets).fillna(0.0).astype(float)
        target = model["target_weights"].reindex(assets).fillna(0.0).astype(float)

        if preset == "Current portfolio":
                candidate = current
        elif preset == "Official target":
                candidate = target
        elif preset == "Equal weight":
                candidate = pd.Series(1.0 / max(len(assets), 1), index=assets)
        elif preset == "Inverse volatility":
                volatility = model["returns"].reindex(columns=assets).std(ddof=1) * math.sqrt(TRADING_DAYS)
                positive = volatility.where(volatility > EPS)
                inverse = 1.0 / positive
                inverse = inverse.replace([np.inf, -np.inf], np.nan).fillna(0.0)
                candidate = inverse if float(inverse.sum()) > EPS else pd.Series(1.0, index=assets)
                candidate = candidate / max(float(candidate.sum()), EPS)
        elif preset == "10% cash buffer":
                candidate = target.copy()
                cash_assets = [
                        ticker
                        for ticker in assets
                        if str(ticker).upper() in CASH_ALIASES
                        or (
                                ticker in model["book"].set_index("Ticker").index
                                and str(model["book"].set_index("Ticker").at[ticker, "Asset Class"]).lower() == "cash"
                        )
                ]
                if cash_assets:
                        cash_ticker = cash_assets[0]
                        risky = candidate.drop(index=cash_ticker, errors="ignore")
                        risky_total = float(risky.sum())
                        if abs(risky_total) > EPS:
                                candidate.loc[risky.index] = risky / risky_total * 0.90
                        candidate.loc[cash_ticker] = 0.10
        elif preset == "Reduce largest position":
                candidate = target.copy()
                if not candidate.empty:
                        largest = candidate.abs().idxmax()
                        reduction = 0.25 * float(candidate.loc[largest])
                        candidate.loc[largest] -= reduction
                        cash_assets = [ticker for ticker in assets if str(ticker).upper() in CASH_ALIASES]
                        if cash_assets:
                                candidate.loc[cash_assets[0]] += reduction
                        else:
                                others = candidate.index.difference([largest])
                                if len(others) > 0:
                                        candidate.loc[others] += reduction / len(others)
        else:
                candidate = target

        return _project_weights_to_bounds_v2(
                candidate.reindex(assets).fillna(0.0),
                lower.reindex(assets).fillna(-2.0),
                upper.reindex(assets).fillna(2.0),
                target_sum=1.0,
        )


def _whatif_validation_v2(
        weights: pd.Series,
        lower: pd.Series,
        upper: pd.Series,
        gross_limit: float | None,
) -> dict[str, Any]:
        aligned = pd.to_numeric(weights, errors="coerce").fillna(0.0).astype(float)
        lower = pd.to_numeric(lower.reindex(aligned.index), errors="coerce").fillna(-np.inf)
        upper = pd.to_numeric(upper.reindex(aligned.index), errors="coerce").fillna(np.inf)

        weight_sum = float(aligned.sum())
        gross = float(aligned.abs().sum())
        max_abs = float(aligned.abs().max()) if not aligned.empty else 0.0
        hhi = float((aligned.abs() ** 2).sum())
        effective_positions = _safe_div(1.0, hhi) if hhi > EPS else np.nan

        below = aligned < lower - 1e-8
        above = aligned > upper + 1e-8
        violations = aligned.index[below | above].tolist()

        gross_ok = gross_limit is None or gross <= float(gross_limit) + 1e-8
        return {
                "weight_sum": weight_sum,
                "gross": gross,
                "net": weight_sum,
                "max_abs": max_abs,
                "hhi": hhi,
                "effective_positions": effective_positions,
                "sum_ok": abs(weight_sum - 1.0) <= 1e-6,
                "bounds_ok": len(violations) == 0,
                "gross_ok": gross_ok,
                "violations": violations,
                "gross_limit": gross_limit,
        }


def _metric_card_html_v2(
        label: str,
        value: str,
        delta_value: float | None,
        delta_format: str,
        good_when_higher: bool,
        comparison_label: str = "vs current",
) -> str:
        css_class = "info"
        delta_text = "No comparison"

        if delta_value is not None and np.isfinite(delta_value):
                if delta_format == "percent":
                        delta_text = f"{delta_value:+.2%} {comparison_label}"
                        threshold = 1e-8
                else:
                        delta_text = f"{delta_value:+.2f} {comparison_label}"
                        threshold = 1e-8

                if abs(delta_value) <= threshold:
                        css_class = "info"
                else:
                        improvement = delta_value > 0 if good_when_higher else delta_value < 0
                        css_class = "positive" if improvement else "negative"

        return (
                f'<div class="pl2-kpi {css_class}">'
                f'<div class="pl2-kpi-label">{label}</div>'
                f'<div class="pl2-kpi-value">{value}</div>'
                f'<div class="pl2-kpi-delta">{delta_text}</div>'
                f"</div>"
        )


def _render_whatif_metric_cards_v2(
        current_metrics: Mapping[str, Any],
        whatif_metrics: Mapping[str, Any],
) -> None:
        specifications = [
                ("Expected return", "Expected Return", "percent", True),
                ("Volatility", "Volatility", "percent", False),
                ("Sharpe", "Sharpe", "number", True),
                ("Max drawdown", "Max Drawdown", "percent", True),
                ("CVaR 95%", "CVaR 95% (1D)", "percent", False),
                ("Effective bets", "Effective Bets", "number", True),
        ]

        cards: list[str] = []
        for label, key, value_format, good_when_higher in specifications:
                current_value = _safe_float(current_metrics.get(key))
                whatif_value = _safe_float(whatif_metrics.get(key))
                delta = None if current_value is None or whatif_value is None else whatif_value - current_value
                value = _fmt_pct(whatif_value) if value_format == "percent" else _fmt_num(whatif_value)
                cards.append(
                        _metric_card_html_v2(
                                label,
                                value,
                                delta,
                                value_format,
                                good_when_higher,
                        )
                )

        st.markdown(
                '<div class="pl2-kpi-grid">' + "".join(cards) + "</div>",
                unsafe_allow_html=True,
        )


def _whatif_allocation_figure_v2(
        current: pd.Series,
        target: pd.Series,
        whatif: pd.Series,
) -> go.Figure:
        assets = list(dict.fromkeys(list(current.index) + list(target.index) + list(whatif.index)))
        fig = go.Figure()
        fig.add_trace(
                go.Bar(
                        x=assets,
                        y=current.reindex(assets).fillna(0.0),
                        name="Current",
                        marker_color="#64748b",
                        hovertemplate="%{x}<br>Current: %{y:.2%}<extra></extra>",
                )
        )
        fig.add_trace(
                go.Bar(
                        x=assets,
                        y=target.reindex(assets).fillna(0.0),
                        name="Official target",
                        marker_color="#38bdf8",
                        hovertemplate="%{x}<br>Target: %{y:.2%}<extra></extra>",
                )
        )
        fig.add_trace(
                go.Bar(
                        x=assets,
                        y=whatif.reindex(assets).fillna(0.0),
                        name="What-if",
                        marker_color="#a78bfa",
                        hovertemplate="%{x}<br>What-if: %{y:.2%}<extra></extra>",
                )
        )
        fig.update_layout(
                title="Allocation State Comparison",
                barmode="group",
                height=430,
                yaxis_title="Portfolio weight",
                yaxis_tickformat=".0%",
                legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
                margin=dict(l=20, r=20, t=72, b=35),
        )
        return fig


def _whatif_delta_figure_v2(
        current: pd.Series,
        whatif: pd.Series,
) -> go.Figure:
        delta = whatif.reindex(current.index.union(whatif.index)).fillna(0.0) - current.reindex(current.index.union(whatif.index)).fillna(0.0)
        delta = delta.sort_values()
        colors = ["#ef4444" if value < 0 else "#22c55e" for value in delta.values]
        fig = go.Figure(
                go.Bar(
                        x=delta.values,
                        y=delta.index,
                        orientation="h",
                        marker_color=colors,
                        customdata=np.abs(delta.values),
                        hovertemplate="%{y}<br>Change: %{x:+.2%}<extra></extra>",
                )
        )
        fig.add_vline(x=0.0, line_width=1, line_color="rgba(226,232,240,.35)")
        fig.update_layout(
                title="Trade Direction Preview",
                height=max(390, 34 * len(delta) + 150),
                xaxis_title="Weight change vs current",
                xaxis_tickformat="+.1%",
                margin=dict(l=20, r=20, t=65, b=35),
                showlegend=False,
        )
        return fig


def _asset_risk_return_map_v2(asset_table: pd.DataFrame) -> go.Figure:
        frame = asset_table.copy()
        frame["Weight Abs"] = pd.to_numeric(frame["Weight"], errors="coerce").abs().fillna(0.0)
        frame["Sharpe Numeric"] = pd.to_numeric(frame["Sharpe"], errors="coerce")
        frame["Marker Size"] = np.clip(12.0 + frame["Weight Abs"] * 90.0, 12.0, 52.0)

        fig = go.Figure(
                go.Scatter(
                        x=frame["Volatility"],
                        y=frame["CAGR"],
                        mode="markers+text",
                        text=frame["Ticker"],
                        textposition="top center",
                        marker=dict(
                                size=frame["Marker Size"],
                                color=frame["Sharpe Numeric"],
                                colorscale="RdYlGn",
                                cmin=-1.0,
                                cmax=1.5,
                                showscale=True,
                                colorbar=dict(title="Sharpe"),
                                line=dict(width=1, color="rgba(248,250,252,.35)"),
                        ),
                        customdata=np.column_stack(
                                [
                                        frame["Weight"],
                                        frame["Risk Contribution %"],
                                        frame["Max Drawdown"],
                                        frame["Beta"],
                                ]
                        ),
                        hovertemplate=(
                                "<b>%{text}</b><br>"
                                "CAGR: %{y:.2%}<br>"
                                "Volatility: %{x:.2%}<br>"
                                "Weight: %{customdata[0]:.2%}<br>"
                                "Risk share: %{customdata[1]:.2%}<br>"
                                "Max drawdown: %{customdata[2]:.2%}<br>"
                                "Beta: %{customdata[3]:.2f}<extra></extra>"
                        ),
                )
        )
        fig.add_hline(y=0.0, line_width=1, line_dash="dot", line_color="rgba(226,232,240,.25)")
        fig.update_layout(
                title="Asset Risk / Return Map",
                height=470,
                xaxis_title="Annualized volatility",
                yaxis_title="Historical CAGR",
                xaxis_tickformat=".0%",
                yaxis_tickformat=".0%",
                margin=dict(l=20, r=20, t=65, b=35),
        )
        return fig


def _asset_growth_figure_v2(series: pd.Series, ticker: str) -> go.Figure:
        clean = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        growth = (1.0 + clean).cumprod()
        fig = go.Figure(
                go.Scatter(
                        x=growth.index,
                        y=growth.values,
                        mode="lines",
                        line=dict(color="#38bdf8", width=2),
                        fill="tozeroy",
                        fillcolor="rgba(56,189,248,.08)",
                        hovertemplate="%{x|%Y-%m-%d}<br>Growth: %{y:.3f}<extra></extra>",
                )
        )
        fig.update_layout(
                title=f"{ticker} · Growth of 1",
                height=360,
                yaxis_title="Growth of 1",
                margin=dict(l=20, r=20, t=60, b=30),
                showlegend=False,
        )
        return fig


def _asset_drawdown_figure_v2(series: pd.Series, ticker: str) -> go.Figure:
        clean = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        wealth = (1.0 + clean).cumprod()
        peak = wealth.cummax().clip(lower=1.0)
        drawdown = wealth / peak - 1.0
        fig = go.Figure(
                go.Scatter(
                        x=drawdown.index,
                        y=drawdown.values,
                        mode="lines",
                        line=dict(color="#ef4444", width=1.8),
                        fill="tozeroy",
                        fillcolor="rgba(239,68,68,.15)",
                        hovertemplate="%{x|%Y-%m-%d}<br>Drawdown: %{y:.2%}<extra></extra>",
                )
        )
        fig.update_layout(
                title=f"{ticker} · Drawdown",
                height=360,
                yaxis_title="Drawdown",
                yaxis_tickformat=".0%",
                margin=dict(l=20, r=20, t=60, b=30),
                showlegend=False,
        )
        return fig


def _book_exposure_figure_v2(
        book: pd.DataFrame,
        current_weights: pd.Series,
        whatif_weights: pd.Series,
        dimension: str,
) -> go.Figure:
        metadata = book.set_index("Ticker")
        frame = pd.DataFrame({"Ticker": current_weights.index})
        frame[dimension] = frame["Ticker"].map(metadata[dimension]).fillna("Unclassified")
        frame["Current"] = frame["Ticker"].map(current_weights).fillna(0.0)
        frame["What-If"] = frame["Ticker"].map(whatif_weights).fillna(0.0)
        grouped = frame.groupby(dimension, dropna=False)[["Current", "What-If"]].sum().sort_values("What-If")

        fig = go.Figure()
        fig.add_trace(
                go.Bar(
                        x=grouped["Current"],
                        y=grouped.index.astype(str),
                        orientation="h",
                        name="Current",
                        marker_color="#64748b",
                        hovertemplate="%{y}<br>Current: %{x:.2%}<extra></extra>",
                )
        )
        fig.add_trace(
                go.Bar(
                        x=grouped["What-If"],
                        y=grouped.index.astype(str),
                        orientation="h",
                        name="What-if",
                        marker_color="#a78bfa",
                        hovertemplate="%{y}<br>What-if: %{x:.2%}<extra></extra>",
                )
        )
        fig.update_layout(
                title=f"Exposure by {dimension}",
                barmode="group",
                height=max(380, 42 * len(grouped) + 150),
                xaxis_tickformat=".0%",
                legend=dict(orientation="h", yanchor="bottom", y=1.02),
                margin=dict(l=20, r=20, t=65, b=30),
        )
        return fig


def _build_trade_preview_v2(
        model: dict[str, Any],
        whatif_weights: pd.Series,
        whatif_risk: pd.DataFrame,
) -> pd.DataFrame:
        assets = pd.Index(model["returns"].columns)
        current = model["current_weights"].reindex(assets).fillna(0.0)
        whatif = whatif_weights.reindex(assets).fillna(0.0)
        delta = whatif - current
        nav = float(model.get("nav", 0.0) or 0.0)
        risk_map = (
                whatif_risk.set_index("Ticker")["Risk Contribution %"]
                if not whatif_risk.empty
                else pd.Series(dtype=float)
        )
        expected = model["expected_returns"].reindex(assets).fillna(0.0)

        table = pd.DataFrame(
                {
                        "Ticker": assets,
                        "Current Weight": current.values,
                        "What-If Weight": whatif.values,
                        "Weight Change": delta.values,
                        "Action": np.where(delta.values > 1e-8, "BUY", np.where(delta.values < -1e-8, "SELL", "HOLD")),
                        "Trade Value": delta.values * nav,
                        "Expected Return Contribution": whatif.values * expected.values,
                        "Risk Contribution %": assets.map(risk_map).fillna(0.0).values,
                }
        )
        table["Absolute Trade Value"] = table["Trade Value"].abs()
        return table.sort_values("Absolute Trade Value", ascending=False).drop(columns=["Absolute Trade Value"])




