def _pl23_method_family(method: str) -> str:
        return PL23_METHOD_FAMILIES.get(str(method), "Other")


def _pl23_method_description(method: str) -> str:
        return PL23_METHOD_DESCRIPTIONS.get(str(method), "Constrained portfolio construction method.")


def _pl23_coerce_optimizer_result(
        value: Any,
        method_hint: str | None = None,
        assets: Sequence[str] | None = None,
) -> OptimizerResult | None:
        """Rehydrate optimizer results stored across Streamlit hot reloads.

        Streamlit can preserve objects in ``st.session_state`` while reloading the
        module.    Instances created by the previous class definition then fail a
        strict ``isinstance(value, OptimizerResult)`` check even though they still
        expose the same attributes.    This helper deliberately uses a conservative
        structural conversion and also accepts mapping-based audit payloads.
        """
        if value is None:
                return None

        if isinstance(value, Mapping):
                getter = value.get
        else:
                getter = lambda name, default=None: getattr(value, name, default)

        raw_weights = getter("weights", None)
        if raw_weights is None:
                return None

        try:
                if isinstance(raw_weights, pd.Series):
                        weights = pd.to_numeric(raw_weights.copy(), errors="coerce")
                elif isinstance(raw_weights, Mapping):
                        weights = pd.to_numeric(pd.Series(dict(raw_weights), dtype=float), errors="coerce")
                else:
                        sequence = list(raw_weights)
                        if assets is None or len(sequence) != len(list(assets)):
                                return None
                        weights = pd.Series(sequence, index=list(assets), dtype=float)
        except Exception:
                return None

        weights = weights.replace([np.inf, -np.inf], np.nan).fillna(0.0)
        if assets is not None:
                weights = weights.reindex(list(assets)).fillna(0.0)

        # Preserve an exact unit budget when a legacy result is already normalised
        # up to floating-point noise. This avoids false audit/test failures after
        # Streamlit hot reloads without altering genuinely levered portfolios.
        total_weight = float(weights.sum())
        if len(weights) and abs(total_weight - 1.0) <= 1e-12:
                weights.iloc[-1] = float(weights.iloc[-1]) + (1.0 - total_weight)

        raw_report = getter("constraint_report", None)
        if isinstance(raw_report, pd.DataFrame):
                report = raw_report.copy()
        elif isinstance(raw_report, Sequence) and not isinstance(raw_report, (str, bytes)):
                try:
                        report = pd.DataFrame(raw_report)
                except Exception:
                        report = pd.DataFrame()
        elif isinstance(raw_report, Mapping):
                try:
                        report = pd.DataFrame(raw_report)
                except Exception:
                        report = pd.DataFrame()
        else:
                report = pd.DataFrame()

        method = str(getter("method", method_hint or "Unknown") or method_hint or "Unknown")
        message = str(getter("message", "Recovered optimizer result") or "Recovered optimizer result")
        success = bool(getter("success", False))
        objective_value = _safe_float(getter("objective_value", None))
        raw_iterations = getter("iterations", None)
        try:
                iterations = int(raw_iterations) if raw_iterations is not None and not pd.isna(raw_iterations) else None
        except Exception:
                iterations = None

        return OptimizerResult(
                success=success,
                weights=weights,
                method=method,
                message=message,
                objective_value=objective_value,
                iterations=iterations,
                constraint_report=report,
        )


def _pl23_normalize_optimizer_suite(
        suite: Any,
        assets: Sequence[str],
) -> dict[str, OptimizerResult]:
        """Return a current-class optimizer suite without trusting stale objects."""
        if not isinstance(suite, Mapping):
                return {}
        normalized: dict[str, OptimizerResult] = {}
        for method, value in suite.items():
                recovered = _pl23_coerce_optimizer_result(value, str(method), assets)
                if recovered is not None:
                        normalized[str(method)] = recovered
        return normalized


def _pl23_allocation_matrix(
        suite: Mapping[str, OptimizerResult],
        assets: Sequence[str],
        *,
        feasible_only: bool = False,
) -> pd.DataFrame:
        rows: list[dict[str, Any]] = []
        for method, value in suite.items():
                result = _pl23_coerce_optimizer_result(value, str(method), assets)
                if result is None:
                        continue
                if feasible_only and not result.success:
                        continue
                weights = result.weights.reindex(list(assets)).fillna(0.0)
                rows.append({"Method": method, **{asset: float(weights.get(asset, 0.0)) for asset in assets}})
        return pd.DataFrame(rows).set_index("Method") if rows else pd.DataFrame(columns=list(assets))


def _pl23_method_concentration(
        suite: Mapping[str, OptimizerResult],
        assets: Sequence[str],
) -> pd.Series:
        values: dict[str, float] = {}
        for method, value in suite.items():
                result = _pl23_coerce_optimizer_result(value, str(method), assets)
                if result is None:
                        continue
                weights = result.weights.reindex(list(assets)).fillna(0.0)
                values[method] = float(np.square(weights.values).sum())
        return pd.Series(values, dtype=float)


def _pl23_rank_optimizer_table(
        table: pd.DataFrame,
        suite: Mapping[str, OptimizerResult] | None = None,
        assets: Sequence[str] | None = None,
) -> pd.DataFrame:
        """Add transparent peer ranking without changing original optimizer metrics."""
        if table is None or table.empty:
                return pd.DataFrame()
        ranked = table.copy()
        ranked["Family"] = ranked["Method"].map(_pl23_method_family)
        if suite and len(assets) > 0:
                concentration = _pl23_method_concentration(suite, assets)
                ranked["HHI"] = ranked["Method"].map(concentration)
                ranked["Effective Positions"] = ranked["HHI"].apply(
                        lambda value: _safe_div(1.0, float(value)) if _safe_float(value) not in (None, 0.0) else np.nan
                )
        else:
                ranked["HHI"] = np.nan
                ranked["Effective Positions"] = np.nan

        feasible_mask = ranked["Feasible"].fillna(False).astype(bool)
        ranked["Composite Score"] = np.nan
        if feasible_mask.any():
                score_parts: list[pd.Series] = []
                higher_better = ["Sharpe", "Sortino", "Information Ratio", "Diversification Ratio", "Max Drawdown", "Effective Positions"]
                lower_better = ["Volatility", "CVaR 95%", "Tracking Error", "Turnover", "HHI"]
                for column in higher_better:
                        if column in ranked.columns:
                                numeric = pd.to_numeric(ranked.loc[feasible_mask, column], errors="coerce")
                                if numeric.notna().any():
                                        score_parts.append(numeric.rank(pct=True, method="average"))
                for column in lower_better:
                        if column in ranked.columns:
                                numeric = pd.to_numeric(ranked.loc[feasible_mask, column], errors="coerce")
                                if numeric.notna().any():
                                        score_parts.append(numeric.rank(pct=True, ascending=False, method="average"))
                if score_parts:
                        score = pd.concat(score_parts, axis=1).mean(axis=1) * 100.0
                        ranked.loc[score.index, "Composite Score"] = score
        ranked["Rank"] = np.nan
        valid_scores = pd.to_numeric(ranked["Composite Score"], errors="coerce")
        if valid_scores.notna().any():
                ranked.loc[valid_scores.notna(), "Rank"] = valid_scores[valid_scores.notna()].rank(
                        ascending=False, method="min"
                )
        return ranked


def _pl23_optimizer_summary(ranked: pd.DataFrame) -> dict[str, Any]:
        if ranked is None or ranked.empty:
                return {}
        feasible = ranked.loc[ranked["Feasible"].fillna(False).astype(bool)].copy()
        if feasible.empty:
                return {"Feasible": 0, "Total": len(ranked)}

        def method_at(column: str, *, highest: bool) -> str:
                numeric = pd.to_numeric(feasible[column], errors="coerce") if column in feasible.columns else pd.Series(dtype=float)
                if numeric.empty or not numeric.notna().any():
                        return "N/A"
                index = numeric.idxmax() if highest else numeric.idxmin()
                return str(feasible.loc[index, "Method"])

        return {
                "Feasible": int(len(feasible)),
                "Total": int(len(ranked)),
                "Best Sharpe": method_at("Sharpe", highest=True),
                "Lowest Vol": method_at("Volatility", highest=False),
                "Lowest CVaR": method_at("CVaR 95%", highest=False),
                "Lowest Turnover": method_at("Turnover", highest=False),
                "Best Diversification": method_at("Diversification Ratio", highest=True),
                "Top Composite": method_at("Composite Score", highest=True),
        }


def _pl23_constraint_snapshot(
        model: dict[str, Any],
        settings: OptimizerSettings,
        use_turnover: bool,
        use_min_return: bool,
        use_max_vol: bool,
) -> pd.DataFrame:
        current = model.get("current_metrics", {})
        rows = [
                {"Constraint": "Long-only", "Status": "Active" if settings.long_only else "Inactive", "Limit": "w ? 0" if settings.long_only else "Long/short", "Current": "PASS"},
                {"Constraint": "Gross exposure", "Status": "Active", "Limit": _fmt_pct(settings.gross_limit), "Current": _fmt_pct(float(model["current_weights"].abs().sum()))},
                {"Constraint": "Global minimum", "Status": "Active", "Limit": _fmt_pct(settings.global_min_weight), "Current": _fmt_pct(float(model["current_weights"].min()))},
                {"Constraint": "Global maximum", "Status": "Active", "Limit": _fmt_pct(settings.global_max_weight), "Current": _fmt_pct(float(model["current_weights"].max()))},
                {"Constraint": "Fixed cash", "Status": "Active" if settings.fix_cash_weight else "Inactive", "Limit": "Current cash weight", "Current": _fmt_pct(float(model["current_weights"].reindex([a for a in model["current_weights"].index if _is_cash(a)]).fillna(0.0).sum()))},
                {"Constraint": "Turnover cap", "Status": "Active" if use_turnover else "Inactive", "Limit": _fmt_pct(settings.turnover_limit) if settings.turnover_limit is not None else "-", "Current": "0.00%"},
                {"Constraint": "Return floor", "Status": "Active" if use_min_return else "Inactive", "Limit": _fmt_pct(settings.minimum_expected_return) if settings.minimum_expected_return is not None else "-", "Current": _fmt_pct(current.get("Expected Return"))},
                {"Constraint": "Volatility cap", "Status": "Active" if use_max_vol else "Inactive", "Limit": _fmt_pct(settings.maximum_volatility) if settings.maximum_volatility is not None else "-", "Current": _fmt_pct(current.get("Volatility"))},
        ]
        return pd.DataFrame(rows)


def _pl23_optimizer_map_figure(
        table: pd.DataFrame,
        x_metric: str,
        y_metric: str,
        color_metric: str,
        size_metric: str,
        show_labels: bool,
        selected_method: str | None = None,
) -> go.Figure:
        fig = go.Figure()
        if table is None or table.empty:
                return fig
        data = table.loc[table["Feasible"].fillna(False).astype(bool)].copy()
        if data.empty:
                data = table.copy()
        for column in {x_metric, y_metric, color_metric, size_metric}:
                data[column] = pd.to_numeric(data[column], errors="coerce")
        data = data.dropna(subset=[x_metric, y_metric])
        size_values = pd.to_numeric(data[size_metric], errors="coerce").abs().fillna(0.0)
        if size_values.max() > size_values.min():
                marker_size = 11.0 + 17.0 * (size_values - size_values.min()) / (size_values.max() - size_values.min())
        else:
                marker_size = pd.Series(16.0, index=data.index)
        fig.add_trace(
                go.Scatter(
                        x=data[x_metric],
                        y=data[y_metric],
                        mode="markers+text" if show_labels else "markers",
                        text=data["Method"] if show_labels else None,
                        textposition="top center",
                        customdata=np.stack([
                                data["Method"].astype(str),
                                data["Family"].astype(str),
                                pd.to_numeric(data.get("Composite Score", np.nan), errors="coerce"),
                        ], axis=-1),
                        hovertemplate=(
                                "<b>%{customdata[0]}</b><br>Family: %{customdata[1]}<br>"
                                + f"{x_metric}: %{{x:.4f}}<br>{y_metric}: %{{y:.4f}}<br>"
                                + "Composite score: %{customdata[2]:.1f}<extra></extra>"
                        ),
                        marker=dict(
                                size=marker_size,
                                color=pd.to_numeric(data[color_metric], errors="coerce"),
                                colorscale="Viridis",
                                showscale=True,
                                colorbar=dict(title=color_metric),
                                line=dict(color="rgba(255,255,255,.20)", width=.8),
                        ),
                        name="Feasible methods",
                )
        )
        if selected_method is not None and (data["Method"].astype(str) == str(selected_method)).any():
                selected_row = data.loc[data["Method"].astype(str) == str(selected_method)].iloc[0]
                fig.add_trace(
                        go.Scatter(
                                x=[selected_row[x_metric]],
                                y=[selected_row[y_metric]],
                                mode="markers",
                                marker=dict(
                                        size=30,
                                        color="rgba(0,0,0,0)",
                                        line=dict(color="#f8fafc", width=2.6),
                                        symbol="circle-open",
                                ),
                                hoverinfo="skip",
                                showlegend=False,
                                name="Selected method",
                        )
                )
        fig.update_layout(
                title="Interactive Optimizer Trade-off Map",
                height=540,
                xaxis_title=x_metric,
                yaxis_title=y_metric,
                margin=dict(l=25, r=25, t=65, b=35),
        )
        if any(token in x_metric for token in ["Return", "Volatility", "Drawdown", "CVaR", "Error", "Turnover"]):
                fig.update_xaxes(tickformat=".1%")
        if any(token in y_metric for token in ["Return", "Volatility", "Drawdown", "CVaR", "Error", "Turnover"]):
                fig.update_yaxes(tickformat=".1%")
        return _pl22_polish_figure(fig, 540)


def _pl23_allocation_heatmap(matrix: pd.DataFrame) -> go.Figure:
        fig = go.Figure()
        if matrix is None or matrix.empty:
                return fig
        text = matrix.map(lambda value: f"{float(value):.1%}" if pd.notna(value) else "")
        fig.add_trace(
                go.Heatmap(
                        z=matrix.values,
                        x=matrix.columns,
                        y=matrix.index,
                        text=text.values,
                        texttemplate="%{text}",
                        colorscale=[[0.0, "#07111f"], [0.35, "#0ea5e9"], [1.0, "#a78bfa"]],
                        zmin=float(min(0.0, np.nanmin(matrix.values))),
                        zmax=float(max(0.01, np.nanmax(matrix.values))),
                        colorbar=dict(title="Weight"),
                        hovertemplate="%{y}<br>%{x}: %{z:.2%}<extra></extra>",
                )
        )
        fig.update_layout(
                title="Allocation Matrix · Methods × Assets",
                height=max(420, 34 * len(matrix) + 150),
                margin=dict(l=25, r=25, t=65, b=40),
        )
        return _pl22_polish_figure(fig)


def _pl23_candidate_allocation_figure(
        assets: Sequence[str],
        current: pd.Series,
        official: pd.Series,
        candidate: pd.Series,
        method: str,
) -> go.Figure:
        assets = list(assets)
        fig = go.Figure()
        fig.add_bar(name="Current", x=assets, y=current.reindex(assets).fillna(0.0), marker_color="#64748b")
        fig.add_bar(name="Official target", x=assets, y=official.reindex(assets).fillna(0.0), marker_color="#38bdf8")
        fig.add_bar(name=method, x=assets, y=candidate.reindex(assets).fillna(0.0), marker_color="#a78bfa")
        fig.update_layout(
                title=f"Allocation Review · {method}",
                barmode="group",
                height=440,
                yaxis_title="Portfolio weight",
                yaxis_tickformat=".0%",
                margin=dict(l=25, r=25, t=65, b=35),
        )
        return _pl22_polish_figure(fig, 440)


def _pl23_candidate_delta_figure(current: pd.Series, candidate: pd.Series) -> go.Figure:
        delta = candidate.reindex(current.index).fillna(0.0) - current.fillna(0.0)
        data = pd.DataFrame({"Ticker": delta.index, "Delta": delta.values}).sort_values("Delta")
        colors = ["#22c55e" if value > 0 else "#ef4444" if value < 0 else "#64748b" for value in data["Delta"]]
        fig = go.Figure(go.Bar(x=data["Delta"], y=data["Ticker"], orientation="h", marker_color=colors))
        fig.update_layout(
                title="Active Weight Change vs Current",
                height=max(360, 36 * len(data) + 130),
                xaxis_title="Weight change",
                xaxis_tickformat="+.1%",
                margin=dict(l=25, r=25, t=65, b=35),
        )
        fig.add_vline(x=0.0, line_color="rgba(226,232,240,.45)", line_width=1)
        return _pl22_polish_figure(fig)


def _pl23_comparison_table(
        model: dict[str, Any],
        candidate_weights: pd.Series,
) -> pd.DataFrame:
        candidate_metrics = compute_portfolio_metrics(
                model["returns"],
                candidate_weights,
                model["expected_returns"],
                model["settings"].risk_free_rate,
                model["benchmark_returns"],
        )
        candidate_metrics["Diversification Ratio"] = diversification_ratio(candidate_weights, model["covariance"])
        current = dict(model.get("current_metrics", {}))
        target = dict(model.get("target_metrics", {}))
        metric_names = [
                "Expected Return", "Volatility", "Sharpe", "Sortino", "Max Drawdown",
                "CVaR 95% (1D)", "Tracking Error", "Information Ratio", "Diversification Ratio",
        ]
        rows = []
        for metric in metric_names:
                rows.append(
                        {
                                "Metric": metric,
                                "Current": current.get(metric),
                                "Official Target": target.get(metric),
                                "Candidate": candidate_metrics.get(metric),
                                "Delta vs Current": (_safe_float(candidate_metrics.get(metric), 0.0) or 0.0) - (_safe_float(current.get(metric), 0.0) or 0.0),
                                "Delta vs Target": (_safe_float(candidate_metrics.get(metric), 0.0) or 0.0) - (_safe_float(target.get(metric), 0.0) or 0.0),
                        }
                )
        return pd.DataFrame(rows)


def _pl23_consensus_table(matrix: pd.DataFrame) -> pd.DataFrame:
        if matrix is None or matrix.empty:
                return pd.DataFrame()
        return pd.DataFrame(
                {
                        "Asset": matrix.columns,
                        "Median Weight": matrix.median(axis=0).values,
                        "Mean Weight": matrix.mean(axis=0).values,
                        "Minimum Weight": matrix.min(axis=0).values,
                        "Maximum Weight": matrix.max(axis=0).values,
                        "Dispersion": matrix.std(axis=0, ddof=0).values,
                }
        ).sort_values("Median Weight", ascending=False)


def _pl23_sensitivity_values(parameter: str, base_settings: OptimizerSettings, base_risk_aversion: float, base_robustness: float) -> list[float]:
        if parameter == "Global max weight":
                center = float(base_settings.global_max_weight)
                return sorted(set(float(np.clip(value, 0.05, 1.0)) for value in np.linspace(max(0.10, center * 0.60), min(1.0, center * 1.60), 7)))
        if parameter == "Turnover cap":
                center = float(base_settings.turnover_limit if base_settings.turnover_limit is not None else 0.30)
                return sorted(set(float(np.clip(value, 0.02, 1.50)) for value in np.linspace(max(0.05, center * 0.40), min(1.50, center * 1.80), 7)))
        if parameter == "Risk aversion":
                center = float(base_risk_aversion)
                return sorted(set(float(np.clip(value, 0.1, 50.0)) for value in np.linspace(max(0.5, center * 0.40), min(50.0, center * 2.0), 7)))
        if parameter == "Robustness":
                center = float(base_robustness)
                return sorted(set(float(np.clip(value, 0.0, 0.90)) for value in np.linspace(max(0.0, center - 0.30), min(0.90, center + 0.30), 7)))
        if parameter == "CVaR confidence":
                return [0.85, 0.90, 0.925, 0.95, 0.975, 0.985, 0.99]
        return []


def run_optimizer_sensitivity_v23(
        model: dict[str, Any],
        method: str,
        settings: OptimizerSettings,
        parameter: str,
        values: Sequence[float],
        *,
        risk_aversion: float,
        robustness: float,
        resamples: int,
) -> pd.DataFrame:
        rows: list[dict[str, Any]] = []
        base_dict = asdict(settings)
        for value in values:
                local_settings = settings
                local_risk_aversion = float(risk_aversion)
                local_robustness = float(robustness)
                if parameter == "Global max weight":
                        local_settings = OptimizerSettings(**{**base_dict, "global_max_weight": float(value)})
                elif parameter == "Turnover cap":
                        local_settings = OptimizerSettings(**{**base_dict, "turnover_limit": float(value)})
                elif parameter == "Risk aversion":
                        local_risk_aversion = float(value)
                elif parameter == "Robustness":
                        local_robustness = float(value)
                elif parameter == "CVaR confidence":
                        local_settings = OptimizerSettings(**{**base_dict, "cvar_alpha": float(value)})
                try:
                        result = optimise_portfolio_advanced(
                                model,
                                method,
                                local_settings,
                                model.get("sector_caps", {}),
                                risk_aversion=local_risk_aversion,
                                robustness=local_robustness,
                                resamples=int(resamples),
                        )
                        weights = result.weights.reindex(model["returns"].columns).fillna(0.0)
                        metrics = compute_portfolio_metrics(
                                model["returns"], weights, model["expected_returns"],
                                model["settings"].risk_free_rate, model["benchmark_returns"],
                        )
                        metrics["Diversification Ratio"] = diversification_ratio(weights, model["covariance"])
                        rows.append(
                                {
                                        "Parameter": parameter,
                                        "Value": float(value),
                                        "Method": method,
                                        "Feasible": bool(result.success),
                                        "Expected Return": metrics.get("Expected Return"),
                                        "Volatility": metrics.get("Volatility"),
                                        "Sharpe": metrics.get("Sharpe"),
                                        "Max Drawdown": metrics.get("Max Drawdown"),
                                        "CVaR 95%": metrics.get("CVaR 95% (1D)"),
                                        "Turnover": 0.5 * float(np.abs(weights - model["current_weights"].reindex(weights.index).fillna(0.0)).sum()),
                                        "Top Weight": float(weights.max()),
                                        "Effective Positions": _safe_div(1.0, float(np.square(weights.values).sum())),
                                        "Message": result.message,
                                }
                        )
                except Exception as exc:
                        rows.append({"Parameter": parameter, "Value": float(value), "Method": method, "Feasible": False, "Message": str(exc)})
        return pd.DataFrame(rows)


def _pl23_sensitivity_figure(table: pd.DataFrame, metric: str) -> go.Figure:
        fig = go.Figure()
        if table is None or table.empty:
                return fig
        data = table.copy()
        data[metric] = pd.to_numeric(data[metric], errors="coerce")
        feasible = data.loc[data["Feasible"].fillna(False).astype(bool)]
        failed = data.loc[~data["Feasible"].fillna(False).astype(bool)]
        fig.add_trace(
                go.Scatter(
                        x=feasible["Value"], y=feasible[metric], mode="lines+markers",
                        name="Feasible", line=dict(color="#38bdf8", width=2.4), marker=dict(size=9),
                )
        )
        if not failed.empty:
                fig.add_trace(
                        go.Scatter(
                                x=failed["Value"], y=[0.0] * len(failed), mode="markers",
                                name="Infeasible", marker=dict(color="#ef4444", symbol="x", size=11),
                        )
                )
        parameter = str(data["Parameter"].iloc[0]) if "Parameter" in data.columns and not data.empty else "Parameter"
        fig.update_layout(
                title=f"Sensitivity · {metric} vs {parameter}",
                height=430,
                xaxis_title=parameter,
                yaxis_title=metric,
                margin=dict(l=25, r=25, t=65, b=35),
        )
        if any(token in metric for token in ["Return", "Volatility", "Drawdown", "CVaR", "Turnover", "Weight"]):
                fig.update_yaxes(tickformat=".1%")
        if any(token in parameter for token in ["weight", "Turnover", "confidence"]):
                fig.update_xaxes(tickformat=".1%")
        return _pl22_polish_figure(fig, 430)


def _pl23_export_payload(
        model: dict[str, Any],
        table: pd.DataFrame,
        suite: Mapping[str, OptimizerResult],
        settings: OptimizerSettings,
        risk_aversion: float,
        robustness: float,
        resamples: int,
) -> bytes:
        allocation = _pl23_allocation_matrix(suite, model["returns"].columns)
        payload = {
                "generated_at_utc": datetime.now(timezone.utc).isoformat(),
                "portfolio_lab_version": "2.3",
                "settings": asdict(settings),
                "risk_aversion": float(risk_aversion),
                "robustness": float(robustness),
                "bootstrap_resamples": int(resamples),
                "results": table.replace({np.nan: None}).to_dict(orient="records") if isinstance(table, pd.DataFrame) else [],
                "allocations": allocation.reset_index().replace({np.nan: None}).to_dict(orient="records") if not allocation.empty else [],
        }
        return json.dumps(payload, indent=2, default=str).encode("utf-8")



def _render_optimizer_studio_v2(model: dict[str, Any]) -> dict[str, Any]:
        """Optimizer Studio 2.3 - complete multi-model construction workflow.

        All former controls, tables, method map, target publication and constrained
        efficient frontier remain available. The section adds ranking, allocation
        comparison, sensitivity, candidate review and audit exports without changing
        the underlying optimisation mathematics.
        """
        _inject_optimizer_css_v23()
        st.markdown(
                """
                <div class="pl23-hero">
                        <div class="eyebrow">Portfolio Construction · Multi-Model Optimisation · UX 2.3</div>
                        <div class="title">Optimizer Studio Decision Workspace</div>
                        <div class="copy">Configure the mandate, compare all portfolio construction methods on a common basis, inspect allocation dispersion, solve the constrained efficient frontier, test parameter sensitivity and publish only a reviewed feasible target.</div>
                </div>
                """,
                unsafe_allow_html=True,
        )

        all_methods = list(PL23_OPTIMIZER_METHODS)
        previous_settings = model.get("optimizer_suite_settings")
