                                        height=_pl22_height(filtered, minimum=260, maximum=640),
                                        column_config={
                                                "Rank": st.column_config.NumberColumn(format="%.0f"),
                                                "Composite Score": st.column_config.ProgressColumn(min_value=0.0, max_value=100.0, format="%.1f"),
                                                "Expected Return": st.column_config.NumberColumn(format="percent"),
                                                "Volatility": st.column_config.NumberColumn(format="percent"),
                                                "Max Drawdown": st.column_config.NumberColumn(format="percent"),
                                                "CVaR 95%": st.column_config.NumberColumn(format="percent"),
                                                "Tracking Error": st.column_config.NumberColumn(format="percent"),
                                                "Turnover": st.column_config.NumberColumn(format="percent"),
                                                "Effective Positions": st.column_config.NumberColumn(format="%.2f"),
                                        },
