                        metric_options = [
                                "Expected Return", "Volatility", "Sharpe", "Sortino", "Max Drawdown",
                                "CVaR 95%", "Tracking Error", "Information Ratio", "Diversification Ratio",
                                "Turnover", "Composite Score", "Effective Positions",
                        ]
                        map_controls = st.columns([1, 1, 1, 1, .65])
