                        y_metric = map_controls[1].selectbox("Y axis", metric_options, index=0, key="pl23_map_y")
                        color_metric = map_controls[2].selectbox("Colour", metric_options, index=2, key="pl23_map_color")
                        size_metric = map_controls[3].selectbox("Bubble size", metric_options, index=9, key="pl23_map_size")
                        show_labels = map_controls[4].checkbox("Labels", value=True, key="pl23_map_labels")
