                                        f'<div class="name">{selected_method_map}</div><div class="desc">{_pl23_method_description(selected_method_map)}</div>'
                                        f'<span class="pl23-score">Composite score · {_fmt_num(result_row.get("Composite Score"))}</span></div>',
                                        unsafe_allow_html=True,
