PL24_RISK_LIMIT_DEFAULTS: dict[str, float] = {
        "Maximum target volatility": 0.20,
        "Maximum target beta": 1.20,
        "Maximum tracking error": 0.15,
        "Maximum single-name risk contribution": 0.45,
        "Maximum pairwise correlation": 0.90,
        "Minimum effective risk bets": 2.00,
}


def _pl24_metric_dict(model: Mapping[str, Any], portfolio: str) -> dict[str, Any]:
        prefix = "current" if str(portfolio).lower().startswith("current") else "target"
        combined: dict[str, Any] = {}
        raw = model.get(f"{prefix}_metrics", {})
        extended = model.get(f"{prefix}_extended_metrics", {})
        if isinstance(raw, Mapping):
                combined.update(raw)
        if isinstance(extended, Mapping):
                combined.update(extended)
        return combined


def _pl24_metric_value(model: Mapping[str, Any], portfolio: str, *keys: str) -> float:
        metrics = _pl24_metric_dict(model, portfolio)
        for key in keys:
                value = _safe_float(metrics.get(key))
                if value is not None:
                        return float(value)
        return np.nan


def _pl24_clean_risk_table(table: Any, assets: Sequence[str] | None = None) -> pd.DataFrame:
        columns = [
                "Ticker", "Weight", "Standalone Vol", "Marginal Risk",
                "Component Risk", "Risk Contribution %",
        ]
        if not isinstance(table, pd.DataFrame) or table.empty:
                return pd.DataFrame(columns=columns)
        frame = table.copy()
        for column in columns:
                if column not in frame.columns:
                        frame[column] = np.nan if column != "Ticker" else ""
        frame = frame[columns]
        frame["Ticker"] = frame["Ticker"].astype(str)
        for column in columns[1:]:
                frame[column] = pd.to_numeric(frame[column], errors="coerce").fillna(0.0)
        if assets is not None:
                order = {str(asset): i for i, asset in enumerate(assets)}
                frame["__order"] = frame["Ticker"].map(order).fillna(len(order))
                frame = frame.sort_values("__order").drop(columns="__order")
        return frame.reset_index(drop=True)


def _pl24_effective_risk_bets(risk_table: pd.DataFrame) -> float:
        frame = _pl24_clean_risk_table(risk_table)
        if frame.empty:
                return np.nan
        contribution = pd.to_numeric(frame["Risk Contribution %"], errors="coerce").fillna(0.0).abs()
        total = float(contribution.sum())
        if total <= EPS:
                return np.nan
        shares = contribution / total
        denominator = float(np.square(shares).sum())
        return _safe_div(1.0, denominator)


def _pl24_risk_concentration_snapshot(risk_table: pd.DataFrame) -> dict[str, Any]:
        frame = _pl24_clean_risk_table(risk_table)
        if frame.empty:
                return {
                        "Top Contributor": "N/A", "Top Contribution": np.nan,
                        "Top Two Contribution": np.nan, "Risk HHI": np.nan,
                        "Effective Risk Bets": np.nan,
                }
        frame["Absolute Contribution"] = frame["Risk Contribution %"].abs()
        total = float(frame["Absolute Contribution"].sum())
        if total > EPS:
                frame["Share"] = frame["Absolute Contribution"] / total
        else:
                frame["Share"] = 0.0
        ranked = frame.sort_values("Share", ascending=False).reset_index(drop=True)
        return {
                "Top Contributor": str(ranked.iloc[0]["Ticker"]) if not ranked.empty else "N/A",
                "Top Contribution": float(ranked.iloc[0]["Share"]) if not ranked.empty else np.nan,
                "Top Two Contribution": float(ranked.head(2)["Share"].sum()),
                "Risk HHI": float(np.square(ranked["Share"]).sum()),
                "Effective Risk Bets": _pl24_effective_risk_bets(frame),
        }


def _pl24_risk_summary_table(model: Mapping[str, Any]) -> pd.DataFrame:
        current_risk = _pl24_clean_risk_table(model.get("current_risk", pd.DataFrame()))
        target_risk = _pl24_clean_risk_table(model.get("target_risk", pd.DataFrame()))
        current_concentration = _pl24_risk_concentration_snapshot(current_risk)
        target_concentration = _pl24_risk_concentration_snapshot(target_risk)
        specs = [
                ("Annualized Volatility", ("Annualized Volatility", "Volatility"), "percent", "lower"),
                ("Beta", ("Beta",), "number", "context"),
                ("Tracking Error", ("Tracking Error",), "percent", "lower"),
                ("Information Ratio", ("Information Ratio",), "number", "higher"),
                ("CVaR 95% (1D)", ("CVaR 95% (1D)", "CVaR 95%"), "percent", "lower"),
                ("Maximum Drawdown", ("Max Drawdown",), "percent", "higher"),
                ("Tail Ratio", ("Tail Ratio",), "number", "higher"),
                ("Ulcer Index", ("Ulcer Index",), "percent", "lower"),
                ("Downside Capture", ("Downside Capture",), "capture", "lower"),
                ("Diversification Ratio", ("Diversification Ratio",), "number", "higher"),
        ]
        rows: list[dict[str, Any]] = []
        for label, keys, display, preference in specs:
                current = _pl24_metric_value(model, "Current", *keys)
                target = _pl24_metric_value(model, "Target", *keys)
                rows.append(
                        {
                                "Metric": label,
                                "Current": current,
                                "Target": target,
                                "Delta": target - current if np.isfinite(current) and np.isfinite(target) else np.nan,
                                "Display": display,
                                "Preference": preference,
                        }
                )
        for label, key, preference in [
                ("Largest Risk Contribution", "Top Contribution", "lower"),
                ("Top-Two Risk Concentration", "Top Two Contribution", "lower"),
                ("Risk HHI", "Risk HHI", "lower"),
                ("Effective Risk Bets", "Effective Risk Bets", "higher"),
        ]:
                current = _safe_float(current_concentration.get(key))
                target = _safe_float(target_concentration.get(key))
                rows.append(
                        {
                                "Metric": label,
                                "Current": np.nan if current is None else current,
                                "Target": np.nan if target is None else target,
                                "Delta": (target - current) if current is not None and target is not None else np.nan,
                                "Display": "percent" if "Contribution" in label or "Concentration" in label or label == "Risk HHI" else "number",
                                "Preference": preference,
                        }
                )
        return pd.DataFrame(rows)


def _pl24_format_summary_table(table: pd.DataFrame) -> pd.DataFrame:
        rows: list[dict[str, Any]] = []
        for _, row in table.iterrows():
                display = str(row.get("Display", "number"))
                current = _safe_float(row.get("Current"))
                target = _safe_float(row.get("Target"))
                delta = _safe_float(row.get("Delta"))
                if display == "percent":
                        formatter = lambda value: "N/A" if value is None else f"{value:.2%}"
                        delta_text = "N/A" if delta is None else f"{delta:+.2%}"
                elif display == "capture":
                        formatter = lambda value: "N/A" if value is None else f"{value:.1f}%"
                        delta_text = "N/A" if delta is None else f"{delta:+.1f} pp"
                else:
                        formatter = lambda value: "N/A" if value is None else f"{value:.2f}"
                        delta_text = "N/A" if delta is None else f"{delta:+.2f}"
                preference = str(row.get("Preference", "context"))
                if delta is None or preference == "context":
                        assessment = "Context"
                elif (preference == "higher" and delta > 1e-12) or (preference == "lower" and delta < -1e-12):
                        assessment = "Improved"
                elif abs(delta) <= 1e-12:
                        assessment = "Unchanged"
                else:
                        assessment = "Deteriorated"
                rows.append(
                        {
                                "Metric": row.get("Metric"),
                                "Current": formatter(current),
                                "Target": formatter(target),
                                "Delta": delta_text,
                                "Assessment": assessment,
                        }
                )
        return pd.DataFrame(rows)


def _pl24_pairwise_correlation_table(correlation: pd.DataFrame) -> pd.DataFrame:
        if not isinstance(correlation, pd.DataFrame) or correlation.empty:
                return pd.DataFrame(columns=["Asset A", "Asset B", "Correlation", "Absolute Correlation"])
        matrix = correlation.apply(pd.to_numeric, errors="coerce")
        rows: list[dict[str, Any]] = []
        columns = list(matrix.columns)
        for i, left in enumerate(columns):
                for right in columns[i + 1:]:
                        value = _safe_float(matrix.loc[left, right])
                        if value is None:
                                continue
                        rows.append(
                                {
                                        "Asset A": str(left),
                                        "Asset B": str(right),
                                        "Correlation": float(value),
                                        "Absolute Correlation": abs(float(value)),
                                }
                        )
        return pd.DataFrame(rows).sort_values("Absolute Correlation", ascending=False).reset_index(drop=True)


def _pl24_cluster_order(correlation: pd.DataFrame) -> list[str]:
        """Return a stable hierarchical-clustering order for a correlation matrix.

        Pandas may expose ``DataFrame.values`` / ``to_numpy(copy=False)`` as a
        read-only view under Copy-on-Write.    Clustering needs to overwrite the
        diagonal, so always materialise a writable NumPy copy before mutation.
        """
        if not isinstance(correlation, pd.DataFrame) or correlation.empty:
                return []

        labels = [str(value) for value in correlation.columns]
        matrix_frame = (
                correlation
                .reindex(index=correlation.columns, columns=correlation.columns)
                .apply(pd.to_numeric, errors="coerce")
                .fillna(0.0)
                .clip(-1.0, 1.0)
        )

        # Explicit writable C-contiguous copy.    Do not mutate ``matrix_frame.values``.
        matrix_values = np.array(
                matrix_frame.to_numpy(dtype=float, copy=True),
                dtype=float,
                copy=True,
                order="C",
        )
        np.fill_diagonal(matrix_values, 1.0)

        if SCIPY_AVAILABLE and len(matrix_values) > 2:
                try:
                        distance = np.array(
                                np.sqrt(np.clip(0.5 * (1.0 - matrix_values), 0.0, 1.0)),
                                dtype=float,
                                copy=True,
                                order="C",
                        )
                        np.fill_diagonal(distance, 0.0)
                        condensed = squareform(distance, checks=False)
                        tree = linkage(condensed, method="average")
                        order = leaves_list(tree)
                        return [labels[int(index)] for index in order]
                except Exception:
                        # Deterministic fallback keeps the workspace available even when
                        # SciPy clustering fails because of degenerate inputs.
                        pass

        matrix = pd.DataFrame(matrix_values, index=labels, columns=labels)
        average = matrix.abs().mean(axis=1).sort_values(ascending=False)
        return [str(value) for value in average.index]


def _pl24_covariance_diagnostics(covariance: pd.DataFrame) -> tuple[pd.DataFrame, dict[str, Any]]:
        """Return stable covariance diagnostics on the stochastic sleeve.

        Deterministic cash accrual has near-zero variance. Including it in PCA
        and condition-number diagnostics creates a mechanically huge condition
        number and an uninformative zero eigenvalue even when the risky sleeve
        is numerically sound. The full matrix is still checked for PSD, while
        eigen-spectrum and conditioning are computed on assets with material
        standalone variance.
        """
        empty_columns = ["Component", "Eigenvalue", "Explained Variance", "Cumulative Variance"]
        if not isinstance(covariance, pd.DataFrame) or covariance.empty:
                return pd.DataFrame(columns=empty_columns), {}

        matrix = (
                covariance
                .reindex(index=covariance.columns, columns=covariance.columns)
                .apply(pd.to_numeric, errors="coerce")
                .fillna(0.0)
        )
        full_values = np.array(matrix.to_numpy(dtype=float, copy=True), dtype=float, copy=True)
        full_symmetric = (full_values + full_values.T) / 2.0
        full_eigenvalues = np.linalg.eigvalsh(full_symmetric)

        diagonal = np.clip(np.diag(full_symmetric), 0.0, None)
        max_variance = float(diagonal.max()) if len(diagonal) else 0.0
        variance_floor = max(1e-12, max_variance * 1e-8)
        active_mask = diagonal > variance_floor
        active_assets = [str(asset) for asset, keep in zip(matrix.index, active_mask) if keep]
        excluded_assets = [str(asset) for asset, keep in zip(matrix.index, active_mask) if not keep]

        if int(active_mask.sum()) >= 1:
                diagnostic_values = full_symmetric[np.ix_(active_mask, active_mask)]
        else:
                diagnostic_values = full_symmetric
                active_assets = [str(asset) for asset in matrix.index]
                excluded_assets = []

        eigenvalues = np.linalg.eigvalsh(diagnostic_values)
        eigenvalues = np.sort(np.clip(eigenvalues, 0.0, None))[::-1]
        total = float(eigenvalues.sum())
        explained = eigenvalues / total if total > EPS else np.zeros_like(eigenvalues)
        cumulative = np.cumsum(explained)
        table = pd.DataFrame(
                {
                        "Component": [f"PC{i + 1}" for i in range(len(eigenvalues))],
                        "Eigenvalue": eigenvalues,
                        "Explained Variance": explained,
                        "Cumulative Variance": cumulative,
                }
        )
        positive = eigenvalues[eigenvalues > max(EPS, variance_floor * 1e-4)]
        condition = float(positive.max() / positive.min()) if len(positive) else np.nan
        effective_dimension = _safe_div(total ** 2, float(np.square(eigenvalues).sum()))
        summary = {
                "Minimum Eigenvalue": float(full_eigenvalues.min()) if len(full_eigenvalues) else np.nan,
                "Condition Number": condition,
                "First PC Share": float(explained[0]) if len(explained) else np.nan,
                "First Two PC Share": float(explained[:2].sum()) if len(explained) else np.nan,
                "Effective Dimension": effective_dimension,
                "Diagnostic Assets": active_assets,
                "Excluded Near-Zero Variance Assets": excluded_assets,
                "Variance Floor": variance_floor,
        }
        return table, summary

def _pl24_shocked_covariance(covariance: pd.DataFrame, correlation_shock: float) -> pd.DataFrame:
        if not isinstance(covariance, pd.DataFrame) or covariance.empty:
                return pd.DataFrame()
        covariance = covariance.reindex(index=covariance.columns, columns=covariance.columns).apply(pd.to_numeric, errors="coerce").fillna(0.0)
        vol = np.sqrt(np.clip(np.diag(covariance.values), 0.0, None))
        denominator = np.outer(vol, vol)
        correlation = np.divide(covariance.values, denominator, out=np.zeros_like(covariance.values), where=denominator > EPS)
        correlation = np.clip(correlation, -0.99, 0.99)
        np.fill_diagonal(correlation, 1.0)
        mask = ~np.eye(len(correlation), dtype=bool)
        correlation[mask] = np.clip(correlation[mask] + float(correlation_shock), -0.99, 0.99)
        shocked = np.outer(vol, vol) * correlation
        shocked_frame = pd.DataFrame(shocked, index=covariance.index, columns=covariance.columns)
        return nearest_psd(shocked_frame)


def _pl24_portfolio_volatility(weights: pd.Series, covariance: pd.DataFrame) -> float:
        if not isinstance(covariance, pd.DataFrame) or covariance.empty:
                return np.nan
        assets = [asset for asset in covariance.columns if asset in weights.index]
        if not assets:
                return np.nan
        w = pd.to_numeric(weights.reindex(assets), errors="coerce").fillna(0.0).values
        cov = covariance.loc[assets, assets].values
        return math.sqrt(max(float(w.T @ cov @ w), 0.0))


def _pl24_rolling_risk_frame(
        portfolio_returns: pd.Series,
        benchmark_returns: pd.Series,
        window: int,
        risk_free_rate: float,
) -> pd.DataFrame:
        base = rolling_analytics(portfolio_returns, benchmark_returns, int(window), risk_free_rate)
        portfolio = pd.to_numeric(portfolio_returns, errors="coerce").rename("p")
        benchmark = pd.to_numeric(benchmark_returns, errors="coerce").rename("b")
        aligned = pd.concat([portfolio, benchmark], axis=1).dropna()
        if aligned.empty:
                return base
        active = aligned["p"] - aligned["b"]
        base.loc[aligned.index, "Rolling Tracking Error"] = active.rolling(window).std(ddof=1) * math.sqrt(TRADING_DAYS)
        base.loc[aligned.index, "Rolling Active Return"] = active.rolling(window).mean() * TRADING_DAYS
        base.loc[aligned.index, "Rolling Information Ratio"] = (
                base.loc[aligned.index, "Rolling Active Return"]
                / base.loc[aligned.index, "Rolling Tracking Error"].replace(0.0, np.nan)
        )

        def rolling_var(values: np.ndarray) -> float:
                clean = values[np.isfinite(values)]
                if len(clean) < max(20, int(window * 0.5)):
                        return np.nan
                return max(0.0, -float(np.quantile(clean, 0.05)))

        def rolling_cvar(values: np.ndarray) -> float:
                clean = values[np.isfinite(values)]
                if len(clean) < max(20, int(window * 0.5)):
                        return np.nan
                threshold = float(np.quantile(clean, 0.05))
                tail = clean[clean <= threshold]
                return max(0.0, -float(np.mean(tail))) if len(tail) else np.nan

        base["Rolling VaR 95%"] = portfolio.rolling(window).apply(rolling_var, raw=True)
        base["Rolling CVaR 95%"] = portfolio.rolling(window).apply(rolling_cvar, raw=True)
        wealth = (1.0 + portfolio.fillna(0.0)).cumprod()
        base["Drawdown"] = wealth / wealth.cummax() - 1.0
        return base


def _pl24_regime_table(rolling_target: pd.DataFrame) -> tuple[pd.DataFrame, dict[str, Any]]:
        column = "Rolling Volatility"
        if not isinstance(rolling_target, pd.DataFrame) or column not in rolling_target or rolling_target[column].dropna().empty:
                return pd.DataFrame(columns=["Regime", "Observations", "Share", "Average Volatility", "Average Beta", "Average Correlation"]), {}
        vol = pd.to_numeric(rolling_target[column], errors="coerce")
        valid = vol.dropna()
        low_cut = float(valid.quantile(0.33))
        high_cut = float(valid.quantile(0.67))
        labels = pd.Series(index=rolling_target.index, dtype=object)
        labels.loc[vol <= low_cut] = "Low volatility"
        labels.loc[(vol > low_cut) & (vol <= high_cut)] = "Normal volatility"
        labels.loc[vol > high_cut] = "High volatility"
        work = rolling_target.copy()
        work["Regime"] = labels
        rows: list[dict[str, Any]] = []
        for regime in ["Low volatility", "Normal volatility", "High volatility"]:
                sample = work.loc[work["Regime"] == regime]
                if sample.empty:
                        continue
                rows.append(
                        {
                                "Regime": regime,
                                "Observations": int(len(sample)),
                                "Share": float(len(sample) / max(len(valid), 1)),
                                "Average Volatility": float(pd.to_numeric(sample.get("Rolling Volatility"), errors="coerce").mean()),
                                "Average Beta": float(pd.to_numeric(sample.get("Rolling Beta"), errors="coerce").mean()),
                                "Average Correlation": float(pd.to_numeric(sample.get("Rolling Correlation"), errors="coerce").mean()),
                        }
                )
        latest_date = valid.index[-1]
        latest_regime = str(labels.loc[latest_date])
        percentile = float((valid <= valid.iloc[-1]).mean())
        summary = {
                "Current Regime": latest_regime,
                "Volatility Percentile": percentile,
                "Low Cut": low_cut,
                "High Cut": high_cut,
                "Latest Volatility": float(valid.iloc[-1]),
        }
        return pd.DataFrame(rows), summary


def _pl24_factor_return_panel(
        model: Mapping[str, Any],
        selected_factors: Sequence[str],
) -> tuple[pd.DataFrame, pd.DataFrame]:
        selected = [factor for factor in selected_factors if factor in FACTOR_PROXY_MAP]
        diagnostics: list[dict[str, Any]] = []
        factor_returns: dict[str, pd.Series] = {}
        settings = model.get("settings")
        period = getattr(settings, "period", "5y")
        interval = getattr(settings, "interval", "1d")
        existing_prices = model.get("prices", pd.DataFrame())
        for factor in selected:
                ticker = FACTOR_PROXY_MAP[factor]
                price = pd.Series(dtype=float)
                error = ""
                if isinstance(existing_prices, pd.DataFrame) and ticker in existing_prices.columns:
                        price = pd.to_numeric(existing_prices[ticker], errors="coerce").dropna()
                else:
                        payload = _download_single_asset(ticker, period, interval)
                        candidate = payload.get("price", pd.Series(dtype=float))
                        if isinstance(candidate, pd.Series):
                                price = pd.to_numeric(candidate, errors="coerce").dropna()
                        error = str(payload.get("error") or "")
                returns = price.pct_change(fill_method=None).dropna() if not price.empty else pd.Series(dtype=float)
                if not returns.empty:
                        factor_returns[factor] = returns
                diagnostics.append(
                        {
                                "Factor": factor,
                                "Proxy": ticker,
                                "Status": "OK" if not returns.empty else "KO",
                                "Observations": int(len(returns)),
                                "Start": returns.index.min() if not returns.empty else pd.NaT,
                                "End": returns.index.max() if not returns.empty else pd.NaT,
                                "Error": error,
                        }
                )
        panel = pd.concat(factor_returns, axis=1).sort_index() if factor_returns else pd.DataFrame()
        return panel, pd.DataFrame(diagnostics)


def _pl24_newey_west_covariance(x_design: np.ndarray, residuals: np.ndarray, lags: int) -> np.ndarray:
        n, k = x_design.shape
        bread = np.linalg.pinv(x_design.T @ x_design)
        meat = np.zeros((k, k), dtype=float)
        for t in range(n):
                xt = x_design[t][:, None]
                meat += float(residuals[t] ** 2) * (xt @ xt.T)
        for lag in range(1, max(0, int(lags)) + 1):
                weight = 1.0 - lag / (lags + 1.0)
                gamma = np.zeros((k, k), dtype=float)
                for t in range(lag, n):
                        xt = x_design[t][:, None]
                        xlag = x_design[t - lag][:, None]
                        gamma += float(residuals[t] * residuals[t - lag]) * (xt @ xlag.T)
                meat += weight * (gamma + gamma.T)
        return bread @ meat @ bread


def _pl24_fit_factor_model(
        portfolio_returns: pd.Series,
        factor_returns: pd.DataFrame,
        factor_map: Mapping[str, str],
        window: int | str,
) -> dict[str, Any]:
        portfolio = pd.to_numeric(portfolio_returns, errors="coerce").rename("Portfolio")
        factors = factor_returns.apply(pd.to_numeric, errors="coerce") if isinstance(factor_returns, pd.DataFrame) else pd.DataFrame()
        aligned = pd.concat([portfolio, factors], axis=1).dropna()
        if window != "All":
                aligned = aligned.tail(int(window))
        factor_columns = [column for column in factors.columns if column in aligned.columns]
        minimum = max(60, len(factor_columns) * 10)
        if len(aligned) < minimum or not factor_columns:
                return {
                        "exposures": pd.DataFrame(),
                        "summary": {"Warning": "Insufficient aligned observations for a stable proxy regression."},
                        "factor_correlation": pd.DataFrame(),
                        "residuals": pd.Series(dtype=float),
                }
        y = aligned["Portfolio"].values.astype(float)
        x = aligned[factor_columns].values.astype(float)
        x_design = np.column_stack([np.ones(len(x)), x])
        coefficients, _, _, _ = np.linalg.lstsq(x_design, y, rcond=None)
        fitted = x_design @ coefficients
        residuals = y - fitted
        ss_res = float(np.sum(np.square(residuals)))
        ss_total = float(np.sum(np.square(y - np.mean(y))))
        r2 = 1.0 - ss_res / ss_total if ss_total > EPS else np.nan
        adjusted_r2 = 1.0 - (1.0 - r2) * (len(y) - 1.0) / max(len(y) - len(factor_columns) - 1.0, 1.0) if np.isfinite(r2) else np.nan
        hac_lags = int(max(1, math.floor(4.0 * (len(y) / 100.0) ** (2.0 / 9.0))))
        nw_cov = _pl24_newey_west_covariance(x_design, residuals, hac_lags)
        standard_errors = np.sqrt(np.clip(np.diag(nw_cov), 0.0, None))
        t_stats = np.divide(coefficients, standard_errors, out=np.full_like(coefficients, np.nan), where=standard_errors > EPS)

        factor_covariance = aligned[factor_columns].cov().values * TRADING_DAYS
        beta = coefficients[1:]
        factor_variance = max(float(beta.T @ factor_covariance @ beta), 0.0)
        residual_variance = max(float(np.var(residuals, ddof=1) * TRADING_DAYS), 0.0)
        total_model_variance = factor_variance + residual_variance
        factor_components = beta * (factor_covariance @ beta)
        factor_risk_contribution = factor_components / total_model_variance if total_model_variance > EPS else np.zeros_like(beta)

        factor_mean = aligned[factor_columns].mean() * TRADING_DAYS
        factor_vol = aligned[factor_columns].std(ddof=1) * math.sqrt(TRADING_DAYS)
        factor_corr = aligned[factor_columns].corr()
        inverse_corr = np.linalg.pinv(factor_corr.fillna(0.0).values)
        vif = np.clip(np.diag(inverse_corr), 0.0, None)
        pair_table = _pl24_pairwise_correlation_table(factor_corr)
        max_corr = float(pair_table["Absolute Correlation"].max()) if not pair_table.empty else 0.0
        condition_number = float(np.linalg.cond(factor_corr.fillna(0.0).values)) if len(factor_corr) else np.nan

        rows: list[dict[str, Any]] = []
        for index, factor in enumerate(factor_columns):
                factor_beta = float(beta[index])
                rows.append(
                        {
                                "Factor": str(factor),
                                "Proxy": str(factor_map.get(str(factor), "")),
                                "Beta": factor_beta,
                                "HAC t-stat": float(t_stats[index + 1]),
                                "VIF": float(vif[index]) if index < len(vif) else np.nan,
                                "Annual Proxy Return": float(factor_mean[factor]),
                                "Annual Proxy Volatility": float(factor_vol[factor]),
                                "Approx. Return Contribution": factor_beta * float(factor_mean[factor]),
                                "Factor Risk Contribution %": float(factor_risk_contribution[index]),
                        }
                )
        summary = {
                "Annual Alpha": float(coefficients[0] * TRADING_DAYS),
                "Alpha HAC t-stat": float(t_stats[0]),
                "R²": r2,
                "Adjusted R²": adjusted_r2,
                "Residual Volatility": math.sqrt(residual_variance),
                "Systematic Risk Share": _safe_div(factor_variance, total_model_variance),
                "Observations": int(len(aligned)),
                "Factor Count": int(len(factor_columns)),
                "HAC Lags": int(hac_lags),
                "Condition Number": condition_number,
                "Maximum Factor Correlation": max_corr,
                "Method": "OLS on user-selected liquid ETF proxies with Newey-West/HAC diagnostics; descriptive, not a licensed factor model.",
        }
        residual_series = pd.Series(residuals, index=aligned.index, name="Residual")
        return {
                "exposures": pd.DataFrame(rows),
                "summary": summary,
                "factor_correlation": factor_corr,
                "residuals": residual_series,
        }


def _pl24_factor_results_to_payload(results: Mapping[str, Any]) -> dict[str, Any]:
        payload: dict[str, Any] = {}
        for portfolio, item in results.items():
                if not isinstance(item, Mapping):
                        continue
                payload[str(portfolio)] = {
                        "summary": dict(item.get("summary", {})) if isinstance(item.get("summary"), Mapping) else {},
                        "exposures": item.get("exposures", pd.DataFrame()),
                        "factor_correlation": item.get("factor_correlation", pd.DataFrame()),
                        "residuals": item.get("residuals", pd.Series(dtype=float)),
                }
        return payload


def _pl24_risk_limit_table(
        model: Mapping[str, Any],
        limits: Mapping[str, float],
) -> pd.DataFrame:
        target_risk = _pl24_clean_risk_table(model.get("target_risk", pd.DataFrame()))
        concentration = _pl24_risk_concentration_snapshot(target_risk)
        pair_table = _pl24_pairwise_correlation_table(model.get("correlation", pd.DataFrame()))
        max_pair = float(pair_table["Absolute Correlation"].max()) if not pair_table.empty else np.nan
        observations = [
                ("Maximum target volatility", _pl24_metric_value(model, "Target", "Annualized Volatility", "Volatility"), "max"),
                ("Maximum target beta", _pl24_metric_value(model, "Target", "Beta"), "max"),
                ("Maximum tracking error", _pl24_metric_value(model, "Target", "Tracking Error"), "max"),
                ("Maximum single-name risk contribution", _safe_float(concentration.get("Top Contribution")), "max"),
                ("Maximum pairwise correlation", max_pair, "max"),
                ("Minimum effective risk bets", _safe_float(concentration.get("Effective Risk Bets")), "min"),
        ]
        rows: list[dict[str, Any]] = []
        for name, value, direction in observations:
                limit = float(limits.get(name, PL24_RISK_LIMIT_DEFAULTS[name]))
                observed = np.nan if value is None else float(value)
                passed = bool(np.isfinite(observed) and ((observed <= limit + 1e-12) if direction == "max" else (observed >= limit - 1e-12)))
                rows.append(
                        {
                                "Risk Limit": name,
                                "Observed": observed,
                                "Limit": limit,
                                "Direction": "\u2264" if direction == "max" else "\u2265",
                                "Status": "PASS" if passed else "BREACH",
                        }
                )
        return pd.DataFrame(rows)


def _pl24_risk_budget_comparison_figure(current: pd.DataFrame, target: pd.DataFrame) -> go.Figure:
        current = _pl24_clean_risk_table(current)
        target = _pl24_clean_risk_table(target)
        assets = list(dict.fromkeys(current["Ticker"].tolist() + target["Ticker"].tolist()))
        current_map = current.set_index("Ticker")["Risk Contribution %"] if not current.empty else pd.Series(dtype=float)
        target_map = target.set_index("Ticker")["Risk Contribution %"] if not target.empty else pd.Series(dtype=float)
        figure = go.Figure()
        figure.add_trace(go.Bar(name="Current", x=assets, y=[float(current_map.get(asset, 0.0)) for asset in assets], marker_color="#64748b"))
        figure.add_trace(go.Bar(name="Target", x=assets, y=[float(target_map.get(asset, 0.0)) for asset in assets], marker_color="#8b5cf6"))
        figure.update_layout(title="Risk Budget Comparison", barmode="group", height=430, yaxis_tickformat=".0%", margin=dict(l=20, r=20, t=60, b=35), legend=dict(orientation="h"))
        return figure


def _pl24_capital_vs_risk_figure(weights: pd.Series, risk_table: pd.DataFrame, title: str) -> go.Figure:
        risk = _pl24_clean_risk_table(risk_table)
        assets = list(weights.index)
        risk_map = risk.set_index("Ticker")["Risk Contribution %"] if not risk.empty else pd.Series(dtype=float)
        figure = go.Figure()
        figure.add_trace(go.Bar(name="Capital weight", y=assets, x=weights.reindex(assets).fillna(0.0), orientation="h", marker_color="#64748b"))
        figure.add_trace(go.Bar(name="Risk contribution", y=assets, x=[float(risk_map.get(asset, 0.0)) for asset in assets], orientation="h", marker_color="#f59e0b"))
        figure.update_layout(title=title, barmode="group", height=max(380, 55 * len(assets) + 130), xaxis_tickformat=".0%", margin=dict(l=20, r=20, t=60, b=35), legend=dict(orientation="h"))
        return figure


def _pl24_active_risk_delta_figure(current: pd.DataFrame, target: pd.DataFrame) -> go.Figure:
        current = _pl24_clean_risk_table(current)
        target = _pl24_clean_risk_table(target)
        assets = list(dict.fromkeys(current["Ticker"].tolist() + target["Ticker"].tolist()))
        current_map = current.set_index("Ticker")["Risk Contribution %"] if not current.empty else pd.Series(dtype=float)
        target_map = target.set_index("Ticker")["Risk Contribution %"] if not target.empty else pd.Series(dtype=float)
        delta = pd.Series({asset: float(target_map.get(asset, 0.0) - current_map.get(asset, 0.0)) for asset in assets}).sort_values()
        colors = ["#22c55e" if value < 0 else "#ef4444" for value in delta.values]
        figure = go.Figure(go.Bar(x=delta.values, y=delta.index, orientation="h", marker_color=colors))
        figure.update_layout(title="Change in Risk Contribution · Target vs Current", height=max(380, 55 * len(delta) + 130), xaxis_tickformat="+.1%", margin=dict(l=20, r=20, t=60, b=35))
        return figure


def _pl24_group_risk_figure(current_group: pd.DataFrame, target_group: pd.DataFrame, dimension: str) -> go.Figure:
        groups = list(dict.fromkeys(current_group.get(dimension, pd.Series(dtype=str)).astype(str).tolist() + target_group.get(dimension, pd.Series(dtype=str)).astype(str).tolist()))
        current_map = current_group.set_index(dimension)["Risk Contribution %"] if not current_group.empty else pd.Series(dtype=float)
        target_map = target_group.set_index(dimension)["Risk Contribution %"] if not target_group.empty else pd.Series(dtype=float)
        figure = go.Figure()
        figure.add_trace(go.Bar(name="Current", y=groups, x=[float(current_map.get(group, 0.0)) for group in groups], orientation="h", marker_color="#64748b"))
        figure.add_trace(go.Bar(name="Target", y=groups, x=[float(target_map.get(group, 0.0)) for group in groups], orientation="h", marker_color="#8b5cf6"))
        figure.update_layout(title=f"Risk Contribution by {dimension}", barmode="group", height=max(380, 48 * len(groups) + 130), xaxis_tickformat=".0%", margin=dict(l=20, r=20, t=60, b=35), legend=dict(orientation="h"))
        return figure


def _pl24_matrix_figure(matrix: pd.DataFrame, title: str, correlation: bool) -> go.Figure:
        values = matrix.values if isinstance(matrix, pd.DataFrame) else np.empty((0, 0))
        figure = go.Figure(
                go.Heatmap(
                        z=values,
                        x=list(matrix.columns) if isinstance(matrix, pd.DataFrame) else [],
                        y=list(matrix.index) if isinstance(matrix, pd.DataFrame) else [],
                        colorscale="RdBu",
                        zmid=0.0,
                        zmin=-1.0 if correlation else None,
                        zmax=1.0 if correlation else None,
                        text=np.round(values, 2 if correlation else 5),
                        texttemplate="%{text}",
                        hovertemplate="%{y} / %{x}<br>%{z:.4f}<extra></extra>",
                )
        )
        figure.update_layout(title=title, height=max(480, 48 * len(matrix) + 160), margin=dict(l=20, r=20, t=60, b=35))
        return figure


def _pl24_eigen_figure(table: pd.DataFrame) -> go.Figure:
        figure = go.Figure()
        if isinstance(table, pd.DataFrame) and not table.empty:
                figure.add_trace(go.Bar(name="Explained variance", x=table["Component"], y=table["Explained Variance"], marker_color="#38bdf8"))
                figure.add_trace(go.Scatter(name="Cumulative variance", x=table["Component"], y=table["Cumulative Variance"], mode="lines+markers", yaxis="y2", line=dict(color="#a78bfa")))
        figure.update_layout(title="Covariance Eigen-Spectrum", height=430, yaxis=dict(title="Explained variance", tickformat=".0%"), yaxis2=dict(title="Cumulative", tickformat=".0%", overlaying="y", side="right", range=[0, 1.05]), margin=dict(l=20, r=20, t=60, b=35), legend=dict(orientation="h"))
        return figure


def _pl24_rolling_metric_figure(
        current: pd.DataFrame,
        target: pd.DataFrame,
        metric: str,
        title: str,
) -> go.Figure:
        figure = go.Figure()
        for name, frame, color in [("Current", current, "#64748b"), ("Target", target, "#38bdf8")]:
                if isinstance(frame, pd.DataFrame) and metric in frame.columns:
                        figure.add_trace(go.Scatter(x=frame.index, y=frame[metric], mode="lines", name=name, line=dict(color=color)))
        figure.update_layout(title=title, height=430, margin=dict(l=20, r=20, t=60, b=35), hovermode="x unified", legend=dict(orientation="h"))
        if any(token in metric for token in ["Volatility", "Tracking Error", "VaR", "CVaR", "Return", "Drawdown"]):
                figure.update_yaxes(tickformat=".1%")
        return figure


def _pl24_factor_beta_figure(results: Mapping[str, Any]) -> go.Figure:
        figure = go.Figure()
        palette = {"Current": "#64748b", "Target": "#8b5cf6"}
        factors: list[str] = []
        for item in results.values():
                exposures = item.get("exposures", pd.DataFrame()) if isinstance(item, Mapping) else pd.DataFrame()
                if isinstance(exposures, pd.DataFrame) and not exposures.empty:
                        factors.extend(exposures["Factor"].astype(str).tolist())
        factors = list(dict.fromkeys(factors))
        for portfolio, item in results.items():
                exposures = item.get("exposures", pd.DataFrame()) if isinstance(item, Mapping) else pd.DataFrame()
                if not isinstance(exposures, pd.DataFrame) or exposures.empty:
                        continue
                beta_map = exposures.set_index("Factor")["Beta"]
                figure.add_trace(go.Bar(name=str(portfolio), y=factors, x=[float(beta_map.get(factor, 0.0)) for factor in factors], orientation="h", marker_color=palette.get(str(portfolio), "#38bdf8")))
        figure.update_layout(title="Proxy Factor Betas", barmode="group", height=max(430, 48 * len(factors) + 150), margin=dict(l=20, r=20, t=60, b=35), legend=dict(orientation="h"))
        return figure


def _pl24_factor_contribution_figure(results: Mapping[str, Any], column: str, title: str) -> go.Figure:
        figure = go.Figure()
        palette = {"Current": "#64748b", "Target": "#8b5cf6"}
        factors: list[str] = []
        for item in results.values():
                exposures = item.get("exposures", pd.DataFrame()) if isinstance(item, Mapping) else pd.DataFrame()
                if isinstance(exposures, pd.DataFrame) and not exposures.empty:
                        factors.extend(exposures["Factor"].astype(str).tolist())
        factors = list(dict.fromkeys(factors))
        for portfolio, item in results.items():
                exposures = item.get("exposures", pd.DataFrame()) if isinstance(item, Mapping) else pd.DataFrame()
                if not isinstance(exposures, pd.DataFrame) or exposures.empty or column not in exposures.columns:
                        continue
                value_map = exposures.set_index("Factor")[column]
                figure.add_trace(go.Bar(name=str(portfolio), y=factors, x=[float(value_map.get(factor, 0.0)) for factor in factors], orientation="h", marker_color=palette.get(str(portfolio), "#38bdf8")))
        figure.update_layout(title=title, barmode="group", height=max(430, 48 * len(factors) + 150), margin=dict(l=20, r=20, t=60, b=35), legend=dict(orientation="h"))
        if "Contribution" in column:
                figure.update_xaxes(tickformat=".1%")
        return figure


def _pl24_json_safe(value: Any) -> Any:
        """Convert nested pandas/NumPy objects into strict JSON-safe values.

        ``json.dumps(default=...)`` can convert unsupported dictionary values,
        but it cannot repair unsupported dictionary keys.  Factor residual
        series use ``Timestamp`` indices; converting such a Series with
        ``to_dict()`` therefore creates Timestamp keys and raises
        ``TypeError: keys must be str, int, float, bool or None``.

        This serializer preserves DataFrame/Series indexes explicitly instead
        of silently dropping them and converts every mapping key to text.
        """
        if value is None:
                return None

        if isinstance(value, (str, bool, int)):
                return value

        if isinstance(value, float):
                return value if np.isfinite(value) else None

        if isinstance(value, np.integer):
                return int(value)

        if isinstance(value, np.floating):
                number = float(value)
                return number if np.isfinite(number) else None

        if isinstance(value, (pd.Timestamp, datetime, np.datetime64)):
                timestamp = pd.Timestamp(value)
                return None if pd.isna(timestamp) else timestamp.isoformat()

        if isinstance(value, (pd.Timedelta, np.timedelta64)):
                delta = pd.Timedelta(value)
                return None if pd.isna(delta) else delta.isoformat()

        if isinstance(value, pd.DataFrame):
                frame = value.copy()
                include_index = not isinstance(frame.index, pd.RangeIndex)
                index_field = str(frame.index.name or "__index__")
                if index_field in {str(column) for column in frame.columns}:
                        index_field = "__index__"
                records: list[dict[str, Any]] = []
                for index, row in frame.iterrows():
                        record = {
                                str(column): _pl24_json_safe(row[column])
                                for column in frame.columns
                        }
                        if include_index:
                                record[index_field] = _pl24_json_safe(index)
                        records.append(record)
                return records

        if isinstance(value, pd.Series):
                return {
                        "name": None if value.name is None else str(value.name),
                        "records": [
                                {
                                        "index": _pl24_json_safe(index),
                                        "value": _pl24_json_safe(item),
                                }
                                for index, item in value.items()
                        ],
                }

        if isinstance(value, pd.Index):
                return [_pl24_json_safe(item) for item in value.tolist()]

        if isinstance(value, np.ndarray):
                return _pl24_json_safe(value.tolist())

        if isinstance(value, Mapping):
                return {
                        str(_pl24_json_safe(key)): _pl24_json_safe(item)
                        for key, item in value.items()
                }

        if isinstance(value, (list, tuple, set)):
                return [_pl24_json_safe(item) for item in value]

        try:
                missing = pd.isna(value)
                if isinstance(missing, (bool, np.bool_)) and bool(missing):
                        return None
        except Exception:
                pass

        return str(value)


def _pl24_risk_export_payload(
        model: Mapping[str, Any],
        summary_table: pd.DataFrame,
        limit_table: pd.DataFrame,
        factor_results: Mapping[str, Any],
        factor_diagnostics: pd.DataFrame,
) -> bytes:
        payload = {
                "module": "Portfolio Lab 2.4 Risk & Factors",
                "generated_at_utc": _utc_now_iso(),
                "valuation_date": model.get("returns", pd.DataFrame()).index.max() if isinstance(model.get("returns"), pd.DataFrame) and not model.get("returns").empty else None,
                "risk_summary": summary_table,
                "risk_limits": limit_table,
                "current_risk": model.get("current_risk", pd.DataFrame()),
                "target_risk": model.get("target_risk", pd.DataFrame()),
                "correlation": model.get("correlation", pd.DataFrame()),
                "covariance": model.get("covariance", pd.DataFrame()),
                "factor_results": _pl24_factor_results_to_payload(factor_results),
                "factor_data_diagnostics": factor_diagnostics,
                "methodology": {
                        "risk_decomposition": "Euler decomposition of annualised covariance risk.",
                        "rolling_risk": "Historical rolling estimates on aligned daily returns.",
                        "factor_model": "Descriptive OLS on liquid ETF proxies with HAC diagnostics; not a licensed commercial factor model.",
                },
        }
        safe_payload = _pl24_json_safe(payload)
        return json.dumps(
                safe_payload,
                indent=2,
                ensure_ascii=False,
                allow_nan=False,
        ).encode("utf-8")


