def _render_risk_factors_v2(model: dict[str, Any]) -> None:
        _pl24_inject_risk_styles()
        model = enhance_model_v2(model)
        model.setdefault("factor_results_v24", {})
        model.setdefault("factor_diagnostics_v24", pd.DataFrame())
        st.markdown(
                """
                <div class="pl24-risk-hero">
                    <div class="pl24-risk-kicker">Whole-portfolio risk · decomposition · dependence · factors · UX 2.4</div>
                    <div class="pl24-risk-title">Institutional Risk & Factor Decision Workspace</div>
                    <div class="pl24-risk-copy">Move from top-line volatility to a governed view of where risk originates, how dependencies can fail, how the target changes the risk budget, and which liquid proxy factors explain the portfolio. All original Risk & Factors information remains available inside the structured workflow.</div>
                </div>
                """,
                unsafe_allow_html=True,
        )

        current_risk = _pl24_clean_risk_table(model.get("current_risk", pd.DataFrame()), model["returns"].columns)
        target_risk = _pl24_clean_risk_table(model.get("target_risk", pd.DataFrame()), model["returns"].columns)
        model["current_risk"] = current_risk
        model["target_risk"] = target_risk
        current_concentration = _pl24_risk_concentration_snapshot(current_risk)
        target_concentration = _pl24_risk_concentration_snapshot(target_risk)
        summary_table = _pl24_risk_summary_table(model)

        status_chips = [
                f'<span class="pl24-chip">Assets · {len(model["returns"].columns)}</span>',
                f'<span class="pl24-chip">Observations · {len(model["returns"])}</span>',
                f'<span class="pl24-chip">Target beta · {_fmt_num(_pl24_metric_value(model, "Target", "Beta"))}</span>',
                f'<span class="pl24-chip">Target volatility · {_fmt_pct(_pl24_metric_value(model, "Target", "Annualized Volatility", "Volatility"))}</span>',
                f'<span class="pl24-chip">Effective risk bets · {_fmt_num(target_concentration.get("Effective Risk Bets"))}</span>',
                f'<span class="pl24-chip">Top target risk · {target_concentration.get("Top Contributor", "N/A")} · {_fmt_pct(target_concentration.get("Top Contribution"))}</span>',
        ]
        st.markdown('<div class="pl24-chip-row">' + ''.join(status_chips) + '</div>', unsafe_allow_html=True)

        overview_tab, decomposition_tab, dependence_tab, rolling_tab, factor_tab, governance_tab = st.tabs(
                [
                        "01 · Risk Overview",
                        "02 · Decomposition & Exposures",
                        "03 · Correlation & Concentration",
                        "04 · Rolling Risk & Regimes",
                        "05 · Factor Lab",
                        "06 · Governance & Export",
                ]
        )

        with overview_tab:
                st.markdown('<div class="pl24-section-title">Executive Risk Overview</div>', unsafe_allow_html=True)
                st.markdown('<div class="pl24-section-copy">A concise current-versus-target risk view, followed by deterministic mandate checks. Limits are monitoring thresholds, not an optimisation mandate unless also configured in Optimizer Studio.</div>', unsafe_allow_html=True)
                target_metrics = _pl24_metric_dict(model, "Target")
                current_metrics = _pl24_metric_dict(model, "Current")
                cards = st.columns(6)
                cards[0].metric("Target volatility", _fmt_pct(_pl24_metric_value(model, "Target", "Annualized Volatility", "Volatility")), delta=_fmt_pct(_pl24_metric_value(model, "Target", "Annualized Volatility", "Volatility") - _pl24_metric_value(model, "Current", "Annualized Volatility", "Volatility")))
                cards[1].metric("Target beta", _fmt_num(target_metrics.get("Beta")), delta=_fmt_num(_pl24_metric_value(model, "Target", "Beta") - _pl24_metric_value(model, "Current", "Beta")))
                cards[2].metric("Tracking error", _fmt_pct(target_metrics.get("Tracking Error")), delta=_fmt_pct(_pl24_metric_value(model, "Target", "Tracking Error") - _pl24_metric_value(model, "Current", "Tracking Error")))
                cards[3].metric("CVaR 95% · 1D", _fmt_pct(target_metrics.get("CVaR 95% (1D)")), delta=_fmt_pct(_pl24_metric_value(model, "Target", "CVaR 95% (1D)") - _pl24_metric_value(model, "Current", "CVaR 95% (1D)")))
                cards[4].metric("Tail ratio", _fmt_num(target_metrics.get("Tail Ratio")), delta=_fmt_num(_pl24_metric_value(model, "Target", "Tail Ratio") - _pl24_metric_value(model, "Current", "Tail Ratio")))
                cards[5].metric("Effective risk bets", _fmt_num(target_concentration.get("Effective Risk Bets")), delta=_fmt_num((_safe_float(target_concentration.get("Effective Risk Bets")) or np.nan) - (_safe_float(current_concentration.get("Effective Risk Bets")) or np.nan)))

                left, right = st.columns(2)
                with left:
                        with st.container(border=True):
                                st.plotly_chart(_pl24_risk_budget_comparison_figure(current_risk, target_risk), width="stretch", key="pl24_overview_risk_budget")
                with right:
                        with st.container(border=True):
                                st.plotly_chart(_pl24_active_risk_delta_figure(current_risk, target_risk), width="stretch", key="pl24_overview_risk_delta")

                comparison_left, comparison_right = st.columns([1.15, .85])
                with comparison_left:
                        with st.container(border=True):
                                st.markdown('<div class="pl24-section-title">Current vs Target Risk Metrics</div>', unsafe_allow_html=True)
                                st.dataframe(_pl24_format_summary_table(summary_table), width="stretch", hide_index=True, height=560)
                with comparison_right:
                        with st.container(border=True):
                                st.markdown('<div class="pl24-section-title">Risk Monitoring Limits</div>', unsafe_allow_html=True)
                                limit_inputs = {
                                        "Maximum target volatility": st.number_input("Maximum target volatility", min_value=0.01, max_value=2.00, value=float(st.session_state.get("pl24_limit_vol", PL24_RISK_LIMIT_DEFAULTS["Maximum target volatility"])), step=0.01, format="%.2f", key="pl24_limit_vol"),
                                        "Maximum target beta": st.number_input("Maximum target beta", min_value=-5.0, max_value=10.0, value=float(st.session_state.get("pl24_limit_beta", PL24_RISK_LIMIT_DEFAULTS["Maximum target beta"])), step=0.05, key="pl24_limit_beta"),
                                        "Maximum tracking error": st.number_input("Maximum tracking error", min_value=0.0, max_value=2.0, value=float(st.session_state.get("pl24_limit_te", PL24_RISK_LIMIT_DEFAULTS["Maximum tracking error"])), step=0.01, format="%.2f", key="pl24_limit_te"),
                                        "Maximum single-name risk contribution": st.number_input("Maximum single-name risk contribution", min_value=0.01, max_value=1.5, value=float(st.session_state.get("pl24_limit_single_rc", PL24_RISK_LIMIT_DEFAULTS["Maximum single-name risk contribution"])), step=0.01, format="%.2f", key="pl24_limit_single_rc"),
                                        "Maximum pairwise correlation": st.number_input("Maximum pairwise correlation", min_value=0.0, max_value=1.0, value=float(st.session_state.get("pl24_limit_corr", PL24_RISK_LIMIT_DEFAULTS["Maximum pairwise correlation"])), step=0.01, format="%.2f", key="pl24_limit_corr"),
                                        "Minimum effective risk bets": st.number_input("Minimum effective risk bets", min_value=1.0, max_value=float(max(2, len(model["returns"].columns))), value=float(st.session_state.get("pl24_limit_effective", min(PL24_RISK_LIMIT_DEFAULTS["Minimum effective risk bets"], float(max(2, len(model["returns"].columns)))))), step=0.25, key="pl24_limit_effective"),
                                }
                                limit_table = _pl24_risk_limit_table(model, limit_inputs)
                                st.dataframe(limit_table, width="stretch", hide_index=True, height=305, column_config={"Observed": st.column_config.NumberColumn(format="%.4f"), "Limit": st.column_config.NumberColumn(format="%.4f")})
                                breach_count = int((limit_table["Status"] == "BREACH").sum())
                                if breach_count:
                                        st.warning(f"{breach_count} deterministic monitoring limit(s) breached. Review the target before publication or execution.")
                                else:
                                        st.success("All configured risk monitoring limits pass.")
                st.session_state["pl24_risk_limit_table"] = limit_table

        with decomposition_tab:
                st.markdown('<div class="pl24-section-title">Risk Decomposition & Exposure Drill-Down</div>', unsafe_allow_html=True)
                st.markdown('<div class="pl24-section-copy">Euler risk contribution is reconciled to total portfolio volatility. Group views preserve net exposure, gross exposure, position count and risk contribution.</div>', unsafe_allow_html=True)
                dimension = st.radio("Risk view", ["Asset", "Asset Class", "Sector", "Strategy", "Currency"], horizontal=True, key="pl24_risk_dimension")
                if dimension == "Asset":
                        left, right = st.columns(2)
                        with left:
                                with st.container(border=True):
                                        st.plotly_chart(_pl24_capital_vs_risk_figure(model["current_weights"], current_risk, "Current Capital Weight vs Risk Contribution"), width="stretch", key="pl24_current_capital_risk")
                        with right:
                                with st.container(border=True):
                                        st.plotly_chart(_pl24_capital_vs_risk_figure(model["target_weights"], target_risk, "Target Capital Weight vs Risk Contribution"), width="stretch", key="pl24_target_capital_risk")
                        combined = pd.concat([current_risk.assign(Portfolio="Current"), target_risk.assign(Portfolio="Target")], ignore_index=True)
                        with st.container(border=True):
                                st.dataframe(
                                        combined,
                                        width="stretch", hide_index=True,
                                        height=_pl22_height(combined, minimum=330, maximum=650),
                                        column_config={
                                                "Weight": st.column_config.ProgressColumn(min_value=float(min(-1.0, combined["Weight"].min())), max_value=float(max(1.0, combined["Weight"].max())), format="percent"),
                                                "Standalone Vol": st.column_config.NumberColumn(format="percent"),
                                                "Marginal Risk": st.column_config.NumberColumn(format="percent"),
                                                "Component Risk": st.column_config.NumberColumn(format="percent"),
                                                "Risk Contribution %": st.column_config.ProgressColumn(min_value=float(min(-1.0, combined["Risk Contribution %"].min())), max_value=float(max(1.0, combined["Risk Contribution %"].max())), format="percent"),
                                        },
                                )
                else:
                        current_group = group_exposure_and_risk(model["book"], model["current_weights"], current_risk, dimension)
                        target_group = group_exposure_and_risk(model["book"], model["target_weights"], target_risk, dimension)
                        left, right = st.columns([1.05, .95])
                        with left:
                                with st.container(border=True):
                                        st.plotly_chart(_pl24_group_risk_figure(current_group, target_group, dimension), width="stretch", key=f"pl24_group_risk_{dimension.lower().replace(' ', '_')}")
                        with right:
                                combined = pd.concat([current_group.assign(Portfolio="Current"), target_group.assign(Portfolio="Target")], ignore_index=True)
                                with st.container(border=True):
                                        st.dataframe(combined, width="stretch", hide_index=True, height=_pl22_height(combined, minimum=390, maximum=620), column_config={"Net Weight": st.column_config.NumberColumn(format="percent"), "Gross Weight": st.column_config.NumberColumn(format="percent"), "Risk Contribution %": st.column_config.ProgressColumn(min_value=float(min(-1.0, combined["Risk Contribution %"].min())), max_value=float(max(1.0, combined["Risk Contribution %"].max())), format="percent")})

                st.markdown('<div class="pl24-section-title">Risk Concentration Snapshot</div>', unsafe_allow_html=True)
                concentration_table = pd.DataFrame(
                        [
                                {"Portfolio": "Current", **current_concentration},
                                {"Portfolio": "Target", **target_concentration},
                        ]
                )
                st.dataframe(concentration_table, width="stretch", hide_index=True, column_config={"Top Contribution": st.column_config.NumberColumn(format="percent"), "Top Two Contribution": st.column_config.NumberColumn(format="percent"), "Risk HHI": st.column_config.NumberColumn(format="percent")})

        with dependence_tab:
                st.markdown('<div class="pl24-section-title">Correlation, Covariance & Concentration Risk</div>', unsafe_allow_html=True)
                st.markdown('<div class="pl24-section-copy">Inspect pairwise dependence, covariance principal components and the sensitivity of portfolio volatility to a broad correlation shift.</div>', unsafe_allow_html=True)
                matrix_choice = st.radio("Matrix", ["Correlation", "Covariance"], horizontal=True, key="pl24_matrix_choice")
                clustered = st.checkbox("Cluster assets by dependence", value=True, key="pl24_cluster_matrix")
                raw_correlation = model["correlation"].copy()
                valid_correlation_assets = [
                        asset for asset in raw_correlation.columns
                        if asset in raw_correlation.index and np.isfinite(_safe_float(raw_correlation.loc[asset, asset], np.nan))
                ]
                excluded_correlation_assets = [asset for asset in raw_correlation.columns if asset not in valid_correlation_assets]
                diagnostic_correlation = raw_correlation.reindex(index=valid_correlation_assets, columns=valid_correlation_assets)

                if matrix_choice == "Correlation":
                        matrix = diagnostic_correlation
                        order = _pl24_cluster_order(diagnostic_correlation) if clustered else list(matrix.columns)
                else:
                        matrix = model["covariance"]
                        clustered_risky = _pl24_cluster_order(diagnostic_correlation) if clustered else valid_correlation_assets
                        order = list(clustered_risky) + [asset for asset in matrix.columns if asset not in clustered_risky]
                matrix = matrix.reindex(index=order, columns=order)
                with st.container(border=True):
                        st.plotly_chart(_pl24_matrix_figure(matrix, f"{matrix_choice} Matrix" + (" · Clustered" if clustered else ""), matrix_choice == "Correlation"), width="stretch", key="pl24_dependence_matrix")
                        if matrix_choice == "Correlation" and excluded_correlation_assets:
                                st.caption(
                                        "Correlation is undefined for deterministic or near-zero-variance assets. "
                                        f"Excluded from this heatmap: {', '.join(map(str, excluded_correlation_assets))}. "
                                        "They remain included in portfolio weights, risk decomposition and covariance exports."
                                )
                matrix_left, matrix_right = st.columns([1.05, .95])
                pair_table = _pl24_pairwise_correlation_table(diagnostic_correlation)
                eigen_table, eigen_summary = _pl24_covariance_diagnostics(model["covariance"])
                with matrix_left:
                        with st.container(border=True):
                                st.markdown('<div class="pl24-section-title">Highest Pairwise Correlations</div>', unsafe_allow_html=True)
                                st.dataframe(pair_table.head(20), width="stretch", hide_index=True, height=430, column_config={"Correlation": st.column_config.NumberColumn(format="%.3f"), "Absolute Correlation": st.column_config.ProgressColumn(min_value=0.0, max_value=1.0, format="%.3f")})
                with matrix_right:
                        with st.container(border=True):
                                st.plotly_chart(_pl24_eigen_figure(eigen_table), width="stretch", key="pl24_eigen_spectrum")
                                eigen_cards = st.columns(3)
                                eigen_cards[0].metric("First PC share", _fmt_pct(eigen_summary.get("First PC Share")))
                                eigen_cards[1].metric("Effective dimension", _fmt_num(eigen_summary.get("Effective Dimension")))
                                eigen_cards[2].metric("Condition number", _fmt_num(eigen_summary.get("Condition Number")))

                with st.container(border=True):
                        st.markdown('<div class="pl24-section-title">Correlation Shock What-If</div>', unsafe_allow_html=True)
                        correlation_shock = st.slider("Parallel off-diagonal correlation shift", -0.50, 0.50, 0.00, 0.01, key="pl24_corr_shock")
                        shocked_covariance = _pl24_shocked_covariance(model["covariance"], correlation_shock)
                        current_base_vol = _pl24_portfolio_volatility(model["current_weights"], model["covariance"])
                        target_base_vol = _pl24_portfolio_volatility(model["target_weights"], model["covariance"])
                        current_shocked_vol = _pl24_portfolio_volatility(model["current_weights"], shocked_covariance)
                        target_shocked_vol = _pl24_portfolio_volatility(model["target_weights"], shocked_covariance)
                        shock_cards = st.columns(4)
                        shock_cards[0].metric("Current base vol", _fmt_pct(current_base_vol))
                        shock_cards[1].metric("Current shocked vol", _fmt_pct(current_shocked_vol), delta=_fmt_pct(current_shocked_vol - current_base_vol))
                        shock_cards[2].metric("Target base vol", _fmt_pct(target_base_vol))
                        shock_cards[3].metric("Target shocked vol", _fmt_pct(target_shocked_vol), delta=_fmt_pct(target_shocked_vol - target_base_vol))
                        st.caption("This is a covariance what-if that shifts all off-diagonal correlations and repairs the resulting covariance matrix to positive semi-definite form.")

        with rolling_tab:
                st.markdown('<div class="pl24-section-title">Rolling Risk Diagnostics & Regime Context</div>', unsafe_allow_html=True)
                st.markdown('<div class="pl24-section-copy">Historical rolling estimates help identify unstable risk, beta, correlation, active risk and tail behaviour. Regime labels are deterministic volatility terciles, not forecasts.</div>', unsafe_allow_html=True)
                rolling_controls = st.columns([1.0, 1.2, 1.2])
                window = rolling_controls[0].select_slider("Rolling window", options=[21, 63, 126, 252, 504], value=126, key="pl24_rolling_window")
                metric_one = rolling_controls[1].selectbox("Primary metric", ["Rolling Volatility", "Rolling Beta", "Rolling Correlation", "Rolling Tracking Error", "Rolling Information Ratio", "Rolling CVaR 95%", "Drawdown"], index=0, key="pl24_rolling_metric_one")
                metric_two = rolling_controls[2].selectbox("Secondary metric", ["Rolling Beta", "Rolling Correlation", "Rolling Tracking Error", "Rolling Information Ratio", "Rolling CVaR 95%", "Rolling Volatility", "Drawdown"], index=0, key="pl24_rolling_metric_two")
                rolling_current = _pl24_rolling_risk_frame(model["current_return_series"], model["benchmark_returns"], int(window), model["settings"].risk_free_rate)
                rolling_target = _pl24_rolling_risk_frame(model["target_return_series"], model["benchmark_returns"], int(window), model["settings"].risk_free_rate)
                left, right = st.columns(2)
                with left:
                        with st.container(border=True):
                                st.plotly_chart(_pl24_rolling_metric_figure(rolling_current, rolling_target, metric_one, metric_one), width="stretch", key="pl24_rolling_primary")
                with right:
                        with st.container(border=True):
                                st.plotly_chart(_pl24_rolling_metric_figure(rolling_current, rolling_target, metric_two, metric_two), width="stretch", key="pl24_rolling_secondary")
                regime_table, regime_summary = _pl24_regime_table(rolling_target)
                regime_cards = st.columns(5)
                regime_cards[0].metric("Current regime", regime_summary.get("Current Regime", "N/A"))
                regime_cards[1].metric("Volatility percentile", _fmt_pct(regime_summary.get("Volatility Percentile")))
                regime_cards[2].metric("Latest rolling vol", _fmt_pct(regime_summary.get("Latest Volatility")))
                regime_cards[3].metric("Low-vol cut", _fmt_pct(regime_summary.get("Low Cut")))
                regime_cards[4].metric("High-vol cut", _fmt_pct(regime_summary.get("High Cut")))
                with st.container(border=True):
                        st.dataframe(regime_table, width="stretch", hide_index=True, column_config={"Share": st.column_config.NumberColumn(format="percent"), "Average Volatility": st.column_config.NumberColumn(format="percent"), "Average Beta": st.column_config.NumberColumn(format="%.3f"), "Average Correlation": st.column_config.NumberColumn(format="%.3f")})

        with factor_tab:
                st.markdown('<div class="pl24-section-title">ETF Proxy Factor Lab</div>', unsafe_allow_html=True)
                st.markdown('<div class="pl24-section-copy">A descriptive multi-factor regression on user-selected liquid ETF proxies with Newey-West/HAC inference, factor collinearity diagnostics and approximate factor-risk decomposition. It is not a licensed Barra, MAC3, Axioma or Bloomberg factor model.</div>', unsafe_allow_html=True)
                selected_factors = st.multiselect(
                        "Factor proxies",
                        list(FACTOR_PROXY_MAP.keys()),
                        default=["US Market", "US Small Cap", "US Value", "Momentum", "Quality", "Long Rates", "High Yield Credit", "Gold"],
                        key="pl24_factor_selection",
                )
                factor_controls = st.columns([1.0, 1.0, 1.0])
                factor_window = factor_controls[0].selectbox("Factor window", [252, 504, 756, 1260, "All"], index=2, key="pl24_factor_window")
                factor_scope = factor_controls[1].selectbox("Portfolio scope", ["Current & Target", "Target only", "Current only"], index=0, key="pl24_factor_scope")
                run_factor = factor_controls[2].button("Run factor proxy model", type="primary", width="stretch", key="pl24_factor_run")
                if run_factor:
                        with st.spinner("Downloading factor proxies and estimating HAC factor models..."):
                                factor_panel, factor_diagnostics = _pl24_factor_return_panel(model, selected_factors)
                                results: dict[str, Any] = {}
                                if factor_scope in {"Current & Target", "Current only"}:
                                        results["Current"] = _pl24_fit_factor_model(model["current_return_series"], factor_panel, FACTOR_PROXY_MAP, factor_window)
                                if factor_scope in {"Current & Target", "Target only"}:
                                        results["Target"] = _pl24_fit_factor_model(model["target_return_series"], factor_panel, FACTOR_PROXY_MAP, factor_window)
                                model["factor_results_v24"] = results
                                model["factor_diagnostics_v24"] = factor_diagnostics
                                # Preserve the original public fields for cross-module compatibility.
                                preferred = results.get("Target") or results.get("Current") or {}
                                model["factor_exposures"] = preferred.get("exposures", pd.DataFrame()) if isinstance(preferred, Mapping) else pd.DataFrame()
                                model["factor_summary"] = preferred.get("summary", {}) if isinstance(preferred, Mapping) else {}
                                model["factor_diagnostics"] = factor_diagnostics
                                st.session_state["portfolio_lab_model_v1"] = model
                factor_results = model.get("factor_results_v24", {})
                factor_diagnostics = model.get("factor_diagnostics_v24", pd.DataFrame())
                if not isinstance(factor_results, Mapping) or not factor_results:
                        legacy_exposures = model.get("factor_exposures", pd.DataFrame())
                        legacy_summary = model.get("factor_summary", {})
                        if isinstance(legacy_exposures, pd.DataFrame) and not legacy_exposures.empty:
                                factor_results = {"Target": {"exposures": legacy_exposures, "summary": legacy_summary, "factor_correlation": pd.DataFrame(), "residuals": pd.Series(dtype=float)}}
                available_results = {name: item for name, item in factor_results.items() if isinstance(item, Mapping) and isinstance(item.get("exposures"), pd.DataFrame) and not item.get("exposures").empty}
                if not available_results:
                        st.markdown('<div class="pl24-empty"><strong>Factor model not estimated</strong><br>Choose liquid proxies and run the model. Results are stored in the Portfolio Lab model for the current session.</div>', unsafe_allow_html=True)
                else:
                        summary_rows: list[dict[str, Any]] = []
                        for portfolio, item in available_results.items():
                                summary = item.get("summary", {})
                                summary_rows.append({"Portfolio": portfolio, **dict(summary)})
                        summary_frame = pd.DataFrame(summary_rows)
                        metric_cards = st.columns(6)
                        preferred_name = "Target" if "Target" in available_results else next(iter(available_results))
                        preferred_summary = available_results[preferred_name].get("summary", {})
                        metric_cards[0].metric(f"{preferred_name} alpha", _fmt_pct(preferred_summary.get("Annual Alpha")))
                        metric_cards[1].metric("R²", _fmt_pct(preferred_summary.get("R²")))
                        metric_cards[2].metric("Adjusted R²", _fmt_pct(preferred_summary.get("Adjusted R²")))
                        metric_cards[3].metric("Residual volatility", _fmt_pct(preferred_summary.get("Residual Volatility")))
                        metric_cards[4].metric("Systematic risk share", _fmt_pct(preferred_summary.get("Systematic Risk Share")))
                        metric_cards[5].metric("Observations", preferred_summary.get("Observations", "N/A"))
                        charts = st.columns(2)
                        with charts[0]:
                                with st.container(border=True):
                                        st.plotly_chart(_pl24_factor_beta_figure(available_results), width="stretch", key="pl24_factor_betas")
                        with charts[1]:
                                with st.container(border=True):
                                        factor_metric = st.radio("Contribution view", ["Factor Risk Contribution %", "Approx. Return Contribution"], horizontal=True, key="pl24_factor_contribution_view")
                                        st.plotly_chart(_pl24_factor_contribution_figure(available_results, factor_metric, factor_metric), width="stretch", key="pl24_factor_contributions")
                        factor_table_tabs = st.tabs(["Exposure estimates", "Model summary", "Factor correlation", "Residual diagnostics", "Factor data diagnostics"])
                        with factor_table_tabs[0]:
                                exposure_frames = []
                                for portfolio, item in available_results.items():
                                        frame = item.get("exposures", pd.DataFrame()).copy()
                                        frame["Portfolio"] = portfolio
                                        exposure_frames.append(frame)
                                exposure_table = pd.concat(exposure_frames, ignore_index=True) if exposure_frames else pd.DataFrame()
                                st.dataframe(exposure_table, width="stretch", hide_index=True, height=_pl22_height(exposure_table, minimum=360, maximum=650), column_config={"Annual Proxy Return": st.column_config.NumberColumn(format="percent"), "Annual Proxy Volatility": st.column_config.NumberColumn(format="percent"), "Approx. Return Contribution": st.column_config.NumberColumn(format="percent"), "Factor Risk Contribution %": st.column_config.NumberColumn(format="percent")})
                        with factor_table_tabs[1]:
                                st.dataframe(summary_frame, width="stretch", hide_index=True)
                                warnings: list[str] = []
                                for portfolio, item in available_results.items():
                                        summary = item.get("summary", {})
                                        if (_safe_float(summary.get("Maximum Factor Correlation")) or 0.0) > 0.85:
                                                warnings.append(f"{portfolio}: high proxy correlation may make individual betas unstable.")
                                        if (_safe_float(summary.get("Condition Number")) or 0.0) > 100.0:
                                                warnings.append(f"{portfolio}: factor correlation matrix is ill-conditioned.")
                                        if (_safe_float(summary.get("R²")) or 0.0) > 0.98:
                                                warnings.append(f"{portfolio}: very high R² may reflect overlapping ETF holdings and should not be interpreted as causal factor identification.")
                                for warning in warnings:
                                        st.warning(warning)
                        with factor_table_tabs[2]:
                                selected_portfolio = st.selectbox("Correlation model", list(available_results), key="pl24_factor_corr_portfolio")
                                factor_corr = available_results[selected_portfolio].get("factor_correlation", pd.DataFrame())
                                if isinstance(factor_corr, pd.DataFrame) and not factor_corr.empty:
                                        st.plotly_chart(_pl24_matrix_figure(factor_corr, f"{selected_portfolio} Factor Correlation", True), width="stretch", key="pl24_factor_corr_matrix")
                                        st.dataframe(_pl24_pairwise_correlation_table(factor_corr), width="stretch", hide_index=True)
                                else:
                                        st.info("Factor correlation matrix is unavailable for the stored legacy result. Rerun the 2.4 factor model.")
                        with factor_table_tabs[3]:
                                selected_portfolio = st.selectbox("Residual model", list(available_results), key="pl24_factor_residual_portfolio")
                                residuals = available_results[selected_portfolio].get("residuals", pd.Series(dtype=float))
                                if isinstance(residuals, pd.Series) and not residuals.empty:
                                        residual_frame = pd.DataFrame(index=residuals.index)
                                        residual_frame["Cumulative Residual"] = residuals.cumsum()
                                        residual_frame["Rolling Residual Volatility"] = residuals.rolling(63).std(ddof=1) * math.sqrt(TRADING_DAYS)
                                        residual_charts = st.columns(2)
                                        with residual_charts[0]:
                                                fig = go.Figure(go.Scatter(x=residual_frame.index, y=residual_frame["Cumulative Residual"], mode="lines", line=dict(color="#38bdf8")))
                                                fig.update_layout(title="Cumulative Factor-Model Residual", height=390, yaxis_tickformat=".1%", margin=dict(l=20, r=20, t=60, b=35))
                                                st.plotly_chart(fig, width="stretch", key="pl24_factor_residual_cumulative")
                                        with residual_charts[1]:
                                                fig = go.Figure(go.Scatter(x=residual_frame.index, y=residual_frame["Rolling Residual Volatility"], mode="lines", line=dict(color="#a78bfa")))
                                                fig.update_layout(title="63-Day Residual Volatility", height=390, yaxis_tickformat=".1%", margin=dict(l=20, r=20, t=60, b=35))
                                                st.plotly_chart(fig, width="stretch", key="pl24_factor_residual_vol")
                                else:
                                        st.info("Residual series is unavailable for the stored legacy result. Rerun the 2.4 factor model.")
                        with factor_table_tabs[4]:
                                st.dataframe(factor_diagnostics, width="stretch", hide_index=True)

        with governance_tab:
                st.markdown('<div class="pl24-section-title">Risk Governance, Data Quality & Export</div>', unsafe_allow_html=True)
                st.markdown('<div class="pl24-section-copy">A reproducible audit surface for covariance integrity, benchmark coverage, risk reconciliation, proxy-factor data and downstream publication.</div>', unsafe_allow_html=True)
                limit_table = st.session_state.get("pl24_risk_limit_table", _pl24_risk_limit_table(model, PL24_RISK_LIMIT_DEFAULTS))
                factor_results = model.get("factor_results_v24", {}) if isinstance(model.get("factor_results_v24", {}), Mapping) else {}
                factor_diagnostics = model.get("factor_diagnostics_v24", pd.DataFrame())
                eigen_table, eigen_summary = _pl24_covariance_diagnostics(model["covariance"])
                current_rc_sum = float(current_risk["Risk Contribution %"].sum()) if not current_risk.empty else np.nan
                target_rc_sum = float(target_risk["Risk Contribution %"].sum()) if not target_risk.empty else np.nan
                diagnostics = pd.DataFrame(
                        [
                                {"Control": "Return observations", "Value": len(model["returns"]), "Status": "PASS" if len(model["returns"]) >= MIN_OBSERVATIONS else "BREACH", "Method": f"Minimum {MIN_OBSERVATIONS}"},
                                {"Control": "Benchmark observations", "Value": len(model.get("benchmark_returns", pd.Series(dtype=float)).dropna()), "Status": "PASS" if len(model.get("benchmark_returns", pd.Series(dtype=float)).dropna()) >= MIN_OBSERVATIONS else "BREACH", "Method": "Aligned benchmark history"},
                                {"Control": "Covariance minimum eigenvalue", "Value": eigen_summary.get("Minimum Eigenvalue"), "Status": "PASS" if (_safe_float(eigen_summary.get("Minimum Eigenvalue")) or -1.0) >= -1e-8 else "BREACH", "Method": "Positive semi-definite check"},
                                {"Control": "Covariance condition number", "Value": eigen_summary.get("Condition Number"), "Status": "PASS" if (_safe_float(eigen_summary.get("Condition Number")) or np.inf) < 1e8 else "WARNING", "Method": "Stochastic sleeve positive-eigenvalue ratio"},
                                {"Control": "Near-zero variance assets excluded from dependence diagnostics", "Value": ", ".join(eigen_summary.get("Excluded Near-Zero Variance Assets", [])) or "None", "Status": "INFO", "Method": "Cash remains in portfolio risk and exports"},
                                {"Control": "Current risk reconciliation", "Value": current_rc_sum, "Status": "PASS" if np.isfinite(current_rc_sum) and abs(current_rc_sum - 1.0) < 1e-6 else "BREACH", "Method": "Sum of Euler risk contributions"},
                                {"Control": "Target risk reconciliation", "Value": target_rc_sum, "Status": "PASS" if np.isfinite(target_rc_sum) and abs(target_rc_sum - 1.0) < 1e-6 else "BREACH", "Method": "Sum of Euler risk contributions"},
                                {"Control": "Risk monitoring limits", "Value": int((limit_table["Status"] == "BREACH").sum()) if isinstance(limit_table, pd.DataFrame) and not limit_table.empty else np.nan, "Status": "PASS" if isinstance(limit_table, pd.DataFrame) and not limit_table.empty and not (limit_table["Status"] == "BREACH").any() else "WARNING", "Method": "User-configured deterministic limits"},
                                {"Control": "Factor model", "Value": len(factor_results), "Status": "PASS" if factor_results else "NOT RUN", "Method": "ETF proxy OLS/HAC"},
                        ]
                )
                governance_left, governance_right = st.columns([1.15, .85])
                with governance_left:
                        with st.container(border=True):
                                st.dataframe(diagnostics, width="stretch", hide_index=True, height=400)
                with governance_right:
                        with st.container(border=True):
                                st.markdown('<div class="pl24-section-title">Methodology Boundary</div>', unsafe_allow_html=True)
                                st.markdown(
                                        '<div class="pl24-note"><strong>Ex-ante covariance risk</strong><br>Risk budgets use the selected annualised covariance estimator and Euler decomposition.<br><br><strong>Historical rolling risk</strong><br>Rolling beta, correlation, tracking error and tail estimates are backward-looking and window-sensitive.<br><br><strong>ETF proxy factors</strong><br>Factor results describe statistical co-movement with liquid proxies. They are not proprietary fundamental factor exposures or causal estimates.</div>',
                                        unsafe_allow_html=True,
                                )
                export_tabs = st.tabs(["Risk summary", "Risk limits", "Current decomposition", "Target decomposition", "Correlation", "Covariance", "Factor data"])
                with export_tabs[0]:
                        st.dataframe(_pl24_format_summary_table(summary_table), width="stretch", hide_index=True)
                with export_tabs[1]:
                        st.dataframe(limit_table, width="stretch", hide_index=True)
                with export_tabs[2]:
                        st.dataframe(current_risk, width="stretch", hide_index=True)
                with export_tabs[3]:
                        st.dataframe(target_risk, width="stretch", hide_index=True)
                with export_tabs[4]:
                        st.dataframe(model["correlation"], width="stretch")
                with export_tabs[5]:
                        st.dataframe(model["covariance"], width="stretch")
                with export_tabs[6]:
                        st.dataframe(factor_diagnostics, width="stretch", hide_index=True)

                downloads = st.columns(4)
                downloads[0].download_button("Download risk summary CSV", summary_table.to_csv(index=False).encode("utf-8"), file_name="risk_summary_v24.csv", mime="text/csv", width="stretch", key="pl24_download_risk_summary")
                downloads[1].download_button("Download target decomposition CSV", target_risk.to_csv(index=False).encode("utf-8"), file_name="target_risk_decomposition_v24.csv", mime="text/csv", width="stretch", key="pl24_download_target_risk")
                downloads[2].download_button("Download correlation CSV", model["correlation"].to_csv().encode("utf-8"), file_name="portfolio_correlation_v24.csv", mime="text/csv", width="stretch", key="pl24_download_correlation")
                downloads[3].download_button("Download risk audit JSON", _pl24_risk_export_payload(model, summary_table, limit_table, factor_results, factor_diagnostics), file_name="risk_factor_audit_v24.json", mime="application/json", width="stretch", key="pl24_download_audit")

                publish_left, publish_right = st.columns(2)
                if publish_left.button("Publish risk context to Risk Monitor", type="primary", width="stretch", key="pl24_publish_risk_monitor"):
                        context = publish_portfolio_context(model)
                        context["Risk Summary v2.4"] = summary_table.to_dict(orient="records")
                        context["Risk Limits v2.4"] = limit_table.to_dict(orient="records")
                        context["Factor Results v2.4"] = _pl24_factor_results_to_payload(factor_results)
                        st.session_state["risk_monitor_portfolio_context"] = context
                        st.success("Risk and factor context published to Risk Monitor.")
                if publish_right.button("Publish risk context to Decision Engine", width="stretch", key="pl24_publish_decision_engine"):
                        context = publish_portfolio_context(model)
                        context["Risk Summary v2.4"] = summary_table.to_dict(orient="records")
                        context["Risk Limits v2.4"] = limit_table.to_dict(orient="records")
                        context["Factor Results v2.4"] = _pl24_factor_results_to_payload(factor_results)
                        st.session_state["decision_engine_portfolio_context"] = context
                        st.success("Risk and factor context published to Decision Engine.")

        model["risk_summary_v24"] = summary_table
        model["risk_limits_v24"] = st.session_state.get("pl24_risk_limit_table", pd.DataFrame())
        model["risk_factor_context_v24"] = {
                "summary": summary_table,
                "limits": model["risk_limits_v24"],
                "factor_results": model.get("factor_results_v24", {}),
        }
        st.session_state["portfolio_lab_model_v1"] = model

def _render_performance_lab_v2(model: dict[str, Any]) -> None:
        st.subheader("Rebalanced Performance Lab")
        controls = st.columns(5)
        frequency = controls[0].selectbox("Rebalancing", ["Buy & Hold", "Annual", "Quarterly", "Monthly", "Weekly", "Daily"], index=2, key="pl_perf_frequency_v2")
        cost_bps = controls[1].number_input("Transaction cost (bps)", min_value=0.0, max_value=500.0, value=5.0, step=1.0, key="pl_perf_cost_v2")
        band = controls[2].number_input("Rebalance band", min_value=0.0, max_value=0.25, value=0.0, step=0.005, format="%.3f", key="pl_perf_band_v2")
        start_value = controls[3].number_input("Starting value", min_value=1.0, value=float(model["nav"]), step=10_000.0, key="pl_perf_start_v2")
        rolling_window = controls[4].selectbox("Rolling window", [21, 63, 126, 252, 504], index=3, key="pl_perf_rolling_v2")

        current_sim = simulate_rebalanced_portfolio(model["returns"], model["current_weights"], rebalance_frequency=frequency, transaction_cost_bps=float(cost_bps), rebalance_band=float(band), initial_value=float(start_value))
        target_sim = simulate_rebalanced_portfolio(model["returns"], model["target_weights"], rebalance_frequency=frequency, transaction_cost_bps=float(cost_bps), rebalance_band=float(band), initial_value=float(start_value))
        benchmark = model["benchmark_returns"].reindex(target_sim["returns"].index)
        current_metrics = extended_performance_metrics(current_sim["returns"], benchmark, model["settings"].risk_free_rate)
        target_metrics = extended_performance_metrics(target_sim["returns"], benchmark, model["settings"].risk_free_rate)

        c1, c2, c3, c4, c5, c6 = st.columns(6)
        c1.metric("Target CAGR", _fmt_pct(target_metrics.get("CAGR")))
        c2.metric("Target Sharpe", _fmt_num(target_metrics.get("Sharpe")))
        c3.metric("Target Sortino", _fmt_num(target_metrics.get("Sortino")))
        c4.metric("Target Max DD", _fmt_pct(target_metrics.get("Max Drawdown")))
        c5.metric("Total Turnover", _fmt_pct(float(target_sim["turnover"].sum())))
        c6.metric("Total Costs", _fmt_money(float(target_sim["costs"].sum())))

        benchmark_series = benchmark.dropna()
        st.plotly_chart(
                _performance_growth_figure(
                        {"Current": current_sim["returns"], "Target": target_sim["returns"], "Benchmark": benchmark_series},
                        f"Portfolio Growth · {frequency} Rebalancing",
                ),
                width="stretch",
        )
        st.dataframe(_format_extended_metrics_table(current_metrics, target_metrics), width="stretch", hide_index=True)

        annual = annual_return_table({"Current": current_sim["returns"], "Target": target_sim["returns"], "Benchmark": benchmark_series})
        if not annual.empty:
                fig = go.Figure()
                for column in annual.columns:
                        fig.add_trace(go.Bar(name=column, x=annual.index.astype(str), y=annual[column]))
                fig.update_layout(title="Calendar-Year Returns", barmode="group", height=450, yaxis_tickformat=".0%", margin=dict(l=20, r=20, t=60, b=30))
                st.plotly_chart(fig, width="stretch")

        rolling_current = rolling_analytics(current_sim["returns"], benchmark_series, int(rolling_window), model["settings"].risk_free_rate)
        rolling_target = rolling_analytics(target_sim["returns"], benchmark_series, int(rolling_window), model["settings"].risk_free_rate)
        left, right = st.columns(2)
        left.plotly_chart(_rolling_figure({"Current": rolling_current, "Target": rolling_target}, "Rolling Sharpe", "Rolling Sharpe"), width="stretch")
        right.plotly_chart(_rolling_figure({"Current": rolling_current, "Target": rolling_target}, "Rolling Return", "Rolling Return"), width="stretch")
        st.plotly_chart(_drawdown_figure({"Current": current_sim["returns"], "Target": target_sim["returns"], "Benchmark": benchmark_series}, "Drawdown Path"), width="stretch")

        heat_left, heat_right = st.columns(2)
        heat_left.plotly_chart(_monthly_heatmap_figure(monthly_return_matrix(current_sim["returns"]), "Current Monthly Returns"), width="stretch")
        heat_right.plotly_chart(_monthly_heatmap_figure(monthly_return_matrix(target_sim["returns"]), "Target Monthly Returns"), width="stretch")

        st.subheader("Drawdown episodes")
        episodes = drawdown_episodes(target_sim["returns"])
        if not episodes.empty:
                display = episodes.copy()
                display["Depth"] = display["Depth"].apply(_fmt_pct)
                st.dataframe(display, width="stretch", hide_index=True)
        else:
                st.info("No target drawdown episode detected in the selected history.")


def _render_attribution_v2(model: dict[str, Any]) -> None:
        st.subheader("Performance Attribution")
        horizon = st.selectbox("Attribution window", [21, 63, 126, 252, 504, "All"], index=3, key="pl_attr_horizon_v2")
        returns = model["returns"] if horizon == "All" else model["returns"].tail(int(horizon))
        current_table, current_groups = static_attribution(returns, model["current_weights"], model["book"])
        target_table, target_groups = static_attribution(returns, model["target_weights"], model["book"])
        view = st.radio("Attribution dimension", ["Asset", "Asset Class", "Sector", "Strategy", "Currency"], horizontal=True, key="pl_attr_view_v2")

        if view == "Asset":
                current_table["Portfolio"] = "Current"
                target_table["Portfolio"] = "Target"
                combined = pd.concat([current_table, target_table], ignore_index=True)
                st.dataframe(combined, width="stretch", hide_index=True)
                plot_data = target_table.sort_values("Arithmetic Contribution")
                fig = go.Figure(go.Bar(x=plot_data["Arithmetic Contribution"], y=plot_data["Ticker"], orientation="h"))
        else:
                current_group = current_groups.get(view, pd.DataFrame()).copy()
                target_group = target_groups.get(view, pd.DataFrame()).copy()
                current_group["Portfolio"] = "Current"
                target_group["Portfolio"] = "Target"
                st.dataframe(pd.concat([current_group, target_group], ignore_index=True), width="stretch", hide_index=True)
                plot_data = target_group.sort_values("Contribution")
                fig = go.Figure(go.Bar(x=plot_data["Contribution"], y=plot_data[view], orientation="h"))
        fig.update_layout(title="Target Arithmetic Contribution", height=470, xaxis_tickformat=".1%", margin=dict(l=20, r=20, t=60, b=30))
        st.plotly_chart(fig, width="stretch")

        st.subheader("Contribution through time")
        target_weighted = returns.mul(model["target_weights"].reindex(returns.columns).fillna(0.0), axis=1)
        cumulative_contributions = target_weighted.cumsum()
        fig = go.Figure()
        for column in cumulative_contributions.columns:
                fig.add_trace(go.Scatter(x=cumulative_contributions.index, y=cumulative_contributions[column], mode="lines", stackgroup="one", name=column))
        fig.update_layout(title="Cumulative Arithmetic Contribution", height=500, yaxis_tickformat=".1%", margin=dict(l=20, r=20, t=60, b=30), hovermode="x unified")
        st.plotly_chart(fig, width="stretch")
        st.caption("Attribution is holdings/static-weight based. Transaction-level Brinson, Carino and fixed-income attribution require dated holdings, benchmark constituent weights and cash-flow data.")


def _render_rebalance_tca_v2(model: dict[str, Any]) -> None:
        st.subheader("Rebalancing & Transaction Cost Analysis")
        if model.get("rebalancing", pd.DataFrame()).empty:
                st.info("Apply an optimizer or a what-if target to generate the rebalancing blotter.")
                return

        controls = st.columns(4)
        spread_bps = controls[0].number_input("Half-spread / fees (bps)", min_value=0.0, max_value=500.0, value=5.0, step=1.0, key="pl_tca_spread_v2")
        impact_bps = controls[1].number_input("Impact coefficient (bps)", min_value=0.0, max_value=1000.0, value=35.0, step=5.0, key="pl_tca_impact_v2")
        participation_limit = controls[2].slider("Daily ADV participation", 0.01, 0.50, 0.10, 0.01, key="pl_tca_participation_v2")
        urgency = controls[3].slider("Urgency multiplier", 0.50, 3.00, 1.00, 0.10, key="pl_tca_urgency_v2")

        table = build_tca_workbench(
                model,
                spread_bps=float(spread_bps),
                impact_coefficient_bps=float(impact_bps),
                daily_participation_limit=float(participation_limit),
                urgency_multiplier=float(urgency),
        )
        if table.empty:
                st.info("No executable trade was generated.")
                return

        total_turnover = 0.5 * float(pd.to_numeric(table["Weight Delta"], errors="coerce").abs().sum())
        total_trade = float(pd.to_numeric(table["Trade Value"], errors="coerce").abs().sum())
        total_cost = float(pd.to_numeric(table["TCA Cost"], errors="coerce").sum())
        max_days = float(pd.to_numeric(table["Days to Liquidate"], errors="coerce").max())
        c1, c2, c3, c4, c5 = st.columns(5)
        c1.metric("Turnover", _fmt_pct(total_turnover))
        c2.metric("Gross Trade", _fmt_money(total_trade))
        c3.metric("Estimated TCA Cost", _fmt_money(total_cost))
        c4.metric("Cost / NAV", _fmt_pct(_safe_div(total_cost, model["nav"], 0.0)))
        c5.metric("Max Days to Liquidate", "N/A" if not np.isfinite(max_days) else f"{max_days:.1f}")

        display = table.copy()
        for column in ["Current Weight", "Target Weight", "Executable Weight", "Weight Delta", "ADV20 Participation", "Participation"]:
                if column in display.columns:
                        display[column] = display[column].apply(_fmt_pct)
        for column in ["Trade Value", "Estimated Cost", "ADV20 Value", "TCA Cost"]:
                if column in display.columns:
                        display[column] = display[column].apply(_fmt_money)
        st.dataframe(display, width="stretch", hide_index=True)

        active = table.loc[pd.to_numeric(table["Trade Value"], errors="coerce").abs() > 0.0].copy()
        if not active.empty:
                fig = go.Figure()
                fig.add_trace(go.Bar(name="Trade Value", x=active["Ticker"], y=active["Trade Value"]))
                fig.update_layout(title="Order Blotter", height=430, margin=dict(l=20, r=20, t=60, b=30))
                st.plotly_chart(fig, width="stretch")

                cost_fig = go.Figure(go.Bar(x=active["Ticker"], y=active["All-in Cost bps"]))
                cost_fig.update_layout(title="Estimated All-in Cost by Order", height=390, yaxis_title="bps", margin=dict(l=20, r=20, t=60, b=30))
                st.plotly_chart(cost_fig, width="stretch")

        flags = table.loc[(pd.to_numeric(table["Participation"], errors="coerce") > float(participation_limit)) | (pd.to_numeric(table["Days to Liquidate"], errors="coerce") > 1.0)]
        if not flags.empty:
                st.warning("At least one order exceeds the selected participation limit or requires more than one trading day. Stage execution and review signal decay.")

        if st.button("Publish blotter to Trading Plan", type="primary", width="stretch", key="pl_publish_blotter_v2"):
                payload = publish_portfolio_context(model)
                payload["TCA Workbench"] = table.to_dict(orient="records")
                st.session_state["trading_plan_portfolio_context"] = payload
                st.success("Rebalancing and TCA payload published to Trading Plan.")


