def _render_signal_hub_v2(model: dict[str, Any], analysis: Mapping[str, Any] | None, ticker_hint: str | None) -> dict[str, Any]:
        st.subheader("Terminal Signal Hub")
        st.caption("Connect Decision Engine, Momentum, ML, Company Intelligence, Macro, Risk Monitor, Backtest Lab and Options/Futures through a governed signal contract.")

        import_cols = st.columns([2, 1, 1])
        uploaded = import_cols[0].file_uploader("Import signal CSV", type=["csv"], key="pl_signal_upload_v2")
        if uploaded is not None:
                try:
                        imported = pd.read_csv(uploaded)
                        st.session_state[SIGNAL_IMPORT_KEY] = imported
                        st.success("Signal CSV loaded. Expected columns can include Source, Ticker, Score, Direction, Expected Return, Confidence, Horizon and Risk Multiplier.")
                except Exception as exc:
                        st.error(f"Signal CSV import failed: {exc}")
        if import_cols[1].button("Clear bus", width="stretch", key="pl_signal_clear_v2"):
                clear_terminal_signal_bus()
                st.session_state.pop(SIGNAL_IMPORT_KEY, None)
                st.rerun()
        if import_cols[2].button("Refresh discovery", width="stretch", key="pl_signal_refresh_v2"):
                st.rerun()

        signals = collect_terminal_signals(model["book"], analysis, ticker_hint)
        if signals.empty:
                st.info("No module signal is currently available for the portfolio tickers. Modules can call publish_terminal_signal(...) or export a compatible session-state payload.")
        else:
                display_signals = signals.copy()
                display_signals["Expected Return"] = display_signals["Expected Return"].apply(_fmt_pct)
                display_signals["Confidence"] = display_signals["Confidence"].apply(_fmt_pct)
                st.dataframe(display_signals, width="stretch", hide_index=True)

        st.subheader("Source governance")
        sources = sorted(set(DEFAULT_SIGNAL_SOURCE_WEIGHTS) | set(signals["Source"].tolist() if not signals.empty else []))
        source_frame = pd.DataFrame({"Source": sources, "Weight": [DEFAULT_SIGNAL_SOURCE_WEIGHTS.get(source, 0.50) for source in sources]})
        edited_sources = st.data_editor(
                source_frame,
                hide_index=True,
                width="stretch",
                key="pl_signal_source_weights_v2",
                column_config={"Weight": st.column_config.NumberColumn(min_value=0.0, max_value=3.0, format="%.2f")},
        )
        maximum_tilt = st.slider("Maximum annual expected-return tilt", 0.00, 0.25, 0.08, 0.01, key="pl_signal_max_tilt_v2")
        source_weights = {str(row["Source"]): float(row["Weight"]) for _, row in edited_sources.iterrows()}
        consensus, adjusted = aggregate_terminal_signals(signals, model["expected_returns"], source_weights, maximum_tilt)

        if not consensus.empty:
                left, right = st.columns([1, 1.2])
                left.plotly_chart(_signal_consensus_figure(consensus), width="stretch")
                display = consensus.copy()
                for column in ["Signal Tilt", "Baseline Expected Return", "Adjusted Expected Return"]:
                        display[column] = display[column].apply(_fmt_pct)
                right.dataframe(display, width="stretch", hide_index=True)

                apply_cols = st.columns([1, 1, 2])
                if apply_cols[0].button("Apply alpha overlay", type="primary", width="stretch", key="pl_signal_apply_v2"):
                        updated = dict(model)
                        updated["baseline_expected_returns"] = model.get("baseline_expected_returns", model["expected_returns"].copy())
                        updated["expected_returns"] = adjusted
                        updated["signal_consensus"] = consensus
                        updated["signal_records"] = signals
                        updated = enhance_model_v2(updated)
                        st.session_state["portfolio_lab_model_v1"] = updated
                        st.success("Signal overlay applied to expected returns. Re-run the optimizer suite to convert it into target weights.")
                        st.rerun()
                if apply_cols[1].button("Reset alpha overlay", width="stretch", key="pl_signal_reset_v2"):
                        updated = dict(model)
                        if "baseline_expected_returns" in updated:
                                updated["expected_returns"] = updated["baseline_expected_returns"].copy()
                        updated["signal_consensus"] = pd.DataFrame()
                        updated = enhance_model_v2(updated)
                        st.session_state["portfolio_lab_model_v1"] = updated
                        st.rerun()
                apply_cols[2].caption("Risk multipliers are displayed for governance but are not automatically converted into position sizes; the optimizer remains subject to explicit portfolio constraints.")

        st.subheader("Integration contract")
        st.code(
                """from portfolio_lab import publish_terminal_signal\n\npublish_terminal_signal(\n        source=\"Decision Engine\",\n        ticker=ticker,\n        score=signal_score,                    # normalized to [-1, 1]\n        direction=signal,                      # BUY / SELL / NEUTRAL\n        expected_return=forecast,      # annual decimal, optional\n        confidence=confidence,            # [0, 1]\n        horizon=\"3M\",\n        risk_multiplier=1.0,\n        notes=reason,\n)""",
                language="python",
        )
        return model


