def _pl210_normal_cdf(value: float) -> float:
        if not np.isfinite(value):
                return np.nan
        return 0.5 * (1.0 + math.erf(float(value) / math.sqrt(2.0)))


def _pl210_effective_positions(weights: pd.Series) -> float:
        clean = pd.to_numeric(weights, errors="coerce").fillna(0.0).abs()
        gross = float(clean.sum())
        if gross <= EPS:
                return 0.0
        normalized = clean / gross
        concentration = float(np.square(normalized).sum())
        return _safe_div(1.0, concentration, 0.0)


def _pl210_probabilistic_sharpe(returns: pd.Series, benchmark_sharpe: float = 0.0) -> float:
        clean = pd.to_numeric(returns, errors="coerce").dropna()
        if len(clean) < 8 or float(clean.std(ddof=1)) <= EPS:
                return np.nan
        annualization = float(_periods_per_year(clean.index))
        period_sharpe = float(clean.mean() / clean.std(ddof=1))
        benchmark_period = float(benchmark_sharpe) / math.sqrt(max(annualization, 1.0))
        skewness = float(clean.skew()) if len(clean) > 2 else 0.0
        kurtosis = float(clean.kurt()) + 3.0 if len(clean) > 3 else 3.0
        variance_term = 1.0 - skewness * period_sharpe + ((kurtosis - 1.0) / 4.0) * period_sharpe ** 2
        if variance_term <= EPS:
                return np.nan
        standard_error = math.sqrt(variance_term / max(len(clean) - 1, 1))
        if standard_error <= EPS:
                return np.nan
        return _pl210_normal_cdf((period_sharpe - benchmark_period) / standard_error)


def _pl210_wilson_interval(successes: int, observations: int, confidence: float = 0.95) -> tuple[float, float]:
        if observations <= 0:
                return np.nan, np.nan
        z = 1.959963984540054 if confidence >= 0.95 else 1.6448536269514722
        proportion = float(successes) / float(observations)
        denominator = 1.0 + z ** 2 / observations
        centre = (proportion + z ** 2 / (2.0 * observations)) / denominator
        half_width = z * math.sqrt((proportion * (1.0 - proportion) / observations) + z ** 2 / (4.0 * observations ** 2)) / denominator
        return max(0.0, centre - half_width), min(1.0, centre + half_width)


def _pl210_prepare_history(model: Mapping[str, Any]) -> tuple[pd.DataFrame, pd.Series]:
        raw = model.get("returns", pd.DataFrame())
        if not isinstance(raw, pd.DataFrame) or raw.empty:
                return pd.DataFrame(), pd.Series(dtype=float)
        returns = raw.copy()
        returns.index = pd.to_datetime(returns.index, errors="coerce")
        returns = returns.loc[~returns.index.isna()]
        returns = returns.loc[~returns.index.duplicated(keep="last")].sort_index()
        returns = returns.apply(pd.to_numeric, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna(how="any")
        benchmark = pd.to_numeric(model.get("benchmark_returns", pd.Series(dtype=float)), errors="coerce")
        benchmark.index = pd.to_datetime(benchmark.index, errors="coerce")
        benchmark = benchmark.loc[~benchmark.index.isna()]
        benchmark = benchmark.loc[~benchmark.index.duplicated(keep="last")].sort_index()
        benchmark = benchmark.reindex(returns.index)
        return returns, benchmark


def _pl210_split_plan(
        observations: int,
        *,
        training_days: int,
        test_days: int,
        step_days: int,
        embargo_days: int,
        maximum_windows: int,
        scheme: str,
) -> pd.DataFrame:
        columns = ["Window", "Train Start Position", "Train End Position", "Test Start Position", "Test End Position"]
        if observations < training_days + embargo_days + test_days:
                return pd.DataFrame(columns=columns)
        train_end_points = list(range(int(training_days), int(observations - embargo_days - test_days + 1), max(int(step_days), 1)))
        train_end_points = train_end_points[-max(int(maximum_windows), 1):]
        rows: list[dict[str, int]] = []
        for number, train_end in enumerate(train_end_points, start=1):
                train_start = 0 if str(scheme).lower().startswith("expanding") else max(0, train_end - int(training_days))
                test_start = train_end + int(embargo_days)
                test_end = test_start + int(test_days)
                if test_end > observations:
                        continue
                rows.append(
                        {
                                "Window": number,
                                "Train Start Position": train_start,
                                "Train End Position": train_end,
                                "Test Start Position": test_start,
                                "Test End Position": test_end,
                        }
                )
        return pd.DataFrame(rows, columns=columns)


def _pl210_asset_cost_bps(model: Mapping[str, Any], assets: Sequence[str], fallback: float) -> pd.Series:
        costs = pd.Series(float(fallback), index=list(assets), dtype=float)
        book = model.get("book", pd.DataFrame())
        if not isinstance(book, pd.DataFrame) or book.empty or "Ticker" not in book.columns or "Cost bps" not in book.columns:
                return costs
        mapped = book.assign(Ticker=book["Ticker"].astype(str).str.upper()).drop_duplicates("Ticker", keep="last").set_index("Ticker")["Cost bps"]
        mapped = pd.to_numeric(mapped, errors="coerce")
        for asset in costs.index:
                value = _safe_float(mapped.get(str(asset).upper()))
                if value is not None and value >= 0.0:
                        costs.loc[asset] = value
        return costs


def _pl210_fold_cost(
        previous_weights: pd.Series,
        target_weights: pd.Series,
        asset_cost_bps: pd.Series,
        *,
        cost_mode: str,
        global_cost_bps: float,
) -> tuple[float, float, float]:
        assets = target_weights.index.union(previous_weights.index)
        previous = previous_weights.reindex(assets).fillna(0.0)
        target = target_weights.reindex(assets).fillna(0.0)
        absolute_trade = (target - previous).abs()
        gross_traded_notional = float(absolute_trade.sum())
        turnover = 0.5 * gross_traded_notional
        if str(cost_mode).startswith("Book"):
                bps = asset_cost_bps.reindex(assets).fillna(float(global_cost_bps))
                cost_rate = float((absolute_trade * bps / 10_000.0).sum())
        else:
                cost_rate = gross_traded_notional * float(global_cost_bps) / 10_000.0
        return turnover, gross_traded_notional, max(cost_rate, 0.0)


def _pl210_unique_method_path(path: pd.DataFrame, method: str) -> pd.DataFrame:
        if not isinstance(path, pd.DataFrame) or path.empty or "Method" not in path.columns:
                return pd.DataFrame()
        selected = path.loc[path["Method"].astype(str) == str(method)].copy()
        if selected.empty:
                return pd.DataFrame()
        selected = selected.reset_index().rename(columns={selected.index.name or "index": "Date"})
        if "Date" not in selected.columns:
                selected = selected.rename(columns={selected.columns[0]: "Date"})
        selected["Date"] = pd.to_datetime(selected["Date"], errors="coerce")
        selected = selected.dropna(subset=["Date"]).sort_values(["Date", "Window"])
        selected = selected.drop_duplicates("Date", keep="last").set_index("Date").sort_index()
        return selected


def _pl210_walk_forward_suite(
        model: Mapping[str, Any],
        methods: Sequence[str],
        optimizer_settings: OptimizerSettings,
        *,
        training_days: int,
        test_days: int,
        step_days: int,
        embargo_days: int,
        maximum_windows: int,
        scheme: str,
        cost_mode: str,
        transaction_cost_bps: float,
        risk_aversion: float = 3.0,
        robustness: float = 0.35,
        resamples: int = 25,
        seed: int = 42,
) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
        returns, benchmark = _pl210_prepare_history(model)
        if returns.empty:
                return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), pd.DataFrame()
        plan = _pl210_split_plan(
                len(returns),
                training_days=int(training_days),
                test_days=int(test_days),
                step_days=int(step_days),
                embargo_days=int(embargo_days),
                maximum_windows=int(maximum_windows),
                scheme=scheme,
        )
        if plan.empty:
                return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), plan

        assets = list(returns.columns)
        initial_current = pd.to_numeric(model.get("current_weights", pd.Series(dtype=float)), errors="coerce").reindex(assets).fillna(0.0)
        previous_weights = {str(method): initial_current.copy() for method in methods}
        asset_costs = _pl210_asset_cost_bps(model, assets, float(transaction_cost_bps))
        window_rows: list[dict[str, Any]] = []
        path_frames: list[pd.DataFrame] = []
        weight_rows: list[dict[str, Any]] = []

        for _, split in plan.iterrows():
                window_number = int(split["Window"])
                train = returns.iloc[int(split["Train Start Position"]):int(split["Train End Position"])]
                test = returns.iloc[int(split["Test Start Position"]):int(split["Test End Position"])]
                if train.empty or test.empty:
                        continue
                benchmark_train = benchmark.reindex(train.index)
                benchmark_test = benchmark.reindex(test.index)
                covariance = estimate_covariance(
                        train,
                        model=model["settings"].covariance_model,
                        shrinkage=model["settings"].shrinkage,
                        ewma_lambda=model["settings"].ewma_lambda,
                )
                expected_model = model["settings"].expected_return_model
                if expected_model == "Black-Litterman":
                        expected_model = "Historical Geometric"
                expected = expected_returns_from_history(train, model=expected_model, ewma_lambda=model["settings"].ewma_lambda)

                for method in methods:
                        method = str(method)
                        prior = previous_weights[method].reindex(assets).fillna(0.0)
                        temporary = dict(model)
                        temporary.update(
                                {
                                        "returns": train,
                                        "covariance": covariance,
                                        "correlation": train.corr(),
                                        "expected_returns": expected,
                                        "benchmark_returns": benchmark_train,
                                        "current_weights": prior,
                                }
                        )
                        try:
                                result = optimise_portfolio_advanced(
                                        temporary,
                                        method,
                                        optimizer_settings,
                                        risk_aversion=float(risk_aversion),
                                        robustness=float(robustness),
                                        resamples=int(resamples),
                                        seed=int(seed + window_number),
                                )
                        except Exception as exc:
                                result = OptimizerResult(False, prior.copy(), method, f"Validation optimizer error: {exc}")
                        target = pd.to_numeric(result.weights, errors="coerce").reindex(assets).fillna(0.0)
                        if not np.isfinite(target.to_numpy(dtype=float)).all() or float(target.abs().sum()) <= EPS:
                                target = prior.copy()
                        if optimizer_settings.long_only:
                                target = target.clip(lower=0.0)
                        net_sum = float(target.sum())
                        if abs(net_sum) > EPS:
                                target = target / net_sum
                        turnover, gross_trade, cost_rate = _pl210_fold_cost(
                                prior,
                                target,
                                asset_costs,
                                cost_mode=cost_mode,
                                global_cost_bps=float(transaction_cost_bps),
                        )
                        gross_returns = test.mul(target, axis=1).sum(axis=1)
                        net_returns = gross_returns.copy()
                        if not net_returns.empty:
                                net_returns.iloc[0] = float(net_returns.iloc[0]) - float(cost_rate)
                        current_returns = test.mul(initial_current, axis=1).sum(axis=1)
                        in_sample_returns = train.mul(target, axis=1).sum(axis=1)
                        gross_metrics = extended_performance_metrics(gross_returns, benchmark_test, model["settings"].risk_free_rate)
                        net_metrics = extended_performance_metrics(net_returns, benchmark_test, model["settings"].risk_free_rate)
                        in_sample_metrics = extended_performance_metrics(in_sample_returns, benchmark_train, model["settings"].risk_free_rate)
                        optimized_growth = float((1.0 + net_returns).prod() - 1.0)
                        current_growth = float((1.0 + current_returns).prod() - 1.0)
                        benchmark_growth = float((1.0 + benchmark_test.dropna()).prod() - 1.0) if benchmark_test.notna().any() else np.nan
                        active_current = optimized_growth - current_growth
                        active_benchmark = optimized_growth - benchmark_growth if np.isfinite(benchmark_growth) else np.nan
                        constraint_failures = 0
                        if isinstance(result.constraint_report, pd.DataFrame) and not result.constraint_report.empty and "Status" in result.constraint_report.columns:
                                constraint_failures = int((result.constraint_report["Status"].astype(str).str.upper() != "PASS").sum())

                        window_rows.append(
                                {
                                        "Method": method,
                                        "Window": window_number,
                                        "Train Start": train.index.min(),
                                        "Train End": train.index.max(),
                                        "Test Start": test.index.min(),
                                        "Test End": test.index.max(),
                                        "Train Observations": len(train),
                                        "Test Observations": len(test),
                                        "Optimizer Success": bool(result.success),
                                        "Solver Message": str(result.message),
                                        "Constraint Failures": constraint_failures,
                                        "In-Sample Return": float((1.0 + in_sample_returns).prod() - 1.0),
                                        "In-Sample Sharpe": _safe_float(in_sample_metrics.get("Sharpe")),
                                        "OOS Gross Return": float((1.0 + gross_returns).prod() - 1.0),
                                        "OOS Net Return": optimized_growth,
                                        "Current Return": current_growth,
                                        "Benchmark Return": benchmark_growth,
                                        "Active vs Current": active_current,
                                        "Active vs Benchmark": active_benchmark,
                                        "OOS CAGR": _safe_float(net_metrics.get("CAGR")),
                                        "OOS Volatility": _safe_float(net_metrics.get("Annualized Volatility")),
                                        "OOS Sharpe": _safe_float(net_metrics.get("Sharpe")),
                                        "OOS Sortino": _safe_float(net_metrics.get("Sortino")),
                                        "OOS Max Drawdown": _safe_float(net_metrics.get("Max Drawdown")),
                                        "OOS CVaR 95%": _safe_float(net_metrics.get("CVaR 95% (1D)")),
                                        "OOS Tracking Error": _safe_float(net_metrics.get("Tracking Error")),
                                        "OOS Information Ratio": _safe_float(net_metrics.get("Information Ratio")),
                                        "Turnover": turnover,
                                        "Gross Traded Notional": gross_trade,
                                        "Cost Rate": cost_rate,
                                        "Cost bps of NAV": cost_rate * 10_000.0,
                                        "Top Weight": float(target.abs().max()) if len(target) else np.nan,
                                        "Effective Positions": _pl210_effective_positions(target),
                                        "Weight Drift": float((target - prior).abs().sum()),
                                }
                        )
                        weight_rows.append({"Method": method, "Window": window_number, "Test Start": test.index.min(), **target.to_dict()})
                        path_frames.append(
                                pd.DataFrame(
                                        {
                                                "Method": method,
                                                "Window": window_number,
                                                "Optimized Gross": gross_returns,
                                                "Optimized Net": net_returns,
                                                "Current": current_returns,
                                                "Benchmark": benchmark_test,
                                                "Cost Event": [cost_rate] + [0.0] * max(len(test) - 1, 0),
                                        },
                                        index=test.index,
                                )
                        )
                        if result.success:
                                previous_weights[method] = target.copy()

        windows = pd.DataFrame(window_rows)
        path = pd.concat(path_frames).sort_index() if path_frames else pd.DataFrame()
        weights = pd.DataFrame(weight_rows)
        return windows, path, weights, plan


def _pl210_summary_table(
        windows: pd.DataFrame,
        path: pd.DataFrame,
        methods: Sequence[str],
        risk_free_rate: float,
) -> pd.DataFrame:
        rows: list[dict[str, Any]] = []
        for method in methods:
                method_windows = windows.loc[windows["Method"].astype(str) == str(method)].copy() if not windows.empty else pd.DataFrame()
                method_path = _pl210_unique_method_path(path, str(method))
                if method_windows.empty or method_path.empty:
                        continue
                net = pd.to_numeric(method_path.get("Optimized Net"), errors="coerce").dropna()
                current = pd.to_numeric(method_path.get("Current"), errors="coerce").reindex(net.index)
                benchmark = pd.to_numeric(method_path.get("Benchmark"), errors="coerce").reindex(net.index)
                metrics = extended_performance_metrics(net, benchmark, risk_free_rate)
                beat_current = float((method_windows["OOS Net Return"] > method_windows["Current Return"]).mean())
                available_benchmark = method_windows["Benchmark Return"].notna()
                beat_benchmark = float((method_windows.loc[available_benchmark, "OOS Net Return"] > method_windows.loc[available_benchmark, "Benchmark Return"]).mean()) if available_benchmark.any() else np.nan
                active_current = (net - current).dropna()
                active_benchmark = (net - benchmark).dropna()
                psr = _pl210_probabilistic_sharpe(net, 0.0)
                rows.append(
                        {
                                "Method": str(method),
                                "Windows": int(len(method_windows)),
                                "Success Rate": float(method_windows["Optimizer Success"].mean()),
                                "Beat Current": beat_current,
                                "Beat Benchmark": beat_benchmark,
                                "Median Fold Net Return": float(method_windows["OOS Net Return"].median()),
                                "OOS Cumulative Return": float((1.0 + net).prod() - 1.0),
                                "OOS CAGR": _safe_float(metrics.get("CAGR")),
                                "OOS Volatility": _safe_float(metrics.get("Annualized Volatility")),
                                "OOS Sharpe": _safe_float(metrics.get("Sharpe")),
                                "OOS Sortino": _safe_float(metrics.get("Sortino")),
                                "OOS Max Drawdown": _safe_float(metrics.get("Max Drawdown")),
                                "OOS CVaR 95%": _safe_float(metrics.get("CVaR 95% (1D)")),
                                "Active Mean vs Current": float(active_current.mean() * _periods_per_year(active_current.index)) if not active_current.empty else np.nan,
                                "Active Mean vs Benchmark": float(active_benchmark.mean() * _periods_per_year(active_benchmark.index)) if not active_benchmark.empty else np.nan,
                                "Probabilistic Sharpe": psr,
                                "Average Turnover": float(method_windows["Turnover"].mean()),
                                "Total Cost Rate": float(method_windows["Cost Rate"].sum()),
                                "Average Top Weight": float(method_windows["Top Weight"].mean()),
                                "Average Effective Positions": float(method_windows["Effective Positions"].mean()),
                                "Average Weight Drift": float(method_windows["Weight Drift"].mean()),
                                "Median IS Sharpe": float(pd.to_numeric(method_windows["In-Sample Sharpe"], errors="coerce").median()),
                                "Median OOS Fold Sharpe": float(pd.to_numeric(method_windows["OOS Sharpe"], errors="coerce").median()),
                        }
                )
        summary = pd.DataFrame(rows)
        if summary.empty:
                return summary
        summary["Sharpe Decay"] = summary["Median OOS Fold Sharpe"] - summary["Median IS Sharpe"]
        sharpe_rank = summary["OOS Sharpe"].rank(pct=True, na_option="bottom")
        current_score = summary["Beat Current"].fillna(0.0)
        benchmark_score = summary["Beat Benchmark"].fillna(0.0)
        psr_score = summary["Probabilistic Sharpe"].fillna(0.0)
        turnover_score = 1.0 - summary["Average Turnover"].clip(lower=0.0, upper=1.0)
        summary["Validation Score"] = 100.0 * (0.35 * sharpe_rank + 0.20 * current_score + 0.15 * benchmark_score + 0.20 * psr_score + 0.10 * turnover_score)
        summary["Rank"] = summary["Validation Score"].rank(ascending=False, method="min").astype(int)
        return summary.sort_values(["Rank", "Method"]).reset_index(drop=True)


def _pl210_repair_validation_volatility(
        windows: pd.DataFrame,
        path: pd.DataFrame,
        summary: pd.DataFrame,
) -> tuple[pd.DataFrame, pd.DataFrame, bool]:
        """Repair volatility fields saved by Portfolio Lab 2.10.

        Version 2.10 queried ``extended_performance_metrics`` with the legacy
        key ``Volatility`` instead of ``Annualized Volatility``.  Existing
        Streamlit sessions therefore contain otherwise valid validation
        results with missing OOS volatility.  Reconstruct those values from the
        stored unseen return paths without changing any other result.
        """
        repaired_windows = windows.copy() if isinstance(windows, pd.DataFrame) else pd.DataFrame()
        repaired_summary = summary.copy() if isinstance(summary, pd.DataFrame) else pd.DataFrame()
        changed = False

        if isinstance(path, pd.DataFrame) and not path.empty:
                if (
                        not repaired_windows.empty
                        and {"Method", "Window"}.issubset(repaired_windows.columns)
                ):
                        if "OOS Volatility" not in repaired_windows.columns:
                                repaired_windows["OOS Volatility"] = np.nan
                        current_values = pd.to_numeric(
                                repaired_windows["OOS Volatility"],
                                errors="coerce",
                        )
                        for row_index, row in repaired_windows.loc[current_values.isna()].iterrows():
                                fold_path = path.loc[
                                        (path["Method"].astype(str) == str(row["Method"]))
                                        & (
                                                pd.to_numeric(path["Window"], errors="coerce")
                                                == float(row["Window"])
                                        )
                                ]
                                fold_returns = pd.to_numeric(
                                        fold_path.get("Optimized Net"),
                                        errors="coerce",
                                ).dropna()
                                if len(fold_returns) > 1:
                                        volatility = float(
                                                fold_returns.std(ddof=1)
                                                * math.sqrt(_periods_per_year(fold_returns.index))
                                        )
                                        if np.isfinite(volatility):
                                                repaired_windows.at[row_index, "OOS Volatility"] = volatility
                                                changed = True

                if (
                        not repaired_summary.empty
                        and "Method" in repaired_summary.columns
                ):
                        if "OOS Volatility" not in repaired_summary.columns:
                                repaired_summary["OOS Volatility"] = np.nan
                        current_values = pd.to_numeric(
                                repaired_summary["OOS Volatility"],
                                errors="coerce",
                        )
                        for row_index, row in repaired_summary.loc[current_values.isna()].iterrows():
                                method_path = _pl210_unique_method_path(
                                        path,
                                        str(row["Method"]),
                                )
                                method_returns = pd.to_numeric(
                                        method_path.get("Optimized Net"),
                                        errors="coerce",
                                ).dropna()
                                if len(method_returns) > 1:
                                        volatility = float(
                                                method_returns.std(ddof=1)
                                                * math.sqrt(_periods_per_year(method_returns.index))
                                        )
                                        if np.isfinite(volatility):
                                                repaired_summary.at[row_index, "OOS Volatility"] = volatility
                                                changed = True

        return repaired_windows, repaired_summary, changed


def _pl210_weight_stability(weights: pd.DataFrame, method: str) -> pd.DataFrame:
        if not isinstance(weights, pd.DataFrame) or weights.empty:
                return pd.DataFrame()
        selected = weights.loc[weights["Method"].astype(str) == str(method)].copy()
        metadata = {"Method", "Window", "Test Start"}
        assets = [column for column in selected.columns if column not in metadata]
        rows: list[dict[str, Any]] = []
        for asset in assets:
                values = pd.to_numeric(selected[asset], errors="coerce").dropna()
                if values.empty:
                        continue
                rows.append(
                        {
                                "Asset": asset,
                                "Average Weight": float(values.mean()),
                                "Weight Volatility": float(values.std(ddof=1)) if len(values) > 1 else 0.0,
                                "Minimum Weight": float(values.min()),
                                "Maximum Weight": float(values.max()),
                                "Range": float(values.max() - values.min()),
                                "Selection Rate": float((values.abs() > 1e-4).mean()),
                        }
                )
        return pd.DataFrame(rows).sort_values("Average Weight", ascending=False).reset_index(drop=True)


def _pl210_block_bootstrap(
        active_returns: pd.Series,
        *,
        repetitions: int = 1000,
        block_length: int = 21,
        seed: int = 42,
) -> tuple[pd.DataFrame, dict[str, float]]:
        clean = pd.to_numeric(active_returns, errors="coerce").dropna()
        if len(clean) < max(10, block_length):
                return pd.DataFrame(), {}
        values = clean.to_numpy(dtype=float, copy=True)
        n = len(values)
        block = max(2, min(int(block_length), n))
        rng = np.random.default_rng(int(seed))
        annualization = float(_periods_per_year(clean.index))
        estimates = np.empty(max(int(repetitions), 100), dtype=float)
        max_start = max(n - block + 1, 1)
        for i in range(len(estimates)):
                sampled: list[float] = []
                while len(sampled) < n:
                        start = int(rng.integers(0, max_start)) if max_start > 1 else 0
                        sampled.extend(values[start:start + block].tolist())
                sample = np.asarray(sampled[:n], dtype=float)
                estimates[i] = float(sample.mean() * annualization)
        table = pd.DataFrame({"Annualized Active Mean": estimates})
        summary = {
                "Probability Positive": float((estimates > 0.0).mean()),
                "CI 2.5%": float(np.quantile(estimates, 0.025)),
                "Median": float(np.median(estimates)),
                "CI 97.5%": float(np.quantile(estimates, 0.975)),
                "Observed": float(values.mean() * annualization),
        }
        return table, summary


def _pl210_regime_table(method_path: pd.DataFrame) -> pd.DataFrame:
        if method_path.empty:
                return pd.DataFrame()
        frame = method_path[[column for column in ["Optimized Net", "Current", "Benchmark"] if column in method_path.columns]].copy()
        frame = frame.apply(pd.to_numeric, errors="coerce").dropna(subset=["Optimized Net"])
        if frame.empty or "Benchmark" not in frame.columns:
                return pd.DataFrame()
        benchmark = frame["Benchmark"]
        rolling_return = (1.0 + benchmark).rolling(63, min_periods=21).apply(np.prod, raw=True) - 1.0
        rolling_vol = benchmark.rolling(21, min_periods=10).std() * math.sqrt(TRADING_DAYS)
        vol_cut = float(rolling_vol.median()) if rolling_vol.notna().any() else np.nan
        bull = rolling_return >= 0.0
        high = rolling_vol >= vol_cut if np.isfinite(vol_cut) else pd.Series(False, index=frame.index)
        labels = pd.Series(index=frame.index, dtype=object)
        labels.loc[bull & ~high] = "Bull / Lower volatility"
        labels.loc[bull & high] = "Bull / Higher volatility"
        labels.loc[~bull & ~high] = "Bear / Lower volatility"
        labels.loc[~bull & high] = "Bear / Higher volatility"
        frame["Regime"] = labels
        frame["Active vs Current"] = frame["Optimized Net"] - frame.get("Current", 0.0)
        frame["Active vs Benchmark"] = frame["Optimized Net"] - frame["Benchmark"]
        rows: list[dict[str, Any]] = []
        for regime, group in frame.dropna(subset=["Regime"]).groupby("Regime"):
                metrics = extended_performance_metrics(group["Optimized Net"], group["Benchmark"], 0.0)
                rows.append(
                        {
                                "Regime": regime,
                                "Observations": len(group),
                                "Share": len(group) / max(len(frame.dropna(subset=["Regime"])), 1),
                                "Annualized Return": _safe_float(metrics.get("Arithmetic Return")),
                                "Volatility": _safe_float(metrics.get("Annualized Volatility")),
                                "Sharpe": _safe_float(metrics.get("Sharpe")),
                                "Active vs Current": float(group["Active vs Current"].mean() * TRADING_DAYS),
                                "Active vs Benchmark": float(group["Active vs Benchmark"].mean() * TRADING_DAYS),
                        }
                )
        return pd.DataFrame(rows)


def _pl210_governance_table(
        model: Mapping[str, Any],
        windows: pd.DataFrame,
        path: pd.DataFrame,
        summary: pd.DataFrame,
        plan: pd.DataFrame,
        champion: str,
        *,
        training_days: int,
        test_days: int,
        step_days: int,
        embargo_days: int,
        transaction_cost_bps: float,
        acceptance: Mapping[str, float],
) -> pd.DataFrame:
        champion_row = summary.loc[summary["Method"].astype(str) == str(champion)].iloc[0] if not summary.empty and (summary["Method"].astype(str) == str(champion)).any() else pd.Series(dtype=object)
        champion_windows = windows.loc[windows["Method"].astype(str) == str(champion)] if not windows.empty else pd.DataFrame()
        method_path = _pl210_unique_method_path(path, champion)
        benchmark_coverage = float(pd.to_numeric(method_path.get("Benchmark"), errors="coerce").notna().mean()) if not method_path.empty and "Benchmark" in method_path.columns else 0.0
        finite_path = bool(not method_path.empty and np.isfinite(pd.to_numeric(method_path.get("Optimized Net"), errors="coerce").dropna().to_numpy(dtype=float)).all())
        no_leakage = bool(plan.empty or (plan["Train End Position"] <= plan["Test Start Position"]).all())
        overlap = bool(int(step_days) < int(test_days))
        rows = [
                {"Control": "Minimum data length", "Observed": len(model.get("returns", pd.DataFrame())), "Threshold": f">= {training_days + embargo_days + test_days}", "Status": "PASS" if len(model.get("returns", pd.DataFrame())) >= training_days + embargo_days + test_days else "FAIL", "Method": "Resolved complete-case observations"},
                {"Control": "Chronological train/test separation", "Observed": "Separated" if no_leakage else "Overlap", "Threshold": "Train end <= test start", "Status": "PASS" if no_leakage else "FAIL", "Method": f"Embargo {embargo_days} observations"},
                {"Control": "OOS path overlap", "Observed": f"Step {step_days} / test {test_days}", "Threshold": "Step >= test preferred", "Status": "PASS" if not overlap else "REVIEW", "Method": "Latest forecast retained on duplicate OOS dates"},
                {"Control": "Validation windows", "Observed": int(champion_row.get("Windows", 0) or 0), "Threshold": f">= {int(acceptance['minimum_windows'])}", "Status": "PASS" if float(champion_row.get("Windows", 0) or 0) >= float(acceptance["minimum_windows"]) else "REVIEW", "Method": "Champion folds"},
                {"Control": "Optimizer success rate", "Observed": champion_row.get("Success Rate"), "Threshold": f">= {float(acceptance['minimum_success_rate']):.0%}", "Status": "PASS" if float(_safe_float(champion_row.get("Success Rate"), 0.0)) >= float(acceptance["minimum_success_rate"]) else "FAIL", "Method": "Successful solver outcomes"},
                {"Control": "Beat current portfolio", "Observed": champion_row.get("Beat Current"), "Threshold": f">= {float(acceptance['minimum_beat_current']):.0%}", "Status": "PASS" if float(_safe_float(champion_row.get("Beat Current"), 0.0)) >= float(acceptance["minimum_beat_current"]) else "REVIEW", "Method": "Fold-level net return comparison"},
                {"Control": "OOS Sharpe", "Observed": champion_row.get("OOS Sharpe"), "Threshold": f">= {float(acceptance['minimum_oos_sharpe']):.2f}", "Status": "PASS" if float(_safe_float(champion_row.get("OOS Sharpe"), -np.inf)) >= float(acceptance["minimum_oos_sharpe"]) else "REVIEW", "Method": "Concatenated non-duplicated OOS path"},
                {"Control": "OOS maximum drawdown", "Observed": champion_row.get("OOS Max Drawdown"), "Threshold": f">= {float(acceptance['maximum_drawdown']):.0%}", "Status": "PASS" if float(_safe_float(champion_row.get("OOS Max Drawdown"), -1.0)) >= float(acceptance["maximum_drawdown"]) else "REVIEW", "Method": "Net OOS path"},
                {"Control": "Average turnover", "Observed": champion_row.get("Average Turnover"), "Threshold": f"<= {float(acceptance['maximum_average_turnover']):.0%}", "Status": "PASS" if float(_safe_float(champion_row.get("Average Turnover"), np.inf)) <= float(acceptance["maximum_average_turnover"]) else "REVIEW", "Method": "Half L1 transition turnover"},
                {"Control": "Probabilistic Sharpe", "Observed": champion_row.get("Probabilistic Sharpe"), "Threshold": f">= {float(acceptance['minimum_psr']):.0%}", "Status": "PASS" if float(_safe_float(champion_row.get("Probabilistic Sharpe"), 0.0)) >= float(acceptance["minimum_psr"]) else "REVIEW", "Method": "Finite-sample skew/kurtosis adjustment"},
                {"Control": "Benchmark coverage", "Observed": benchmark_coverage, "Threshold": ">= 95%", "Status": "PASS" if benchmark_coverage >= 0.95 else "REVIEW", "Method": "Aligned OOS dates"},
                {"Control": "Finite OOS results", "Observed": "Finite" if finite_path else "Invalid", "Threshold": "No NaN or infinity in net path", "Status": "PASS" if finite_path else "FAIL", "Method": "Numeric integrity"},
                {"Control": "Transaction-cost treatment", "Observed": float(transaction_cost_bps), "Threshold": ">= 0 bps", "Status": "PASS" if float(transaction_cost_bps) >= 0.0 else "FAIL", "Method": "Cost charged at each fold transition"},
                {"Control": "Model boundary", "Observed": "Research validation", "Threshold": "No automatic production approval", "Status": "PASS", "Method": "Explicit governance and publication"},
        ]
        return pd.DataFrame(rows)


def _pl210_status(governance: pd.DataFrame) -> str:
        if governance.empty or "Status" not in governance.columns:
                return "NOT RUN"
        statuses = governance["Status"].astype(str).str.upper()
        if (statuses == "FAIL").any():
                return "FAIL"
        if (statuses == "REVIEW").any():
                return "REVIEW"
        return "PASS"


def _pl210_summary_display(summary: pd.DataFrame) -> pd.DataFrame:
        display = summary.copy()
        percent_columns = [
                "Success Rate", "Beat Current", "Beat Benchmark", "Median Fold Net Return",
                "OOS Cumulative Return", "OOS CAGR", "OOS Volatility", "OOS Max Drawdown",
                "OOS CVaR 95%", "Active Mean vs Current", "Active Mean vs Benchmark",
                "Probabilistic Sharpe", "Average Turnover", "Total Cost Rate", "Average Top Weight",
                "Average Weight Drift", "Sharpe Decay",
        ]
        for column in percent_columns:
                if column in display.columns:
                        display[column] = pd.to_numeric(display[column], errors="coerce").map(_fmt_pct)
        for column in ["OOS Sharpe", "OOS Sortino", "Median IS Sharpe", "Median OOS Fold Sharpe", "Average Effective Positions", "Validation Score"]:
                if column in display.columns:
                        display[column] = pd.to_numeric(display[column], errors="coerce").map(_fmt_num)
        return display


def _pl210_windows_display(windows: pd.DataFrame) -> pd.DataFrame:
        display = windows.copy()
        for column in ["Train Start", "Train End", "Test Start", "Test End"]:
                if column in display.columns:
                        display[column] = pd.to_datetime(display[column], errors="coerce").dt.strftime("%Y-%m-%d")
        for column in [
                "In-Sample Return", "OOS Gross Return", "OOS Net Return", "Current Return", "Benchmark Return",
                "Active vs Current", "Active vs Benchmark", "OOS CAGR", "OOS Volatility", "OOS Max Drawdown",
                "OOS CVaR 95%", "OOS Tracking Error", "Turnover", "Gross Traded Notional", "Cost Rate",
                "Top Weight", "Weight Drift",
        ]:
                if column in display.columns:
                        display[column] = pd.to_numeric(display[column], errors="coerce").map(_fmt_pct)
        for column in ["In-Sample Sharpe", "OOS Sharpe", "OOS Sortino", "OOS Information Ratio", "Effective Positions"]:
                if column in display.columns:
                        display[column] = pd.to_numeric(display[column], errors="coerce").map(_fmt_num)
        return display


def _pl210_method_map(summary: pd.DataFrame) -> go.Figure:
        fig = go.Figure()
        if summary.empty:
                fig.add_annotation(
                        text="No validation summary is available.",
                        x=0.5,
                        y=0.5,
                        xref="paper",
                        yref="paper",
                        showarrow=False,
                )
                fig.update_xaxes(visible=False)
                fig.update_yaxes(visible=False)
                return fig

        frame = summary.copy()
        numeric_columns = [
                "OOS Volatility",
                "OOS CAGR",
                "Beat Current",
                "Validation Score",
                "OOS Sharpe",
                "OOS Max Drawdown",
                "Average Turnover",
        ]
        for column in numeric_columns:
                if column in frame.columns:
                        frame[column] = pd.to_numeric(frame[column], errors="coerce")

        frame = frame.loc[
                np.isfinite(frame["OOS Volatility"])
                & np.isfinite(frame["OOS CAGR"])
        ].copy()

        if frame.empty:
                fig.add_annotation(
                        text="OOS volatility or CAGR is unavailable. Re-run the validation suite.",
                        x=0.5,
                        y=0.5,
                        xref="paper",
                        yref="paper",
                        showarrow=False,
                )
                fig.update_xaxes(visible=False)
                fig.update_yaxes(visible=False)
                fig.update_layout(
                        title="OOS Method Trade-Off Map",
                        height=470,
                        margin=dict(l=20, r=20, t=60, b=30),
                )
                return fig

        fig.add_trace(
                go.Scatter(
                        x=frame["OOS Volatility"],
                        y=frame["OOS CAGR"],
                        mode="markers+text",
                        text=frame["Method"],
                        textposition="top center",
                        marker=dict(
                                size=14 + 26 * frame["Beat Current"].fillna(0.0),
                                color=frame["Validation Score"],
                                colorscale="Viridis",
                                showscale=True,
                                colorbar=dict(title="Score"),
                                line=dict(width=1, color="rgba(255,255,255,.5)"),
                        ),
                        customdata=np.column_stack([
                                frame["OOS Sharpe"].fillna(np.nan),
                                frame["OOS Max Drawdown"].fillna(np.nan),
                                frame["Average Turnover"].fillna(np.nan),
                        ]),
                        hovertemplate="%{text}<br>Vol %{x:.2%}<br>CAGR %{y:.2%}<br>Sharpe %{customdata[0]:.2f}<br>Max DD %{customdata[1]:.2%}<br>Turnover %{customdata[2]:.2%}<extra></extra>",
                )
        )
        fig.update_layout(
                title="OOS Method Trade-Off Map",
                height=470,
                xaxis_title="OOS volatility",
                yaxis_title="OOS CAGR",
                xaxis_tickformat=".1%",
                yaxis_tickformat=".1%",
                margin=dict(l=20, r=20, t=60, b=30),
        )
        return fig


def _pl210_fold_return_figure(windows: pd.DataFrame, method: str) -> go.Figure:
        frame = windows.loc[windows["Method"].astype(str) == str(method)].copy() if not windows.empty else pd.DataFrame()
        fig = go.Figure()
        if frame.empty:
                return fig
        for column, name in [("OOS Net Return", "Optimized net"), ("Current Return", "Current"), ("Benchmark Return", "Benchmark")]:
                if column in frame.columns:
                        fig.add_trace(go.Bar(x=frame["Window"].astype(str), y=frame[column], name=name))
        fig.update_layout(title=f"Fold Returns - {method}", barmode="group", height=440, yaxis_tickformat=".1%", xaxis_title="Validation window", margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _pl210_sharpe_scatter(windows: pd.DataFrame, method: str) -> go.Figure:
        frame = windows.loc[windows["Method"].astype(str) == str(method)].copy() if not windows.empty else pd.DataFrame()
        fig = go.Figure()
        if frame.empty:
                return fig
        fig.add_trace(
                go.Scatter(
                        x=frame["In-Sample Sharpe"],
                        y=frame["OOS Sharpe"],
                        mode="markers+text",
                        text=frame["Window"].map(lambda value: f"W{int(value)}"),
                        textposition="top center",
                        marker=dict(size=10 + 24 * frame["Turnover"].fillna(0.0), color=frame["Active vs Current"], colorscale="RdYlGn", showscale=True, colorbar=dict(title="Active")),
                        hovertemplate="%{text}<br>IS Sharpe %{x:.2f}<br>OOS Sharpe %{y:.2f}<extra></extra>",
                )
        )
        values = pd.concat([pd.to_numeric(frame["In-Sample Sharpe"], errors="coerce"), pd.to_numeric(frame["OOS Sharpe"], errors="coerce")]).dropna()
        if not values.empty:
                low, high = float(values.min()), float(values.max())
                fig.add_trace(go.Scatter(x=[low, high], y=[low, high], mode="lines", name="No decay", line=dict(dash="dash")))
        fig.update_layout(title="In-Sample vs Out-of-Sample Sharpe", height=440, xaxis_title="In-sample Sharpe", yaxis_title="OOS Sharpe", margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _pl210_weight_heatmap(weights: pd.DataFrame, method: str) -> go.Figure:
        frame = weights.loc[weights["Method"].astype(str) == str(method)].copy() if not weights.empty else pd.DataFrame()
        fig = go.Figure()
        if frame.empty:
                return fig
        assets = [column for column in frame.columns if column not in {"Method", "Window", "Test Start"}]
        matrix = frame.set_index("Window")[assets].T
        fig.add_trace(go.Heatmap(z=matrix.values, x=[f"W{int(value)}" for value in matrix.columns], y=matrix.index, colorscale="Blues", zmin=0.0 if np.nanmin(matrix.values) >= -EPS else None, colorbar=dict(title="Weight"), text=np.vectorize(lambda value: f"{value:.1%}")(matrix.values), texttemplate="%{text}", hovertemplate="%{y}<br>%{x}<br>Weight %{z:.2%}<extra></extra>"))
        fig.update_layout(title=f"Fold Allocation Stability - {method}", height=max(380, 80 + 42 * len(matrix.index)), margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _pl210_transition_figure(windows: pd.DataFrame, method: str) -> go.Figure:
        frame = windows.loc[windows["Method"].astype(str) == str(method)].copy() if not windows.empty else pd.DataFrame()
        fig = go.Figure()
        if frame.empty:
                return fig
        fig.add_trace(go.Bar(x=frame["Window"].astype(str), y=frame["Turnover"], name="Turnover"))
        fig.add_trace(go.Scatter(x=frame["Window"].astype(str), y=frame["Top Weight"], name="Top weight", mode="lines+markers", yaxis="y2"))
        fig.add_trace(go.Scatter(x=frame["Window"].astype(str), y=frame["Effective Positions"], name="Effective positions", mode="lines+markers", yaxis="y3"))
        fig.update_layout(
                title="Transition and Concentration by Fold",
                height=440,
                yaxis=dict(title="Turnover", tickformat=".0%"),
                yaxis2=dict(title="Top weight", overlaying="y", side="right", tickformat=".0%", position=1.0),
                yaxis3=dict(title="Effective positions", overlaying="y", side="right", anchor="free", position=0.88),
                margin=dict(l=20, r=90, t=60, b=30),
                legend=dict(orientation="h", y=1.08),
        )
        return fig


def _pl210_bootstrap_figure(table: pd.DataFrame, observed: float) -> go.Figure:
        fig = go.Figure()
        if table.empty:
                return fig
        fig.add_trace(go.Histogram(x=table["Annualized Active Mean"], nbinsx=50, name="Bootstrap"))
        fig.add_vline(x=0.0, line_dash="dash", line_color="rgba(255,255,255,.7)")
        if np.isfinite(observed):
                fig.add_vline(x=float(observed), line_dash="solid", line_color="#38bdf8", annotation_text="Observed")
        fig.update_layout(title="Block-Bootstrap Distribution of Annualized Active Mean", height=430, xaxis_tickformat=".1%", yaxis_title="Resamples", margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _pl210_robustness_grid(
        model: Mapping[str, Any],
        method: str,
        optimizer_settings: OptimizerSettings,
        *,
        train_values: Sequence[int],
        test_values: Sequence[int],
        cost_values: Sequence[float],
        step_policy: str,
        embargo_days: int,
        maximum_windows: int,
        cost_mode: str,
        scheme: str,
) -> pd.DataFrame:
        rows: list[dict[str, Any]] = []
        combinations = [(int(train), int(test), float(cost)) for train in train_values for test in test_values for cost in cost_values]
        for train, test, cost in combinations[:18]:
                step = test if step_policy == "Non-overlapping" else max(21, test // 2)
                windows, path, _, _ = _pl210_walk_forward_suite(
                        model,
                        [method],
                        optimizer_settings,
                        training_days=train,
                        test_days=test,
                        step_days=step,
                        embargo_days=int(embargo_days),
                        maximum_windows=int(maximum_windows),
                        scheme=scheme,
                        cost_mode=cost_mode,
                        transaction_cost_bps=cost,
                )
                summary = _pl210_summary_table(windows, path, [method], model["settings"].risk_free_rate)
                if summary.empty:
                        rows.append({"Method": method, "Training Days": train, "Test Days": test, "Cost bps": cost, "Windows": 0, "Status": "UNAVAILABLE"})
                        continue
                record = summary.iloc[0].to_dict()
                rows.append({"Method": method, "Training Days": train, "Test Days": test, "Cost bps": cost, "Status": "PASS", **record})
        return pd.DataFrame(rows)


def _pl210_robustness_heatmap(table: pd.DataFrame, metric: str, cost_bps: float) -> go.Figure:
        fig = go.Figure()
        if table.empty or metric not in table.columns:
                return fig
        selected = table.loc[np.isclose(pd.to_numeric(table["Cost bps"], errors="coerce"), float(cost_bps))].copy()
        if selected.empty:
                return fig
        pivot = selected.pivot_table(index="Training Days", columns="Test Days", values=metric, aggfunc="mean")
        text = pivot.copy().astype(object)
        for column in text.columns:
                if metric in {"OOS Sharpe", "Validation Score"}:
                        text[column] = pd.to_numeric(pivot[column], errors="coerce").map(lambda value: "" if pd.isna(value) else f"{value:.2f}")
                else:
                        text[column] = pd.to_numeric(pivot[column], errors="coerce").map(lambda value: "" if pd.isna(value) else f"{value:.1%}")
        fig.add_trace(go.Heatmap(z=pivot.values, x=[str(value) for value in pivot.columns], y=[str(value) for value in pivot.index], colorscale="RdYlGn", text=text.values, texttemplate="%{text}", colorbar=dict(title=metric)))
        fig.update_layout(title=f"Design Sensitivity - {metric} at {float(cost_bps):.0f} bps", height=430, xaxis_title="Test days", yaxis_title="Training days", margin=dict(l=20, r=20, t=60, b=30))
        return fig


def _pl210_json_payload(payload: Mapping[str, Any]) -> bytes:
        return json.dumps(_pl24_json_safe(dict(payload)), ensure_ascii=False, indent=2, allow_nan=False).encode("utf-8")


