def _render_validation_v2(model: dict[str, Any]) -> None:
        _pl210_inject_styles()
        st.markdown(
                """
                <div class="pl210-hero">
                  <div class="pl210-kicker">OOS EVIDENCE · CHAMPION / CHALLENGER · STABILITY · STATISTICS · GOVERNANCE · UX 2.10.1</div>
                  <div class="pl210-title">Institutional Validation & Model-Risk Workspace</div>
                  <div class="pl210-copy">Re-estimate portfolio methods on chronological training samples, apply them only to unseen returns, charge transition costs, compare challengers, inspect allocation stability, quantify sampling uncertainty and stage an auditable validation decision without converting research evidence into automatic production approval.</div>
                </div>
                """,
                unsafe_allow_html=True,
        )

        design = st.expander("Validation mandate, split design & acceptance policy", expanded=True)
        with design:
                row_one = st.columns(6)
                preset = row_one[0].selectbox("Method suite", list(PL210_METHOD_PRESETS) + ["Custom"], index=0, key="pl210_method_preset")
                if preset == "Custom":
                        methods = row_one[1].multiselect("Methods", PL210_METHODS, default=["Robust Maximum Sharpe"], key="pl210_custom_methods")
                else:
                        methods = PL210_METHOD_PRESETS[preset]
                        row_one[1].text_input("Methods", value=", ".join(methods), disabled=True, key="pl210_preset_methods")
                split_scheme = row_one[2].selectbox("Training scheme", ["Rolling", "Expanding"], index=0, key="pl210_scheme")
                training = row_one[3].selectbox("Training days", [252, 504, 756, 1008], index=1, key="pl210_training")
                test = row_one[4].selectbox("Test days", [21, 63, 126, 252], index=1, key="pl210_test")
                step = row_one[5].selectbox("Step days", [21, 63, 126, 252], index=1, key="pl210_step")

                row_two = st.columns(7)
                embargo = row_two[0].selectbox("Embargo days", [0, 1, 5, 10, 21], index=0, key="pl210_embargo")
                max_windows = row_two[1].number_input("Maximum windows", min_value=2, max_value=30, value=8, step=1, key="pl210_max_windows")
                cost_mode = row_two[2].selectbox("Cost model", ["Global bps", "Book cost bps"], index=0, key="pl210_cost_mode")
                cost_bps = row_two[3].number_input("Cost per traded notional (bps)", min_value=0.0, max_value=250.0, value=10.0, step=1.0, key="pl210_cost_bps")
                long_only = row_two[4].checkbox("Long only", value=True, key="pl210_long_only")
                maximum_weight = row_two[5].selectbox("Maximum weight", [0.20, 0.25, 0.30, 0.35, 0.50, 1.00], index=3, format_func=lambda value: f"{value:.0%}", key="pl210_max_weight")
                fix_cash = row_two[6].checkbox("Fix cash weight", value=True, key="pl210_fix_cash")

                acceptance_cols = st.columns(7)
                minimum_windows = acceptance_cols[0].number_input("Min windows", 2, 20, int(PL210_DEFAULT_ACCEPTANCE["minimum_windows"]), key="pl210_accept_windows")
                minimum_success = acceptance_cols[1].selectbox("Min solver success", [0.75, 0.85, 0.90, 0.95, 1.00], index=2, format_func=lambda value: f"{value:.0%}", key="pl210_accept_success")
                minimum_beat = acceptance_cols[2].selectbox("Min beat-current rate", [0.25, 0.40, 0.50, 0.60, 0.75], index=2, format_func=lambda value: f"{value:.0%}", key="pl210_accept_beat")
                minimum_sharpe = acceptance_cols[3].selectbox("Min OOS Sharpe", [-0.50, 0.00, 0.25, 0.50, 0.75], index=1, key="pl210_accept_sharpe")
                maximum_dd = acceptance_cols[4].selectbox("Max tolerated drawdown", [-0.10, -0.15, -0.20, -0.25, -0.35, -0.50], index=3, format_func=lambda value: f"{value:.0%}", key="pl210_accept_dd")
                maximum_turnover = acceptance_cols[5].selectbox("Max average turnover", [0.25, 0.40, 0.60, 0.80, 1.00, 1.50], index=2, format_func=lambda value: f"{value:.0%}", key="pl210_accept_turnover")
                minimum_psr = acceptance_cols[6].selectbox("Min PSR", [0.50, 0.60, 0.75, 0.90, 0.95], index=1, format_func=lambda value: f"{value:.0%}", key="pl210_accept_psr")

                run = st.button("Run institutional validation suite", type="primary", width="stretch", key="pl210_run")

        methods = [method for method in methods if method in PL210_METHODS]
        acceptance = {
                "minimum_windows": float(minimum_windows),
                "minimum_success_rate": float(minimum_success),
                "minimum_beat_current": float(minimum_beat),
                "minimum_oos_sharpe": float(minimum_sharpe),
                "maximum_drawdown": float(maximum_dd),
                "maximum_average_turnover": float(maximum_turnover),
                "minimum_psr": float(minimum_psr),
        }
        optimizer_settings = OptimizerSettings(
                method=methods[0] if methods else "Robust Maximum Sharpe",
                long_only=bool(long_only),
                gross_limit=1.0,
                global_min_weight=0.0 if long_only else -float(maximum_weight),
                global_max_weight=float(maximum_weight),
                turnover_limit=None,
                fix_cash_weight=bool(fix_cash),
        )

        if run:
                if not methods:
                        st.error("Select at least one validation method.")
                else:
                        with st.spinner("Running chronological optimizer re-estimation, unseen return evaluation and cost-aware diagnostics..."):
                                windows, path, weights, plan = _pl210_walk_forward_suite(
                                        model,
                                        methods,
                                        optimizer_settings,
                                        training_days=int(training),
                                        test_days=int(test),
                                        step_days=int(step),
                                        embargo_days=int(embargo),
                                        maximum_windows=int(max_windows),
                                        scheme=str(split_scheme),
                                        cost_mode=str(cost_mode),
                                        transaction_cost_bps=float(cost_bps),
                                )
                                summary = _pl210_summary_table(windows, path, methods, model["settings"].risk_free_rate)
                                model["validation_windows_v210"] = windows
                                model["validation_path_v210"] = path
                                model["validation_weights_v210"] = weights
                                model["validation_plan_v210"] = plan
                                model["validation_summary_v210"] = summary
                                model["validation_settings_v210"] = {
                                        "methods": methods,
                                        "training_days": int(training),
                                        "test_days": int(test),
                                        "step_days": int(step),
                                        "embargo_days": int(embargo),
                                        "maximum_windows": int(max_windows),
                                        "scheme": str(split_scheme),
                                        "cost_mode": str(cost_mode),
                                        "transaction_cost_bps": float(cost_bps),
                                        "optimizer_settings": asdict(optimizer_settings),
                                        "acceptance": acceptance,
                                }
                                model["walk_forward_windows"] = windows
                                model["walk_forward_path"] = path
                                st.session_state["portfolio_lab_model_v1"] = model

        windows = model.get("validation_windows_v210", pd.DataFrame())
        path = model.get("validation_path_v210", pd.DataFrame())
        weights = model.get("validation_weights_v210", pd.DataFrame())
        plan = model.get("validation_plan_v210", pd.DataFrame())
        summary = model.get("validation_summary_v210", pd.DataFrame())
        stored_settings = model.get("validation_settings_v210", {})
        robustness_table = model.get("validation_robustness_v210", pd.DataFrame())

        windows, summary, repaired_volatility = _pl210_repair_validation_volatility(
                windows,
                path,
                summary,
        )
        if repaired_volatility:
                model["validation_windows_v210"] = windows
                model["validation_summary_v210"] = summary
                st.session_state["portfolio_lab_model_v1"] = model

        if (
                isinstance(robustness_table, pd.DataFrame)
                and not robustness_table.empty
                and "OOS Volatility" in robustness_table.columns
                and pd.to_numeric(
                        robustness_table["OOS Volatility"],
                        errors="coerce",
                ).notna().sum() == 0
        ):
                robustness_table = pd.DataFrame()
                model.pop("validation_robustness_v210", None)
                st.session_state["portfolio_lab_model_v1"] = model
                st.info(
                        "The stored robustness grid was created by Portfolio Lab 2.10 "
                        "without volatility fields. Re-run the grid once to rebuild "
                        "the complete diagnostics."
                )

        if not isinstance(summary, pd.DataFrame) or summary.empty:
                st.markdown('<div class="pl210-empty"><strong>Validation suite not yet executed</strong><br>Choose a champion/challenger set and run the suite. The engine requires at least one complete training, embargo and test window.</div>', unsafe_allow_html=True)
                st.info("The legacy single-method walk-forward engine remains available through the public walk_forward_optimizer_validation(...) function, but this workspace stores the richer 2.10 audit tables.")
                return

        champion_default = str(summary.sort_values("Rank").iloc[0]["Method"])
        champion_options = summary["Method"].astype(str).tolist()
        champion = st.selectbox("Candidate under review", champion_options, index=champion_options.index(champion_default), key="pl210_champion")
        effective_settings = stored_settings if isinstance(stored_settings, Mapping) else {}
        effective_acceptance = effective_settings.get("acceptance", acceptance) if isinstance(effective_settings, Mapping) else acceptance
        governance = _pl210_governance_table(
                model,
                windows,
                path,
                summary,
                plan,
                champion,
                training_days=int(effective_settings.get("training_days", training)),
                test_days=int(effective_settings.get("test_days", test)),
                step_days=int(effective_settings.get("step_days", step)),
                embargo_days=int(effective_settings.get("embargo_days", embargo)),
                transaction_cost_bps=float(effective_settings.get("transaction_cost_bps", cost_bps)),
                acceptance=effective_acceptance,
        )
        status = _pl210_status(governance)
        model["validation_governance_v210"] = governance
        model["validation_champion_v210"] = champion

        champion_row = summary.loc[summary["Method"].astype(str) == champion].iloc[0]
        top_ranked_method = str(summary.sort_values("Rank").iloc[0]["Method"])
        selected_rank = int(_safe_float(champion_row.get("Rank"), 0.0))
        if champion != top_ranked_method:
                st.info(
                        f"Reviewing challenger #{selected_rank}: {champion}. "
                        f"The current score-ranked candidate is {top_ranked_method}."
                )
        cards = st.columns(8)
        cards[0].metric("Methods", len(summary))
        cards[1].metric("Candidate", champion)
        cards[2].metric("OOS Sharpe", _fmt_num(champion_row.get("OOS Sharpe")))
        cards[3].metric("Beat Current", _fmt_pct(champion_row.get("Beat Current")))
        cards[4].metric("Beat Benchmark", _fmt_pct(champion_row.get("Beat Benchmark")))
        cards[5].metric("PSR", _fmt_pct(champion_row.get("Probabilistic Sharpe")))
        cards[6].metric("Average Turnover", _fmt_pct(champion_row.get("Average Turnover")))
        cards[7].metric("Validation", status)

        tabs = st.tabs([
                "01 · Executive & Mandate",
                "02 · OOS Performance",
                "03 · Fold & Weight Stability",
                "04 · Robustness & Sensitivity",
                "05 · Statistical Evidence",
                "06 · Governance & Export",
        ])

        with tabs[0]:
                st.markdown("### Champion / Challenger Overview")
                left, right = st.columns([1.2, 0.8])
                with left:
                        st.dataframe(_pl210_summary_display(summary), width="stretch", hide_index=True, height=_pl22_height(summary, minimum=280, maximum=560))
                with right:
                        st.plotly_chart(_pl210_method_map(summary), width="stretch", key="pl210_method_map")
                st.markdown("### Validation Design Manifest")
                manifest = pd.DataFrame([
                        {"Setting": "Methods", "Value": ", ".join(effective_settings.get("methods", champion_options))},
                        {"Setting": "Training scheme", "Value": effective_settings.get("scheme", split_scheme)},
                        {"Setting": "Training / test / step", "Value": f"{effective_settings.get('training_days', training)} / {effective_settings.get('test_days', test)} / {effective_settings.get('step_days', step)} observations"},
                        {"Setting": "Embargo", "Value": f"{effective_settings.get('embargo_days', embargo)} observations"},
                        {"Setting": "Cost model", "Value": f"{effective_settings.get('cost_mode', cost_mode)} · {float(effective_settings.get('transaction_cost_bps', cost_bps)):.1f} bps"},
                        {"Setting": "Official OOS overlap rule", "Value": "Latest forecast retained when test windows overlap"},
                        {"Setting": "Portfolio implementation", "Value": "Weights fixed within each test fold; next fold re-estimates from prior accepted weights"},
                ])
                st.dataframe(manifest, width="stretch", hide_index=True)

        with tabs[1]:
                st.markdown("### Concatenated Unseen Performance")
                method_path = _pl210_unique_method_path(path, champion)
                if method_path.empty:
                        st.info("No OOS path is available for the selected method.")
                else:
                        show_gross = st.checkbox("Show gross optimized path", value=True, key="pl210_show_gross")
                        series_map = {"Optimized net": method_path["Optimized Net"], "Current": method_path["Current"], "Benchmark": method_path["Benchmark"]}
                        if show_gross and "Optimized Gross" in method_path.columns:
                                series_map = {"Optimized gross": method_path["Optimized Gross"], **series_map}
                        st.plotly_chart(_performance_growth_figure(series_map, f"Concatenated OOS Growth - {champion}"), width="stretch", key="pl210_oos_growth")
                        charts = st.columns(2)
                        charts[0].plotly_chart(_drawdown_figure({"Optimized net": method_path["Optimized Net"], "Current": method_path["Current"], "Benchmark": method_path["Benchmark"]}, "OOS Drawdown"), width="stretch", key="pl210_oos_drawdown")
                        charts[1].plotly_chart(_pl210_fold_return_figure(windows, champion), width="stretch", key="pl210_fold_returns")
                champion_windows = windows.loc[windows["Method"].astype(str) == champion].copy()
                st.markdown("### Complete Fold Ledger")
                st.dataframe(_pl210_windows_display(champion_windows), width="stretch", hide_index=True, height=_pl22_height(champion_windows, minimum=400, maximum=720))

        with tabs[2]:
                st.markdown("### Allocation Stability and Estimation Decay")
                plots = st.columns(2)
                plots[0].plotly_chart(_pl210_weight_heatmap(weights, champion), width="stretch", key="pl210_weight_heatmap")
                plots[1].plotly_chart(_pl210_sharpe_scatter(windows, champion), width="stretch", key="pl210_sharpe_scatter")
                st.plotly_chart(_pl210_transition_figure(windows, champion), width="stretch", key="pl210_transition_figure")
                stability = _pl210_weight_stability(weights, champion)
                if stability.empty:
                        st.info("No fold-level allocation matrix is available.")
                else:
                        st.dataframe(
                                stability,
                                width="stretch",
                                hide_index=True,
                                column_config={
                                        "Average Weight": st.column_config.NumberColumn(format="percent"),
                                        "Weight Volatility": st.column_config.NumberColumn(format="percent"),
                                        "Minimum Weight": st.column_config.NumberColumn(format="percent"),
                                        "Maximum Weight": st.column_config.NumberColumn(format="percent"),
                                        "Range": st.column_config.NumberColumn(format="percent"),
                                        "Selection Rate": st.column_config.NumberColumn(format="percent"),
                                },
                        )
                        unstable = stability.loc[stability["Range"] > 0.25, "Asset"].astype(str).tolist()
                        if unstable:
                                st.warning("Large fold-to-fold allocation ranges detected for: " + ", ".join(unstable))

        with tabs[3]:
                st.markdown("### Window-Design and Cost Robustness Grid")
                robustness_controls = st.columns(6)
                robust_train = robustness_controls[0].multiselect("Training designs", [252, 504, 756, 1008], default=[252, 504, 756], key="pl210_robust_train")
                robust_test = robustness_controls[1].multiselect("Test designs", [21, 63, 126, 252], default=[21, 63], key="pl210_robust_test")
                robust_cost = robustness_controls[2].multiselect("Cost assumptions", [0.0, 5.0, 10.0, 25.0, 50.0], default=[0.0, 10.0, 25.0], key="pl210_robust_cost")
                robust_step = robustness_controls[3].selectbox("Grid step policy", ["Non-overlapping", "Half-overlap"], key="pl210_robust_step")
                robust_windows = robustness_controls[4].number_input("Windows per design", 3, 10, 6, key="pl210_robust_windows")
                run_robust = robustness_controls[5].button("Run robustness grid", type="primary", width="stretch", key="pl210_run_robust")
                combinations = len(robust_train) * len(robust_test) * len(robust_cost)
                st.caption(f"Requested combinations: {combinations}. The engine executes at most 18 combinations per run to control latency.")
                if run_robust:
                        with st.spinner("Re-estimating the champion across alternate windows and cost assumptions..."):
                                robustness_table = _pl210_robustness_grid(
                                        model,
                                        champion,
                                        optimizer_settings,
                                        train_values=robust_train,
                                        test_values=robust_test,
                                        cost_values=robust_cost,
                                        step_policy=robust_step,
                                        embargo_days=int(effective_settings.get("embargo_days", embargo)),
                                        maximum_windows=int(robust_windows),
                                        cost_mode=str(effective_settings.get("cost_mode", cost_mode)),
                                        scheme=str(effective_settings.get("scheme", split_scheme)),
                                )
                                model["validation_robustness_v210"] = robustness_table
                                st.session_state["portfolio_lab_model_v1"] = model
                if not isinstance(robustness_table, pd.DataFrame) or robustness_table.empty:
                        st.markdown('<div class="pl210-empty"><strong>Robustness grid not yet executed</strong><br>Run alternate train/test/cost designs after selecting the validation champion.</div>', unsafe_allow_html=True)
                else:
                        heat_controls = st.columns(2)
                        heat_metric = heat_controls[0].selectbox("Heatmap metric", ["OOS Sharpe", "OOS CAGR", "Beat Current", "OOS Max Drawdown", "Average Turnover", "Validation Score"], key="pl210_robust_metric")
                        available_costs = sorted(pd.to_numeric(robustness_table["Cost bps"], errors="coerce").dropna().unique().tolist())
                        heat_cost = heat_controls[1].selectbox("Displayed cost", available_costs, format_func=lambda value: f"{value:.0f} bps", key="pl210_robust_cost_view")
                        st.plotly_chart(_pl210_robustness_heatmap(robustness_table, heat_metric, float(heat_cost)), width="stretch", key="pl210_robust_heatmap")
                        st.dataframe(_pl210_summary_display(robustness_table), width="stretch", hide_index=True, height=_pl22_height(robustness_table, minimum=360, maximum=680))

        with tabs[4]:
                st.markdown("### Sampling Uncertainty and Regime Evidence")
                method_path = _pl210_unique_method_path(path, champion)
                bootstrap_controls = st.columns(3)
                comparison = bootstrap_controls[0].selectbox("Active comparison", ["Current", "Benchmark"], key="pl210_bootstrap_comparison")
                block_length = bootstrap_controls[1].selectbox("Bootstrap block length", [5, 10, 21, 42, 63], index=2, key="pl210_bootstrap_block")
                repetitions = bootstrap_controls[2].selectbox("Bootstrap repetitions", [500, 1000, 2500, 5000], index=1, key="pl210_bootstrap_reps")
                if method_path.empty or comparison not in method_path.columns:
                        st.info("No aligned OOS active-return path is available for bootstrap analysis.")
                else:
                        active = method_path["Optimized Net"] - method_path[comparison]
                        bootstrap_table, bootstrap_summary = _pl210_block_bootstrap(active, repetitions=int(repetitions), block_length=int(block_length), seed=42)
                        statistical_cards = st.columns(6)
                        statistical_cards[0].metric("Probabilistic Sharpe", _fmt_pct(champion_row.get("Probabilistic Sharpe")))
                        statistical_cards[1].metric("Bootstrap P(active > 0)", _fmt_pct(bootstrap_summary.get("Probability Positive")))
                        statistical_cards[2].metric("Observed active mean", _fmt_pct(bootstrap_summary.get("Observed")))
                        statistical_cards[3].metric("95% CI low", _fmt_pct(bootstrap_summary.get("CI 2.5%")))
                        statistical_cards[4].metric("95% CI high", _fmt_pct(bootstrap_summary.get("CI 97.5%")))
                        champion_windows = windows.loc[windows["Method"].astype(str) == champion]
                        wins = int((champion_windows["OOS Net Return"] > champion_windows[f"{comparison} Return"]).sum()) if f"{comparison} Return" in champion_windows.columns else 0
                        low, high = _pl210_wilson_interval(wins, len(champion_windows))
                        statistical_cards[5].metric("Fold win-rate 95% CI", f"{_fmt_pct(low)} - {_fmt_pct(high)}")
                        st.caption(
                                "Probabilistic Sharpe tests the selected method's absolute "
                                "OOS Sharpe against zero. The bootstrap tests annualized "
                                f"active mean versus {comparison.lower()}; the two hypotheses "
                                "are intentionally different."
                        )
                        if (
                                _safe_float(champion_row.get("Probabilistic Sharpe"), 0.0) >= 0.90
                                and _safe_float(bootstrap_summary.get("Probability Positive"), 0.0) < 0.50
                        ):
                                st.warning(
                                        "Evidence split: absolute risk-adjusted performance is "
                                        "positive, but the selected method does not yet show "
                                        f"convincing relative performance versus {comparison.lower()}."
                                )
                        st.plotly_chart(_pl210_bootstrap_figure(bootstrap_table, bootstrap_summary.get("Observed", np.nan)), width="stretch", key="pl210_bootstrap_figure")
                regime = _pl210_regime_table(method_path)
                st.markdown("### OOS Regime Attribution")
                if regime.empty:
                        st.info("The OOS path is too short to resolve the rolling benchmark regimes.")
                else:
                        st.dataframe(regime, width="stretch", hide_index=True, column_config={"Share": st.column_config.NumberColumn(format="percent"), "Annualized Return": st.column_config.NumberColumn(format="percent"), "Volatility": st.column_config.NumberColumn(format="percent"), "Active vs Current": st.column_config.NumberColumn(format="percent"), "Active vs Benchmark": st.column_config.NumberColumn(format="percent")})

        with tabs[5]:
                st.markdown("### Validation Governance, Audit and Cross-Module Publication")
                governance_display = governance.copy()
                for index, row in governance_display.iterrows():
                        control = str(row["Control"])
                        observed = row["Observed"]
                        if control in {"Optimizer success rate", "Beat current portfolio", "OOS maximum drawdown", "Average turnover", "Probabilistic Sharpe", "Benchmark coverage"}:
                                governance_display.at[index, "Observed"] = _fmt_pct(observed)
                        elif control == "OOS Sharpe":
                                governance_display.at[index, "Observed"] = _fmt_num(observed)
                        elif control == "Transaction-cost treatment":
                                governance_display.at[index, "Observed"] = f"{float(observed):.1f} bps"
                st.dataframe(governance_display, width="stretch", hide_index=True, height=_pl22_height(governance_display, minimum=420, maximum=700))

                export_cols = st.columns(6)
                export_cols[0].download_button("Download summary CSV", summary.to_csv(index=False).encode("utf-8"), "validation_summary_v2101.csv", "text/csv", key="pl210_download_summary")
                export_cols[1].download_button("Download folds CSV", windows.to_csv(index=False).encode("utf-8"), "validation_folds_v2101.csv", "text/csv", key="pl210_download_folds")
                export_cols[2].download_button("Download weights CSV", weights.to_csv(index=False).encode("utf-8"), "validation_weights_v2101.csv", "text/csv", key="pl210_download_weights")
                export_cols[3].download_button("Download OOS path CSV", path.reset_index().to_csv(index=False).encode("utf-8"), "validation_oos_path_v2101.csv", "text/csv", key="pl210_download_path")
                export_cols[4].download_button("Download governance CSV", governance.to_csv(index=False).encode("utf-8"), "validation_governance_v2101.csv", "text/csv", key="pl210_download_governance")
                audit_payload = {
                        "version": "2.10.1",
                        "generated_at": datetime.now(timezone.utc).isoformat(),
                        "champion": champion,
                        "status": status,
                        "settings": effective_settings,
                        "summary": summary,
                        "windows": windows,
                        "weights": weights,
                        "oos_path": path.reset_index(),
                        "robustness": robustness_table,
                        "governance": governance,
                }
                export_cols[5].download_button("Download audit JSON", _pl210_json_payload(audit_payload), "validation_audit_v2101.json", "application/json", key="pl210_download_json")

                context = {
                        "version": "2.10.1",
                        "champion": champion,
                        "status": status,
                        "summary": summary.loc[summary["Method"].astype(str) == champion].to_dict("records"),
                        "governance": governance.to_dict("records"),
                        "settings": effective_settings,
                }
                st.caption(
                        f"Published contexts retain validation status {status}. "
                        "Publication transfers evidence only; it does not approve a model "
                        "or alter portfolio weights automatically."
                )
                publish_cols = st.columns(4)
                if publish_cols[0].button("Publish to Optimizer Studio", type="primary", width="stretch", key="pl210_publish_optimizer"):
                        st.session_state["optimizer_validation_context"] = context
                        st.success("Validation context published to Optimizer Studio.")
                if publish_cols[1].button("Publish to Decision Engine", type="primary", width="stretch", key="pl210_publish_decision"):
                        st.session_state["decision_engine_validation_context"] = context
                        st.success("Validation context published to Decision Engine.")
                if publish_cols[2].button("Publish to Risk Monitor", type="primary", width="stretch", key="pl210_publish_risk"):
                        st.session_state["risk_monitor_validation_context"] = context
                        st.success("Validation context published to Risk Monitor.")
                if publish_cols[3].button("Publish to Backtest Lab", type="primary", width="stretch", key="pl210_publish_backtest"):
                        st.session_state["backtest_lab_external_validation"] = context
                        st.success("Validation context published to Backtest Lab.")

                st.markdown(
                        """
                        <div class="pl210-boundary"><strong>Methodology boundary</strong><br>
                        The workspace uses chronological walk-forward re-estimation and unseen return evaluation. Test-fold weights remain static inside each fold, costs are charged on fold transitions, overlapping OOS dates retain the latest forecast, and statistical evidence remains sample-dependent. A PASS is a governed research decision under the selected thresholds - not proof of future performance, independent validation, regulatory approval or authorization to trade.</div>
                        """,
                        unsafe_allow_html=True,
                )


def _render_governance_v2(model: dict[str, Any]) -> None:
        st.subheader("Data, Model & Integration Control")
        st.dataframe(model["governance"], width="stretch", hide_index=True)
        if model.get("governance_warnings"):
                for warning in model["governance_warnings"]:
                        st.warning(warning)
        else:
                st.success("No material governance warning detected by the mechanical checks.")

        left, right = st.columns(2)
        with left:
                st.subheader("Market data diagnostics")
                st.dataframe(model["data_diagnostics"], width="stretch", hide_index=True)
        with right:
                st.subheader("Return coverage")
                coverage = model["coverage_table"].copy()
                if "Coverage" in coverage.columns:
                        coverage["Coverage"] = coverage["Coverage"].apply(_fmt_pct)
                st.dataframe(coverage, width="stretch", hide_index=True)

        st.subheader("Cross-module state")
        integration_rows = []
        for source, keys in KNOWN_SIGNAL_STATE_KEYS.items():
                available = [key for key in keys if key in st.session_state]
                integration_rows.append({"Module": source, "Detected Keys": ", ".join(available), "Status": "CONNECTED" if available else "WAITING"})
        integration_rows.extend(
                [
                        {"Module": "Shared Signal Bus", "Detected Keys": SIGNAL_BUS_KEY, "Status": "CONNECTED" if st.session_state.get(SIGNAL_BUS_KEY) else "EMPTY"},
                        {"Module": "Portfolio Context", "Detected Keys": PORTFOLIO_CONTEXT_KEY, "Status": "PUBLISHED" if PORTFOLIO_CONTEXT_KEY in st.session_state else "LOCAL"},
                ]
        )
        st.dataframe(pd.DataFrame(integration_rows), width="stretch", hide_index=True)

        publish_col, export_col = st.columns(2)
        if publish_col.button("Publish portfolio context", type="primary", width="stretch", key="pl_publish_context_v2"):
                publish_portfolio_context(model)
                st.success("Portfolio context published to Risk Monitor, Decision Engine, Backtest Lab and Trading Plan session contracts.")
        export_data = build_export_zip_v2(model)
        export_col.download_button(
                "Download institutional audit pack",
                data=export_data,
                file_name=f"portfolio_lab_v2_audit_{datetime.now().strftime('%Y%m%d_%H%M%S')}.zip",
                mime="application/zip",
                width="stretch",
        )

        st.subheader("Model manifest")
        st.json(model["manifest"])


# =============================================================================
# V2 PUBLIC ENTRY POINT - BACKWARD-COMPATIBLE REBIND
# =============================================================================


def render_portfolio_lab_v2(
        ticker: str | None = None,
        price_data: pd.DataFrame | None = None,
        analysis: dict[str, Any] | None = None,
) -> None:
        """Render the institutional Portfolio Lab 2.4 workbench.

        ``price_data`` and ``analysis`` remain compatible with the parent router.
        The single-ticker analysis is also offered to the Signal Hub instead of
        being discarded as in v1.
        """
        del price_data    # Multi-asset market data remain managed internally.

        _inject_portfolio_css_v22()
        _render_header_v2()

        existing_model = st.session_state.get("portfolio_lab_model_v1")
        with st.expander("Portfolio Book & Model Configuration", expanded=not isinstance(existing_model, dict)):
                book = _render_book_editor(ticker)
                settings, run_model = _render_settings_form()
                bl_views = _render_bl_views(book, settings.expected_return_model == "Black-Litterman")

                action_cols = st.columns([1, 1, 2])
                action_cols[0].caption("Run builds the aligned multi-asset data, expected-return and covariance models.")
                if action_cols[1].button("Clear analytics", width="stretch", key="pl_clear_model_v2"):
                        for key in [
                                "portfolio_lab_model_v1", "pl_frontier_v2", "pl_frontier_alloc_v2",
                                "portfolio_lab_whatif_weights_v2",
                        ]:
                                st.session_state.pop(key, None)
                        st.rerun()
                action_cols[2].caption("Model outputs remain stale after a book edit until Run Portfolio Lab is pressed again.")

                if run_model:
                        try:
                                with st.spinner("Building portfolio book, market data, covariance, risk and governance layers..."):
                                        model = build_portfolio_model(book, settings, bl_views=bl_views)
                                        model = enhance_model_v2(model)
                                st.session_state["portfolio_lab_model_v1"] = model
                                publish_portfolio_context(model)
                                st.success(f"Portfolio Lab {PORTFOLIO_LAB_VERSION} model built. Review Governance before relying on outputs.")
                        except Exception as exc:
                                st.error(f"Portfolio model failed: {exc}")

        model = st.session_state.get("portfolio_lab_model_v1")
        if not isinstance(model, dict):
                st.info("Configure the Portfolio Book, then click Run Portfolio Lab.")
                st.caption("The demonstration portfolio is never loaded automatically and is not presented as a real portfolio.")
                return

        # Upgrade a previously built v1 model in memory without forcing another
        # market-data download.
        if "current_extended_metrics" not in model:
                model = enhance_model_v2(model)
                st.session_state["portfolio_lab_model_v1"] = model

        current_fingerprint = _book_fingerprint(book)
        if model.get("book_fingerprint") != current_fingerprint:
                st.warning("Portfolio Book changed after the last model run. Analytics below still use the previous resolved book; rerun Portfolio Lab before making a decision.")

        # Refresh cross-module discovery without changing expected returns until the
        # user explicitly approves the overlay in Signal Hub.
        discovered_signals = collect_terminal_signals(model["book"], analysis, ticker)
        if not discovered_signals.empty:
                source_weights = DEFAULT_SIGNAL_SOURCE_WEIGHTS
                consensus, _ = aggregate_terminal_signals(discovered_signals, model["expected_returns"], source_weights, 0.08)
                model["discovered_signal_records"] = discovered_signals
                if model.get("signal_consensus", pd.DataFrame()).empty:
                        model["signal_consensus_preview"] = consensus

        _render_model_status_strip(model)

        sections = [
                "Command Center",
                "Book & What-If",
                "Optimizer Studio",
                "Risk & Factors",
                "Performance Lab",
                "Attribution",
                "Rebalance & TCA",
                "Stress & Scenarios",
                "Signal Hub",
                "Validation",
                "Governance & Export",
        ]
        section = st.radio(
                "Portfolio workspace",
                sections,
                horizontal=True,
                label_visibility="collapsed",
                key="portfolio_lab_workspace_v2",
        )

        if section == "Command Center":
                _render_dashboard_v2(model)
        elif section == "Book & What-If":
                _render_book_whatif_v2(model)
        elif section == "Optimizer Studio":
                model = _render_optimizer_studio_v2(model)
        elif section == "Risk & Factors":
                _render_risk_factors_v2(model)
        elif section == "Performance Lab":
                _render_performance_lab_v2(model)
        elif section == "Attribution":
                _render_attribution_v2(model)
        elif section == "Rebalance & TCA":
                _render_rebalance_tca_v2(model)
        elif section == "Stress & Scenarios":
                _render_scenarios_v2(model)
        elif section == "Signal Hub":
                model = _render_signal_hub_v2(model, analysis, ticker)
        elif section == "Validation":
                _render_validation_v2(model)
        elif section == "Governance & Export":
                _render_governance_v2(model)


# Existing app.py integrations import render_portfolio_lab_v1. Rebinding keeps
# that import stable while delivering the v2 implementation.
render_portfolio_lab_v1 = render_portfolio_lab_v2
render_portfolio_lab = render_portfolio_lab_v2

