def _pl25_clean_return_series(series: pd.Series | None) -> pd.Series:
    if series is None:
        return pd.Series(dtype=float)
    clean = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
    if isinstance(clean.index, pd.DatetimeIndex):
        clean = clean[~clean.index.duplicated(keep="last")].sort_index()
    return clean.astype(float)


def _pl25_slice_frame(
    frame: pd.DataFrame,
    benchmark: pd.Series,
    window_mode: str,
    custom_start: Any = None,
    custom_end: Any = None,
) -> tuple[pd.DataFrame, pd.Series, str]:
    returns = frame.apply(pd.to_numeric, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna(how="all")
    bench = _pl25_clean_return_series(benchmark).reindex(returns.index)
    if returns.empty:
        return returns, bench, "No observations"

    end = pd.Timestamp(returns.index.max())
    if window_mode == "1Y":
        start = end - pd.DateOffset(years=1)
    elif window_mode == "3Y":
        start = end - pd.DateOffset(years=3)
    elif window_mode == "5Y":
        start = end - pd.DateOffset(years=5)
    elif window_mode == "Custom":
        start = pd.Timestamp(custom_start) if custom_start is not None else pd.Timestamp(returns.index.min())
        end = pd.Timestamp(custom_end) if custom_end is not None else end
    else:
        start = pd.Timestamp(returns.index.min())

    sliced = returns.loc[(returns.index >= start) & (returns.index <= end)].copy()
    sliced_benchmark = bench.reindex(sliced.index)
    label = f"{pd.Timestamp(sliced.index.min()).date()} – {pd.Timestamp(sliced.index.max()).date()}" if not sliced.empty else "No observations"
    return sliced, sliced_benchmark, label


def _pl25_monthly_heatmap_figure(matrix: pd.DataFrame, title: str) -> go.Figure:
    """Pandas 3.x compatible monthly heatmap without DataFrame.applymap."""
    if matrix is None or matrix.empty:
        fig = go.Figure()
        fig.update_layout(title=title, height=360, annotations=[dict(text="No monthly data", x=0.5, y=0.5, showarrow=False)])
        return fig

    numeric = matrix.apply(pd.to_numeric, errors="coerce")
    text = pd.DataFrame(index=numeric.index, columns=numeric.columns, dtype=object)
    for column in numeric.columns:
        text[column] = numeric[column].map(lambda value: "" if pd.isna(value) else f"{float(value):.1%}")

    finite = numeric.to_numpy(dtype=float)
    finite = finite[np.isfinite(finite)]
    scale = float(np.nanquantile(np.abs(finite), 0.95)) if finite.size else 0.10
    scale = max(scale, 0.03)

    fig = go.Figure(
        go.Heatmap(
            z=numeric.values,
            x=numeric.columns,
            y=numeric.index.astype(str),
            text=text.values,
            texttemplate="%{text}",
            textfont=dict(size=11),
            colorscale="RdYlGn",
            zmid=0.0,
            zmin=-scale,
            zmax=scale,
            colorbar=dict(title="Return", tickformat=".0%"),
            hovertemplate="%{y} · %{x}<br>Return %{z:.2%}<extra></extra>",
        )
    )
    fig.update_layout(
        title=title,
        height=max(360, 34 * len(numeric) + 130),
        margin=dict(l=20, r=20, t=60, b=30),
        xaxis_title="Month",
        yaxis_title="Year",
    )
    return fig


# Rebind the legacy helper so every existing call becomes pandas 3.x safe.
_monthly_heatmap_figure = _pl25_monthly_heatmap_figure


