def _pl25_period_return(series: pd.Series, start: pd.Timestamp, end: pd.Timestamp, annualize: bool = False) -> float:
    clean = _pl25_clean_return_series(series)
    selected = clean.loc[(clean.index >= start) & (clean.index <= end)] if isinstance(clean.index, pd.DatetimeIndex) else clean
    if selected.empty:
        return np.nan
    total = float((1.0 + selected).prod() - 1.0)
    if not annualize:
        return total
    years = len(selected) / TRADING_DAYS
    if years <= 0.0 or total <= -1.0:
        return np.nan
    return float((1.0 + total) ** (1.0 / years) - 1.0)


def _pl25_trailing_return_table(series_map: Mapping[str, pd.Series]) -> pd.DataFrame:
    valid = {name: _pl25_clean_return_series(series) for name, series in series_map.items()}
    valid = {name: series for name, series in valid.items() if not series.empty and isinstance(series.index, pd.DatetimeIndex)}
    if not valid:
        return pd.DataFrame()

    common_end = min(series.index.max() for series in valid.values())
    quarter_month = ((common_end.month - 1) // 3) * 3 + 1
    definitions = [
        ("MTD", pd.Timestamp(common_end.year, common_end.month, 1), False, "Cumulative"),
        ("QTD", pd.Timestamp(common_end.year, quarter_month, 1), False, "Cumulative"),
        ("YTD", pd.Timestamp(common_end.year, 1, 1), False, "Cumulative"),
        ("1Y", common_end - pd.DateOffset(years=1), False, "Cumulative"),
        ("3Y", common_end - pd.DateOffset(years=3), True, "Annualized"),
        ("5Y", common_end - pd.DateOffset(years=5), True, "Annualized"),
    ]
    common_start = max(series.index.min() for series in valid.values())
    rows: list[dict[str, Any]] = []
    for label, start, annualize, convention in definitions:
        row: dict[str, Any] = {"Period": label, "Convention": convention}
        for name, series in valid.items():
            enough = series.index.min() <= start
            row[name] = _pl25_period_return(series, start, common_end, annualize) if enough else np.nan
        rows.append(row)

    si_years = max((common_end - common_start).days / 365.25, 0.0)
    si_row: dict[str, Any] = {"Period": "Since inception", "Convention": "Annualized" if si_years > 1.0 else "Cumulative"}
    for name, series in valid.items():
        si_row[name] = _pl25_period_return(series, common_start, common_end, si_years > 1.0)
    rows.append(si_row)
    return pd.DataFrame(rows)


def _pl25_metrics_table(
    current: Mapping[str, Any],
    target: Mapping[str, Any],
    benchmark: Mapping[str, Any],
) -> pd.DataFrame:
    metric_groups = {
        "Return": ["Cumulative Return", "CAGR", "Arithmetic Return", "Best Month", "Worst Month", "Best Year", "Worst Year"],
        "Risk": ["Annualized Volatility", "Downside Deviation", "Max Drawdown", "Average Drawdown", "Ulcer Index", "Pain Index", "VaR 95% (1D)", "CVaR 95% (1D)", "VaR 99% (1D)", "CVaR 99% (1D)"],
        "Risk-adjusted": ["Sharpe", "Sortino", "Calmar", "Omega", "UPI", "Recovery Factor", "Serenity Ratio", "Tail Ratio", "Gain / Loss Ratio"],
        "Distribution": ["Win Rate", "Skew", "Excess Kurtosis", "Best Day", "Worst Day", "Max Time Underwater (days)"],
        "Benchmark-relative": ["Beta", "Alpha", "R²", "Active Return", "Tracking Error", "Information Ratio", "Treynor Ratio", "M²", "Upside Capture", "Downside Capture"],
    }
    rows: list[dict[str, Any]] = []
    for category, metrics in metric_groups.items():
        for metric in metrics:
            c = _safe_float(current.get(metric))
            t = _safe_float(target.get(metric))
            b = _safe_float(benchmark.get(metric))
            rows.append(
                {
                    "Category": category,
                    "Metric": metric,
                    "Current": c,
                    "Target": t,
                    "Benchmark": b,
                    "Target vs Current": np.nan if c is None or t is None else t - c,
                    "Target vs Benchmark": np.nan if b is None or t is None else t - b,
                }
            )
    return pd.DataFrame(rows)


def _pl25_metric_display_table(table: pd.DataFrame) -> pd.DataFrame:
    if table.empty:
        return table
    percent_metrics = {
        "Cumulative Return", "CAGR", "Arithmetic Return", "Best Month", "Worst Month", "Best Year", "Worst Year",
        "Annualized Volatility", "Downside Deviation", "Max Drawdown", "Average Drawdown", "Ulcer Index", "Pain Index",
        "VaR 95% (1D)", "CVaR 95% (1D)", "VaR 99% (1D)", "CVaR 99% (1D)", "Win Rate", "Best Day", "Worst Day",
        "Alpha", "Active Return", "Tracking Error", "M²",
    }
    capture_metrics = {"Upside Capture", "Downside Capture"}
    rows: list[dict[str, Any]] = []
    for _, row in table.iterrows():
        metric = str(row["Metric"])
        if metric in percent_metrics:
            formatter = _fmt_pct
        elif metric in capture_metrics:
            formatter = lambda value: "N/A" if _safe_float(value) is None else f"{float(value):.1f}%"
        elif metric == "Max Time Underwater (days)":
            formatter = lambda value: "N/A" if _safe_float(value) is None else f"{int(round(float(value)))}"
        else:
            formatter = _fmt_num
        output = {"Category": row["Category"], "Metric": metric}
        for column in ["Current", "Target", "Benchmark", "Target vs Current", "Target vs Benchmark"]:
            value = _safe_float(row[column])
            if value is None:
                output[column] = "N/A"
            elif column.startswith("Target vs") and metric in percent_metrics:
                output[column] = f"{value:+.2%}"
            elif column.startswith("Target vs") and metric in capture_metrics:
                output[column] = f"{value:+.1f} pp"
            elif column.startswith("Target vs"):
                output[column] = f"{value:+.2f}"
            else:
                output[column] = formatter(value)
        rows.append(output)
    return pd.DataFrame(rows)


def _pl25_rolling_frame(
    portfolio: pd.Series,
    benchmark: pd.Series,
    window: int,
    risk_free_rate: float,
) -> pd.DataFrame:
    p = _pl25_clean_return_series(portfolio)
    b = _pl25_clean_return_series(benchmark).reindex(p.index)
    result = rolling_analytics(p, b, int(window), float(risk_free_rate))
    daily_rf = (1.0 + float(risk_free_rate)) ** (1.0 / TRADING_DAYS) - 1.0

    result["Rolling CAGR"] = (1.0 + p).rolling(window).apply(np.prod, raw=True) ** (TRADING_DAYS / window) - 1.0
    downside = p - daily_rf
    result["Rolling Sortino"] = (
        downside.rolling(window).mean() * TRADING_DAYS
        / downside.clip(upper=0.0).pow(2).rolling(window).mean().pow(0.5).mul(math.sqrt(TRADING_DAYS)).replace(0.0, np.nan)
    )

    aligned = pd.concat([p.rename("p"), b.rename("b")], axis=1).dropna()
    if not aligned.empty:
        active = aligned["p"] - aligned["b"]
        te = active.rolling(window).std(ddof=1) * math.sqrt(TRADING_DAYS)
        result.loc[aligned.index, "Rolling Tracking Error"] = te
        result.loc[aligned.index, "Rolling Information Ratio"] = active.rolling(window).mean() * TRADING_DAYS / te.replace(0.0, np.nan)

    def rolling_var(values: np.ndarray) -> float:
        clean = values[np.isfinite(values)]
        return -float(np.quantile(clean, 0.05)) if len(clean) else np.nan

    def rolling_cvar(values: np.ndarray) -> float:
        clean = values[np.isfinite(values)]
        if not len(clean):
            return np.nan
        q = float(np.quantile(clean, 0.05))
        tail = clean[clean <= q]
        return -float(np.mean(tail)) if len(tail) else -q

    def rolling_max_dd(values: np.ndarray) -> float:
        clean = values[np.isfinite(values)]
        if not len(clean):
            return np.nan
        wealth = np.cumprod(1.0 + clean)
        peak = np.maximum.accumulate(wealth)
        return float(np.min(wealth / np.maximum(peak, EPS) - 1.0))

    result["Rolling VaR 95%"] = p.rolling(window).apply(rolling_var, raw=True)
    result["Rolling CVaR 95%"] = p.rolling(window).apply(rolling_cvar, raw=True)
    result["Rolling Max Drawdown"] = p.rolling(window).apply(rolling_max_dd, raw=True)
    return result


