def _pl25_regime_table(
    target: pd.Series,
    benchmark: pd.Series,
    window: int = 63,
) -> pd.DataFrame:
    aligned = pd.concat([
        _pl25_clean_return_series(target).rename("Target"),
        _pl25_clean_return_series(benchmark).rename("Benchmark"),
    ], axis=1).dropna()
    if len(aligned) < max(window + 20, 80):
        return pd.DataFrame()

    benchmark_trend = (1.0 + aligned["Benchmark"]).rolling(window).apply(np.prod, raw=True) - 1.0
    target_vol = aligned["Target"].rolling(window).std(ddof=1) * math.sqrt(TRADING_DAYS)
    vol_cut = float(target_vol.dropna().median())
    regime = pd.Series(index=aligned.index, dtype=object)
    bull = benchmark_trend >= 0.0
    high_vol = target_vol > vol_cut
    regime.loc[bull & ~high_vol] = "Bull / Lower volatility"
    regime.loc[bull & high_vol] = "Bull / Higher volatility"
    regime.loc[~bull & ~high_vol] = "Bear / Lower volatility"
    regime.loc[~bull & high_vol] = "Bear / Higher volatility"

    rows: list[dict[str, Any]] = []
    for label, dates in regime.dropna().groupby(regime.dropna()).groups.items():
        selected = aligned.loc[dates]
        target_series = selected["Target"]
        benchmark_series = selected["Benchmark"]
        vol = float(target_series.std(ddof=1) * math.sqrt(TRADING_DAYS)) if len(target_series) > 1 else np.nan
        ret = float(target_series.mean() * TRADING_DAYS)
        bench_ret = float(benchmark_series.mean() * TRADING_DAYS)
        rows.append(
            {
                "Regime": label,
                "Observations": len(selected),
                "Share": len(selected) / len(regime.dropna()),
                "Target Return": ret,
                "Target Volatility": vol,
                "Target Sharpe": _safe_div(ret, vol),
                "Benchmark Return": bench_ret,
                "Active Return": ret - bench_ret,
                "Positive-Day Rate": float((target_series > 0.0).mean()),
            }
        )
    return pd.DataFrame(rows).sort_values("Regime").reset_index(drop=True)


def _pl25_distribution_table(series_map: Mapping[str, pd.Series]) -> pd.DataFrame:
    rows: list[dict[str, Any]] = []
    for name, series in series_map.items():
        clean = _pl25_clean_return_series(series)
        if clean.empty:
            continue
        var95, cvar95 = historical_var_cvar(clean, 0.95)
        var99, cvar99 = historical_var_cvar(clean, 0.99)
        rows.append(
            {
                "Portfolio": name,
                "Mean Daily": float(clean.mean()),
                "Daily Volatility": float(clean.std(ddof=1)),
                "Win Rate": float((clean > 0.0).mean()),
                "Skew": float(clean.skew()),
                "Excess Kurtosis": float(clean.kurt()),
                "VaR 95%": var95,
                "CVaR 95%": cvar95,
                "VaR 99%": var99,
                "CVaR 99%": cvar99,
                "Best Day": float(clean.max()),
                "Worst Day": float(clean.min()),
            }
        )
    return pd.DataFrame(rows)


