        worst_windows = _pl25_worst_window_table(series_map)
        if not worst_windows.empty:
            st.markdown('<div class="pl2-subhead">Best & Worst Rolling Windows</div>', unsafe_allow_html=True)
            st.dataframe(worst_windows, width="stretch", hide_index=True)

        st.markdown('<div class="pl2-subhead">Drawdown Episodes</div>', unsafe_allow_html=True)
