        export_cols[1].download_button("Download trailing CSV", trailing.to_csv(index=False).encode("utf-8"), file_name="trailing_returns_v25.csv", mime="text/csv", width="stretch", key="pl25_download_trailing")
        export_cols[2].download_button("Download annual CSV", annual.reset_index().to_csv(index=False).encode("utf-8") if not annual.empty else b"", file_name="annual_returns_v25.csv", mime="text/csv", width="stretch", key="pl25_download_annual")
        export_cols[3].download_button("Download drawdowns CSV", all_episodes.to_csv(index=False).encode("utf-8") if not all_episodes.empty else b"", file_name="drawdown_episodes_v25.csv", mime="text/csv", width="stretch", key="pl25_download_drawdowns")
        export_cols[4].download_button("Download audit JSON", _pl25_json_payload(context), file_name="performance_audit_v25.json", mime="application/json", width="stretch", key="pl25_download_json")

        publish_cols = st.columns(3)
