def _pl211_normalize_status(value: Any, default: str = "N/A") -> str:
    text = str(value or "").strip().upper().replace("_", " ")
    aliases = {
        "OK": "PASS",
        "SUCCESS": "PASS",
        "VALID": "PASS",
        "AVAILABLE": "READY",
        "PRESENT": "READY",
        "WARNING": "REVIEW",
        "WARN": "REVIEW",
        "LIMITED": "REVIEW",
        "ERROR": "FAIL",
        "KO": "FAIL",
        "FAILED": "FAIL",
        "NOT AVAILABLE": "N/A",
        "NONE": "N/A",
        "NA": "N/A",
    }
    text = aliases.get(text, text)
    return text if text in PL211_STATUS_SCORE else default


def _pl211_combine_status(statuses: Iterable[Any], default: str = "N/A") -> str:
    normalized = [_pl211_normalize_status(value, default="N/A") for value in statuses]
    normalized = [value for value in normalized if value != "N/A"]
    if not normalized:
        return default
    if "FAIL" in normalized:
        return "FAIL"
    if any(value in {"REVIEW", "NOT RUN", "WAITING", "EMPTY", "LOCAL"} for value in normalized):
        return "REVIEW"
    if any(value == "NO TRANSITION" for value in normalized):
        return "NO TRANSITION"
    if any(value in {"PASS", "READY", "PUBLISHED", "CONNECTED"} for value in normalized):
        return "PASS"
    return default


def _pl211_recursive_statuses(value: Any, depth: int = 0) -> list[str]:
    if depth > 5 or value is None:
        return []
    statuses: list[str] = []
    if isinstance(value, pd.DataFrame):
        for column in value.columns:
            if str(column).strip().lower() in {"status", "governance", "validation", "state"}:
                statuses.extend(value[column].dropna().astype(str).tolist())
        return statuses
    if isinstance(value, Mapping):
        for key, item in value.items():
            if str(key).strip().lower() in {"status", "governance", "validation", "state", "overall status", "overall_status"}:
                if isinstance(item, (str, int, float, bool)):
                    statuses.append(str(item))
            else:
                statuses.extend(_pl211_recursive_statuses(item, depth + 1))
        return statuses
    if isinstance(value, (list, tuple)):
        for item in value[:250]:
            statuses.extend(_pl211_recursive_statuses(item, depth + 1))
    return statuses


def _pl211_parse_timestamp(value: Any) -> pd.Timestamp:
    try:
        stamp = pd.Timestamp(value)
        if pd.isna(stamp):
            return pd.NaT
        if stamp.tzinfo is None:
            stamp = stamp.tz_localize("UTC")
        else:
            stamp = stamp.tz_convert("UTC")
        return stamp
    except Exception:
        return pd.NaT


def _pl211_find_timestamp(value: Any, depth: int = 0) -> pd.Timestamp:
    if depth > 5 or value is None:
        return pd.NaT
    preferred = {
        "timestamp", "generated_at_utc", "enhanced_at_utc", "as_of", "published_at",
        "created_at", "updated_at", "archived_at", "date",
    }
    if isinstance(value, Mapping):
        for key, item in value.items():
            if str(key).strip().lower() in preferred:
                stamp = _pl211_parse_timestamp(item)
                if not pd.isna(stamp):
                    return stamp
        for item in value.values():
            stamp = _pl211_find_timestamp(item, depth + 1)
            if not pd.isna(stamp):
                return stamp
    elif isinstance(value, pd.DataFrame) and not value.empty:
        for column in value.columns:
            if str(column).strip().lower() in preferred:
                series = pd.to_datetime(value[column], errors="coerce", utc=True).dropna()
                if not series.empty:
                    return pd.Timestamp(series.max())
    elif isinstance(value, (list, tuple)):
        for item in value[:50]:
            stamp = _pl211_find_timestamp(item, depth + 1)
            if not pd.isna(stamp):
                return stamp
    return pd.NaT


def _pl211_age_days(value: Any) -> float:
    stamp = _pl211_find_timestamp(value)
    if pd.isna(stamp):
        return np.nan
    now = pd.Timestamp.now(tz="UTC")
    return max(float((now - stamp).total_seconds() / 86400.0), 0.0)


def _pl211_record_count(value: Any) -> int:
    if value is None:
        return 0
    if isinstance(value, pd.DataFrame):
        return int(len(value))
    if isinstance(value, pd.Series):
        return int(value.notna().sum())
    if isinstance(value, Mapping):
        candidates = []
        for item in value.values():
            if isinstance(item, (pd.DataFrame, pd.Series, list, tuple)):
                candidates.append(_pl211_record_count(item))
        return max(candidates, default=len(value))
    if isinstance(value, (list, tuple)):
        return len(value)
    return 1


def _pl211_context_for_module(model: Mapping[str, Any], model_key: str | None, session_keys: Sequence[str]) -> Any:
    if model_key and model_key in model:
        value = model.get(model_key)
        if value is not None:
            return value
    for key in session_keys:
        if key in st.session_state:
            return st.session_state.get(key)
    return None


def _pl211_module_registry(model: Mapping[str, Any]) -> pd.DataFrame:
    specs = [
        ("Book & Model", "Foundation", None, [], "Critical", "Portfolio book, aligned returns and covariance"),
        ("Optimizer Studio", "Construction", "optimizer_suite_table", ["optimizer_validation_context"], "High", "Candidate allocations and solver diagnostics"),
        ("Risk & Factors", "Risk", "risk_factor_context_v24", ["risk_monitor_portfolio_context"], "Critical", "Risk decomposition, limits and factor evidence"),
        ("Performance Lab", "Performance", "performance_context_v25", ["risk_monitor_performance_context"], "High", "Gross/net performance and rebalancing evidence"),
        ("Attribution", "Performance", "attribution_context_v26", ["risk_monitor_attribution_context"], "Medium", "Absolute, active and risk-adjusted attribution"),
        ("Rebalance & TCA", "Execution", "rebalance_tca_context_v27", ["trading_plan_portfolio_context"], "High", "Orders, liquidity, cost and implementation controls"),
        ("Stress & Scenarios", "Risk", "stress_scenarios_context_v28", ["risk_monitor_stress_context"], "Critical", "Historical, hypothetical, tail and reverse stress"),
        ("Signal Hub", "Research", "signal_context_v29", ["portfolio_lab_signal_context_v29"], "Medium", "Governed source consensus and alpha overlay"),
        ("Validation", "Model Risk", "validation_governance_v210", ["optimizer_validation_context"], "Critical", "Chronological OOS evidence and acceptance policy"),
        ("Portfolio Publication", "Integration", None, [PORTFOLIO_CONTEXT_KEY, PL211_PUBLICATION_KEY], "High", "Versioned downstream portfolio context"),
    ]
    rows: list[dict[str, Any]] = []
    for module, layer, model_key, session_keys, materiality, output in specs:
        context = _pl211_context_for_module(model, model_key, session_keys)
        statuses = _pl211_recursive_statuses(context)
        status = _pl211_combine_status(statuses, default="N/A")
        state = "READY"
        if module == "Book & Model":
            context = model
            governance = model.get("governance", pd.DataFrame())
            status = _pl211_combine_status(_pl211_recursive_statuses(governance), default="PASS")
        elif module == "Optimizer Studio":
            optimizer = model.get("optimizer")
            suite = model.get("optimizer_suite_table", pd.DataFrame())
            if optimizer is not None:
                status = "PASS" if bool(getattr(optimizer, "success", False)) else "REVIEW"
            elif isinstance(suite, pd.DataFrame) and not suite.empty:
                status = _pl211_combine_status(_pl211_recursive_statuses(suite), default="REVIEW")
                state = "CANDIDATES"
            else:
                status, state = "NOT RUN", "WAITING"
        elif module == "Validation":
            governance = model.get("validation_governance_v210", pd.DataFrame())
            if isinstance(governance, pd.DataFrame) and not governance.empty:
                status = _pl211_combine_status(governance.get("Status", pd.Series(dtype=str)), default="REVIEW")
                state = str(model.get("validation_champion_v210", "EVIDENCE"))
            else:
                status, state = "NOT RUN", "WAITING"
        elif module == "Portfolio Publication":
            governed = st.session_state.get(PL211_PUBLICATION_KEY)
            compatibility = st.session_state.get(PORTFOLIO_CONTEXT_KEY)
            if isinstance(governed, Mapping):
                status, state, context = "PASS", "GOVERNED", governed
            elif isinstance(compatibility, Mapping):
                # A legacy/compatibility publication preserves downstream
                # contracts but is not equivalent to the governed 2.11 gate.
                status, state, context = "REVIEW", "COMPATIBILITY", compatibility
            else:
                status, state = "LOCAL", "LOCAL"
        elif context is None or _pl211_record_count(context) == 0:
            if module == "Signal Hub" and _pl29_model_signal_count(model) == 0:
                status, state = "N/A", "EMPTY"
            else:
                status, state = "NOT RUN", "WAITING"
        else:
            status = _pl211_combine_status(statuses, default="PASS")
            state = "AVAILABLE"

        stamp = _pl211_find_timestamp(context)
        rows.append(
            {
                "Module": module,
                "Layer": layer,
                "State": state,
                "Governance": status,
                "Last Update": stamp.isoformat() if not pd.isna(stamp) else "N/A",
                "Age Days": _pl211_age_days(context),
                "Records": _pl211_record_count(context),
                "Materiality": materiality,
                "Primary Output": output,
            }
        )
    return pd.DataFrame(rows)


def _pl211_data_quality_table(model: Mapping[str, Any]) -> pd.DataFrame:
    returns = model.get("returns", pd.DataFrame())
    covariance = model.get("covariance", pd.DataFrame())
    benchmark = model.get("benchmark_returns", pd.Series(dtype=float))
    coverage = model.get("coverage_table", pd.DataFrame())
    current_weights = pd.Series(model.get("current_weights", {}), dtype=float)
    target_weights = pd.Series(model.get("target_weights", {}), dtype=float)
    settings = model.get("settings")
    minimum_coverage = float(getattr(settings, "min_coverage", 0.80)) if settings is not None else 0.80

    observations = len(returns) if isinstance(returns, pd.DataFrame) else 0
    assets = len(returns.columns) if isinstance(returns, pd.DataFrame) else 0
    duplicate_dates = int(pd.Index(returns.index).duplicated().sum()) if isinstance(returns, pd.DataFrame) else 0
    numeric_returns = returns.apply(pd.to_numeric, errors="coerce") if isinstance(returns, pd.DataFrame) else pd.DataFrame()
    nonfinite = int((~np.isfinite(numeric_returns.to_numpy(dtype=float, copy=True))).sum()) if not numeric_returns.empty else 0
    missing_ratio = float(numeric_returns.isna().mean().mean()) if not numeric_returns.empty else 1.0
    benchmark_coverage = float(benchmark.reindex(returns.index).notna().mean()) if isinstance(benchmark, pd.Series) and observations else 0.0
    minimum_asset_coverage = np.nan
    if isinstance(coverage, pd.DataFrame) and not coverage.empty and "Coverage" in coverage.columns:
        minimum_asset_coverage = float(pd.to_numeric(coverage["Coverage"], errors="coerce").min())

    minimum_eigenvalue = np.nan
    condition_number = np.nan
    if isinstance(covariance, pd.DataFrame) and not covariance.empty:
        values = np.array(covariance.to_numpy(dtype=float, copy=True), dtype=float, copy=True)
        values = 0.5 * (values + values.T)
        eigenvalues = np.linalg.eigvalsh(values)
        minimum_eigenvalue = float(eigenvalues.min())
        diagonal = np.diag(values)
        risky = diagonal > 1e-8
        block = values[np.ix_(risky, risky)]
        if block.size:
            condition_number = float(np.linalg.cond(block))

    quote_age = np.nan
    diagnostics = model.get("data_diagnostics", pd.DataFrame())
    if isinstance(diagnostics, pd.DataFrame) and not diagnostics.empty and "End" in diagnostics.columns:
        end_dates = pd.to_datetime(diagnostics["End"], errors="coerce", utc=True).dropna()
        if not end_dates.empty:
            quote_age = max(float((pd.Timestamp.now(tz="UTC").normalize() - end_dates.min().normalize()).days), 0.0)
    if not np.isfinite(quote_age):
        governance = model.get("governance", pd.DataFrame())
        if isinstance(governance, pd.DataFrame) and not governance.empty:
            match = governance.loc[governance.get("Check", pd.Series(dtype=str)).astype(str).str.contains("staleness", case=False, na=False)]
            if not match.empty:
                quote_age = _safe_float(match.iloc[0].get("Value"), np.nan)

    controls = [
        ("Active return assets", assets, ">= 2", "PASS" if assets >= 2 else "FAIL", "Critical", "Data Owner", "Aligned risky and liquidity assets"),
        ("Aligned observations", observations, f">= {MIN_OBSERVATIONS}", "PASS" if observations >= MIN_OBSERVATIONS else "FAIL", "Critical", "Data Owner", "Complete-case return matrix"),
        ("Duplicate return dates", duplicate_dates, "= 0", "PASS" if duplicate_dates == 0 else "FAIL", "Critical", "Data Owner", "Chronological uniqueness"),
        ("Non-finite return cells", nonfinite, "= 0", "PASS" if nonfinite == 0 else "FAIL", "Critical", "Data Owner", "Numeric integrity"),
        ("Average missing-return ratio", missing_ratio, "<= 2%", "PASS" if missing_ratio <= 0.02 else "REVIEW", "High", "Data Owner", "Post-alignment completeness"),
        ("Minimum asset coverage", minimum_asset_coverage, f">= {minimum_coverage:.0%}", "PASS" if np.isfinite(minimum_asset_coverage) and minimum_asset_coverage >= minimum_coverage else "REVIEW", "High", "Data Owner", "Configured retention policy"),
        ("Benchmark coverage", benchmark_coverage, ">= 95%", "PASS" if benchmark_coverage >= 0.95 else "REVIEW", "High", "Performance Owner", "Aligned active-risk dates"),
        ("Oldest quote age", quote_age, "<= 7 days", "PASS" if np.isfinite(quote_age) and quote_age <= 7 else "REVIEW", "High", "Data Owner", "Latest resolved market date"),
        ("Covariance minimum eigenvalue", minimum_eigenvalue, ">= -1e-10", "PASS" if np.isfinite(minimum_eigenvalue) and minimum_eigenvalue >= -1e-10 else "FAIL", "Critical", "Model Owner", "PSD integrity"),
        ("Covariance condition number", condition_number, "< 1e8", "PASS" if np.isfinite(condition_number) and condition_number < 1e8 else "REVIEW", "High", "Model Owner", "Stochastic sleeve conditioning"),
        ("Current weights sum", float(current_weights.sum()), "= 100%", "PASS" if abs(float(current_weights.sum()) - 1.0) <= 1e-6 else "FAIL", "Critical", "Portfolio Owner", "Current portfolio reconciliation"),
        ("Target weights sum", float(target_weights.sum()), "= 100%", "PASS" if abs(float(target_weights.sum()) - 1.0) <= 1e-6 else "FAIL", "Critical", "Portfolio Owner", "Target portfolio reconciliation"),
    ]
    return pd.DataFrame(controls, columns=["Control", "Observed", "Threshold", "Status", "Severity", "Owner", "Evidence"])


def _pl211_pipeline_table(model: Mapping[str, Any], data_quality: pd.DataFrame, modules: pd.DataFrame) -> pd.DataFrame:
    module_status = modules.set_index("Module")["Governance"].to_dict() if not modules.empty else {}
    critical_data = data_quality.loc[data_quality["Severity"].eq("Critical"), "Status"].tolist()
    data_status = _pl211_combine_status(critical_data, default="REVIEW")
    model_status = _pl211_combine_status(model.get("governance", pd.DataFrame()).get("Status", pd.Series(dtype=str)), default="PASS")
    current_weights = pd.Series(model.get("current_weights", {}), dtype=float)
    target_weights = pd.Series(model.get("target_weights", {}), dtype=float)
    target_active = bool((target_weights.reindex(current_weights.index).fillna(0.0) - current_weights).abs().max() > 1e-6)
    optimizer = model.get("optimizer")
    if optimizer is not None:
        target_status, target_state = ("PASS" if bool(getattr(optimizer, "success", False)) else "REVIEW"), str(getattr(optimizer, "method", "Optimizer"))
    elif target_active:
        target_status, target_state = "REVIEW", "Manual / working target"
    else:
        target_status, target_state = "REVIEW", "Current portfolio · no active target"

    risk_status = module_status.get("Risk & Factors", "NOT RUN")
    risk_evidence = "Risk budgets, factors and limits"
    top_risk_ticker, top_risk_share = _pl211_top_risk_summary(model)
    if np.isfinite(top_risk_share) and top_risk_share > 0.40:
        risk_evidence = f"{top_risk_ticker} contributes {top_risk_share:.2%} of target volatility"
        if _pl211_normalize_status(risk_status) != "FAIL":
            risk_status = "REVIEW"

    validation_status = module_status.get("Validation", "NOT RUN")
    execution_status = module_status.get("Rebalance & TCA", "NOT RUN")
    execution_evidence = "Transition, TCA and cash funding"
    rebalance_context = _pl211_context_for_module(
        model,
        "rebalance_tca_context_v27",
        ["trading_plan_portfolio_context"],
    )
    if isinstance(rebalance_context, Mapping):
        orders = rebalance_context.get("orders")
        if not isinstance(orders, pd.DataFrame):
            orders = rebalance_context.get("order_blotter")
        active_orders = None
        if isinstance(orders, pd.DataFrame) and not orders.empty and "Action" in orders.columns:
            active_orders = int(orders["Action"].astype(str).str.upper().isin(["BUY", "SELL"]).sum())
        if active_orders == 0 or (active_orders is None and not target_active):
            execution_status = "NO TRANSITION"
            execution_evidence = "Current equals target; no executable transition"
    signal_count = _pl29_model_signal_count(model)
    signal_status = module_status.get("Signal Hub", "N/A") if signal_count else "N/A"

    governed = st.session_state.get(PL211_PUBLICATION_KEY)
    compatibility = st.session_state.get(PORTFOLIO_CONTEXT_KEY)
    publication_status = "LOCAL"
    publication_state = "Local model only"
    published = None
    if isinstance(governed, Mapping):
        published = governed
        publication_state = "Governed context published"
        publication_status = "PASS"
    elif isinstance(compatibility, Mapping):
        published = compatibility
        publication_state = "Compatibility context only; governed publication pending"
        publication_status = "REVIEW"
    if isinstance(published, Mapping):
        published_fp = str(published.get("Book Fingerprint") or published.get("Manifest", {}).get("book_fingerprint") or "")
        current_fp = str(model.get("book_fingerprint") or model.get("manifest", {}).get("book_fingerprint") or "")
        if published_fp and current_fp and published_fp != current_fp:
            publication_status, publication_state = "REVIEW", "Published context is stale"

    rows = [
        ("1", "Data", data_status, f"{len(model.get('returns', pd.DataFrame())):,} aligned observations", "Resolve data integrity or freshness exceptions"),
        ("2", "Model", model_status, str(model.get("settings").covariance_model if model.get("settings") else "Portfolio model"), "Review covariance and expected-return assumptions"),
        ("3", "Target", target_status, target_state, "Approve a governed target or retain Current explicitly"),
        ("4", "Risk", risk_status, risk_evidence, "Resolve limit breaches before publication"),
        ("5", "Validation", validation_status, str(model.get("validation_champion_v210", "No champion selected")), "Run or review chronological OOS validation"),
        ("6", "Execution", execution_status, execution_evidence, "Resolve execution or liquidity exceptions"),
        ("7", "Signals", signal_status, f"{signal_count} covered ticker(s)", "Add independent sources or document no-signal decision"),
        ("8", "Publication", publication_status, publication_state, "Publish a versioned, fingerprinted context"),
    ]
    return pd.DataFrame(rows, columns=["Stage", "Control Layer", "Status", "Evidence", "Next Action"])


def _pl211_top_risk_summary(model: Mapping[str, Any]) -> tuple[str, float]:
    frame = model.get("target_risk", pd.DataFrame())
    if not isinstance(frame, pd.DataFrame) or frame.empty or "Risk Contribution %" not in frame.columns:
        return "N/A", np.nan
    work = frame.copy()
    work["Risk Contribution %"] = pd.to_numeric(work["Risk Contribution %"], errors="coerce")
    work = work.dropna(subset=["Risk Contribution %"]).sort_values("Risk Contribution %", ascending=False)
    if work.empty:
        return "N/A", np.nan
    return str(work.iloc[0].get("Ticker", "N/A")), float(work.iloc[0]["Risk Contribution %"])


def _pl211_validation_status(model: Mapping[str, Any]) -> str:
    governance = model.get("validation_governance_v210", pd.DataFrame())
    if isinstance(governance, pd.DataFrame) and not governance.empty:
        return _pl211_combine_status(governance.get("Status", pd.Series(dtype=str)), default="REVIEW")
    return "NOT RUN"


def _pl211_action_queue(model: Mapping[str, Any], data_quality: pd.DataFrame, modules: pd.DataFrame, pipeline: pd.DataFrame) -> pd.DataFrame:
    rows: list[dict[str, Any]] = []

    def add(severity: str, domain: str, issue: str, evidence: str, action: str, owner: str, status: str, source: str) -> None:
        rows.append({
            "Priority": 1 if severity == "Critical" else 2 if severity == "High" else 3 if severity == "Medium" else 4,
            "Severity": severity,
            "Domain": domain,
            "Issue": issue,
            "Evidence": evidence,
            "Recommended Action": action,
            "Owner": owner,
            "Status": status,
            "Source": source,
        })

    for _, row in data_quality.loc[~data_quality["Status"].eq("PASS")].iterrows():
        add(str(row["Severity"]), "Data / Model", str(row["Control"]), str(row["Observed"]), str(row["Evidence"]), str(row["Owner"]), str(row["Status"]), "Governance")

    top_ticker, top_share = _pl211_top_risk_summary(model)
    if np.isfinite(top_share) and top_share > 0.40:
        add("High", "Risk", "Single-name risk concentration", f"{top_ticker} contributes {top_share:.2%} of target volatility", "Review risk budget, target weights and diversification constraints", "Risk Owner", "REVIEW", "Risk & Factors")

    target_metrics = model.get("target_extended_metrics", {})
    max_dd = _safe_float(target_metrics.get("Max Drawdown"), np.nan) if isinstance(target_metrics, Mapping) else np.nan
    if np.isfinite(max_dd) and max_dd < -0.25:
        add("High", "Performance", "Historical drawdown exceeds policy reference", _fmt_pct(max_dd), "Review downside constraints and stress evidence", "Portfolio Owner", "REVIEW", "Performance Lab")

    validation_status = _pl211_validation_status(model)
    if validation_status in {"REVIEW", "FAIL", "NOT RUN"}:
        champion = str(model.get("validation_champion_v210", "N/A"))
        add("Critical" if validation_status == "FAIL" else "High", "Model Risk", "Validation evidence is not PASS", champion, "Resolve failed acceptance criteria or document governed research use", "Model Validation", validation_status, "Validation")

    if model.get("optimizer") is None:
        add("Medium", "Construction", "No official optimizer target selected", "Target currently equals or derives from Current", "Select and review a feasible optimizer candidate or document hold decision", "Portfolio Owner", "REVIEW", "Optimizer Studio")

    signal_count = _pl29_model_signal_count(model)
    if signal_count == 0:
        add("Low", "Research", "No governed signal coverage", "0 covered tickers", "Document signal-independent mandate or connect validated research sources", "Research Owner", "N/A", "Signal Hub")

    # Avoid duplicating a specific exception with a generic pipeline item.
    # A pipeline action is added only when that control layer has no more
    # informative action already registered above.
    represented_layers = set()
    for item in rows:
        domain = str(item.get("Domain", "")).lower()
        if "data" in domain:
            represented_layers.add("Data")
        if domain in {"risk"}:
            represented_layers.add("Risk")
        if domain in {"model risk", "validation"}:
            represented_layers.add("Validation")
        if domain in {"construction", "target"}:
            represented_layers.add("Target")
        if domain in {"research", "signals"}:
            represented_layers.add("Signals")
        if domain in {"publication", "integration"}:
            represented_layers.add("Publication")

    attention_statuses = ["FAIL", "REVIEW", "NOT RUN", "LOCAL", "WAITING"]
    for _, row in pipeline.loc[pipeline["Status"].isin(attention_statuses)].iterrows():
        layer = str(row["Control Layer"])
        if layer in represented_layers:
            continue
        add(
            "High" if row["Status"] == "FAIL" else "Medium",
            layer,
            f"Pipeline stage requires attention: {layer}",
            str(row["Evidence"]),
            str(row["Next Action"]),
            "Control Owner",
            str(row["Status"]),
            "Command Center",
        )

    if not rows:
        return pd.DataFrame(columns=["Priority", "Severity", "Domain", "Issue", "Evidence", "Recommended Action", "Owner", "Status", "Source"])
    frame = pd.DataFrame(rows).drop_duplicates(subset=["Issue", "Source"], keep="first")
    severity_order = pd.Categorical(frame["Severity"], categories=["Critical", "High", "Medium", "Low"], ordered=True)
    frame = frame.assign(_severity=severity_order).sort_values(["_severity", "Priority", "Domain", "Issue"]).drop(columns="_severity").reset_index(drop=True)
    return frame


def _pl211_readiness(pipeline: pd.DataFrame, action_queue: pd.DataFrame) -> dict[str, Any]:
    weights = {
        "Data": 0.20,
        "Model": 0.15,
        "Target": 0.15,
        "Risk": 0.15,
        "Validation": 0.15,
        "Execution": 0.10,
        "Signals": 0.05,
        "Publication": 0.05,
    }
    score = 0.0
    for _, row in pipeline.iterrows():
        weight = weights.get(str(row["Control Layer"]), 0.0)
        score += weight * PL211_STATUS_SCORE.get(_pl211_normalize_status(row["Status"]), 0.25)
    critical_fail = False
    if not action_queue.empty:
        critical_fail = bool(((action_queue["Severity"] == "Critical") & (action_queue["Status"] == "FAIL")).any())
    if critical_fail or (pipeline["Status"] == "FAIL").any():
        status = "FAIL"
    elif pipeline["Status"].isin(["REVIEW", "NOT RUN", "LOCAL", "WAITING"]).any():
        status = "REVIEW"
    else:
        status = "PASS"
    return {"Score": float(score), "Status": status, "Critical Fail": critical_fail}


def _pl211_metric_delta_table(model: Mapping[str, Any]) -> pd.DataFrame:
    current = model.get("current_extended_metrics", {})
    target = model.get("target_extended_metrics", {})
    benchmark_series = model.get("benchmark_returns", pd.Series(dtype=float))
    risk_free = float(getattr(model.get("settings"), "risk_free_rate", 0.0))
    benchmark_metrics = extended_performance_metrics(benchmark_series.dropna(), benchmark_series.dropna(), risk_free) if isinstance(benchmark_series, pd.Series) and not benchmark_series.dropna().empty else {}
    metrics = [
        "CAGR", "Annualized Volatility", "Sharpe", "Sortino", "Max Drawdown",
        "CVaR 95% (1D)", "Calmar", "Omega", "Tail Ratio", "Ulcer Index",
        "Tracking Error", "Information Ratio", "Downside Capture",
    ]
    rows = []
    for metric in metrics:
        c = _safe_float(current.get(metric), np.nan) if isinstance(current, Mapping) else np.nan
        t = _safe_float(target.get(metric), np.nan) if isinstance(target, Mapping) else np.nan
        b = _safe_float(benchmark_metrics.get(metric), np.nan) if isinstance(benchmark_metrics, Mapping) else np.nan
        rows.append({"Metric": metric, "Current": c, "Target": t, "Benchmark": b, "Target vs Current": t - c if np.isfinite(t) and np.isfinite(c) else np.nan, "Target vs Benchmark": t - b if np.isfinite(t) and np.isfinite(b) else np.nan})
    return pd.DataFrame(rows)


_PL211_PERCENT_METRICS = {
    "CAGR",
    "Annualized Volatility",
    "Max Drawdown",
    "CVaR 95% (1D)",
    "Ulcer Index",
    "Tracking Error",
    "Downside Capture",
}
_PL211_RATIO_METRICS = {
    "Sharpe",
    "Sortino",
    "Calmar",
    "Omega",
    "Tail Ratio",
    "Information Ratio",
}


def _pl211_format_metric_value(metric: str, value: Any, *, delta: bool = False) -> str:
    number = _safe_float(value, np.nan)
    if not np.isfinite(number):
        return "N/A"
    if metric in _PL211_PERCENT_METRICS:
        return f"{number:+.2%}" if delta else f"{number:.2%}"
    if metric in _PL211_RATIO_METRICS:
        return f"{number:+.2f}" if delta else f"{number:.2f}"
    return f"{number:+,.2f}" if delta else f"{number:,.2f}"


def _pl211_metric_display_table(frame: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return pd.DataFrame(columns=getattr(frame, "columns", []))
    display = frame.copy()
    value_columns = [
        column
        for column in ["Current", "Target", "Benchmark", "Target vs Current", "Target vs Benchmark"]
        if column in display.columns
    ]
    for column in value_columns:
        display[column] = display[column].astype(object)
    for index, row in display.iterrows():
        metric = str(row.get("Metric", ""))
        for column in ["Current", "Target", "Benchmark"]:
            if column in display.columns:
                display.at[index, column] = _pl211_format_metric_value(metric, row.get(column), delta=False)
        for column in ["Target vs Current", "Target vs Benchmark"]:
            if column in display.columns:
                display.at[index, column] = _pl211_format_metric_value(metric, row.get(column), delta=True)
    return display


def _pl211_risk_display_table(frame: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return pd.DataFrame(columns=getattr(frame, "columns", []))
    display = frame.copy()
    percent_columns = {
        "Weight",
        "Standalone Vol",
        "Marginal Risk",
        "Component Risk",
        "Risk Contribution %",
    }
    for column in percent_columns.intersection(display.columns):
        display[column] = pd.to_numeric(display[column], errors="coerce").map(
            lambda value: "N/A" if not np.isfinite(value) else f"{float(value):.2%}"
        )
    return display


def _pl211_correlation_display_table(frame: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return pd.DataFrame(columns=getattr(frame, "columns", []))
    display = frame.copy()
    if "Correlation" in display.columns:
        display["Correlation"] = pd.to_numeric(display["Correlation"], errors="coerce").map(
            lambda value: "N/A" if not np.isfinite(value) else f"{float(value):.1%}"
        )
    return display


def _pl211_validation_display_table(frame: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return pd.DataFrame(columns=getattr(frame, "columns", []))
    display = frame.copy()
    percent_tokens = (
        "rate",
        "return",
        "cagr",
        "volatility",
        "drawdown",
        "cvar",
        "turnover",
        "active mean",
        "psr",
        "probabilistic",
        "coverage",
    )
    ratio_tokens = ("sharpe", "sortino", "calmar", "omega", "information ratio")
    integer_tokens = ("window", "fold", "observations")
    bps_tokens = ("bps",)
    for column in display.columns:
        lower = str(column).lower()
        numeric = pd.to_numeric(display[column], errors="coerce")
        if any(token in lower for token in integer_tokens) and numeric.notna().any():
            display[column] = numeric.map(lambda value: "N/A" if not np.isfinite(value) else f"{int(round(float(value))):,}")
        elif any(token in lower for token in bps_tokens) and numeric.notna().any():
            display[column] = numeric.map(lambda value: "N/A" if not np.isfinite(value) else f"{float(value):.2f} bps")
        elif any(token in lower for token in ratio_tokens) and numeric.notna().any():
            display[column] = numeric.map(lambda value: "N/A" if not np.isfinite(value) else f"{float(value):.2f}")
        elif any(token in lower for token in percent_tokens) and numeric.notna().any():
            display[column] = numeric.map(lambda value: "N/A" if not np.isfinite(value) else f"{float(value):.2%}")
    return display


def _pl211_pipeline_figure(pipeline: pd.DataFrame) -> go.Figure:
    work = pipeline.copy()
    work["Score"] = work["Status"].map(lambda value: PL211_STATUS_SCORE.get(_pl211_normalize_status(value), 0.0))
    colours = work["Status"].map(lambda value: PL211_STATUS_COLOUR.get(_pl211_normalize_status(value), "#64748b"))
    figure = go.Figure(go.Bar(
        x=work["Score"],
        y=work["Control Layer"],
        orientation="h",
        marker_color=colours,
        text=work["Status"],
        textposition="inside",
        customdata=np.column_stack([work["Evidence"], work["Next Action"]]),
        hovertemplate="<b>%{y}</b><br>Status: %{text}<br>Evidence: %{customdata[0]}<br>Next: %{customdata[1]}<extra></extra>",
    ))
    figure.update_layout(
        title="Decision Pipeline Readiness",
        height=390,
        xaxis=dict(range=[0, 1], tickformat=".0%", title="Stage status score"),
        yaxis=dict(autorange="reversed", title=""),
        margin=dict(l=20, r=20, t=55, b=25),
        showlegend=False,
    )
    return _pl22_polish_figure(figure)


def _pl211_allocation_risk_figure(model: Mapping[str, Any]) -> go.Figure:
    current = pd.Series(model.get("current_weights", {}), dtype=float)
    target = pd.Series(model.get("target_weights", {}), dtype=float)
    assets = current.index.union(target.index)
    risk = model.get("target_risk", pd.DataFrame())
    risk_series = pd.Series(0.0, index=assets)
    if isinstance(risk, pd.DataFrame) and not risk.empty and {"Ticker", "Risk Contribution %"}.issubset(risk.columns):
        risk_series = pd.to_numeric(risk.set_index("Ticker")["Risk Contribution %"], errors="coerce").reindex(assets).fillna(0.0)
    figure = go.Figure()
    figure.add_bar(name="Current weight", x=assets, y=current.reindex(assets).fillna(0.0), marker_color="#64748b")
    figure.add_bar(name="Target weight", x=assets, y=target.reindex(assets).fillna(0.0), marker_color="#38bdf8")
    figure.add_scatter(name="Target risk contribution", x=assets, y=risk_series, mode="lines+markers", yaxis="y2", line=dict(width=2.5, color="#fb7185"), marker=dict(size=8))
    figure.update_layout(
        title="Capital Allocation and Euler Risk Budget",
        barmode="group",
        height=430,
        yaxis=dict(title="Capital weight", tickformat=".0%"),
        yaxis2=dict(title="Risk contribution", tickformat=".0%", overlaying="y", side="right", rangemode="tozero"),
        legend=dict(orientation="h", y=1.12),
        margin=dict(l=25, r=25, t=65, b=30),
    )
    return _pl22_polish_figure(figure)


def _pl211_drawdown_figure(model: Mapping[str, Any]) -> go.Figure:
    figure = go.Figure()
    series_map = {
        "Current": model.get("current_return_series", pd.Series(dtype=float)),
        "Target": model.get("target_return_series", pd.Series(dtype=float)),
        "Benchmark": model.get("benchmark_returns", pd.Series(dtype=float)),
    }
    colours = {"Current": "#64748b", "Target": "#38bdf8", "Benchmark": "#fb7185"}
    for name, returns in series_map.items():
        if not isinstance(returns, pd.Series) or returns.dropna().empty:
            continue
        wealth = (1.0 + returns.fillna(0.0)).cumprod()
        drawdown = wealth / wealth.cummax() - 1.0
        figure.add_scatter(x=drawdown.index, y=drawdown, name=name, mode="lines", line=dict(color=colours[name], width=1.8))
    figure.update_layout(title="Historical Drawdown Comparison", height=360, yaxis=dict(tickformat=".0%", title="Drawdown"), xaxis_title="Date", margin=dict(l=25, r=20, t=55, b=25), legend=dict(orientation="h", y=1.12))
    return _pl22_polish_figure(figure)


def _pl211_status_distribution_figure(controls: pd.DataFrame) -> go.Figure:
    counts = controls["Status"].astype(str).map(_pl211_normalize_status).value_counts().reindex(["PASS", "REVIEW", "FAIL", "N/A"], fill_value=0)
    figure = go.Figure(go.Bar(
        x=counts.index,
        y=counts.values,
        marker_color=[PL211_STATUS_COLOUR.get(value, "#64748b") for value in counts.index],
        text=counts.values,
        textposition="outside",
    ))
    figure.update_layout(title="Control Status Distribution", height=320, yaxis_title="Controls", xaxis_title="", showlegend=False, margin=dict(l=20, r=20, t=55, b=25))
    return _pl22_polish_figure(figure)


def _pl211_correlation_pairs(model: Mapping[str, Any], limit: int = 8) -> pd.DataFrame:
    matrix = model.get("correlation", pd.DataFrame())
    if not isinstance(matrix, pd.DataFrame) or matrix.empty:
        return pd.DataFrame(columns=["Asset 1", "Asset 2", "Correlation"])
    work = matrix.apply(pd.to_numeric, errors="coerce")
    rows = []
    for i, left in enumerate(work.index):
        for j, right in enumerate(work.columns):
            if j <= i:
                continue
            value = _safe_float(work.iloc[i, j], np.nan)
            if np.isfinite(value):
                rows.append({"Asset 1": str(left), "Asset 2": str(right), "Correlation": float(value), "Absolute Correlation": abs(float(value))})
    if not rows:
        return pd.DataFrame(columns=["Asset 1", "Asset 2", "Correlation"])
    return pd.DataFrame(rows).sort_values("Absolute Correlation", ascending=False).head(limit).drop(columns="Absolute Correlation")


