def _pl211_lineage_figure(lineage: pd.DataFrame) -> go.Figure:
    if lineage.empty:
        return _pl2_theme(go.Figure())
    labels: list[str] = []
    for column in ["Source", "Transformation", "Output", "Consumers"]:
        for value in lineage[column].astype(str):
            if value not in labels:
                labels.append(value)
    index = {label: i for i, label in enumerate(labels)}
    sources, targets, values, colours = [], [], [], []
    state_colours = {"ACTIVE": "rgba(56,189,248,.55)", "AVAILABLE": "rgba(34,197,94,.55)", "PUBLISHED": "rgba(34,197,94,.65)", "EMPTY": "rgba(148,163,184,.35)", "WAITING": "rgba(100,116,139,.35)", "LOCAL": "rgba(245,158,11,.45)"}
    for _, row in lineage.iterrows():
        chain = [str(row["Source"]), str(row["Transformation"]), str(row["Output"]), str(row["Consumers"])]
        for left, right in zip(chain[:-1], chain[1:]):
            sources.append(index[left])
            targets.append(index[right])
            values.append(1.0)
            colours.append(state_colours.get(str(row["State"]), "rgba(148,163,184,.35)"))
    figure = go.Figure(go.Sankey(
        node=dict(label=labels, pad=14, thickness=14, color="rgba(30,41,59,.95)", line=dict(color="rgba(148,163,184,.35)", width=0.5)),
        link=dict(source=sources, target=targets, value=values, color=colours),
    ))
    figure.update_layout(title="Portfolio Data and Decision Lineage", height=540, margin=dict(l=15, r=15, t=55, b=15))
    return _pl22_polish_figure(figure)


