    specs = [
        ("Shared Portfolio Context", PORTFOLIO_CONTEXT_KEY, "Risk Monitor · Decision Engine · Backtest Lab · Trading Plan"),
        ("Governed Publication 2.11", PL211_PUBLICATION_KEY, "All approved downstream consumers"),
        ("Risk Context", "risk_monitor_portfolio_context", "Risk Monitor"),
        ("Performance Context", "risk_monitor_performance_context", "Risk Monitor"),
        ("Attribution Context", "risk_monitor_attribution_context", "Risk Monitor"),
        ("Rebalance / TCA Context", "trading_plan_portfolio_context", "Trading Plan"),
        ("Stress Context", "risk_monitor_stress_context", "Risk Monitor"),
        ("Signal Context", "portfolio_lab_signal_context_v29", "Optimizer · Decision Engine · Risk Monitor · Backtest Lab"),
        ("Validation Context", "optimizer_validation_context", "Optimizer · Decision Engine · Risk Monitor · Backtest Lab"),
        ("Backtest Portfolio", "backtest_lab_external_portfolio", "Backtest Lab"),
        ("Backtest Validation", "backtest_lab_external_validation", "Backtest Lab"),
    ]
    rows = []
