def _pl212_parse_bool(value: Any, default: bool = True) -> bool:
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return bool(default)
    if isinstance(value, (bool, np.bool_)):
        return bool(value)
    if isinstance(value, (int, np.integer, float, np.floating)):
        return bool(int(value))
    text = str(value).strip().lower()
    if text in {"true", "t", "yes", "y", "1", "active", "enabled", "include"}:
        return True
    if text in {"false", "f", "no", "n", "0", "inactive", "disabled", "exclude", ""}:
        return False
    return bool(default)


_pl212_clean_book_parent = _clean_book


def _clean_book(book: pd.DataFrame) -> pd.DataFrame:
    """Backward-compatible cleaner with robust boolean parsing."""
    frame = pd.DataFrame(book).copy()
    if "Active" in frame.columns:
        frame["Active"] = frame["Active"].map(_pl212_parse_bool)
    return _pl212_clean_book_parent(frame)


def _pl212_normalize_symbol(value: Any) -> str:
    text = str(value or "").strip().upper()
    text = re.sub(r"\s+", "", text)
    return text


def _pl212_normalize_exchange(value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip().upper())


def _pl212_symbol_candidates(symbol: Any, exchange_hint: Any = "") -> list[str]:
    base = _pl212_normalize_symbol(symbol)
    if not base:
        return []
    candidates = [base]
    if re.fullmatch(r"[A-Z0-9]+\.[A-Z]", base):
        candidates.append(base[:-2] + "-" + base[-1])
    if "/" in base:
        candidates.append(base.replace("/", "-"))
    hint = _pl212_normalize_exchange(exchange_hint)
    suffix = PL212_EXCHANGE_SUFFIX.get(hint)
    if suffix and "." not in base and not base.startswith("^"):
        candidates.append(base + suffix)
    return list(dict.fromkeys(candidates))


def _pl212_asset_class_from_quote_type(value: Any) -> str:
    quote_type = str(value or "").strip().upper()
    mapping = {
        "EQUITY": "Equity",
        "ETF": "Equity",
        "INDEX": "Equity",
        "MUTUALFUND": "Fund",
        "MONEYMARKET": "Cash",
        "CRYPTOCURRENCY": "Crypto",
        "CURRENCY": "FX",
        "FUTURE": "Commodity",
        "OPTION": "Other",
        "BOND": "Bond",
    }
    return mapping.get(quote_type, "Other")


def _pl212_quote_value(record: Mapping[str, Any], *keys: str) -> Any:
    lower = {str(key).lower(): value for key, value in dict(record).items()}
    for key in keys:
        if key.lower() in lower and lower[key.lower()] not in (None, ""):
            return lower[key.lower()]
    return None


def _pl212_normalize_search_quote(record: Mapping[str, Any]) -> dict[str, Any]:
    symbol = _pl212_normalize_symbol(_pl212_quote_value(record, "symbol", "ticker"))
    name = str(_pl212_quote_value(record, "longname", "shortname", "name") or "").strip()
    quote_type = str(_pl212_quote_value(record, "quoteType", "typeDisp", "type") or "").strip().upper()
    exchange = str(_pl212_quote_value(record, "exchDisp", "exchange", "exchangeDisplay") or "").strip()
    currency = str(_pl212_quote_value(record, "currency") or "").strip().upper()
    return {
        "Ticker": symbol,
        "Name": name,
        "Instrument Type": quote_type,
        "Asset Class": _pl212_asset_class_from_quote_type(quote_type),
        "Exchange": exchange,
        "Currency": currency,
    }


@st.cache_data(ttl=3600, show_spinner=False)
def _pl212_search_instruments(query: str, max_results: int = 12) -> list[dict[str, Any]]:
    query = str(query or "").strip()
    if not query or not hasattr(yf, "Search"):
        return []
    try:
        try:
            search = yf.Search(query, max_results=max_results, news_count=0)
        except TypeError:
            search = yf.Search(query, max_results=max_results)
        quotes = getattr(search, "quotes", []) or []
    except Exception:
        return []
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for quote in quotes:
        if not isinstance(quote, Mapping):
            continue
        row = _pl212_normalize_search_quote(quote)
        symbol = row["Ticker"]
        if not symbol or symbol in seen:
            continue
        seen.add(symbol)
        rows.append(row)
    return rows[:max_results]


def _pl212_validation_template() -> dict[str, Any]:
    return {column: "" for column in PL212_MASTER_COLUMNS}


@st.cache_data(ttl=900, show_spinner=False)
def _pl212_validate_symbol(symbol: str, exchange_hint: str = "") -> dict[str, Any]:
    input_symbol = _pl212_normalize_symbol(symbol)
    exchange_hint = _pl212_normalize_exchange(exchange_hint)
    record = _pl212_validation_template()
    record.update({
        "Input Ticker": input_symbol,
        "Canonical Ticker": input_symbol,
        "Status": "FAIL",
        "Blocking": True,
        "Provider": "Yahoo Finance",
        "Message": "Instrument has not been resolved.",
    })

    if not input_symbol:
        record["Message"] = "Active row requires a ticker."
        return record

    if input_symbol in CASH_ALIASES:
        currency = input_symbol if len(input_symbol) == 3 and input_symbol != "CASH" else "USD"
        record.update({
            "Status": "CASH",
            "Blocking": False,
            "Name": f"{currency} Cash" if input_symbol != "CASH" else "Cash",
            "Instrument Type": "CASH",
            "Asset Class": "Cash",
            "Exchange": "Internal",
            "Currency": currency,
            "Last Price": 1.0,
            "Last Date": pd.Timestamp.now(tz="UTC").tz_localize(None),
            "Quote Age Days": 0.0,
            "Observations": 0,
            "Provider": "Synthetic cash convention",
            "Message": "Deterministic liquidity sleeve; market-data lookup is not required.",
        })
        return record

    search_rows = _pl212_search_instruments(input_symbol, max_results=12)
    search_by_symbol = {row["Ticker"]: row for row in search_rows}
    suggestions = [
        f"{row['Ticker']} · {row['Name']} · {row['Exchange']}"
        for row in search_rows[:3]
    ]
    record["Suggestion"] = " | ".join(suggestions)

    candidates = _pl212_symbol_candidates(input_symbol, exchange_hint)
    for candidate in list(candidates):
        if candidate in search_by_symbol:
            candidates.insert(0, candidate)
            break
    candidates = list(dict.fromkeys(candidates))

    resolved_payload: dict[str, Any] | None = None
    resolved_symbol = ""
    for candidate in candidates:
        payload = _download_single_asset(candidate, "3mo", "1d")
        price = payload.get("price") if isinstance(payload, Mapping) else None
        if isinstance(price, pd.Series) and not price.dropna().empty:
            resolved_payload = dict(payload)
            resolved_symbol = candidate
            break

    if resolved_payload is None:
        record["Message"] = "No usable market history was found. Check the symbol, exchange suffix or select a provider search result."
        return record

    price = pd.Series(resolved_payload.get("price"), dtype=float).dropna().sort_index()
    metadata = search_by_symbol.get(resolved_symbol, {})
    last_date = pd.Timestamp(price.index[-1]) if not price.empty else pd.NaT
    now = pd.Timestamp.now(tz="UTC").tz_localize(None)
    age_days = float(max(0, (now.normalize() - last_date.normalize()).days)) if pd.notna(last_date) else np.nan
    canonical_mismatch = resolved_symbol != input_symbol
    stale_block = bool(np.isfinite(age_days) and age_days > 14)
    sparse = len(price) < 2
    missing_reference = not metadata

    status = "PASS"
    blocking = False
    messages: list[str] = []
    if canonical_mismatch:
        status = "REVIEW"
        blocking = True
        messages.append(f"Provider-resolved symbol is {resolved_symbol}; apply the canonical symbol before running analytics.")
    if stale_block:
        status = "FAIL"
        blocking = True
        messages.append(f"Latest quote is {int(age_days)} calendar days old.")
    elif np.isfinite(age_days) and age_days > 10:
        status = "REVIEW"
        messages.append(f"Latest quote is {int(age_days)} calendar days old; review market-calendar context.")
    if sparse:
        status = "FAIL"
        blocking = True
        messages.append("Fewer than two usable price observations were returned.")
    if missing_reference:
        if status == "PASS":
            status = "REVIEW"
        messages.append("Price history resolved, but provider reference metadata was limited.")

    quote_type = metadata.get("Instrument Type", "")
    record.update({
        "Canonical Ticker": resolved_symbol,
        "Status": status,
        "Blocking": blocking,
        "Name": metadata.get("Name", ""),
        "Instrument Type": quote_type,
        "Asset Class": metadata.get("Asset Class", _pl212_asset_class_from_quote_type(quote_type)),
        "Exchange": metadata.get("Exchange", exchange_hint),
        "Currency": metadata.get("Currency", ""),
        "Last Price": float(price.iloc[-1]),
        "Last Date": last_date,
        "Quote Age Days": age_days,
        "Observations": int(len(price)),
        "Message": " ".join(messages) if messages else "Exact symbol, current market history and reference metadata resolved.",
    })
    return record


def _pl212_parse_openfigi_response(response: Any) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not isinstance(response, Sequence) or isinstance(response, (str, bytes, bytearray)):
        return rows
    for item in response:
        data = item.get("data", []) if isinstance(item, Mapping) else []
        selected = data[0] if isinstance(data, list) and len(data) == 1 and isinstance(data[0], Mapping) else None
        if selected is None and isinstance(data, list):
            exact = [entry for entry in data if isinstance(entry, Mapping)]
            selected = exact[0] if exact else None
        if selected is None:
            rows.append({"FIGI": "", "Composite FIGI": "", "OpenFIGI Message": str(item.get("warning", item.get("error", "No mapping"))) if isinstance(item, Mapping) else "No mapping"})
        else:
            rows.append({
                "FIGI": str(selected.get("figi", "")),
                "Composite FIGI": str(selected.get("compositeFIGI", "")),
                "OpenFIGI Message": "Mapped" if len(data) == 1 else f"Mapped from {len(data)} candidates; review exchange specificity.",
            })
    return rows


def _pl212_openfigi_enrich(master: pd.DataFrame) -> pd.DataFrame:
    result = master.copy()
    eligible = result.index[
        result["Active"].fillna(False).astype(bool)
        & result["Canonical Ticker"].astype(str).ne("")
        & ~result["Canonical Ticker"].astype(str).isin(CASH_ALIASES)
    ].tolist()
    if not eligible:
        return result

    api_key = os.getenv("OPENFIGI_API_KEY", "").strip()
    chunk_size = 100 if api_key else 10
    for start in range(0, len(eligible), chunk_size):
        indices = eligible[start:start + chunk_size]
        jobs = [{"idType": "TICKER", "idValue": str(result.at[index, "Canonical Ticker"])} for index in indices]
        request = urllib.request.Request(
            "https://api.openfigi.com/v3/mapping",
            data=json.dumps(jobs).encode("utf-8"),
            headers={"Content-Type": "application/json", **({"X-OPENFIGI-APIKEY": api_key} if api_key else {})},
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=12) as response:
                payload = json.loads(response.read().decode("utf-8"))
            mapped = _pl212_parse_openfigi_response(payload)
        except Exception as exc:
            mapped = [{"FIGI": "", "Composite FIGI": "", "OpenFIGI Message": f"OpenFIGI unavailable: {exc}"} for _ in indices]
        for index, mapping in zip(indices, mapped):
            result.at[index, "FIGI"] = mapping.get("FIGI", "")
            result.at[index, "Composite FIGI"] = mapping.get("Composite FIGI", "")
            message = mapping.get("OpenFIGI Message", "")
            if message and message != "Mapped":
                current = str(result.at[index, "Message"] or "")
                result.at[index, "Message"] = (current + " " + message).strip()
    return result


def _pl212_next_row_id() -> str:
    counter = int(st.session_state.get(PL212_ROW_COUNTER_KEY, 0)) + 1
    st.session_state[PL212_ROW_COUNTER_KEY] = counter
    return f"PL-{counter:04d}"


def _pl212_ensure_draft_schema(frame: Any) -> pd.DataFrame:
    work = pd.DataFrame(frame).copy()
    for column in BOOK_COLUMNS:
        if column not in work.columns:
            work[column] = DEFAULT_ROW.get(column, np.nan)
    if PL212_EXCHANGE_HINT not in work.columns:
        work[PL212_EXCHANGE_HINT] = ""
    if PL212_ROW_ID not in work.columns:
        work[PL212_ROW_ID] = ""
    for index in work.index:
        row_id = str(work.at[index, PL212_ROW_ID] or "").strip()
        if not row_id or row_id.lower() == "nan":
            work.at[index, PL212_ROW_ID] = _pl212_next_row_id()
    work["Active"] = work["Active"].map(_pl212_parse_bool)
    work["Ticker"] = work["Ticker"].map(_pl212_normalize_symbol)
    work[PL212_EXCHANGE_HINT] = work[PL212_EXCHANGE_HINT].map(_pl212_normalize_exchange)
    return work[PL212_DRAFT_COLUMNS].reset_index(drop=True)


def _pl212_get_draft(ticker: str | None) -> pd.DataFrame:
    draft = st.session_state.get(PL212_DRAFT_KEY)
    if not isinstance(draft, pd.DataFrame):
        legacy = st.session_state.get("portfolio_lab_book_v1")
        source = legacy if isinstance(legacy, pd.DataFrame) else _initial_book(ticker)
        draft = _pl212_ensure_draft_schema(source)
        st.session_state[PL212_DRAFT_KEY] = draft
    else:
        draft = _pl212_ensure_draft_schema(draft)
        st.session_state[PL212_DRAFT_KEY] = draft
    if PL212_DRAFT_NONCE_KEY not in st.session_state:
        st.session_state[PL212_DRAFT_NONCE_KEY] = 0
    return draft.copy()


def _pl212_sync_draft(draft: pd.DataFrame, invalidate_validation: bool = False) -> pd.DataFrame:
    work = _pl212_ensure_draft_schema(draft)
    st.session_state[PL212_DRAFT_KEY] = work
    st.session_state["portfolio_lab_book_v1"] = work[BOOK_COLUMNS].copy()
    if invalidate_validation:
        st.session_state.pop(PL212_MASTER_FINGERPRINT_KEY, None)
    return work


def _pl212_draft_fingerprint(draft: pd.DataFrame) -> str:
    work = _pl212_ensure_draft_schema(draft).drop(columns=[PL212_ROW_ID], errors="ignore")
    payload = work.fillna("").astype(str).to_csv(index=False).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _pl212_merge_positions(draft: pd.DataFrame, edited: pd.DataFrame) -> pd.DataFrame:
    base = _pl212_ensure_draft_schema(draft).set_index(PL212_ROW_ID, drop=False)
    edit = pd.DataFrame(edited).copy()
    if PL212_ROW_ID not in edit.columns:
        edit[PL212_ROW_ID] = ""
    rows: list[dict[str, Any]] = []
    position_columns = ["Active", "Ticker", PL212_EXCHANGE_HINT, "Name", "Quantity", "Avg Cost", "Current Weight"]
    for _, row in edit.iterrows():
        row_id = str(row.get(PL212_ROW_ID, "") or "").strip()
        if not row_id or row_id.lower() == "nan":
            row_id = _pl212_next_row_id()
        if row_id in base.index:
            target = base.loc[row_id].to_dict()
            if isinstance(target, pd.DataFrame):
                target = target.iloc[-1].to_dict()
        else:
            target = {**DEFAULT_ROW, PL212_ROW_ID: row_id, PL212_EXCHANGE_HINT: ""}
        target[PL212_ROW_ID] = row_id
        for column in position_columns:
            if column in row.index:
                target[column] = row[column]
        rows.append(target)
    return _pl212_ensure_draft_schema(pd.DataFrame(rows))


def _pl212_merge_fixed_slice(draft: pd.DataFrame, edited: pd.DataFrame, columns: Sequence[str]) -> pd.DataFrame:
    work = _pl212_ensure_draft_schema(draft).set_index(PL212_ROW_ID, drop=False)
    edit = pd.DataFrame(edited)
    if PL212_ROW_ID not in edit.columns:
        return work.reset_index(drop=True)
    for _, row in edit.iterrows():
        row_id = str(row.get(PL212_ROW_ID, "") or "").strip()
        if row_id not in work.index:
            continue
        for column in columns:
            if column in row.index:
                work.at[row_id, column] = row[column]
    return _pl212_ensure_draft_schema(work.reset_index(drop=True))


def _pl212_validate_book(draft: pd.DataFrame, enrich_openfigi: bool = False) -> pd.DataFrame:
    work = _pl212_ensure_draft_schema(draft)
    rows: list[dict[str, Any]] = []
    for _, row in work.iterrows():
        template = _pl212_validation_template()
        template[PL212_ROW_ID] = row[PL212_ROW_ID]
        template["Active"] = bool(row["Active"])
        template["Input Ticker"] = _pl212_normalize_symbol(row["Ticker"])
        if not bool(row["Active"]):
            template.update({
                "Canonical Ticker": template["Input Ticker"],
                "Status": "INACTIVE",
                "Blocking": False,
                "Provider": "N/A",
                "Message": "Inactive rows are preserved for audit and excluded from analytics.",
            })
        else:
            resolved = _pl212_validate_symbol(row["Ticker"], row.get(PL212_EXCHANGE_HINT, ""))
            template.update(resolved)
            template[PL212_ROW_ID] = row[PL212_ROW_ID]
            template["Active"] = True
        rows.append(template)
    master = pd.DataFrame(rows, columns=PL212_MASTER_COLUMNS)

    active = master[master["Active"].fillna(False).astype(bool)].copy()
    canonical = active["Canonical Ticker"].astype(str).str.strip()
    duplicate_symbols = set(canonical[canonical.ne("") & canonical.duplicated(keep=False)].tolist())
    if duplicate_symbols:
        duplicate_mask = master["Active"].fillna(False).astype(bool) & master["Canonical Ticker"].isin(duplicate_symbols)
        master.loc[duplicate_mask, "Status"] = "FAIL"
        master.loc[duplicate_mask, "Blocking"] = True
        master.loc[duplicate_mask, "Message"] = master.loc[duplicate_mask, "Message"].astype(str) + " Duplicate canonical instrument in the active book."

    if enrich_openfigi:
        master = _pl212_openfigi_enrich(master)
    return master


def _pl212_issue(severity: str, row_id: str, ticker: str, check: str, message: str) -> dict[str, Any]:
    return {
        "Severity": severity,
        "Line": row_id,
        "Ticker": ticker,
        "Check": check,
        "Message": message,
    }


def _pl212_book_gate(draft: pd.DataFrame, master: pd.DataFrame | None, validation_current: bool) -> dict[str, Any]:
    work = _pl212_ensure_draft_schema(draft)
    active = work[work["Active"].fillna(False).astype(bool)].copy()
    issues: list[dict[str, Any]] = []
    if active.empty:
        issues.append(_pl212_issue("BLOCK", "BOOK", "", "Active positions", "At least one active instrument is required."))
    if active["Ticker"].astype(str).eq("").any():
        for _, row in active[active["Ticker"].astype(str).eq("")].iterrows():
            issues.append(_pl212_issue("BLOCK", row[PL212_ROW_ID], "", "Ticker", "Active row requires a ticker."))

    if not validation_current or not isinstance(master, pd.DataFrame) or master.empty:
        issues.append(_pl212_issue("BLOCK", "BOOK", "", "Security master", "Validate the current draft before running analytics."))
    else:
        for _, row in master[master["Active"].fillna(False).astype(bool)].iterrows():
            ticker = str(row.get("Input Ticker", ""))
            if bool(row.get("Blocking", False)) or str(row.get("Status", "")).upper() == "FAIL":
                issues.append(_pl212_issue("BLOCK", str(row.get(PL212_ROW_ID, "")), ticker, "Instrument validation", str(row.get("Message", "Instrument validation failed."))))
            elif str(row.get("Status", "")).upper() == "REVIEW":
                issues.append(_pl212_issue("WARN", str(row.get(PL212_ROW_ID, "")), ticker, "Instrument validation", str(row.get("Message", "Instrument requires review."))))

    ticker_counts = active["Ticker"].astype(str).value_counts()
    for ticker in ticker_counts[ticker_counts > 1].index:
        issues.append(_pl212_issue("BLOCK", "BOOK", ticker, "Duplicate ticker", "Duplicate active ticker must be resolved before model execution."))

    for _, row in active.iterrows():
        row_id = str(row[PL212_ROW_ID])
        ticker = str(row["Ticker"])
        minimum = _safe_float(row.get("Min Weight"), np.nan)
        maximum = _safe_float(row.get("Max Weight"), np.nan)
        lot = _safe_float(row.get("Lot Size"), np.nan)
        cost = _safe_float(row.get("Cost bps"), np.nan)
        duration = _safe_float(row.get("Duration"), np.nan)
        avg_cost = _safe_float(row.get("Avg Cost"), np.nan)
        currency = str(row.get("Currency", "") or "").strip().upper()
        if not np.isfinite(minimum) or not np.isfinite(maximum) or minimum > maximum:
            issues.append(_pl212_issue("BLOCK", row_id, ticker, "Weight bounds", "Minimum weight must be finite and no greater than maximum weight."))
        if not np.isfinite(lot) or lot <= 0:
            issues.append(_pl212_issue("BLOCK", row_id, ticker, "Lot size", "Lot size must be strictly positive."))
        if not np.isfinite(cost) or cost < 0:
            issues.append(_pl212_issue("BLOCK", row_id, ticker, "Transaction cost", "Cost bps must be finite and non-negative."))
        if np.isfinite(duration) and duration < 0:
            issues.append(_pl212_issue("BLOCK", row_id, ticker, "Duration", "Duration cannot be negative."))
        if np.isfinite(avg_cost) and avg_cost < 0:
            issues.append(_pl212_issue("BLOCK", row_id, ticker, "Average cost", "Average cost cannot be negative."))
        if not re.fullmatch(r"[A-Z]{3}", currency):
            issues.append(_pl212_issue("BLOCK", row_id, ticker, "Currency", "Currency must be a three-letter ISO-style code."))
        if str(row.get("Name", "") or "").strip() in {"", "None"}:
            issues.append(_pl212_issue("WARN", row_id, ticker, "Reference name", "Security name is missing; apply provider metadata or document a local name."))
        if str(row.get("Country", "") or "").strip().lower() in {"", "unclassified", "none"}:
            issues.append(_pl212_issue("WARN", row_id, ticker, "Country", "Country classification is unclassified."))
        if str(row.get("Sector", "") or "").strip().lower() in {"", "unclassified", "none"} and str(row.get("Asset Class", "")) not in {"Cash", "FX"}:
            issues.append(_pl212_issue("WARN", row_id, ticker, "Sector", "Sector classification is unclassified."))
        quantity = _safe_float(row.get("Quantity"), np.nan)
        weight = _safe_float(row.get("Current Weight"), np.nan)
        if (not np.isfinite(quantity) or abs(quantity) <= EPS) and (not np.isfinite(weight) or abs(weight) <= EPS):
            issues.append(_pl212_issue("WARN", row_id, ticker, "Position size", "Both quantity and current weight are empty or zero."))

    issue_frame = pd.DataFrame(issues, columns=["Severity", "Line", "Ticker", "Check", "Message"])
    blockers = int((issue_frame["Severity"] == "BLOCK").sum()) if not issue_frame.empty else 0
    warnings = int((issue_frame["Severity"] == "WARN").sum()) if not issue_frame.empty else 0
    status = "FAIL" if blockers else "REVIEW" if warnings else "PASS"
    if not validation_current:
        status = "UNVALIDATED"
    valid_count = 0
    if isinstance(master, pd.DataFrame) and not master.empty:
        valid_count = int(master[master["Status"].isin(["PASS", "CASH", "REVIEW"]) & master["Active"].fillna(False).astype(bool)].shape[0])
    return {
        "Status": status,
        "Can Run": blockers == 0 and validation_current,
        "Blocking Issues": blockers,
        "Warnings": warnings,
        "Active Rows": int(len(active)),
        "Validated Rows": valid_count,
        "Issues": issue_frame,
    }


def _pl212_input_preflight(book: pd.DataFrame, input_mode: str, portfolio_nav: float) -> pd.DataFrame:
    frame = _clean_book(book)
    rows: list[dict[str, Any]] = []
    if not np.isfinite(float(portfolio_nav)) or float(portfolio_nav) <= 0:
        rows.append({"Severity": "BLOCK", "Check": "Portfolio NAV", "Message": "Portfolio NAV must be strictly positive."})
    if input_mode == "Current Weights":
        weights = pd.to_numeric(frame["Current Weight"], errors="coerce")
        if weights.isna().any():
            rows.append({"Severity": "BLOCK", "Check": "Current weights", "Message": "Every active row requires a current weight in weight mode."})
        total = float(weights.fillna(0.0).sum())
        if abs(total - 1.0) > 0.001:
            rows.append({"Severity": "BLOCK", "Check": "Current-weight sum", "Message": f"Weights sum to {total:.4%}; they must reconcile to 100% within 10 bps."})
        gross = float(weights.fillna(0.0).abs().sum())
        if gross > 1.5:
            rows.append({"Severity": "WARN", "Check": "Gross exposure", "Message": f"Current gross exposure is {gross:.2f}x; confirm leverage intent."})
    else:
        quantity = pd.to_numeric(frame["Quantity"], errors="coerce").fillna(0.0)
        if float(quantity.abs().sum()) <= EPS:
            rows.append({"Severity": "BLOCK", "Check": "Quantities", "Message": "At least one active position must have a non-zero quantity."})
    return pd.DataFrame(rows, columns=["Severity", "Check", "Message"])


def _pl212_apply_security_master(
    draft: pd.DataFrame,
    master: pd.DataFrame,
    apply_canonical: bool = True,
    fill_reference: bool = True,
    overwrite_classification: bool = False,
) -> pd.DataFrame:
    work = _pl212_ensure_draft_schema(draft).set_index(PL212_ROW_ID, drop=False)
    for _, record in pd.DataFrame(master).iterrows():
        row_id = str(record.get(PL212_ROW_ID, ""))
        if row_id not in work.index or not bool(record.get("Active", False)):
            continue
        if str(record.get("Status", "")).upper() not in {"PASS", "REVIEW", "CASH"}:
            continue
        canonical = _pl212_normalize_symbol(record.get("Canonical Ticker", ""))
        if apply_canonical and canonical:
            work.at[row_id, "Ticker"] = canonical
        if fill_reference:
            name = str(record.get("Name", "") or "").strip()
            if name and str(work.at[row_id, "Name"] or "").strip() in {"", "Current analysis ticker", "None"}:
                work.at[row_id, "Name"] = name
            currency = str(record.get("Currency", "") or "").strip().upper()
            if currency and str(work.at[row_id, "Currency"] or "").strip().upper() in {"", "UNCLASSIFIED", "NONE", "USD"}:
                work.at[row_id, "Currency"] = currency
            exchange = str(record.get("Exchange", "") or "").strip()
            if exchange and not str(work.at[row_id, PL212_EXCHANGE_HINT] or "").strip():
                work.at[row_id, PL212_EXCHANGE_HINT] = exchange
        if overwrite_classification:
            asset_class = str(record.get("Asset Class", "") or "").strip()
            if asset_class in PL212_ASSET_CLASSES:
                work.at[row_id, "Asset Class"] = asset_class
    return _pl212_ensure_draft_schema(work.reset_index(drop=True))


def _pl212_header_key(value: Any) -> str:
    text = re.sub(r"[_\-]+", " ", str(value or "").strip().lower())
    return re.sub(r"\s+", " ", text)


def _pl212_suggest_import_target(column: Any) -> str:
    key = _pl212_header_key(column)
    if key in PL212_IMPORT_ALIASES:
        return PL212_IMPORT_ALIASES[key]
    for target in [*BOOK_COLUMNS, PL212_EXCHANGE_HINT]:
        if _pl212_header_key(target) == key:
            return target
    return "Ignore"


def _pl212_map_import_frame(raw: pd.DataFrame, mapping: Mapping[str, str]) -> tuple[pd.DataFrame, list[str]]:
    source = pd.DataFrame(raw).copy()
    used_targets = [target for target in mapping.values() if target and target != "Ignore"]
    duplicates = sorted({target for target in used_targets if used_targets.count(target) > 1})
    errors: list[str] = []
    if duplicates:
        errors.append("Multiple source columns map to: " + ", ".join(duplicates))
    if "Ticker" not in used_targets:
        errors.append("A source column must map to Ticker.")
    if errors:
        return pd.DataFrame(), errors
    mapped = pd.DataFrame(index=source.index)
    for source_column, target in mapping.items():
        if target and target != "Ignore" and source_column in source.columns:
            mapped[target] = source[source_column]
    for column in BOOK_COLUMNS:
        if column not in mapped.columns:
            mapped[column] = DEFAULT_ROW.get(column, np.nan)
    if PL212_EXCHANGE_HINT not in mapped.columns:
        mapped[PL212_EXCHANGE_HINT] = ""
    mapped["Active"] = mapped["Active"].map(_pl212_parse_bool)
    mapped = _pl212_ensure_draft_schema(mapped)
    return mapped, []


def _pl212_minimal_template_csv() -> bytes:
    frame = pd.DataFrame([
        {"Ticker": "AAPL", "Quantity": 10.0, "Avg Cost": 180.0, "Asset Class": "Equity", "Currency": "USD", PL212_EXCHANGE_HINT: "NASDAQ"}
    ])
    return frame.to_csv(index=False).encode("utf-8")


def _pl212_full_template_csv() -> bytes:
    row = {**DEFAULT_ROW, "Ticker": "AAPL", "Quantity": 10.0, PL212_EXCHANGE_HINT: "NASDAQ"}
    return pd.DataFrame([row])[[*BOOK_COLUMNS, PL212_EXCHANGE_HINT]].to_csv(index=False).encode("utf-8")


def _pl212_master_display(master: pd.DataFrame) -> pd.DataFrame:
    display = pd.DataFrame(master).copy()
    if display.empty:
        return display
    for column in ["Last Price"]:
        if column in display.columns:
            display[column] = pd.to_numeric(display[column], errors="coerce")
    if "Last Date" in display.columns:
        display["Last Date"] = pd.to_datetime(display["Last Date"], errors="coerce").dt.strftime("%Y-%m-%d")
    return display


def _pl212_gate_banner(gate: Mapping[str, Any]) -> None:
    status = str(gate.get("Status", "UNVALIDATED")).upper()
    css = {
        "PASS": "pl212-gate-pass",
        "REVIEW": "pl212-gate-review",
        "FAIL": "pl212-gate-fail",
        "UNVALIDATED": "pl212-gate-unvalidated",
    }.get(status, "pl212-gate-unvalidated")
    st.markdown(
        f'<div class="pl212-gate {css}"><strong>Book control · {status}</strong><br>'
        f'{int(gate.get("Active Rows", 0))} active line(s) · {int(gate.get("Validated Rows", 0))} validated · '
        f'{int(gate.get("Blocking Issues", 0))} blocking issue(s) · {int(gate.get("Warnings", 0))} warning(s).</div>',
        unsafe_allow_html=True,
    )


def _render_book_editor(ticker: str | None) -> pd.DataFrame:
    _pl212_inject_css()
    draft = _pl212_get_draft(ticker)

    st.markdown(
        """
        <div class="pl212-hero">
          <div class="pl212-eyebrow">Position intake · security master · classifications · mandate · preflight</div>
          <div class="pl212-title">Institutional Portfolio Book Builder</div>
          <div class="pl212-copy">Build positions through a controlled security-master workflow. Active instruments must resolve to usable market history before analytics can run. Provider symbols, metadata, constraints and import mappings remain reviewable and auditable.</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    action_cols = st.columns([1, 1, 1, 1, 1.4])
    if action_cols[0].button("Reset book", key="pl_reset_book", width="stretch"):
        st.session_state[PL212_DRAFT_KEY] = _pl212_ensure_draft_schema(_initial_book(ticker))
        st.session_state[PL212_DRAFT_NONCE_KEY] = int(st.session_state.get(PL212_DRAFT_NONCE_KEY, 0)) + 1
        st.session_state.pop("portfolio_lab_model_v1", None)
        st.session_state.pop(PL212_MASTER_KEY, None)
        st.rerun()
    if action_cols[1].button("Load demo", key="pl_load_demo", width="stretch", help="Loads the labelled demonstration portfolio; it is not presented as a real account."):
        st.session_state[PL212_DRAFT_KEY] = _pl212_ensure_draft_schema(DEMO_BOOK.copy())
        st.session_state[PL212_DRAFT_NONCE_KEY] = int(st.session_state.get(PL212_DRAFT_NONCE_KEY, 0)) + 1
        st.session_state.pop("portfolio_lab_model_v1", None)
        st.session_state.pop(PL212_MASTER_KEY, None)
        st.rerun()
    action_cols[2].download_button("Minimal template", data=_pl212_minimal_template_csv(), file_name="portfolio_book_minimal_v212.csv", mime="text/csv", width="stretch", key="pl212_download_minimal_template")
    action_cols[3].download_button("Full template", data=_pl212_full_template_csv(), file_name="portfolio_book_full_v212.csv", mime="text/csv", width="stretch", key="pl212_download_full_template")
    action_cols[4].download_button("Download current draft", data=draft.drop(columns=[PL212_ROW_ID], errors="ignore").to_csv(index=False).encode("utf-8"), file_name="portfolio_book_draft_v212.csv", mime="text/csv", width="stretch", key="pl212_download_current_draft")

    current_fingerprint = _pl212_draft_fingerprint(draft)
    master = st.session_state.get(PL212_MASTER_KEY)
    validation_current = bool(
        isinstance(master, pd.DataFrame)
        and st.session_state.get(PL212_MASTER_FINGERPRINT_KEY) == current_fingerprint
    )
    gate = _pl212_book_gate(draft, master if isinstance(master, pd.DataFrame) else None, validation_current)
    _pl212_gate_banner(gate)

    tabs = st.tabs([
        "01 · Positions & Search",
        "02 · Classification",
        "03 · Mandate & Execution",
        "04 · Security Master",
        "05 · Import & Templates",
    ])

    with tabs[0]:
        with st.expander("Add an instrument through provider search", expanded=False):
            search_cols = st.columns([2.4, 0.7])
            query = search_cols[0].text_input("Company, fund or ticker", key=PL212_SEARCH_QUERY_KEY, placeholder="NVDA, NVIDIA, Airbus, iShares Treasury...")
            if search_cols[1].button("Search", type="primary", width="stretch", key="pl212_search_button"):
                st.session_state[PL212_SEARCH_RESULTS_KEY] = _pl212_search_instruments(query, max_results=12)
            results = st.session_state.get(PL212_SEARCH_RESULTS_KEY, [])
            if results:
                result_frame = pd.DataFrame(results)
                st.dataframe(result_frame, width="stretch", hide_index=True)
                labels = [f"{row['Ticker']} · {row['Name']} · {row['Exchange']} · {row['Instrument Type']}" for row in results]
                selected_label = st.selectbox("Resolved instrument", labels, key="pl212_search_selection")
                selected = results[labels.index(selected_label)]
                if st.button("Add selected instrument to draft", width="stretch", key="pl212_add_search_result"):
                    new_row = {
                        **DEFAULT_ROW,
                        PL212_ROW_ID: _pl212_next_row_id(),
                        PL212_EXCHANGE_HINT: selected.get("Exchange", ""),
                        "Ticker": selected.get("Ticker", ""),
                        "Name": selected.get("Name", ""),
                        "Asset Class": selected.get("Asset Class", "Other"),
                        "Currency": selected.get("Currency", "USD") or "USD",
                        "Quantity": 0.0,
                    }
                    draft = pd.concat([draft, pd.DataFrame([new_row])], ignore_index=True)
                    _pl212_sync_draft(draft, invalidate_validation=True)
                    st.session_state[PL212_DRAFT_NONCE_KEY] += 1
                    st.rerun()
            elif query:
                st.info("No provider search result is stored. The installed yfinance build may not expose Search; manual ticker entry plus validation remains available.")

        master_map: dict[str, Mapping[str, Any]] = {}
        if validation_current and isinstance(master, pd.DataFrame):
            master_map = {str(row[PL212_ROW_ID]): row for _, row in master.iterrows()}
        position_view = draft[[PL212_ROW_ID, "Active", "Ticker", PL212_EXCHANGE_HINT, "Name", "Quantity", "Avg Cost", "Current Weight"]].copy()
        position_view.insert(1, "Validation", [str(master_map.get(str(row_id), {}).get("Status", "UNVALIDATED")) for row_id in position_view[PL212_ROW_ID]])
        position_view["Canonical Ticker"] = [str(master_map.get(str(row_id), {}).get("Canonical Ticker", "")) for row_id in position_view[PL212_ROW_ID]]
        position_view["Validation Message"] = [str(master_map.get(str(row_id), {}).get("Message", "Validate the current draft.")) for row_id in position_view[PL212_ROW_ID]]
        edited_positions = st.data_editor(
            position_view,
            width="stretch",
            height=390,
            num_rows="dynamic",
            hide_index=True,
            disabled=[PL212_ROW_ID, "Validation", "Canonical Ticker", "Validation Message"],
            column_config={
                PL212_ROW_ID: st.column_config.TextColumn("Line", help="Stable internal line identifier."),
                "Validation": st.column_config.TextColumn("Status"),
                "Active": st.column_config.CheckboxColumn("Active", default=True),
                "Ticker": st.column_config.TextColumn("Ticker", required=True, help="Enter the data-provider symbol. Use Exchange Hint or provider search for ambiguous listings."),
                PL212_EXCHANGE_HINT: st.column_config.TextColumn("Exchange / MIC hint", help="Optional venue hint such as NASDAQ, XPAR, XLON or TSX."),
                "Name": st.column_config.TextColumn("Local / provider name"),
                "Quantity": st.column_config.NumberColumn("Quantity", format="%.6f"),
                "Avg Cost": st.column_config.NumberColumn("Average cost", min_value=0.0, format="%.6f"),
                "Current Weight": st.column_config.NumberColumn("Current weight", format="percent", help="Decimal input: 0.25 = 25%. Required only in Current Weights mode."),
                "Canonical Ticker": st.column_config.TextColumn("Canonical symbol"),
                "Validation Message": st.column_config.TextColumn("Control message", width="large"),
            },
            key=f"pl212_positions_editor_{st.session_state[PL212_DRAFT_NONCE_KEY]}",
        )
        new_draft = _pl212_merge_positions(draft, edited_positions)
        if _pl212_draft_fingerprint(new_draft) != _pl212_draft_fingerprint(draft):
            draft = _pl212_sync_draft(new_draft, invalidate_validation=True)
        else:
            draft = new_draft

    with tabs[1]:
        classification_columns = ["Asset Class", "Sector", "Country", "Currency", "Strategy"]
        classification_view = draft[[PL212_ROW_ID, "Ticker", *classification_columns]].copy()
        edited_classification = st.data_editor(
            classification_view,
            width="stretch",
            height=360,
            hide_index=True,
            disabled=[PL212_ROW_ID, "Ticker"],
            column_config={
                PL212_ROW_ID: st.column_config.TextColumn("Line"),
                "Ticker": st.column_config.TextColumn("Ticker"),
                "Asset Class": st.column_config.SelectboxColumn("Asset class", options=PL212_ASSET_CLASSES, required=True),
                "Sector": st.column_config.TextColumn("Sector / exposure bucket", required=True),
                "Country": st.column_config.TextColumn("Country / domicile", required=True),
                "Currency": st.column_config.TextColumn("Currency", required=True, help="Three-letter ISO-style code."),
                "Strategy": st.column_config.TextColumn("Strategy / sleeve", required=True),
            },
            key=f"pl212_classification_editor_{st.session_state[PL212_DRAFT_NONCE_KEY]}",
        )
        new_draft = _pl212_merge_fixed_slice(draft, edited_classification, classification_columns)
        if _pl212_draft_fingerprint(new_draft) != _pl212_draft_fingerprint(draft):
            draft = _pl212_sync_draft(new_draft, invalidate_validation=True)
        else:
            draft = new_draft

    with tabs[2]:
        mandate_columns = ["Expected Return Override", "Min Weight", "Max Weight", "Cost bps", "Lot Size", "Duration", "Beta Override"]
        mandate_view = draft[[PL212_ROW_ID, "Ticker", *mandate_columns]].copy()
        edited_mandate = st.data_editor(
            mandate_view,
            width="stretch",
            height=360,
            hide_index=True,
            disabled=[PL212_ROW_ID, "Ticker"],
            column_config={
                PL212_ROW_ID: st.column_config.TextColumn("Line"),
                "Ticker": st.column_config.TextColumn("Ticker"),
                "Expected Return Override": st.column_config.NumberColumn("Expected-return override", format="percent", help="Optional annual decimal return."),
                "Min Weight": st.column_config.NumberColumn("Minimum weight", min_value=-2.0, max_value=2.0, format="percent"),
                "Max Weight": st.column_config.NumberColumn("Maximum weight", min_value=0.0, max_value=2.0, format="percent"),
                "Cost bps": st.column_config.NumberColumn("One-way cost (bps)", min_value=0.0, format="%.2f"),
                "Lot Size": st.column_config.NumberColumn("Lot size", min_value=0.000001, format="%.6f"),
                "Duration": st.column_config.NumberColumn("Duration", min_value=0.0, format="%.3f"),
                "Beta Override": st.column_config.NumberColumn("Beta override", format="%.4f"),
            },
            key=f"pl212_mandate_editor_{st.session_state[PL212_DRAFT_NONCE_KEY]}",
        )
        new_draft = _pl212_merge_fixed_slice(draft, edited_mandate, mandate_columns)
        if _pl212_draft_fingerprint(new_draft) != _pl212_draft_fingerprint(draft):
            draft = _pl212_sync_draft(new_draft, invalidate_validation=True)
        else:
            draft = new_draft
        weight_sum = pd.to_numeric(draft.loc[draft["Active"], "Current Weight"], errors="coerce").sum(min_count=1)
        mandate_metrics = st.columns(4)
        mandate_metrics[0].metric("Active lines", int(draft["Active"].sum()))
        mandate_metrics[1].metric("Current-weight sum", "N/A" if pd.isna(weight_sum) else f"{float(weight_sum):.2%}")
        mandate_metrics[2].metric("Minimum total max capacity", f"{pd.to_numeric(draft.loc[draft['Active'], 'Max Weight'], errors='coerce').fillna(0.0).sum():.2%}")
        mandate_metrics[3].metric("Cost range", f"{pd.to_numeric(draft.loc[draft['Active'], 'Cost bps'], errors='coerce').min():.1f}–{pd.to_numeric(draft.loc[draft['Active'], 'Cost bps'], errors='coerce').max():.1f} bps" if draft["Active"].any() else "N/A")

    with tabs[3]:
        validate_cols = st.columns([1.0, 1.0, 1.0, 1.8])
        enrich_figi = validate_cols[0].checkbox("OpenFIGI enrichment", value=False, key="pl212_openfigi_enrichment", help="Optional permanent-ID enrichment. Ticker validation does not depend on FIGI availability.")
        if validate_cols[1].button("Validate instruments", type="primary", width="stretch", key="pl212_validate_book"):
            with st.spinner("Resolving symbols, market history and reference metadata..."):
                validated = _pl212_validate_book(draft, enrich_openfigi=enrich_figi)
            st.session_state[PL212_MASTER_KEY] = validated
            st.session_state[PL212_MASTER_FINGERPRINT_KEY] = _pl212_draft_fingerprint(draft)
            st.session_state[PL212_MASTER_TIMESTAMP_KEY] = _utc_now_iso()
            st.rerun()
        if validate_cols[2].button("Clear validation", width="stretch", key="pl212_clear_validation"):
            st.session_state.pop(PL212_MASTER_KEY, None)
            st.session_state.pop(PL212_MASTER_FINGERPRINT_KEY, None)
            st.rerun()
        validate_cols[3].caption("Validation confirms exact provider symbols and usable market history. OpenFIGI is an optional permanent-identifier enrichment and may require exchange-specific review.")

        master = st.session_state.get(PL212_MASTER_KEY)
        current_fingerprint = _pl212_draft_fingerprint(draft)
        validation_current = bool(isinstance(master, pd.DataFrame) and st.session_state.get(PL212_MASTER_FINGERPRINT_KEY) == current_fingerprint)
        if isinstance(master, pd.DataFrame) and not master.empty:
            apply_cols = st.columns([1.0, 1.0, 1.0, 1.2])
            apply_canonical = apply_cols[0].checkbox("Apply canonical symbols", value=True, key="pl212_apply_canonical")
            fill_reference = apply_cols[1].checkbox("Fill blank reference fields", value=True, key="pl212_fill_reference")
            overwrite_classification = apply_cols[2].checkbox("Overwrite asset class", value=False, key="pl212_overwrite_classification")
            if apply_cols[3].button("Apply reviewed master data", width="stretch", disabled=not validation_current, key="pl212_apply_master"):
                updated = _pl212_apply_security_master(draft, master, apply_canonical, fill_reference, overwrite_classification)
                _pl212_sync_draft(updated, invalidate_validation=True)
                st.session_state[PL212_DRAFT_NONCE_KEY] += 1
                st.rerun()
            if not validation_current:
                st.warning("The displayed security master belongs to an earlier draft. Revalidate before applying or running analytics.")
            st.dataframe(
                _pl212_master_display(master),
                width="stretch",
                hide_index=True,
                height=_pl22_height(master, minimum=300, maximum=650),
                column_config={
                    "Active": st.column_config.CheckboxColumn("Active"),
                    "Blocking": st.column_config.CheckboxColumn("Blocking"),
                    "Last Price": st.column_config.NumberColumn("Last price", format="%.6f"),
                    "Quote Age Days": st.column_config.NumberColumn("Age (days)", format="%.0f"),
                    "Observations": st.column_config.NumberColumn("Observations", format="%d"),
                },
            )
            st.caption(f"Validated at {st.session_state.get(PL212_MASTER_TIMESTAMP_KEY, 'N/A')} · draft fingerprint {str(st.session_state.get(PL212_MASTER_FINGERPRINT_KEY, ''))[:16]}…")
        else:
            st.info("No security-master validation is stored. Validate the draft to unlock model execution.")

    with tabs[4]:
        uploaded = st.file_uploader("Import portfolio CSV into a staging area", type=["csv"], key="pl212_book_upload")
        if uploaded is not None:
            token = f"{uploaded.name}:{uploaded.size}"
            if st.session_state.get(PL212_IMPORT_TOKEN_KEY) != token:
                try:
                    raw = pd.read_csv(uploaded)
                    st.session_state[PL212_IMPORT_RAW_KEY] = raw
                    st.session_state[PL212_IMPORT_TOKEN_KEY] = token
                except Exception as exc:
                    st.error(f"CSV staging failed: {exc}")
        raw = st.session_state.get(PL212_IMPORT_RAW_KEY)
        if isinstance(raw, pd.DataFrame):
            st.markdown("#### Column mapping")
            st.caption("No column is discarded silently. Map each source field or explicitly acknowledge ignored columns before committing the import.")
            targets = ["Ignore", *BOOK_COLUMNS, PL212_EXCHANGE_HINT]
            mapping: dict[str, str] = {}
            map_columns = st.columns(3)
            token_hash = hashlib.sha256(str(st.session_state.get(PL212_IMPORT_TOKEN_KEY, "")).encode("utf-8")).hexdigest()[:8]
            for index, source_column in enumerate(raw.columns):
                suggested = _pl212_suggest_import_target(source_column)
                mapping[str(source_column)] = map_columns[index % 3].selectbox(
                    str(source_column),
                    targets,
                    index=targets.index(suggested) if suggested in targets else 0,
                    key=f"pl212_map_{token_hash}_{index}",
                )
            preview, mapping_errors = _pl212_map_import_frame(raw, mapping)
            ignored = [source for source, target in mapping.items() if target == "Ignore"]
            acknowledge_ignored = True
            if ignored:
                st.warning("Ignored source columns: " + ", ".join(ignored))
                acknowledge_ignored = st.checkbox("I acknowledge that the listed source columns are not part of the Portfolio Lab schema.", key=f"pl212_ignore_ack_{token_hash}")
            if mapping_errors:
                for error in mapping_errors:
                    st.error(error)
            elif not preview.empty:
                st.dataframe(preview.drop(columns=[PL212_ROW_ID], errors="ignore").head(20), width="stretch", hide_index=True)
                commit_cols = st.columns(2)
                if commit_cols[0].button("Replace draft with staged import", type="primary", width="stretch", disabled=not acknowledge_ignored, key=f"pl212_import_replace_{token_hash}"):
                    _pl212_sync_draft(preview, invalidate_validation=True)
                    st.session_state[PL212_DRAFT_NONCE_KEY] += 1
                    st.rerun()
                if commit_cols[1].button("Append staged import", width="stretch", disabled=not acknowledge_ignored, key=f"pl212_import_append_{token_hash}"):
                    combined = pd.concat([draft, preview], ignore_index=True)
                    _pl212_sync_draft(combined, invalidate_validation=True)
                    st.session_state[PL212_DRAFT_NONCE_KEY] += 1
                    st.rerun()
        else:
            st.caption("Upload a CSV to preview, map and validate it before changing the active draft.")

    draft = _pl212_sync_draft(draft)
    current_fingerprint = _pl212_draft_fingerprint(draft)
    master = st.session_state.get(PL212_MASTER_KEY)
    validation_current = bool(isinstance(master, pd.DataFrame) and st.session_state.get(PL212_MASTER_FINGERPRINT_KEY) == current_fingerprint)
    gate = _pl212_book_gate(draft, master if isinstance(master, pd.DataFrame) else None, validation_current)
    st.session_state[PL212_GATE_KEY] = gate
    st.markdown("#### Portfolio book preflight")
    preflight_metrics = st.columns(5)
    preflight_metrics[0].metric("Status", gate["Status"])
    preflight_metrics[1].metric("Active", gate["Active Rows"])
    preflight_metrics[2].metric("Validated", gate["Validated Rows"])
    preflight_metrics[3].metric("Blocking", gate["Blocking Issues"])
    preflight_metrics[4].metric("Warnings", gate["Warnings"])
    if not gate["Issues"].empty:
        st.dataframe(gate["Issues"], width="stretch", hide_index=True, height=_pl22_height(gate["Issues"], minimum=180, maximum=500))
    else:
        st.success("The active portfolio book passed security-master, schema and mandate preflight controls.")
    return _clean_book(draft[BOOK_COLUMNS])


def _pl212_widget_default(key: str, value: Any) -> None:
    if key not in st.session_state:
        st.session_state[key] = value


def _render_settings_form() -> tuple[PortfolioSettings, bool]:
    existing = st.session_state.get("portfolio_lab_model_v1")
    existing_settings = existing.get("settings") if isinstance(existing, Mapping) else None
    _pl212_widget_default("pl212_input_mode", getattr(existing_settings, "input_mode", "Quantities"))
    _pl212_widget_default("pl212_portfolio_nav", float(getattr(existing_settings, "portfolio_nav", 100_000.0)))
    _pl212_widget_default("pl212_period", getattr(existing_settings, "period", "5y"))
    _pl212_widget_default("pl212_benchmark", getattr(existing_settings, "benchmark", DEFAULT_BENCHMARK))
    _pl212_widget_default("pl212_risk_free", float(getattr(existing_settings, "risk_free_rate", 0.02)))
    _pl212_widget_default("pl212_covariance", getattr(existing_settings, "covariance_model", "Diagonal Shrinkage"))
    _pl212_widget_default("pl212_shrinkage", float(getattr(existing_settings, "shrinkage", 0.25)))
    _pl212_widget_default("pl212_ewma", float(getattr(existing_settings, "ewma_lambda", 0.94)))
    _pl212_widget_default("pl212_expected_returns", getattr(existing_settings, "expected_return_model", "Historical Geometric"))
    _pl212_widget_default("pl212_min_coverage", float(getattr(existing_settings, "min_coverage", 0.80)))
    pending_benchmark = st.session_state.pop("pl212_pending_benchmark", None)
    if pending_benchmark:
        st.session_state["pl212_benchmark"] = pending_benchmark

    st.markdown("#### Model configuration and execution gate")
    row1 = st.columns([1.1, 1.1, 1.0, 1.4, 0.8])
    input_mode = row1[0].selectbox("Current portfolio input", ["Quantities", "Current Weights"], key="pl212_input_mode")
    portfolio_nav = row1[1].number_input("Portfolio NAV (weight mode)", min_value=1.0, step=10_000.0, key="pl212_portfolio_nav")
    period = row1[2].selectbox("History", ["1y", "2y", "5y", "10y", "max"], key="pl212_period")
    benchmark = _pl212_normalize_symbol(row1[3].text_input("Benchmark", key="pl212_benchmark")) or DEFAULT_BENCHMARK
    validate_benchmark = row1[4].button("Validate benchmark", width="stretch", key="pl212_validate_benchmark")
    if validate_benchmark:
        record = _pl212_validate_symbol(benchmark, "")
        st.session_state[PL212_BENCHMARK_RECORD_KEY] = record
        st.session_state[PL212_BENCHMARK_FINGERPRINT_KEY] = benchmark
        st.rerun()

    benchmark_record = st.session_state.get(PL212_BENCHMARK_RECORD_KEY)
    benchmark_current = bool(isinstance(benchmark_record, Mapping) and st.session_state.get(PL212_BENCHMARK_FINGERPRINT_KEY) == benchmark)
    if benchmark_current:
        benchmark_status = str(benchmark_record.get("Status", "FAIL"))
        benchmark_message = str(benchmark_record.get("Message", ""))
        benchmark_canonical = str(benchmark_record.get("Canonical Ticker", benchmark))
        if benchmark_canonical and benchmark_canonical != benchmark:
            bcols = st.columns([3.0, 1.0])
            bcols[0].warning(f"Benchmark {benchmark}: {benchmark_message}")
            if bcols[1].button(f"Use {benchmark_canonical}", width="stretch", key="pl212_use_benchmark_canonical"):
                st.session_state["pl212_pending_benchmark"] = benchmark_canonical
                st.session_state.pop(PL212_BENCHMARK_RECORD_KEY, None)
                st.rerun()
        elif benchmark_status in {"PASS", "REVIEW"} and not bool(benchmark_record.get("Blocking", False)):
            st.success(f"Benchmark {benchmark} · {benchmark_status} · {benchmark_message}")
        else:
            st.error(f"Benchmark {benchmark} · {benchmark_status} · {benchmark_message}")
    else:
        st.info("Validate the benchmark after changing its symbol. Model execution remains locked until it resolves to usable market history.")

    row2 = st.columns(5)
    risk_free_rate = row2[0].number_input("Risk-free rate", min_value=-0.10, max_value=0.30, step=0.005, format="%.3f", key="pl212_risk_free")
    covariance_model = row2[1].selectbox("Covariance", ["Diagonal Shrinkage", "Sample", "EWMA"], key="pl212_covariance")
    shrinkage = row2[2].slider("Shrinkage", 0.0, 1.0, step=0.05, key="pl212_shrinkage")
    ewma_lambda = row2[3].slider("EWMA lambda", 0.80, 0.99, step=0.01, key="pl212_ewma")
    expected_return_model = row2[4].selectbox("Expected returns", ["Historical Geometric", "Historical Arithmetic", "EWMA", "Black-Litterman"], key="pl212_expected_returns")

    row3 = st.columns([1.6, 1.6, 1.0])
    min_coverage = row3[0].slider("Minimum return-history coverage", 0.50, 1.00, step=0.05, key="pl212_min_coverage")
    row3[1].caption("Black-Litterman views are configured below when selected. Security validation and benchmark validation remain separate from model assumptions.")

    draft = st.session_state.get(PL212_DRAFT_KEY, pd.DataFrame())
    book = _clean_book(pd.DataFrame(draft)[BOOK_COLUMNS] if isinstance(draft, pd.DataFrame) and set(BOOK_COLUMNS).issubset(draft.columns) else pd.DataFrame())
    gate = st.session_state.get(PL212_GATE_KEY, {"Can Run": False, "Warnings": 0, "Blocking Issues": 1, "Status": "UNVALIDATED", "Issues": pd.DataFrame()})
    input_issues = _pl212_input_preflight(book, input_mode, float(portfolio_nav))
    benchmark_blocking = not benchmark_current or not isinstance(benchmark_record, Mapping) or bool(benchmark_record.get("Blocking", True)) or str(benchmark_record.get("Status", "FAIL")) == "FAIL"
    combined_warnings = int(gate.get("Warnings", 0)) + (int((input_issues["Severity"] == "WARN").sum()) if not input_issues.empty else 0)
    combined_blockers = int(gate.get("Blocking Issues", 0)) + (int((input_issues["Severity"] == "BLOCK").sum()) if not input_issues.empty else 0) + int(benchmark_blocking)
    warning_ack = True
    if combined_warnings > 0:
        warning_ack = st.checkbox("I reviewed the non-blocking book and model-input warnings.", key="pl212_warning_ack")
    can_run = bool(gate.get("Can Run", False) and combined_blockers == 0 and warning_ack)
    run = row3[2].button("Run Portfolio Lab", type="primary", width="stretch", disabled=not can_run, key="pl212_run_portfolio")

    gate_cols = st.columns(4)
    gate_cols[0].metric("Execution gate", "OPEN" if can_run else "LOCKED")
    gate_cols[1].metric("Book status", str(gate.get("Status", "UNVALIDATED")))
    gate_cols[2].metric("Blocking controls", combined_blockers)
    gate_cols[3].metric("Warnings", combined_warnings)
    if not input_issues.empty:
        st.dataframe(input_issues, width="stretch", hide_index=True)
    if not can_run:
        st.caption("Run remains disabled until active instruments, canonical symbols, benchmark, schema and input-mode reconciliations pass. Warnings require explicit acknowledgement.")

    settings = PortfolioSettings(
        input_mode=input_mode,
        portfolio_nav=float(portfolio_nav),
        period=period,
        interval="1d",
        benchmark=benchmark,
        risk_free_rate=float(risk_free_rate),
        covariance_model=covariance_model,
        shrinkage=float(shrinkage),
        ewma_lambda=float(ewma_lambda),
        expected_return_model=expected_return_model,
        min_coverage=float(min_coverage),
    )
    return settings, run


_pl212_enhance_model_parent = enhance_model_v2


def enhance_model_v2(model: dict[str, Any]) -> dict[str, Any]:
    enhanced = _pl212_enhance_model_parent(model)
    master = st.session_state.get(PL212_MASTER_KEY)
    gate = st.session_state.get(PL212_GATE_KEY)
    benchmark = st.session_state.get(PL212_BENCHMARK_RECORD_KEY)
    if isinstance(master, pd.DataFrame):
        enhanced["security_master_v212"] = master.copy()
    if isinstance(gate, Mapping):
        enhanced["book_gate_v212"] = {key: value for key, value in gate.items() if key != "Issues"}
        if isinstance(gate.get("Issues"), pd.DataFrame):
            enhanced["book_preflight_v212"] = gate["Issues"].copy()
    if isinstance(benchmark, Mapping):
        enhanced["benchmark_validation_v212"] = dict(benchmark)
    enhanced.setdefault("manifest", {})["security_master_version"] = "2.12"
    enhanced["manifest"]["security_master_validated_at_utc"] = st.session_state.get(PL212_MASTER_TIMESTAMP_KEY)
    enhanced["manifest"]["module"] = f"Portfolio Lab v{PORTFOLIO_LAB_VERSION}"
    enhanced["manifest"]["version"] = PORTFOLIO_LAB_VERSION
    return enhanced


_pl212_data_quality_parent = _pl211_data_quality_table


def _pl211_data_quality_table(model: Mapping[str, Any]) -> pd.DataFrame:
    base = _pl212_data_quality_parent(model)
    master = model.get("security_master_v212")
    gate = model.get("book_gate_v212", {})
    benchmark = model.get("benchmark_validation_v212", {})
    rows: list[dict[str, Any]] = []
    if isinstance(master, pd.DataFrame) and not master.empty:
        active = master[master["Active"].fillna(False).astype(bool)]
        validated = active[active["Status"].isin(["PASS", "REVIEW", "CASH"])]
        coverage = float(len(validated) / len(active)) if len(active) else 0.0
        blockers = int(active["Blocking"].fillna(False).astype(bool).sum())
        canonical_mismatch = int((active["Input Ticker"].astype(str) != active["Canonical Ticker"].astype(str)).sum())
        rows.extend([
            {"Domain": "Data / Foundation", "Control": "Security-master coverage", "Observed": coverage, "Threshold": "= 100%", "Status": "PASS" if coverage >= 1.0 - 1e-12 else "FAIL", "Severity": "Critical", "Owner": "Data Owner", "Evidence": "Active instruments resolved through the book security master"},
            {"Domain": "Data / Foundation", "Control": "Blocking instrument records", "Observed": blockers, "Threshold": "= 0", "Status": "PASS" if blockers == 0 else "FAIL", "Severity": "Critical", "Owner": "Data Owner", "Evidence": "Ticker, history and canonical-symbol controls"},
            {"Domain": "Data / Foundation", "Control": "Canonical symbol mismatches", "Observed": canonical_mismatch, "Threshold": "= 0", "Status": "PASS" if canonical_mismatch == 0 else "REVIEW", "Severity": "High", "Owner": "Data Owner", "Evidence": "Input symbols reconciled to provider canonical symbols"},
        ])
    else:
        rows.append({"Domain": "Data / Foundation", "Control": "Security-master coverage", "Observed": 0.0, "Threshold": "= 100%", "Status": "REVIEW", "Severity": "Critical", "Owner": "Data Owner", "Evidence": "No security-master validation attached to the model"})
    if isinstance(benchmark, Mapping) and bool(benchmark):
        status = "PASS" if str(benchmark.get("Status")) in {"PASS", "REVIEW"} and not bool(benchmark.get("Blocking", False)) else "FAIL"
        rows.append({"Domain": "Data / Foundation", "Control": "Benchmark instrument validation", "Observed": 1.0 if status == "PASS" else 0.0, "Threshold": "= 100%", "Status": status, "Severity": "High", "Owner": "Performance Owner", "Evidence": str(benchmark.get("Message", ""))})
    elif gate:
        rows.append({"Domain": "Data / Foundation", "Control": "Benchmark instrument validation", "Observed": 0.0, "Threshold": "= 100%", "Status": "REVIEW", "Severity": "High", "Owner": "Performance Owner", "Evidence": "No benchmark validation attached to the model"})
    return pd.concat([base, pd.DataFrame(rows)], ignore_index=True) if rows else base


def _pl212_add_audit_evidence(base_zip: bytes, model: Mapping[str, Any]) -> bytes:
    source = BytesIO(base_zip)
    output = BytesIO()
    with zipfile.ZipFile(source, "r") as existing, zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        existing_files = {name: existing.read(name) for name in existing.namelist() if name not in {"audit_file_manifest.csv", "audit_file_manifest.json"}}
        for name, data in existing_files.items():
            archive.writestr(name, data)
        master = model.get("security_master_v212", pd.DataFrame())
        preflight = model.get("book_preflight_v212", pd.DataFrame())
        benchmark = model.get("benchmark_validation_v212", {})
        additions: dict[str, tuple[bytes, str, str]] = {}
        if isinstance(master, pd.DataFrame):
            additions["security_master_v212.csv"] = (master.to_csv(index=False).encode("utf-8"), "Data", "Security-master validation and canonical symbols")
        if isinstance(preflight, pd.DataFrame):
            additions["book_preflight_v212.csv"] = (preflight.to_csv(index=False).encode("utf-8"), "Governance", "Portfolio-book blocking controls and warnings")
        additions["benchmark_validation_v212.json"] = (json.dumps(_pl211_json_safe(benchmark), indent=2, ensure_ascii=False, allow_nan=False).encode("utf-8"), "Data", "Benchmark instrument validation")
        for name, (data, _, _) in additions.items():
            archive.writestr(name, data)
        manifest_rows: list[dict[str, Any]] = []
        descriptions = {
            **{name: ("Inherited", "Portfolio Lab audit evidence") for name in existing_files},
            **{name: (category, description) for name, (_, category, description) in additions.items()},
        }
        for name in archive.namelist():
            data = archive.read(name)
            category, description = descriptions.get(name, ("Other", "Audit evidence"))
            manifest_rows.append({"File": name, "Bytes": len(data), "SHA-256": hashlib.sha256(data).hexdigest(), "Category": category, "Description": description})
        manifest = pd.DataFrame(manifest_rows)
        archive.writestr("audit_file_manifest.csv", manifest.to_csv(index=False).encode("utf-8"))
        archive.writestr("audit_file_manifest.json", json.dumps(_pl211_json_safe(manifest), indent=2, ensure_ascii=False, allow_nan=False).encode("utf-8"))
    output.seek(0)
    return output.getvalue()


_pl212_audit_parent = _pl211_build_audit_zip


def _pl211_build_audit_zip(model: Mapping[str, Any], controls: pd.DataFrame, data_quality: pd.DataFrame, modules: pd.DataFrame, pipeline: pd.DataFrame, action_queue: pd.DataFrame, inventory: pd.DataFrame, lineage: pd.DataFrame, integrations: pd.DataFrame, exceptions: pd.DataFrame) -> bytes:
    base = _pl212_audit_parent(model, controls, data_quality, modules, pipeline, action_queue, inventory, lineage, integrations, exceptions)
    return _pl212_add_audit_evidence(base, model)


# Keep all public aliases stable after the 2.12 overrides.
render_portfolio_lab_v1 = render_portfolio_lab_v2
render_portfolio_lab = render_portfolio_lab_v2
for _name in [
    "_pl212_search_instruments",
    "_pl212_validate_symbol",
    "_pl212_validate_book",
    "_pl212_book_gate",
    "_pl212_map_import_frame",
]:
    if _name not in __all__:
        __all__.append(_name)
